INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1BBSC8eTJZl', 1, '{"title":"金匮上课前言","description":"<p>        金匮是延续伤寒论而来的，属于杂病范畴之内，每个章节讨论不同的病，但是其辨证的基础还是以伤寒论为主，本次伤寒与金匮的解说与书籍的撰写，我采用许多过去历代的经方大师如江阴曹颖甫撰写的《伤寒发微》与《金匮发微》，四川唐容川撰写的《中西汇通医书五种》，陆九芝、傅青主、戴天章著，秦伯未、林直清校定《世补齐医书全集》，江忍庵增批，林直清勘的《徐灵胎医书全集》等等，经方也因为这些历代名家的研究与发扬，才能流传至今，这些名家也因此而流芳百世。 </p>\n<p></p>\n<p>        每当想起唐朝名医孙思邈时，我就会发出会心的一笑，因为他是先写出《千金要方》一书，当时他以为这将是经典之作，数年之后他看到了汉朝张仲景所写的《伤寒杂病论》，大为惊讶于经方，于是将《千金要方》做了许多修正，也就是后来的《千金翼方》，足证历代名医都将经方视为唯一的最高指导原则，也就是说不知道使用经方的中医，是不配被称为中医的，更不配被称为名家或是国手，所以要发扬中医学，就必须发扬经方，唯经方才是真正能够代表我国的正统医学。 </p>\n<p></p>\n<p>       经方的辨症论治法，不但极其科学，治疗效果迅速，好处比西方医学不知超过多少，比方说西方医学制造出许多吓人的病名，许多病人一听到自己得到某种病后，当时就已然吓傻了，心慌焦虑随之而来，完全失去斗志，任由西医药与病魔的宰割，使得绝大多数的病人是因为西医药的过度治疗与心理的惊吓而死亡的，并不是因为病而死的。</p>\n<p></p>\n<p>        反观中医学的辨症法，中医学不立病名，是因为立病名，会让疾病的定义变为更狭隘，符合于老子所谓的名可名非常名，中医学讲究同症同治，就是不受到病名的限制，立下病名对于病情非但是于事无补，有时病名立得过多，连西医自己都搅乱掉了，而西医认为不立病名是无法说服众人的，于是各种奇怪的病名充斥，试问西医师，那种病是被你们治好的呢，答案是没有一个病被他们真正的治好。而经方依据的辨症法则，只要医师使用得当，就可以很迅速的让病人恢复过来，无论医师是面对何种西医所谓的病，只要症状一样就可以使用同方来治疗，当病人只知道自己的症状，不知道自己的病名时，病人必然无惧于任何症状，在一开始与疾病作战时，病人的这种心理就已经胜利了，加上由训练精良的医师来施治，怎会治不好呢？ 现在临床上遇到最大的问题，就是病人被西医制造的病名先吓住后，中医再动手治疗，也就是说中医尚未开始治病时，就已经先输一着，治疗上就倍增困难，中药什么药都有，就是没有大胆丸，心理上的恐惧却往往是病人的致命伤所在，时常是无知胜于有知，这里的有知，指的是半个有知，如果是全有知，当然最好，但是病人怎么可能都是全知呢？ </p>\n<p></p>\n<p>        这次的人纪教学，将在金匮讲授完毕后全部结束，而我的临床经验医案传承，将利用地纪来撰写，所有地纪中提出应用的处方都来自经方，所以我暂时不再另外写一本专门介绍我实际临床案例的书籍，可能以后有变化也不一定，但是目前尚无此打算，就请大家拭目以待地纪著作的完成。 </p>\n<p></p>\n<p>                漢唐中醫 漢唐中醫 倪海厦 倪海厦</p>\n<p>                谨记于 05/20/2007 佛罗里达州自家书房</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050010,"no":1}}', '2025-01-18T07:09:51.000Z', '2025-01-18T07:09:51.000Z', '2025-01-18T07:09:51.000Z', '金匮是延续伤寒论而来的，属于杂病范畴之内，每个章节讨论不同的病，但是其辨证的基础还是以伤寒论为主，本次伤寒与金匮的解说与书籍的撰写，我采用许多过去历代的经方大师如江阴曹颖甫撰写的《伤寒发微》与《金匮发微》，四川唐容川撰写的《中西汇通医书五种》，陆九芝、傅青主、戴天章著，秦伯未、林直清校定《世补齐医书全集》，江忍庵增批，林直清勘的《徐灵胎医书全集》等等，经方也因为这些历代名家的研究与发扬，才能流传至今，这些名家也因此而流芳百世。 每当想起唐朝名医孙思邈时，我就会发出会心的一笑，因为他是先写出《千金要方》一书，当时他以为这将是经典之作，数年之后他看到了汉朝张仲景所写的《伤寒杂病论》，大为惊讶于经方，于是将《千金要方》做了许多修正，也就是后来的《千金翼方》，足证历代名医都将经方视为唯一的最高指导原则，也就是说不知道使用经方的中医，是不配被称为中医的，更不配被称为名家或是国手，所以要发扬中医学，就必须发扬经方，唯经方才是真正能够代表我国的正统医学。 经方的辨症论治法，不但极其科学，治疗效果迅速，好处比西方医学不知超过多少，比方说西方医学制造出许多吓人的病名，许多病人一听到自己得到某种病后，当时就已然吓傻了，心慌焦虑随之而来，完全失去斗志，任由西医药与病魔的宰割，使得绝大多数的病人是因为西医药的过度治疗与心理的惊吓而死亡的，并不是因为病而死的。 反观中医学的辨症法，中医学不立病名，是因为立病名，会让疾病的定义变为更狭隘，符合于老子所谓的名可名非常名，中医学讲究同症同治，就是不受到病名的限制，立下病名对于病情非但是于事无补，有时病名立得过多，连西医自己都搅乱掉了，而西医认为不立病名是无法说服众人的，于是各种奇怪的病名充斥，试问西医师，那种病是被你们治好的呢，答案是没有一个病被他们真正的治好。而经方依据的辨症法则，只要医师使用得当，就可以很迅速的让病人恢复过来，无论医师是面对何种西医所谓的病，只要症状一样就可以使用同方来治疗，当病人只知道自己的症状，不知道自己的病名时，病人必然无惧于任何症状，在一开始与疾病作战时，病人的这种心理就已经胜利了，加上由训练精良的医师来施治，怎会治不好呢？ 现在临床上遇到最大的问题，就是病人被西医制造的病名先吓住后，中医再动手治疗，也就是说中医尚未开始治病时，就已经先输一着，治疗上就倍增困难，中药什么药都有，就是没有大胆丸，心理上的恐惧却往往是病人的致命伤所在，时常是无知胜于有知，这里的有知，指的是半个有知，如果是全有知，当然最好，但是病人怎么可能都是全知呢？ 这次的人纪教学，将在金匮讲授完毕后全部结束，而我的临床经验医案传承，将利用地纪来撰写，所有地纪中提出应用的处方都来自经方，所以我暂时不再另外写一本专门介绍我实际临床案例的书籍，可能以后有变化也不一定，但是目前尚无此打算，就请大家拭目以待地纪著作的完成。 漢唐中醫 漢唐中醫 倪海厦 倪海厦 谨记于 05/20/2007 佛罗里达州自家书房', '2025-01-18T07:09:51.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eWgAGNdK3M8', 1, '{"title":"续伤寒篇-辨霍乱病脉证","description":"<p>1、问曰：病有霍乱者何？</p>\n<p></p>\n<p>     答曰：呕吐而利 是名霍乱。  </p><p>2、问曰：病发热，头痛，，恶寒，吐利者，此属何病</p>\n<p></p>\n<p>     答曰：此名霍乱霍乱自吐下，又利止复更发热也。</p><p>3、伤寒，其脉微涩者，本是霍乱，今是伤寒，，却四五日至阴经，阳转入阴，必利，本呕下利者，不可治也。欲似大便而反失气，仍不利者，此属阳明也，便必鞭，十三日愈。所以然者， 经尽故也。</p><p>4、下利后，当便鞭，鞭则能食者愈。今反不能食，到后经中颇能食，复过一经能食，过之一日当愈。不愈者，不属阳明也。</p><p>5、利止，恶寒脉微，而复利，亡血也，$f{四逆加人参汤}主之。</p><p>6、霍乱头痛，发热，身疼痛，热多欲饮水者，$f{五苓散}主之，寒多不用水者，$f{理中丸}主之 </p><p>7、吐利止而身痛不休者当消息和解其外，宜$f{桂枝汤}小和之。  </p><p>8、吐利汗出 发热恶寒， 四肢拘急， 手足厥冷者，$f{四逆汤}主之。既吐且利，小便复利，而大汗出，下利清谷，内寒外热，，脉微欲绝者$f{四逆汤}主之。</p><p>9、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。</p><p>10、利发汗小烦者，以新虚不胜谷气故也 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050020,"no":2}}', '2025-01-18T07:12:40.000Z', '2025-01-18T07:12:40.000Z', '2025-01-18T07:12:40.000Z', '1、问曰：病有霍乱者何？ 答曰：呕吐而利 是名霍乱。 2、问曰：病发热，头痛，，恶寒，吐利者，此属何病 答曰：此名霍乱霍乱自吐下，又利止复更发热也。 3、伤寒，其脉微涩者，本是霍乱，今是伤寒，，却四五日至阴经，阳转入阴，必利，本呕下利者，不可治也。欲似大便而反失气，仍不利者，此属阳明也，便必鞭，十三日愈。所以然者， 经尽故也。 4、下利后，当便鞭，鞭则能食者愈。今反不能食，到后经中颇能食，复过一经能食，过之一日当愈。不愈者，不属阳明也。 5、利止，恶寒脉微，而复利，亡血也，$f{四逆加人参汤}主之。 6、霍乱头痛，发热，身疼痛，热多欲饮水者，$f{五苓散}主之，寒多不用水者，$f{理中丸}主之 7、吐利止而身痛不休者当消息和解其外，宜$f{桂枝汤}小和之。 8、吐利汗出 发热恶寒， 四肢拘急， 手足厥冷者，$f{四逆汤}主之。既吐且利，小便复利，而大汗出，下利清谷，内寒外热，，脉微欲绝者$f{四逆汤}主之。 9、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。 10、利发汗小烦者，以新虚不胜谷气故也', '2025-01-18T07:12:40.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q2P6KdHdm5U', 1, '{"title":"藏府经络先后病脉证第一","description":"<p>1、问曰： 上工治未病， 何也  </p>\n<p></p>\n<p>     师曰： 夫治未病者， 见肝之病， 知肝传脾， 当先实脾，四季脾王不受邪，即勿补之。</p>\n<p></p>\n<p>    中工不晓相传，见肝之病，不解实脾惟治肝也。</p>\n<p></p>\n<p>    夫肝之病，补用酸，助用焦苦， 益用甘味之药调之。肝虚则用此法，实则不任用之。  </p>\n<p></p>\n<p>    经曰： 无实实， 无虚虚， 补不足， 损有余。 是其义也。余藏准此  。</p><p>2、夫人禀五常 因风气而生长，风气虽能生万物，亦能害万物，如水能载舟，亦能覆舟。若五藏元真通畅，人即安和，客气邪风， 中人多死， 千般疢（chèn ） 难， 不越三条 。</p>\n<p></p>\n<p>    一者 皮肤所中，经络受邪入藏府，为外所因也；</p>\n<p></p>\n<p>   二者，四肢九窍，血脉相传，壅塞不通，为内所因也；</p>\n<p></p>\n<p>  三者，房室金刃虫兽所伤。 </p>\n<p></p>\n<p>    以此详之， 病由都尽。 若人能养慎 ，不令邪风干忤经络 适中经络，未流传府藏，即医治之，四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处。理者，是皮肤藏府之文理也。</p><p>3、问曰：病人有气色见于面部，愿问其说 ？</p>\n<p></p>\n<p>  师曰：鼻头色青，腹中痛，苦冷者死；鼻头色微黑者，有水气； </p>\n<p></p>\n<p>  色黄者，胸上有寒 ； 色白者，亡血也 ；设微赤，非时者死。其目正圆者，痉，不治。</p>\n<p></p>\n<p> 又色青为痛，</p>\n<p></p>\n<p> 色黑为劳，</p>\n<p></p>\n<p> 色赤为风，</p>\n<p></p>\n<p> 色黄者，便难，</p>\n<p></p>\n<p> 色鲜明者，有留饮。  </p>\n<p></p>\n<p></p><p>4、师曰：病人语声寂寂然，喜惊呼者 ，骨节间病；语声喑喑然不彻者 ，心膈间病 ；语声啾啾然细而长者 ，头中痛。</p><p>5、师曰 ：息摇肩者，心中坚 ；息引胸中上气者 ，咳 ；息张口短 气者 ，肺痿吐沫。</p><p>6、师曰：吸而微数，其病在中焦实也。当下之则愈。虚者不治。 在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸  动摇振振 ，不治。</p><p>7、师曰：寸口脉动者，因其王时而动，四时各随其色，非其时， 色脉皆当病。</p><p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过， 何谓也？</p>\n<p></p>\n<p>      师曰： 冬至之后， 甲子夜半，少阳起，少阳之时， 阳始生， 天得温和，此为未至而至也； 以得甲子，而天未温和者，此为至而不至也； 以得甲子而天大寒不解，此为至而不去也 ；以得甲子而天温如盛夏五六月时，此为至而太过也。</p><p>9、师曰：病人脉，浮者在前，其病在表；浮者在后，其病在里， 腰痛背强不能行 ，必短气而极也。</p><p>10、问曰：经云 ：厥阳独行 ，何谓也？</p>\n<p></p>\n<p>       师曰 ：此为有阳无阴 ，故称厥阳。</p><p>11、问曰：寸脉洪大而滑，，洪则为实、滑则为气 ，实气相抟 ，血气入藏即死 ，入府即愈 ，此为卒厥 ，何谓也？</p>\n<p></p>\n<p>      师曰：唇口青身冷，为入藏，即死；如身和汗自出，为入腑， 即愈。</p><p>12、问曰：脉脱入藏即死 ，入府即愈 ，何谓也？</p>\n<p></p>\n<p>       师曰 ：非为一病 ，百病皆然。譬如浸淫疮，从口起流向四肢 者，可治；从四肢流来入口者，不可治。病在外者可 治 ，入里者难治。</p><p>13、问曰： 阳病十八 ，何谓也？ 师曰： 头痛 ，项腰脊臂脚掣痛。</p>\n<p></p>\n<p>      阴病十八 ，何谓也？</p>\n<p></p>\n<p>     师曰： 欬上气喘哕咽肠鸣胀满心痛拘急。 五藏病各有十八， 合为九十病；人又有六微，微有十八病，合为一百八 病。五劳七伤六极 ，妇人三六病，不在其中。清邪居上 ，浊邪居下 ，大邪中表，小邪中里，谷饦之邪，从 口入者 ，宿食也。 五邪中人 ，各有法度 ，风中于前， 寒中于后，湿伤于下 ，雾伤于上，风令脉浮 ，寒令脉 急 ，雾伤皮腠，湿流关节 ，食伤脾胃，极寒伤经，极热伤络。</p><p>14、问曰 ：病有急当救里救表者 ，何谓也？</p>\n<p></p>\n<p>     师曰：病医下之，续得下利清谷不止 ，身体疼痛者 ，急当救里 ；后身体疼痛 ，清便自调者，急当救表也。</p><p>15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。</p><p>16、师曰 ：五藏病各有得者，愈 ；五藏病各有所恶，各随其所不喜者为病。</p><p>17、病者素不应食 ，而反暴思之 ，必发热也。</p><p>18、夫诸病在藏，欲攻之 ，当随其所得而攻之，如渴者舆$f{猪苓汤} ，余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050030,"no":3}}', '2025-01-18T07:13:10.000Z', '2025-01-18T07:13:10.000Z', '2025-01-18T07:13:10.000Z', '1、问曰： 上工治未病， 何也 师曰： 夫治未病者， 见肝之病， 知肝传脾， 当先实脾，四季脾王不受邪，即勿补之。 中工不晓相传，见肝之病，不解实脾惟治肝也。 夫肝之病，补用酸，助用焦苦， 益用甘味之药调之。肝虚则用此法，实则不任用之。 经曰： 无实实， 无虚虚， 补不足， 损有余。 是其义也。余藏准此 。 2、夫人禀五常 因风气而生长，风气虽能生万物，亦能害万物，如水能载舟，亦能覆舟。若五藏元真通畅，人即安和，客气邪风， 中人多死， 千般疢（chèn ） 难， 不越三条 。 一者 皮肤所中，经络受邪入藏府，为外所因也； 二者，四肢九窍，血脉相传，壅塞不通，为内所因也； 三者，房室金刃虫兽所伤。 以此详之， 病由都尽。 若人能养慎 ，不令邪风干忤经络 适中经络，未流传府藏，即医治之，四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处。理者，是皮肤藏府之文理也。 3、问曰：病人有气色见于面部，愿问其说 ？ 师曰：鼻头色青，腹中痛，苦冷者死；鼻头色微黑者，有水气； 色黄者，胸上有寒 ； 色白者，亡血也 ；设微赤，非时者死。其目正圆者，痉，不治。 又色青为痛， 色黑为劳， 色赤为风， 色黄者，便难， 色鲜明者，有留饮。 4、师曰：病人语声寂寂然，喜惊呼者 ，骨节间病；语声喑喑然不彻者 ，心膈间病 ；语声啾啾然细而长者 ，头中痛。 5、师曰 ：息摇肩者，心中坚 ；息引胸中上气者 ，咳 ；息张口短 气者 ，肺痿吐沫。 6、师曰：吸而微数，其病在中焦实也。当下之则愈。虚者不治。 在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸 动摇振振 ，不治。 7、师曰：寸口脉动者，因其王时而动，四时各随其色，非其时， 色脉皆当病。 8、问曰：有未至而至，有至而不至，有至而不去，有至而太过， 何谓也？ 师曰： 冬至之后， 甲子夜半，少阳起，少阳之时， 阳始生， 天得温和，此为未至而至也； 以得甲子，而天未温和者，此为至而不至也； 以得甲子而天大寒不解，此为至而不去也 ；以得甲子而天温如盛夏五六月时，此为至而太过也。 9、师曰：病人脉，浮者在前，其病在表；浮者在后，其病在里， 腰痛背强不能行 ，必短气而极也。 10、问曰：经云 ：厥阳独行 ，何谓也？ 师曰 ：此为有阳无阴 ，故称厥阳。 11、问曰：寸脉洪大而滑，，洪则为实、滑则为气 ，实气相抟 ，血气入藏即死 ，入府即愈 ，此为卒厥 ，何谓也？ 师曰：唇口青身冷，为入藏，即死；如身和汗自出，为入腑， 即愈。 12、问曰：脉脱入藏即死 ，入府即愈 ，何谓也？ 师曰 ：非为一病 ，百病皆然。譬如浸淫疮，从口起流向四肢 者，可治；从四肢流来入口者，不可治。病在外者可 治 ，入里者难治。 13、问曰： 阳病十八 ，何谓也？ 师曰： 头痛 ，项腰脊臂脚掣痛。 阴病十八 ，何谓也？ 师曰： 欬上气喘哕咽肠鸣胀满心痛拘急。 五藏病各有十八， 合为九十病；人又有六微，微有十八病，合为一百八 病。五劳七伤六极 ，妇人三六病，不在其中。清邪居上 ，浊邪居下 ，大邪中表，小邪中里，谷饦之邪，从 口入者 ，宿食也。 五邪中人 ，各有法度 ，风中于前， 寒中于后，湿伤于下 ，雾伤于上，风令脉浮 ，寒令脉 急 ，雾伤皮腠，湿流关节 ，食伤脾胃，极寒伤经，极热伤络。 14、问曰 ：病有急当救里救表者 ，何谓也？ 师曰：病医下之，续得下利清谷不止 ，身体疼痛者 ，急当救里 ；后身体疼痛 ，清便自调者，急当救表也。 15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。 16、师曰 ：五藏病各有得者，愈 ；五藏病各有所恶，各随其所不喜者为病。 17、病者素不应食 ，而反暴思之 ，必发热也。 18、夫诸病在藏，欲攻之 ，当随其所得而攻之，如渴者舆$f{猪苓汤} ，余皆仿此。', '2025-01-18T07:13:10.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EFq5orwY5uR', 1, '{"title":"痉湿暍病脉证治法第二","description":"<p>1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉。太阳病发 热汗出 ，而不恶寒 ，名曰柔痉。</p><p>2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治。</p><p>3、太阳病 ，发汗太多 ， 因致痉。</p><p>4、夫风病 ，下之则痉 ，复发汗 ，必拘急。</p><p>5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉。</p><p>6、病者，身热足寒，颈项强急，恶寒，时头热，面赤目赤， 独头动摇 ，卒口噤 ，背反张者，痉病也。若发其汗 ，其脉如蛇。</p><p>7、暴腹胀大者，为欲解。脉如故，反伏弦者，痉，夫痉脉， 按之紧如弦 ，直上下行。</p><p>8、痉病有灸疮 ，难治。</p><p>9、太阳病其证备 ，身体强 ，几几然 ，脉反沉迟 ，此为痉， $f{栝篓桂枝汤}主之。</p><p>10、太阳病 ，无汗，小便反少 ，气上胸 ， 口噤不得语 ，欲作刚痉 ，$f{葛根汤}主之。</p><p>11、痉为病 ，胸满口噤 ，卧不着席 ，脚挛急 ，必齘齿 ，可与$f{大承气汤}。</p><p>12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹。湿痹之候 ，小便不利 ，大便反快 ，但当利其小便。</p><p>13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也。</p><p>14、湿家 ，其人但头汗出 ，背强欲得被覆向火 ，若下之早， 则哕 ，或胸满，，小便不利 ，舌上如胎者 ，以丹田有热 ，胸上有寒 ，渴欲得饮而不能饮 ，则口燥烦也。</p><p>15、湿家下之，额上汗出，微喘，小便利者，死；若下利不止者 ，亦死。</p><p>16、风湿相抟（应为『抟 tuán』非『搏』，后文同此），一身尽疼痛，法当汗出而解，值天阴雨不止，医云：此可发其汗， 汗之病不愈者，何也？</p>\n<p></p>\n<p>       盖发其汗 ，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，但微微似欲汗出者，风湿俱去也。</p><p>17、湿家，病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大， 自能饮食，腹中和无病，病在头中寒湿 ，故鼻塞 ，内药鼻中则愈。</p><p>18、湿家 ，身烦疼，可与$f{麻黄加术汤}，发其汗为宜 ，慎不可以火攻之。</p><p>19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。 </p><p>20、风湿 ，脉浮 ，身重 ，汗出恶风者 ，$f{防己黄耆汤}主之。 </p><p>21、伤寒八九日，风湿搏相 ，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利 ，$f{去桂枝加白术汤}主之。</p><p>22、风湿相抟，骨节疼烦 ，掣痛不得屈伸 ，近之则痛剧 ，汗出短气，小便不利，恶风不欲去衣 ，或身微肿，$f{甘草附子汤} 主之。</p><p>23、太阳中暍，发热恶寒 ，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳 ，身即热 ， 口开前板齿燥 ；若发其汗 ，则恶寒甚 ；加温针 ，则发热甚； 数下之， 则淋甚。</p><p>24、太阳中热者 ，暍是也 ，汗出恶寒 ，身热而渴 ，$f{白虎加人参汤}主之。</p><p>25、太阳中暍，身热疼重 ，而脉微弱，此以夏月伤冷水，水行皮中所致也 ，一物$f{瓜蒂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050040,"no":4}}', '2025-01-18T07:13:31.000Z', '2025-01-18T07:13:31.000Z', '2025-01-18T07:13:31.000Z', '1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉。太阳病发 热汗出 ，而不恶寒 ，名曰柔痉。 2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治。 3、太阳病 ，发汗太多 ， 因致痉。 4、夫风病 ，下之则痉 ，复发汗 ，必拘急。 5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉。 6、病者，身热足寒，颈项强急，恶寒，时头热，面赤目赤， 独头动摇 ，卒口噤 ，背反张者，痉病也。若发其汗 ，其脉如蛇。 7、暴腹胀大者，为欲解。脉如故，反伏弦者，痉，夫痉脉， 按之紧如弦 ，直上下行。 8、痉病有灸疮 ，难治。 9、太阳病其证备 ，身体强 ，几几然 ，脉反沉迟 ，此为痉， $f{栝篓桂枝汤}主之。 10、太阳病 ，无汗，小便反少 ，气上胸 ， 口噤不得语 ，欲作刚痉 ，$f{葛根汤}主之。 11、痉为病 ，胸满口噤 ，卧不着席 ，脚挛急 ，必齘齿 ，可与$f{大承气汤}。 12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹。湿痹之候 ，小便不利 ，大便反快 ，但当利其小便。 13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也。 14、湿家 ，其人但头汗出 ，背强欲得被覆向火 ，若下之早， 则哕 ，或胸满，，小便不利 ，舌上如胎者 ，以丹田有热 ，胸上有寒 ，渴欲得饮而不能饮 ，则口燥烦也。 15、湿家下之，额上汗出，微喘，小便利者，死；若下利不止者 ，亦死。 16、风湿相抟（应为『抟 tuán』非『搏』，后文同此），一身尽疼痛，法当汗出而解，值天阴雨不止，医云：此可发其汗， 汗之病不愈者，何也？ 盖发其汗 ，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，但微微似欲汗出者，风湿俱去也。 17、湿家，病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大， 自能饮食，腹中和无病，病在头中寒湿 ，故鼻塞 ，内药鼻中则愈。 18、湿家 ，身烦疼，可与$f{麻黄加术汤}，发其汗为宜 ，慎不可以火攻之。 19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。 20、风湿 ，脉浮 ，身重 ，汗出恶风者 ，$f{防己黄耆汤}主之。 21、伤寒八九日，风湿搏相 ，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利 ，$f{去桂枝加白术汤}主之。 22、风湿相抟，骨节疼烦 ，掣痛不得屈伸 ，近之则痛剧 ，汗出短气，小便不利，恶风不欲去衣 ，或身微肿，$f{甘草附子汤} 主之。 23、太阳中暍，发热恶寒 ，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳 ，身即热 ， 口开前板齿燥 ；若发其汗 ，则恶寒甚 ；加温针 ，则发热甚； 数下之， 则淋甚。 24、太阳中热者 ，暍是也 ，汗出恶寒 ，身热而渴 ，$f{白虎加人参汤}主之。 25、太阳中暍，身热疼重 ，而脉微弱，此以夏月伤冷水，水行皮中所致也 ，一物$f{瓜蒂汤}主之。', '2025-01-18T07:13:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OeVFpYJ6TYW', 1, '{"title":"百合狐惑阴阳毒证治第三","description":"<p>1、论曰：百合病者 ，百脉一宗 ，悉致其病也。意欲食 ，复不能食 ，常默默然 ，欲卧不能卧 ，欲行不能行，饮食或有美时 ，或有不欲闻食臭时 ，如寒无寒 ，如热无热 ， 口苦，小便赤，诸药不能治，得药则剧吐利 ，如有神灵者 ，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅淅然者，四十日愈；若溺快然， 但头眩者 ，二十日愈。其证或未病而预见 ，或病四五日而出 ，或病二十日或一月后见者 ，各随证治之。</p><p>2、百合病，不经吐下发汗，病形如初者，$f{百合地黄汤}主之。 </p><p>3、百合病 ，发汗后者 ，$f{百合知母汤}主之。 </p><p>4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之。 </p><p>5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之。 </p><p>6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之。 </p><p>7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之。 </p><p>8、百合病变发热者 ，$f{百合滑石散}主之。 </p><p>9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之。 见阳攻阴 ，复发其汗 ，此为逆 ；见阴攻阳 ，乃复下之， 此亦为逆。</p><p>10、狐惑之为病，状如伤寒，默默欲眠 ， 目不得闭 ，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭 ，其面目乍赤 、乍黑、乍白，蚀于上部则声嚘，甘草赤、乍黑 、乍白 ，蚀于上部则声嚘 ，$f{甘草泻心汤}主之。蚀于下部则咽干， $f{苦参汤}洗之。蚀于肛者 ，$u{雄黄}熏之。</p><p>11、病者脉数，无热微烦，默默但欲卧 ，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也， $f{赤小豆当归散}主之。</p><p>12、阳毒之为病 ，面赤斑斑如锦纹 ，咽喉痛 ，唾脓血 ，五日可治，七日不可治，${升麻鳖甲汤}主之。阴毒之为病，面目青， 身痛如被杖 ，咽喉痛 ，五日可治，七日不可治，${升麻鳖甲去雄黄蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050050,"no":5}}', '2025-01-18T07:15:40.000Z', '2025-01-18T07:15:40.000Z', '2025-01-18T07:15:40.000Z', '1、论曰：百合病者 ，百脉一宗 ，悉致其病也。意欲食 ，复不能食 ，常默默然 ，欲卧不能卧 ，欲行不能行，饮食或有美时 ，或有不欲闻食臭时 ，如寒无寒 ，如热无热 ， 口苦，小便赤，诸药不能治，得药则剧吐利 ，如有神灵者 ，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅淅然者，四十日愈；若溺快然， 但头眩者 ，二十日愈。其证或未病而预见 ，或病四五日而出 ，或病二十日或一月后见者 ，各随证治之。 2、百合病，不经吐下发汗，病形如初者，$f{百合地黄汤}主之。 3、百合病 ，发汗后者 ，$f{百合知母汤}主之。 4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之。 5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之。 6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之。 7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之。 8、百合病变发热者 ，$f{百合滑石散}主之。 9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之。 见阳攻阴 ，复发其汗 ，此为逆 ；见阴攻阳 ，乃复下之， 此亦为逆。 10、狐惑之为病，状如伤寒，默默欲眠 ， 目不得闭 ，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭 ，其面目乍赤 、乍黑、乍白，蚀于上部则声嚘，甘草赤、乍黑 、乍白 ，蚀于上部则声嚘 ，$f{甘草泻心汤}主之。蚀于下部则咽干， $f{苦参汤}洗之。蚀于肛者 ，$u{雄黄}熏之。 11、病者脉数，无热微烦，默默但欲卧 ，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也， $f{赤小豆当归散}主之。 12、阳毒之为病 ，面赤斑斑如锦纹 ，咽喉痛 ，唾脓血 ，五日可治，七日不可治，${升麻鳖甲汤}主之。阴毒之为病，面目青， 身痛如被杖 ，咽喉痛 ，五日可治，七日不可治，${升麻鳖甲去雄黄蜀椒}主之。', '2025-01-18T07:15:40.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sb94nnnZSf2', 1, '{"title":"疟病脉证并治第四","description":"<p>1、师曰：疟脉自弦 ，弦数者多热 ，弦迟者多寒 ，弦小紧者下之差 ，弦迟者可温之 ，弦紧者可发汗 、针灸也，浮大者 可吐之 ，弦数者 ，风发也， 以饮食消息止之。</p><p>2、疟病结为癥瘕 ，如其不差 ，当云何？</p>\n<p></p>\n<p>       师曰：此名疟母， 急治之。 以月一日发 ，当以十五日愈 ；设不差 ，当月尽解， 宜$f{鳖甲煎丸}。</p><p>3、师曰： 阴气孤绝，，阳气独发 ，则热而少气 、烦冤 ，手足热而欲呕，名曰瘅疟；若但热不寒者 ，邪气内藏于心，外舍分肉之间 ，令人消铄肌肉。</p><p>4、温疟者 ，其脉如平，身无寒 ，但热 ，骨节烦疼 ， 时呕， $f{白虎加桂枝汤}主之。</p><p>5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之。 </p><p>6、《补充》$f{牡蛎汤}   治牝疟</p><p>7、《补充》$f{柴胡去半夏加栝蒌汤}    治疟病以发渴者，亦治劳疟。</p><p>8、《补充》$f{柴胡桂姜汤}    治疟寒多微有热，或但寒不热。（服一剂如神）</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050060,"no":6}}', '2025-01-18T07:15:51.000Z', '2025-01-18T07:15:51.000Z', '2025-01-18T07:15:51.000Z', '1、师曰：疟脉自弦 ，弦数者多热 ，弦迟者多寒 ，弦小紧者下之差 ，弦迟者可温之 ，弦紧者可发汗 、针灸也，浮大者 可吐之 ，弦数者 ，风发也， 以饮食消息止之。 2、疟病结为癥瘕 ，如其不差 ，当云何？ 师曰：此名疟母， 急治之。 以月一日发 ，当以十五日愈 ；设不差 ，当月尽解， 宜$f{鳖甲煎丸}。 3、师曰： 阴气孤绝，，阳气独发 ，则热而少气 、烦冤 ，手足热而欲呕，名曰瘅疟；若但热不寒者 ，邪气内藏于心，外舍分肉之间 ，令人消铄肌肉。 4、温疟者 ，其脉如平，身无寒 ，但热 ，骨节烦疼 ， 时呕， $f{白虎加桂枝汤}主之。 5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之。 6、《补充》$f{牡蛎汤} 治牝疟 7、《补充》$f{柴胡去半夏加栝蒌汤} 治疟病以发渴者，亦治劳疟。 8、《补充》$f{柴胡桂姜汤} 治疟寒多微有热，或但寒不热。（服一剂如神）', '2025-01-18T07:15:51.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('28xphHVXuPE', 1, '{"title":"中风历节病脉并第五","description":"<p>1、夫风之为病 ，当半身不遂 ，或但臂不遂者，此为痹，脉微而数 ， 中风使然。</p><p>2、寸口脉浮而紧，紧则为寒，浮则为虚 ，寒虚相抟 ，邪在皮肤 ，浮者血虚，络脉空虚，贼邪不泻 ，或左或右 ，邪气反 缓 ，正气即气即急 ，正气引邪 ，喎僻不遂。</p>\n<p></p>\n<p>       邪在于络 ，肌肤不仁 ；邪在于经，即重不胜 ；邪入于府 ，即不识人 ；邪入于藏 ，舌则难言 ，口吐涎沫。</p><p>3、寸口脉迟而缓 ，迟则为寒 ，缓则为虚； 营缓则为亡血， 卫缓则为中风 ；邪气中经，则身痒而瘾疹；心气不足 ，邪气入中 ，则胸满而短气。</p><p>4、$f{防己地黄汤}   治病如狂状 ，妄行独语不休，无寒热，其脉浮。</p><p>5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者。</p><p>6、$f{风引汤}，治除热瘫痫</p><p>7、$f{头风摩散方}</p><p>8、寸口脉沉而弱 ，沉即主骨 ，弱即主筋 ，沉即为肾 ，弱即为肝 ，汗出入水中 ，如水伤心 ，历节黄汗出 ，故曰历节。</p><p>9、趺阳脉浮而滑，滑则谷气实，浮则汗自出。太阴脉浮而弱 ，弱则血不足 ，浮则为风 ，风血相抟 ， 即疼痛如掣。</p>\n<p>盛人脉涩小 ，短气 ，自汗出 ，历节疼 ，不可屈伸 ，此皆饮酒汗出当风所致。</p><p>10、诸肢节疼痛 ，身体尪羸 ，脚肿如脱 ，头眩短气 ，温温欲吐 ，$f{桂枝芍药知母汤}主之。</p><p>11、味酸则伤筋，筋伤则缓，名曰泄。咸则伤骨，骨伤则痿，名曰枯 ；枯泄相抟 ，名曰断泄。营气不通 ，卫不独行 ，营卫俱微 ，三焦无所御，四属断绝 ，身体羸瘦，独足肿大 ，黄汗  出 ，胫冷 ，假令发热 ，使为历节也。</p><p>12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之。 </p><p>13、$f{矾石汤}治脚气冲心</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050070,"no":7}}', '2025-01-18T07:16:08.000Z', '2025-01-18T07:16:08.000Z', '2025-01-18T07:16:08.000Z', '1、夫风之为病 ，当半身不遂 ，或但臂不遂者，此为痹，脉微而数 ， 中风使然。 2、寸口脉浮而紧，紧则为寒，浮则为虚 ，寒虚相抟 ，邪在皮肤 ，浮者血虚，络脉空虚，贼邪不泻 ，或左或右 ，邪气反 缓 ，正气即气即急 ，正气引邪 ，喎僻不遂。 邪在于络 ，肌肤不仁 ；邪在于经，即重不胜 ；邪入于府 ，即不识人 ；邪入于藏 ，舌则难言 ，口吐涎沫。 3、寸口脉迟而缓 ，迟则为寒 ，缓则为虚； 营缓则为亡血， 卫缓则为中风 ；邪气中经，则身痒而瘾疹；心气不足 ，邪气入中 ，则胸满而短气。 4、$f{防己地黄汤} 治病如狂状 ，妄行独语不休，无寒热，其脉浮。 5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者。 6、$f{风引汤}，治除热瘫痫 7、$f{头风摩散方} 8、寸口脉沉而弱 ，沉即主骨 ，弱即主筋 ，沉即为肾 ，弱即为肝 ，汗出入水中 ，如水伤心 ，历节黄汗出 ，故曰历节。 9、趺阳脉浮而滑，滑则谷气实，浮则汗自出。太阴脉浮而弱 ，弱则血不足 ，浮则为风 ，风血相抟 ， 即疼痛如掣。 盛人脉涩小 ，短气 ，自汗出 ，历节疼 ，不可屈伸 ，此皆饮酒汗出当风所致。 10、诸肢节疼痛 ，身体尪羸 ，脚肿如脱 ，头眩短气 ，温温欲吐 ，$f{桂枝芍药知母汤}主之。 11、味酸则伤筋，筋伤则缓，名曰泄。咸则伤骨，骨伤则痿，名曰枯 ；枯泄相抟 ，名曰断泄。营气不通 ，卫不独行 ，营卫俱微 ，三焦无所御，四属断绝 ，身体羸瘦，独足肿大 ，黄汗 出 ，胫冷 ，假令发热 ，使为历节也。 12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之。 13、$f{矾石汤}治脚气冲心', '2025-01-18T07:16:08.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cea3eDc6G5J', 1, '{"title":"血痹虚劳病脉并治第六","description":"<p>1、问曰 ：血痹之病 ，从何得之？</p>\n<p></p>\n<p>     师曰 ：夫尊荣人，骨弱 ，肌肤盛 ，重因疲劳汗出 ，卧不时动摇，加被微风 ，遂得之。但以脉自微涩在寸口，关上小紧 ，宜针引阳气 ，令脉和紧去则愈。</p><p>2、血痹 ，阴阳俱微 ，寸口关上微，尺中小紧，外证身体不仁 ，如风痹状 ，$f{黄耆桂枝五物汤}主之。</p><p>3、夫男子平人脉大为劳 ，脉极虚亦为劳。</p><p>4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也。</p><p>5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白， 时目瞑 ，兼衄 ，少腹满 ，此为劳使之然。</p><p>6、劳之为病，其脉浮大 ，手足烦，春夏剧，秋冬差 ，阴寒精自出 ，痠削不能行。</p><p>7、男子脉浮弱而涩 ，为无子，精气清冷。</p><p>8、夫失精家，少腹弦急 ，阴头寒 ， 目眩 ，髮落，脉极虚芤迟 ，为清谷 ，亡血失精。脉得诸芤动微紧 ，男子失精 ，女子梦交 ，$f{桂枝龙骨牡蛎汤}主之。</p><p>9、男子平人脉虚弱细微者 ，喜盗汗也。</p><p>10、人年五六十，其病脉大者，痹侠背行。若肠鸣马刀侠瘿者 ， 皆为劳得之。</p><p>11、脉沉小迟，名脱气，其人疾行则喘喝，手足逆寒，腹满， 甚则溏泄 ，食不消化也。</p><p>12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚， 虚寒相抟 ，此名为革 ，妇人则半产漏下 ，男子则亡血失精。</p><p>13、虚劳里急，悸衄腹中痛，梦失精，四肢痠疼，手足烦热，， 咽干口燥 ，$f{小建中汤}主之。</p><p>14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之。</p><p>15、虚劳腰痛 ，少腹拘急 ，小便不利者 ，$f{八味肾气丸}主之。</p><p>16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之。 </p><p>17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之。 </p><p>18、五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤 ，经络荣卫气伤 ， 内有干血 ，肌肤甲错 ，两目黯黑， 缓中补虚 ，$f{大黄蟅虫丸}主之。</p><p>19、方剂补充《千金翼》$f{灸甘草汤}  治虚劳不足汗出而闷，脉结悸，行动如常， 不出百日，危急者十一日死。</p>\n<p></p>\n<p>    《肘后》$f{獭肝散}</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050080,"no":8}}', '2025-01-18T07:16:26.000Z', '2025-01-18T07:16:26.000Z', '2025-01-18T07:16:26.000Z', '1、问曰 ：血痹之病 ，从何得之？ 师曰 ：夫尊荣人，骨弱 ，肌肤盛 ，重因疲劳汗出 ，卧不时动摇，加被微风 ，遂得之。但以脉自微涩在寸口，关上小紧 ，宜针引阳气 ，令脉和紧去则愈。 2、血痹 ，阴阳俱微 ，寸口关上微，尺中小紧，外证身体不仁 ，如风痹状 ，$f{黄耆桂枝五物汤}主之。 3、夫男子平人脉大为劳 ，脉极虚亦为劳。 4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也。 5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白， 时目瞑 ，兼衄 ，少腹满 ，此为劳使之然。 6、劳之为病，其脉浮大 ，手足烦，春夏剧，秋冬差 ，阴寒精自出 ，痠削不能行。 7、男子脉浮弱而涩 ，为无子，精气清冷。 8、夫失精家，少腹弦急 ，阴头寒 ， 目眩 ，髮落，脉极虚芤迟 ，为清谷 ，亡血失精。脉得诸芤动微紧 ，男子失精 ，女子梦交 ，$f{桂枝龙骨牡蛎汤}主之。 9、男子平人脉虚弱细微者 ，喜盗汗也。 10、人年五六十，其病脉大者，痹侠背行。若肠鸣马刀侠瘿者 ， 皆为劳得之。 11、脉沉小迟，名脱气，其人疾行则喘喝，手足逆寒，腹满， 甚则溏泄 ，食不消化也。 12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚， 虚寒相抟 ，此名为革 ，妇人则半产漏下 ，男子则亡血失精。 13、虚劳里急，悸衄腹中痛，梦失精，四肢痠疼，手足烦热，， 咽干口燥 ，$f{小建中汤}主之。 14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之。 15、虚劳腰痛 ，少腹拘急 ，小便不利者 ，$f{八味肾气丸}主之。 16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之。 17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之。 18、五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤 ，经络荣卫气伤 ， 内有干血 ，肌肤甲错 ，两目黯黑， 缓中补虚 ，$f{大黄蟅虫丸}主之。 19、方剂补充《千金翼》$f{灸甘草汤} 治虚劳不足汗出而闷，脉结悸，行动如常， 不出百日，危急者十一日死。 《肘后》$f{獭肝散}', '2025-01-18T07:16:26.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwKZ0zYFmM8', 1, '{"title":"肺痿肺痈咳嗽上气病脉证治第七.","description":"<p>1、问曰：热在上焦者 ， 因咳为肺痿 ，肺痿之病 ，从何得之？</p>\n<p> </p>\n<p>     师曰 ：或从汗出，或从呕吐 ，或从消渴，小便利数 ，或从便 难 ，又被快药下利 ，重亡津液 ，故得之。</p><p>2、问曰： 寸口脉数 ，其人咳， 口中反有浊唾涎沫者何？</p>\n<p>      师曰：为肺痿之病。若口中辟辟燥咳 ，即胸中隐隐痛，脉反滑数，此为肺痈 ，咳唾脓血。脉数虚者为肺痿 ，数实者为肺痈。</p>\n<p></p><p>3、问曰：病咳逆，脉之，何以知其为肺痈？ 当有脓血吐之则死， 其脉何类？</p>\n<p></p>\n<p>    师曰：寸口脉浮而数，浮则为风 ，数则为热；浮则汗出 ，数则恶寒，风中于卫，呼气不入；热过于营，吸而不出。 风伤皮毛，热伤血脉。风舍于肺，其人则咳 ， 口干喘满 ；咽燥不渴多吐浊沫 ，时时振寒。热之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。</p><p>4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚。</p><p>5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈。</p><p>6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数。  所以然者，以上虚不能制下故也。此为肺中冷，必眩多涎唾，$f{甘草干姜汤}以温之 ；若服汤已渴者 ，属消渴。</p><p>7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之。 </p><p>8、咳逆上气 ，时时吐浊 ，但坐不得眠 ，$f{皂荚丸}主之。 </p><p>9、咳而脉浮者，$f{厚朴麻黄汤}主之。咳而脉沉者，$f{泽漆汤}主 之。</p><p>10、火逆上气 ，咽喉不利 ，止逆下气者 ，$f{麦门冬汤}主之。 </p><p>11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之。 </p><p>12、咳而胸满 ，振寒，脉数咽干 ，不渴 ，时出浊唾腥臭 ，久久吐脓如米粥者 ，为肺痈，，$f{桔梗汤}主之。</p><p>13、咳而上气 ，此为肺胀 ，其人喘 ， 目如脱状 ，脉浮大者， $f{越婢加半夏汤}主之。肺胀，咳而上 气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。</p><p>14、方剂补充《千金》$f{甘草汤} 方  治喉痛</p><p>15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050090,"no":9}}', '2025-01-18T07:17:00.000Z', '2025-01-18T07:17:00.000Z', '2025-01-18T07:17:00.000Z', '1、问曰：热在上焦者 ， 因咳为肺痿 ，肺痿之病 ，从何得之？ 师曰 ：或从汗出，或从呕吐 ，或从消渴，小便利数 ，或从便 难 ，又被快药下利 ，重亡津液 ，故得之。 2、问曰： 寸口脉数 ，其人咳， 口中反有浊唾涎沫者何？ 师曰：为肺痿之病。若口中辟辟燥咳 ，即胸中隐隐痛，脉反滑数，此为肺痈 ，咳唾脓血。脉数虚者为肺痿 ，数实者为肺痈。 3、问曰：病咳逆，脉之，何以知其为肺痈？ 当有脓血吐之则死， 其脉何类？ 师曰：寸口脉浮而数，浮则为风 ，数则为热；浮则汗出 ，数则恶寒，风中于卫，呼气不入；热过于营，吸而不出。 风伤皮毛，热伤血脉。风舍于肺，其人则咳 ， 口干喘满 ；咽燥不渴多吐浊沫 ，时时振寒。热之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。 4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚。 5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈。 6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数。 所以然者，以上虚不能制下故也。此为肺中冷，必眩多涎唾，$f{甘草干姜汤}以温之 ；若服汤已渴者 ，属消渴。 7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之。 8、咳逆上气 ，时时吐浊 ，但坐不得眠 ，$f{皂荚丸}主之。 9、咳而脉浮者，$f{厚朴麻黄汤}主之。咳而脉沉者，$f{泽漆汤}主 之。 10、火逆上气 ，咽喉不利 ，止逆下气者 ，$f{麦门冬汤}主之。 11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之。 12、咳而胸满 ，振寒，脉数咽干 ，不渴 ，时出浊唾腥臭 ，久久吐脓如米粥者 ，为肺痈，，$f{桔梗汤}主之。 13、咳而上气 ，此为肺胀 ，其人喘 ， 目如脱状 ，脉浮大者， $f{越婢加半夏汤}主之。肺胀，咳而上 气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。 14、方剂补充《千金》$f{甘草汤} 方 治喉痛 15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫。', '2025-01-18T07:17:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
