INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NNs6l5Xxa78', 1, '{"title":"阴阳易差后劳复第二十三","description":"","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","section":9050250,"no":25}}', '2025-01-18T07:23:11.000Z', '2025-01-18T07:23:11.000Z', '2025-01-18T07:23:11.000Z', '', '2025-01-18T07:23:11.000Z', 1, NULL, 'Kcb7X2K5LTh', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OQv6QA2ddsl', 4, '{"title":"1","description":"<p>        金匮是延续伤寒论而来的，属于杂病范畴之内，每个章节讨论不同的病，但是其辨证的基础还是以伤寒论为主，本次伤寒与金匮的解说与书籍的撰写，我采用许多过去历代的经方大师如江阴曹颖甫撰写的《伤寒发微》与《金匮发微》，四川唐容川撰写的《中西汇通医书五种》，陆九芝、傅青主、戴天章著，秦伯未、林直清校定《世补齐医书全集》，江忍庵增批，林直清勘的《徐灵胎医书全集》等等，经方也因为这些历代名家的研究与发扬，才能流传至今，这些名家也因此而流芳百世。 </p>\n<p></p>\n<p>        每当想起唐朝名医孙思邈时，我就会发出会心的一笑，因为他是先写出《千金要方》一书，当时他以为这将是经典之作，数年之后他看到了汉朝张仲景所写的《伤寒杂病论》，大为惊讶于经方，于是将《千金要方》做了许多修正，也就是后来的《千金翼方》，足证历代名医都将经方视为唯一的最高指导原则，也就是说不知道使用经方的中医，是不配被称为中医的，更不配被称为名家或是国手，所以要发扬中医学，就必须发扬经方，唯经方才是真正能够代表我国的正统医学。 </p>\n<p></p>\n<p>       经方的辨症论治法，不但极其科学，治疗效果迅速，好处比西方医学不知超过多少，比方说西方医学制造出许多吓人的病名，许多病人一听到自己得到某种病后，当时就已然吓傻了，心慌焦虑随之而来，完全失去斗志，任由西医药与病魔的宰割，使得绝大多数的病人是因为西医药的过度治疗与心理的惊吓而死亡的，并不是因为病而死的。</p>\n<p></p>\n<p>        反观中医学的辨症法，中医学不立病名，是因为立病名，会让疾病的定义变为更狭隘，符合于老子所谓的名可名非常名，中医学讲究同症同治，就是不受到病名的限制，立下病名对于病情非但是于事无补，有时病名立得过多，连西医自己都搅乱掉了，而西医认为不立病名是无法说服众人的，于是各种奇怪的病名充斥，试问西医师，那种病是被你们治好的呢，答案是没有一个病被他们真正的治好。而经方依据的辨症法则，只要医师使用得当，就可以很迅速的让病人恢复过来，无论医师是面对何种西医所谓的病，只要症状一样就可以使用同方来治疗，当病人只知道自己的症状，不知道自己的病名时，病人必然无惧于任何症状，在一开始与疾病作战时，病人的这种心理就已经胜利了，加上由训练精良的医师来施治，怎会治不好呢？ 现在临床上遇到最大的问题，就是病人被西医制造的病名先吓住后，中医再动手治疗，也就是说中医尚未开始治病时，就已经先输一着，治疗上就倍增困难，中药什么药都有，就是没有大胆丸，心理上的恐惧却往往是病人的致命伤所在，时常是无知胜于有知，这里的有知，指的是半个有知，如果是全有知，当然最好，但是病人怎么可能都是全知呢？ </p>\n<p></p>\n<p>        这次的人纪教学，将在金匮讲授完毕后全部结束，而我的临床经验医案传承，将利用地纪来撰写，所有地纪中提出应用的处方都来自经方，所以我暂时不再另外写一本专门介绍我实际临床案例的书籍，可能以后有变化也不一定，但是目前尚无此打算，就请大家拭目以待地纪著作的完成。 </p>\n<p></p>\n<p>                漢唐中醫 漢唐中醫 倪海厦 倪海厦</p>\n<p>                谨记于 05/20/2007 佛罗里达州自家书房</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905001001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T02:15:16.000Z', '2025-02-26T02:15:16.000Z', '2025-02-26T02:15:16.000Z', '金匮是延续伤寒论而来的，属于杂病范畴之内，每个章节讨论不同的病，但是其辨证的基础还是以伤寒论为主，本次伤寒与金匮的解说与书籍的撰写，我采用许多过去历代的经方大师如江阴曹颖甫撰写的《伤寒发微》与《金匮发微》，四川唐容川撰写的《中西汇通医书五种》，陆九芝、傅青主、戴天章著，秦伯未、林直清校定《世补齐医书全集》，江忍庵增批，林直清勘的《徐灵胎医书全集》等等，经方也因为这些历代名家的研究与发扬，才能流传至今，这些名家也因此而流芳百世。 每当想起唐朝名医孙思邈时，我就会发出会心的一笑，因为他是先写出《千金要方》一书，当时他以为这将是经典之作，数年之后他看到了汉朝张仲景所写的《伤寒杂病论》，大为惊讶于经方，于是将《千金要方》做了许多修正，也就是后来的《千金翼方》，足证历代名医都将经方视为唯一的最高指导原则，也就是说不知道使用经方的中医，是不配被称为中医的，更不配被称为名家或是国手，所以要发扬中医学，就必须发扬经方，唯经方才是真正能够代表我国的正统医学。 经方的辨症论治法，不但极其科学，治疗效果迅速，好处比西方医学不知超过多少，比方说西方医学制造出许多吓人的病名，许多病人一听到自己得到某种病后，当时就已然吓傻了，心慌焦虑随之而来，完全失去斗志，任由西医药与病魔的宰割，使得绝大多数的病人是因为西医药的过度治疗与心理的惊吓而死亡的，并不是因为病而死的。 反观中医学的辨症法，中医学不立病名，是因为立病名，会让疾病的定义变为更狭隘，符合于老子所谓的名可名非常名，中医学讲究同症同治，就是不受到病名的限制，立下病名对于病情非但是于事无补，有时病名立得过多，连西医自己都搅乱掉了，而西医认为不立病名是无法说服众人的，于是各种奇怪的病名充斥，试问西医师，那种病是被你们治好的呢，答案是没有一个病被他们真正的治好。而经方依据的辨症法则，只要医师使用得当，就可以很迅速的让病人恢复过来，无论医师是面对何种西医所谓的病，只要症状一样就可以使用同方来治疗，当病人只知道自己的症状，不知道自己的病名时，病人必然无惧于任何症状，在一开始与疾病作战时，病人的这种心理就已经胜利了，加上由训练精良的医师来施治，怎会治不好呢？ 现在临床上遇到最大的问题，就是病人被西医制造的病名先吓住后，中医再动手治疗，也就是说中医尚未开始治病时，就已经先输一着，治疗上就倍增困难，中药什么药都有，就是没有大胆丸，心理上的恐惧却往往是病人的致命伤所在，时常是无知胜于有知，这里的有知，指的是半个有知，如果是全有知，当然最好，但是病人怎么可能都是全知呢？ 这次的人纪教学，将在金匮讲授完毕后全部结束，而我的临床经验医案传承，将利用地纪来撰写，所有地纪中提出应用的处方都来自经方，所以我暂时不再另外写一本专门介绍我实际临床案例的书籍，可能以后有变化也不一定，但是目前尚无此打算，就请大家拭目以待地纪著作的完成。 漢唐中醫 漢唐中醫 倪海厦 倪海厦 谨记于 05/20/2007 佛罗里达州自家书房', '2025-02-26T02:15:16.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '1BBSC8eTJZl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6kPHijBhuHb', 4, '{"title":"1","description":"<p>1、问曰：病有霍乱者何？</p>\n<p></p>\n<p>     答曰：呕吐而利 是名霍乱。  </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002001,"note":"        霍乱之名始见于《汉书·严助传》，其言夏月暑时呕泄霍乱之病相随属者是也。\n\n       此病南方为患，北方罕见，盖因地气之湿，遇天之阳气外张，互相蒸之，逼人汗泄太过，导致血热而燥渴，于是在饱食之后又食冷物，于是湿热不得外出，宿食不化，浊气上升故吐，清气下降故泄，肠胃不适，因而吐泄不止，由此可知霍乱之名，就是指吐泄不止之证也。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '1、问曰：病有霍乱者何？ 答曰：呕吐而利 是名霍乱。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qeCru5j2PmB', 4, '{"title":"2","description":"<p>2、问曰：病发热，头痛，，恶寒，吐利者，此属何病</p>\n<p></p>\n<p>     答曰：此名霍乱霍乱自吐下，又利止复更发热也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002002,"note":"       这段的目的是要后学者能区分出太阳伤寒与霍乱是不同的，如果出现$m{表里并病}时，应$m{先治里症}，然后$n{再解表症}。像发热、头痛、身疼、恶寒这些是太阳伤寒无疑，而现在兼有呕吐与下利，这是$m{表里皆病}的现象，这也可以称之为『霍乱』。\n\n        遇到这种情形时，要先治霍乱之吐下症，等到吐利好了，如果出现发热等太阳证时，再去治表。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2、问曰：病发热，头痛，，恶寒，吐利者，此属何病 答曰：此名霍乱霍乱自吐下，又利止复更发热也。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('15wGASDaeTC', 4, '{"title":"3","description":"<p>3、伤寒，其脉微涩者，本是霍乱，今是伤寒，，却四五日至阴经，阳转入阴，必利，本呕下利者，不可治也。欲似大便而反失气，仍不利者，此属阳明也，便必鞭，十三日愈。所以然者， 经尽故也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002003,"note":"       伤寒之症如脉微涩者，这是$f{四逆汤}证，病家是因为心阳不振，导致寒水不能气化造成血寒于体内，病原是来自霍乱，而今有伤寒之症，因此用麻黄汤之类无法治好，失治后三周左右，病由阳入太阴，就会下利，此时还有上热未去，无法给予热药，故不可施治。\n\n       等到阳热自回后，大便转燥而利止，即排出矢气，这时就是阳明证，其便必硬，二周内会好，这是因为阳明经尽止于二周。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '3、伤寒，其脉微涩者，本是霍乱，今是伤寒，，却四五日至阴经，阳转入阴，必利，本呕下利者，不可治也。欲似大便而反失气，仍不利者，此属阳明也，便必鞭，十三日愈。所以然者， 经尽故也。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dVIGvq614xN', 4, '{"title":"4、下利后，当便鞭，鞭则能食者愈","description":"<p>4、下利后，当便鞭，鞭则能食者愈。今反不能食，到后经中颇能食，复过一经能食，过之一日当愈。不愈者，不属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002004,"note":"      下利之症如转热后，大便必硬。如果大便硬而胃口好，这是回到阳明证，表示自己会痊愈的，不需要治。\n\n     但是如果病人没有胃口，就要等十三日，之后病人能开始吃食物以后就会好了。如果没好，就表示病不在少阳与阳明，可能已经入里了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '4、下利后，当便鞭，鞭则能食者愈。今反不能食，到后经中颇能食，复过一经能食，过之一日当愈。不愈者，不属阳明也。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nhF7uXiFxos', 4, '{"title":"5","description":"<p>5、利止，恶寒脉微，而复利，亡血也，$f{四逆加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002005,"note":"      如果下利停止，病人又出现恶寒脉微小无力，之后又开始下利时，就表示病人血寒了，此时救逆的处方就是四逆加人参汤了。\n\n      四逆汤是温阳救逆第一方，功能起死回生，多使用于心脏衰竭之危症时。此处之失血，并不是真的贫血，而是血寒，所以不用当归、川芎、白芍之类的补血药物。","videoMemo":"","fangList":["四逆加人参汤"],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '5、利止，恶寒脉微，而复利，亡血也，$f{四逆加人参汤}主之。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KRPMzIZQ1m5', 4, '{"title":"6","description":"<p>6、霍乱头痛，发热，身疼痛，热多欲饮水者，$f{五苓散}主之，寒多不用水者，$f{理中丸}主之 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002006,"note":"      病人霍乱吐利不止时，出现头痛、发热、身体疼痛、病家多热又欲饮水者，给予五苓散。如果是寒多而不饮水者，表示里寒湿重，此时给予理中丸服。 \n\n     伤寒治则是当有表症时，必先解表，而今有伤寒症但兼具吐利时，就不可解表。五苓散之功在能将表之寒水引回体内，再自小便排出，使得新水能取代旧水，故能止渴。理中丸能去里寒湿同时补足肠胃的津液，是治疗肠胃寒湿之主要处方。","videoMemo":"","fangList":["五苓散","理中丸"],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '6、霍乱头痛，发热，身疼痛，热多欲饮水者，$f{五苓散}主之，寒多不用水者，$f{理中丸}主之', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eGWYFmUFyDQ', 4, '{"title":"7","description":"<p>7、吐利止而身痛不休者当消息和解其外，宜$f{桂枝汤}小和之。  </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002007,"note":"      这里是说里症之吐利好了以后，如果病家还有身痛等表症时，我们就该帮他解表，解表用桂枝汤就可以了。","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '7、吐利止而身痛不休者当消息和解其外，宜$f{桂枝汤}小和之。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('73UOgtYx30Q', 4, '{"title":"8","description":"<p>8、吐利汗出 发热恶寒， 四肢拘急， 手足厥冷者，$f{四逆汤}主之。既吐且利，小便复利，而大汗出，下利清谷，内寒外热，，脉微欲绝者$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002008,"note":"       里阳不守而上浮，就会呕吐而且汗出。阴寒内结，就会下利而恶寒。这是水气盛血衰之症，于是造成四肢拘急而且冰冷的现象，这是$f{四逆汤}证。\n\n     病家又吐又下利，照理说应该津液已经失去，然而小便还有，又出大汗，甚至于还下利出未消化的食物，这是里真寒、外假热的症状，其脉微小欲绝之象，此为脉症相合，易治之症，是标准的$f{四逆汤}证。","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '8、吐利汗出 发热恶寒， 四肢拘急， 手足厥冷者，$f{四逆汤}主之。既吐且利，小便复利，而大汗出，下利清谷，内寒外热，，脉微欲绝者$f{四逆汤}主之。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F3EM5N7q621', 4, '{"title":"9","description":"<p>9、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002009,"note":"        遇到吐到已经无可吐，下利到已经无可利的阶段时，病人必虚汗出不止，因为里阴已极虚，无法固阳，因而仅存之阳外出，故可见汗出，此时四肢已经无阴可以滋润，又无阳可以伸屈，所以四肢会拘急不解，脉当是微细欲绝，这是通脉四逆汤加猪胆汁汤证。","videoMemo":"","fangList":["通脉四逆加猪胆汁汤"],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '9、吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，$f{通脉四逆加猪胆汁汤}主之。', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CDp4UKLQfEw', 4, '{"title":"10、利发汗小烦者，以新虚不胜谷气故也","description":"<p>10、利发汗小烦者，以新虚不胜谷气故也 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905002010,"note":"       这是说按照前面所说的用$f{四逆汤}后吐利停了，再服用$f{桂枝汤}发汗后，病人的脉已正常了，本来应该就好了，但是出现吃饭后肠胃好像\n不消化的现象时，这是因为病体刚才恢复过来，肠胃之气尚虚故也，稍事休息一阵，就会自己好的，这是不需要处方治疗的。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '2025-02-26T06:38:31.000Z', '10、利发汗小烦者，以新虚不胜谷气故也', '2025-02-26T06:38:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'eWgAGNdK3M8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L9lAtF4LR6Z', 4, '{"title":"1","description":"<p>1、问曰： 上工治未病， 何也  </p>\n<p></p>\n<p>     师曰： 夫治未病者， 见肝之病， 知肝传脾， 当先实脾，四季脾王不受邪，即勿补之。</p>\n<p></p>\n<p>    中工不晓相传，见肝之病，不解实脾惟治肝也。</p>\n<p></p>\n<p>    夫肝之病，补用酸，助用焦苦， 益用甘味之药调之。肝虚则用此法，实则不任用之。  </p>\n<p></p>\n<p>    经曰： 无实实， 无虚虚， 补不足， 损有余。 是其义也。余藏准此  。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003001,"note":"        从这段可知治肝有三个重点，补用$n{酸}，助用$n{焦苦}，益用$n{甘味}。所以治疗肝病经方中就有三个方子。补它的时候用酸，如乌梅丸。助的时候用焦苦，像吴茱萸汤。吴茱萸性燥，是很焦苦的药，它能够止呕。如果是『甘味之药调之』像小建中汤之类。这是治疗肝虚的时候用的三个法则，肝实的时候就不能用。\n\n        肝实在伤寒论介绍厥阴篇的时候，病人出现下利，有时呕吐就是肝实热发炎，就是肝肿起来，肝实热里面发炎的东西『热』往外走，进入大肠，拉出来都便浓血，又臭，伤寒里面就出方了，它叫『白头翁汤证』，白头翁可以止痢，可以止腹痛。白头翁加黄柏、秦皮，还有黄连，都是寒凉的药，后面陆续会跟大家介绍。\n\n      实热症的话用凉药，虚症用刚刚讲的三个方剂。所以我们治疗肝病，不管他是西医讲的名词肝硬化或肝癌，基本上我们处方的时候就在这几种方子里，这是张仲景以肝来举例子。『无实实，无虚虚，补不足，损有余。是其义也。余藏准此。』依此类推。\n\n     诸位要了解所谓：上工治未病，这个就是张仲景的原意。比如说肝出现问题时，我们应该先去实脾，这是最基本的法则。就是我们不让肝病继续传入脾脏，也就是把病局限在肝里面，不让它再传经，这是张仲景一个来自内经的观念，就是上工治未病，我们中医的最高阶段就是上工治未病，而西医是治已病。就好像一对夫妻要准备离婚了，到律师事务所去签字时，此时就是叫做『病已沉』。其实在离婚之前就已经有很多症状，显示如果继续恶化下去必将面临离婚，有症状的时候律师（西医）不会出面，中医会出面。「有症状了！」所以我们就开始动手。所以中医是辨症论治，这叫做上工治未病，如果要等到生病后才开始治疗就太慢了！内经的经义比西医学更广，西医学只限于局部在脏腑里面。\n\n      但是像『小建中汤为治肝补脾不二法门』这不是法则，误用之则大误病情矣。小建中汤只是用它的甘味来调脾胃，并不是用小建中汤来治肝病，因为『盖肝知本味酸，而中含有胆液则苦『胃实为生血之原』我介绍伤寒论时有提到，血的来源是脾胃。当我们肠胃吸收了食物以后『肝胆之液，渗入胃』，胃里面有三样东西：肝的酸、胆的苦、还有脾脏的甜与胰脏的黏液。如果太冷了，我们肝受到寒后，就会吐酸，所以呕酸的时候我们用燥来止呕。病人会呕酸就是肝液外出，我们用吴茱萸汤来治疗。如果肝热则吐胆汁，热则吐苦味。「老师，为什么我早上起来嘴巴苦苦的？」这就是胆汁上逆，是小柴胡汤证，诸位现在很熟稔了。\n\n      如果苦味很严重时，小柴胡汤里面黄芩就要重用、半夏也要重用、半夏能够降逆止呕，就是说胆汁往上逆时，我们需要用半夏把它往下降下去，所以小柴胡汤能和胃气。\n\n    『湿胜则肝胆不调』中医最难让人家去了解的，就是『气』，实际上什么叫气？西医看不到气，只看到一个循环系统，不管是我们的淋巴腺循环系统或者是血液循环系统，西医看不到是气在推动这个循环系统，它的原动力就是中医讲的气。\n\n      肝胆的气不够好，就是肝胆的原动力量不够了。肝本身是我们身上最大解毒的脏，西医医学里面也是这样讲，我们吃进很多东西，如果肝功能不是很正常时，代谢系统就不会很好，结果解毒的功能就不能完全发挥出来。\n\n      中医的观念，这种状况就叫做『郁』，气郁在肝里面，肝没有办法蠕动。正常时我们身体会把全身的血液，与身上残余的毒素，通通带回肝里面，然后经过肝脏解毒过以后再释放出来，进入我们的心脏。肝气郁久了以后，会造成食物残毒停留在这里，囤积久了就会生出湿。生湿出来后病人就容易有恶心。其实胃本身没有问题，而是肝藏湿气郁结积聚于此，压迫到胃，所以会恶心，自然就吐了很多湿液出来。有的时候早上起来刷牙时，会有恶心，就是因为里湿太盛造成的。\n\n       所以一般病人只要有呕，大部分都是有湿在里面。诸位看『湿胜则肝胆不调，故多呕。』湿囤积在身体里面太久以后，我们身体的环境就改变了，非常容易生虫，不要说是我们吃进\n去食物里面有菜虫，不用吃到菜虫，只要猪肉丢在那边，也会生虫的，只因为湿太盛了。所以如果我们肠胃消化不好时，食物在我们身体里面就会停留过久，坏掉的食物也会生虫的。补肝用酸，助用焦苦，此时可用乌梅丸。\n\n      中医有苦的药，像黄连、黄芩等，而苦的药都是寒凉的药，主泄、主向下走。只有乌梅丸，张仲景出了这个处方，他用的方法不是苦寒，而是利用苦温。因为温能化湿，只有温才能把湿化掉，所以乌梅丸里面有『以乌梅之酸，细辛、干姜、蜀椒、桂枝、附子之温，及黄连、黄柏之苦燥，而后胃温湿化，肝胆之郁，方得条达。』\n\n      胃受到温药以后湿被排掉了，这个时候湿被排出来，于是整个虫的生态环境就被改变掉了，虫才会出来，于是肝郁能够条达。中医的观念里面肝脏是木，树木要能开花，花要开的很好，才能够结果实，基本上它要能得到很多很新鲜的空气，它的生态环境要很好才行。乌梅丸就是能够让你身体里面那棵树长得很好，那棵树的名字叫肝，肝就是木。\n\n     中医的湿分为两种情形，一种是有蛔虫病，身体里面生有蛔虫，严重的时候就呕吐，因为里湿太盛于是吐出来很多虫，还有大虫、小虫之分，还有虫卵。还有一种就是久痢，无时无刻不在下利，很久都治不好，大部分这种下利是当我们到了有瘴疠的地方，比如说到了中国云贵高原这一带，或者是西南边陲一带，我碰过一个案例，一个美国人，他是作防卫系统的，美国在巴西有个基地，他就到南美洲去，在那个基地待了两年，他是设计外围警卫系统的工程师，那两年是什么都没得到，但是一回来就得到下利，我用所有能治下利的处方都治不好，这时就要靠乌梅丸。\n\n      台湾的乌梅丸不纯，因为乌梅必须要先蒸过，先把乌梅泡在醋里面泡一个晚上，让醋渗透进去，酸才能入肝，然后再用米饭来蒸它，蒸完以后再把乌梅里的核拿出来才能入药，小孩子平常没事时就可以吃乌梅丸，一般小孩子吃十五粒，大人大概吃二十五粒，有一种状况不能吃，就是下利便浓血时不要吃，其他通通可以吃，对肝病的人来说，乌梅丸可以专门用来补肝的。\n \n       张仲景已经告诉大家该怎么做，只是外面的乌梅丸不纯，所以我们只有靠自己来做，我们自己做的乌梅丸，你放在嘴巴里时是又酸又苦，因为黄连用了四两在里边，很苦，可是苦能驱虫，解毒驱虫的力量很强，里面的蜀椒就是杀虫的，这个是治肝胆湿热很好用的处方。\n\n        第二个就是吴茱萸汤，大家看『胃中虚寒，干呕，吐涎沫。』吐涎沫出来时，我们开吴茱萸汤，吴茱萸汤方就是吴茱萸加生姜还有人参、甘草。吴茱萸汤也是专门治疗胃下垂时用的处方。胃下垂在中医的观念里面，下垂就是功能不好了，中医叫做胃寒，为什么会寒？因为肝脏功能不好才引起胃寒，由于肝把胃压迫到，胃就没办法动，结果就是胃下垂了，很多长年喝酒的人，就会造成肝脏的负担，进一步就造成胃下垂，此时吴茱萸汤很好用。实际上吴茱萸就是入肝经的药。\n\n     此处不是用酸来补肝，这是寒湿初起之时，所以肝脏未虚，肝脏有虚的时候就要靠乌梅丸，肝脏虚掉的人体内较易生虫，而且会有长久的下利。如果肝没有虚，就只需要助胃阳而止呕，这时就用吴茱萸汤。吴茱萸的性很热很燥，如果要用甘味来调肝，就是专指建中汤而言，以上的三个方法，就是乌梅丸证，小建中汤证，还有吴茱萸汤证，这些都是治肝于未病时用的。\n\n      肝实热的话会有下利后重，所谓下利后重，就是上完厕所之后还是想再上一次，肛门感觉很灼热，大便出来很腥臭，有下利未尽的感觉，就是所谓白头翁汤证，这就跟我们这里说的又不一样了。\n\n    『若不问虚实而概用建中汤以治肝补脾不病胀懑即病烦躁。』所以我们要分出很多不同的状况，不仅仅是说肝病发出来后，我们赶快就用小建中汤去实脾，现在外面的中医就是这样做的，结果造成越吃腹水就越胀大，所以我们需要临症来决定如何使用，乌梅丸非常的好用，但是我讲的乌梅丸是真正的乌梅丸，外面的乌梅丸拿起来咬下去没有味道，我们自己制做的你不用咬，只要放在嘴巴里时你就会想赶快把它吞下去，待在嘴巴里会很难过。当你都感到难过，虫吃到就更难过，虫一碰到辛辣的东西就往下逃，逃后再碰到苦的把它泄下去，整个生态环境改掉了。 平常我们吃乌梅丸的时机会选在晚上睡觉前吃，吃了以后早上起来上厕所时就会很愉快。\n\n      只有一种状况就是遇到病人下利便浓血时不要吃，因为下利便浓血是里面太热了，乌梅丸里有一大堆蜀椒干姜细辛热性的药在里面，病人里热已经很盛了，如果再加热药入内，只会造成流血更多。除了这种明明就是白头翁汤证，你给他吃到乌梅丸才会有问题，其他都不会有问题的，就算没有虫也可以吃它，所以乌梅丸是很好用的丸剂。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T08:52:32.000Z', '2025-02-26T08:52:32.000Z', '2025-02-26T08:52:32.000Z', '1、问曰： 上工治未病， 何也 师曰： 夫治未病者， 见肝之病， 知肝传脾， 当先实脾，四季脾王不受邪，即勿补之。 中工不晓相传，见肝之病，不解实脾惟治肝也。 夫肝之病，补用酸，助用焦苦， 益用甘味之药调之。肝虚则用此法，实则不任用之。 经曰： 无实实， 无虚虚， 补不足， 损有余。 是其义也。余藏准此 。', '2025-02-26T08:52:32.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LDBM7kY65cu', 4, '{"title":"2","description":"<p>2、夫人禀五常 因风气而生长，风气虽能生万物，亦能害万物，如水能载舟，亦能覆舟。若五藏元真通畅，人即安和，客气邪风， 中人多死， 千般疢（chèn ） 难， 不越三条 。</p>\n<p></p>\n<p>    一者 皮肤所中，经络受邪入藏府，为外所因也；</p>\n<p></p>\n<p>   二者，四肢九窍，血脉相传，壅塞不通，为内所因也；</p>\n<p></p>\n<p>  三者，房室金刃虫兽所伤。 </p>\n<p></p>\n<p>    以此详之， 病由都尽。 若人能养慎 ，不令邪风干忤经络 适中经络，未流传府藏，即医治之，四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处。理者，是皮肤藏府之文理也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003002,"note":"      简单讲这整段的内容就是分三个，我帮诸位整理一下就很简单 了。中医的观念，你会生病，不外三种。\n\n      一种是虫蛇刀伤，当然现在还加上枪伤，这种是属于外科治症。\n\n   其他一个是内因，一个是外感。\n\n   内因就是喜怒忧思悲恐情志造成的病，像后面讲的百合汤证就是其中一种。\n\n  外感是因为风寒暑湿燥热而致病的，这些就是造成我们一个人生病的主要原因。\n\n      为什么我常常跟大家讲「要有平常心」。比方说，妈妈坐在那边烦恼儿子闹同性恋，如果你烦恼后的第二天他就不闹同性恋，这个烦恼我们就可以做。问题是你没有办法解决！所有人都在 那边哀声叹气的怨叹，实际上于事无补，而且不但是于事无补，反而造成自己身体障碍更多，然后让更多人都担心，这是恶性循环。\n\n      基本上一个人如果能够有个观念「我不贪」，你的病就已经去掉百分之八十了，譬如说做婆婆的你，媳妇才一进门你就贪了，什么叫贪？你希望媳妇帮你煮饭洗衣服烧菜。结果媳妇没做，你就很难过很生气，你就开始忧、就开始悲、就开始思、就开始怒，这就是后来很多病的来源。很多病源就是我常讲的「这是婆婆病，这是媳妇病」，其实都是因为生气才出来的。这是小人特有的病，小人的屎尿会比一般人多许多，诸如此类的我后面会慢慢跟各位介绍，\n\n     为什么有个人会像狗一样走到哪里都要上厕所，而且上厕所的时候一次分十几个地方，一个地方小一点，这也是有原因的。读中医学时如果能将我国的风鉴之术加进去，对一个人我们就可以看得很清楚。\n\n     至于外感风邪，我们为什么要去练功夫？为什么要练像八段锦、太极拳、易筋经？目的就是要外练筋骨皮，练的很勤快，就是要让风寒不能入侵身体，\n\n    为什么要练打坐？就是要练心，不要受到喜怒忧思悲恐，过喜、过忧、过悲、过恐都不好。\n\n    至于刀伤枪伤这没有办法，就是要靠自己小心主动去避免发生了。\n\n   伤寒金匮里面都是跟各位介绍内因外感，实际上所有的病因，不管你生什么病，都只来自这几种，张仲景的意思就是这样。我们在前面介绍针灸时，还有伤寒时没有跟诸位讲过，在介绍金匮时，我打算一堂课教诸位一个动作，这是文式易筋经。\n\n     第一个是按蹻式，可以帮我们把外感去掉，这个没有内因，做按蹻式时，心要保持平稳。按蹻式，蹻脉的蹻。以下所有的易筋经有一个基本动作都是一样的，就是下盘动作都是一样的，自肚脐以下叫下盘，早上起来到公园里面去，不要站在你家床上面，我们脚要直接站在地下面，吸到地气，打赤脚，五个脚指要像鸡爪一样抓在地上，抓的很紧，然后屁股肚脐以下整个肌肉绷的紧紧的，连屁股的肉都绷紧，肛门自然而然会提肛，上半身是放松的，松和紧刚好上身和下身是极端的，以下所有的动作下盘都是一样的。还有上面的动作、眼睛的动作、嘴巴的动作，诀窍就在这里。我如果不告诉你这个诀窍，你做到的只是形，你做不到神，做到形的时候做了半天冒了一身大汗，回到家后你还是你。如果你做到神的时候，做一个动作下来就有效，在呼吸的时候，你会感觉到你肺没有呼吸，是手掌在呼吸，气会很强，如果你做对后就会有这种感觉，如果你做完了在那边喘了半天，你等于是在跑步，这种叫做劳动，你并没有真正的做到运动，因为方法不对。  \n\n       易筋经平常我不太敢练，因为越练精神就越好，我的精神已经很好了，平时只要睡上五个小时就够了，再练下去就不用睡觉了，所以我不敢练，可是我们到五六十岁练的时候你体格就会很好。我今天头发到现在还黑的，这跟我练易筋经很有关系，而且不要花钱，真正的中国功夫是不需要利用外力来练，譬如说我们去举石锁，或者是举重之类，这是练习外家功夫的，这个外力练不好就会伤到你。刀伤外伤都没伤到你，结果你举这个东西然后伤到，是不划算的。\n\n      按蹻式第一个动作就是我们背要挺直，眼睛要瞪怒，眼睛睁开很大，千万不要两眼微张，平常你们听课时这样微张看我就好了，这样看才能用心听，不要用力看，耳朵用力就好了，心在用力，眼睛要瞪怒，舌头顶在上颚，牙齿咬的紧紧的，很凶的样子。不要管呼吸，自然呼吸感觉舒适就好，下盘要绷紧。按蹻式的动作就是这样子，心里好像在想，手按在桌子上要跳起来的感觉。脸部的动作做好，手这样按下去时全身同时绷紧，不必做很大的下按距离，短短的一寸距离就够了，要做到所谓的「寸劲」，就是只有一寸的距离来出力。寸劲就是劲力发出去的时候只需要有一寸的距离就够了，你看一般人打人手挥出去是没有力量的，因为在远处就用力了，结果真正打下去时就没有力量了。寸劲就是原本是松的，在刹那之间将力量聚集在一起打下去。所以平时上半身是松的，往下压时立刻绷紧就是按蹻，好像人要跳起来一样，同一个动作做四十九下，做这四十九下的中间，肚脐以下绷得紧紧的。做完以后全身再放松开来，下堂课我再教大家第二个动作。今晚开始练，练完晚上睡不着觉我不管的。因为这是九阳神功，阳气很旺，手臂很硬，肌肉会绷得很紧。这是文式易筋经，文式有十二个动作。\n\n      内因没有办法避免，只有常常听我讲课保持心情愉快就好了，功夫要自己去练。张仲景认为说，一般人会得到这几种病，如果我们能够『服食节其冷热，苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，三焦通会元真之处。』就是不要受到这些虫蛇的外伤，也不要受到情绪的影响，也没风寒暑湿燥热的影响，常常练功夫强身，偶尔得到风寒时，我们用针或按摩方式让病毒跑出去，或泡热水，这样子的话任何的病毒都没有办法进到你身体。这就是中医认为可以让一个人长年不病的方法，我们不能说长生不老，但是至少让你活到长命百岁，平安的寿终正寝。『三焦通会元真之处』所谓三焦，诸位都学过是体内连系各部位的油网。\n\n      『胸中三焦系统发出乳糜水液，出肌腠流成汗，故曰通会元真。』我们的胸腔里面，我们所有的汗水来源，都靠我们的胃阳，我们东西吃到胃里面去以后，会流出汗，就是因为胃里面很热，胃一热起来的时候，水一进入胃，就立刻进入我们的三焦系统，然后再从此系统发散到皮肤表面就是在流汗，这是正常汗水出来的管道。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T09:27:34.000Z', '2025-02-26T09:27:34.000Z', '2025-02-26T09:27:34.000Z', '2、夫人禀五常 因风气而生长，风气虽能生万物，亦能害万物，如水能载舟，亦能覆舟。若五藏元真通畅，人即安和，客气邪风， 中人多死， 千般疢（chèn ） 难， 不越三条 。 一者 皮肤所中，经络受邪入藏府，为外所因也； 二者，四肢九窍，血脉相传，壅塞不通，为内所因也； 三者，房室金刃虫兽所伤。 以此详之， 病由都尽。 若人能养慎 ，不令邪风干忤经络 适中经络，未流传府藏，即医治之，四肢才觉重滞，即导引吐纳，针灸膏摩，勿令九窍闭塞。更能无犯王法，禽兽灾伤，房室勿令竭乏，服食节其冷热苦酸辛甘，不遣形体有衰，病则无由入其腠理。腠者，是三焦通会元真之处。理者，是皮肤藏府之文理也。', '2025-02-26T09:27:34.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2pT32smegZt', 4, '{"title":"3","description":"<p>3、问曰：病人有气色见于面部，愿问其说 ？</p>\n<p></p>\n<p>  师曰：鼻头色青，腹中痛，苦冷者死；鼻头色微黑者，有水气； </p>\n<p></p>\n<p>  色黄者，胸上有寒 ； 色白者，亡血也 ；设微赤，非时者死。其目正圆者，痉，不治。</p>\n<p></p>\n<p> 又色青为痛，</p>\n<p></p>\n<p> 色黑为劳，</p>\n<p></p>\n<p> 色赤为风，</p>\n<p></p>\n<p> 色黄者，便难，</p>\n<p></p>\n<p> 色鲜明者，有留饮。  </p>\n<p></p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003003,"note":"       张仲景说到鼻头，我常建议当中医师需要学一点相术，所谓鼻头 就是要看印堂位，在相书上面写，印堂叫做疾厄宫，所以看到疾厄宫 有一个横纹，这个人一定有痛，身体里面常常痛，像头痛，胃痛之类， 所以疾厄宫最好不要有横纹。有的人有这个横纹，但是无痛时，就表 示他在四十一岁时命运一定不好，事业上遇到很大的阻力，遇到很多 灾难是非的事情，于是事业停滞不前。譬如说：上校应该升少将了， 结果没升上去，你看看他的鼻头，他就是这里有一个横纹。你可以问 问他当年没升上去的原因是什么？「哎唷，我那年生肝病，所以没升 上去。」刚好是四十一岁那一年出现横纹。\n\n      中医的四诊心法提到望闻 问切部分，包括医宗金鉴里面写的望诊写的都不够详细，诸位需要参考些相书才会比较完整。我给大家介绍像宫笃相法、神相铁关刀、冰 鉴、麻衣相术、柳庄相法等，这些好书是诸位可以做为参考的书，大 家也可以参考我着作的天纪，关于看疾厄的部分我写得很清楚。\n\n         仲师 说印堂这边是青色的，代表腹中痛。很多小孩子印堂青青的一块，就 是肠胃里面太冷，肠寒就是腹太寒了。常见到爸爸妈妈要喂小孩子吃 东西，喂了半天结果是「我不要吃。」跑掉了。爸妈说：『这小孩子真 不好养啊！』 一般爸爸妈妈看到的是形，我一看小孩子印堂是青的， 他当然不吃。这是中医所谓的寒，就是肠胃蠕动太慢。肠子里面静脉 的血回流回心脏的力量不够，于是造成肠子蠕动太慢，这时候我们要 用小建中汤。为什么小建中汤能够去他的肠寒？如果桂枝用三钱的 话，白芍就用六钱，白芍是桂枝的两倍，目的就是要让肠子蠕动，因 为白芍性酸能收敛所以能够止腹痛，让腹部静脉里瘀积的血流回到心 脏里面，然后再加点饴糖在里面，让汤药停在胃肠里面，如此就能够 把肠中的寒去掉。所以你一看这个人鼻头是青色的就代表有腹痛，肚 痛。有的爸妈不会观察，父母抱着小孩子时，你问他：『小孩子几岁 了？ 』『才十个月大。』『他会不会讲话？ 』『当然不会讲话！』『你知不 知道小孩子肚子痛？ 』『他从来没说过他肚子痛啊！』你看这个爸妈多 糊涂？小孩子当然不会告诉你肚子痛，还有的小孩子他会讲话，可是 他根本不想跟你讲，他想去玩，肚痛根本不会死人的，爸妈的脑海里 面是一直想要他吃东西，他脑海里面是一直想要玩，两个人是鸡同鸭 讲。你拿东西给他吃，当然不吃，然后你就说他皮，说他不好养，事 实上他是根本没有胃口。小建中汤喝下去以后胃口会大开，此时你不 需要去喂他，他自己就会跑到饭锅里面自己去抓饭吃，会有这种现象 的。\n\n      『苦冷者死』什么叫苦冷？如果这个印堂的部分整个冰掉了，甚 至于摸下去有点水水的感觉，这是相书上面的疾厄宫。鬓角这个地方 相书上叫做命宫，就像我们排八字有命宫是一样的，重病的时候整个 印堂的地方都青冷掉。\n\n       『鼻头色微黑者有水气』这个人如有水肿，印 堂这边就黑黑的，黑色主的是肾脏，表示肾脏功能已经很差了，像尿 毒病患，不要说是印堂，整个脸都会是黑的，尤其整个天庭的地方都 会是黑色的，而且黯黯的没有反光，这已经是尿毒了。尿毒病患如果给西医洗肾，不但更黑，还会出现黄色，后面会介绍到为什么洗肾不 好。\n\n       『色黄者，胸上有寒；色白者，亡血也』如果印堂这里整个是苍 白的，表示这个人失血，一般病人手术以后或者是出车祸大量失血， 这里都可以看到白色的，表示失血失很多，这是中医的望诊。如果颜 色太黄了，代表胸腔有寒，因为胸腔里有寒的时候，我们的脾脏的黄 色营养就没有办法上去完成土生金，胸腔里面本来就是诸阳的通路， 全身的阳气通通汇集到这里，因此胸腔里面会很热，当胸里面的热不 够时，就表示脾脏没有办法土生金，就是脾脏肿起来了，脾脏出问题 时，第一时间病人的印堂就会黄起来。「老师，如果没有在印堂黄， 在鼻头上黄？ 」这表示那个人会有横财，要发财了，如同股票赚钱或 是中乐透奖之类，此时你不要跟他说：「你胸上有寒。」不要看错，此 黄非彼黄。\n\n      『设微赤非时者，死。』如果看到鼻头有赤色，表示有心脏 病，如果是赤在两印中间偏右或偏左时，这个表示是痔疮发作，千万 不要跟他说你要发心脏病死啦，这只是痔疮，我讲的印堂就是在山根 位，就是鼻头的最上端。\n\n      如果你看到『鼻头微赤，非时者，死』什么 叫非时？青、赤、黄、白、黑依序是春、夏、长夏、秋、冬。你在冬 天应该看到比较暗一点，怎么看到红色的呢？这就叫做时节和病人的 气色正好反。如果冬天你看到眉毛下面红红的，这是红鸾星动，你却 在那边说：『是痔疮！』就不对了。所以我们一定要把时运，就是一个 人的命运跟我们望诊的疾病要分开来。心脏有问题的时候，除了印堂 有红赤以外，还有眼珠，眼珠子内侧近鼻根处这边，诸位可以看到有 一条线一定在左眼内侧。这个一条像眼翳一样生的很大，红红的在左 眼这个地方，这就告诉你，此病人已经有心肌梗塞了，或是心脏血管 堵塞住了，这时可以看到眼翳很重。这个翳不是白内障的翳，是心脏 动脉血管堵塞可以看到的表现。我诊所里面有一次来了一个病人，他 花了五千块美金去检查，西医终于查到说：「你有心脏动脉血管堵 塞。」。同学们上个月跟我去美国看到的案例，我们碰到两个，一个是 开刀开两次以后第二次就马上堵回来，一个是做了心导管还是堵回来 没有用，他花了五千美金去做检查，而他进来诊所，还没有讲第一句 话，我一看他眼睛就告诉他：「你是不是有动脉血管堵塞？ 」他说：「你怎么知道？ 」才不到两秒钟，中医的望诊就是让我们能够站在外 面而知道里面藏的是什么，\n\n      『其目正圆者，痉，不治。』 一个人眼睛瞪 得很大闭不起来，眼瞪圆而不动，这代表阳气浮在上面。就是阳已经 要离开身体了，表示人已经快死掉了。我前面介绍厥阴证时有提到， 一个人但坐不得卧，烦躁，眼睛瞪很大，你想想他的阳亢到了什么程 度？连眼睛想闭都闭不起来，全家人都在睡觉时，他一个坐在那边瞪 大眼，这表示已经快要死了。脑膜炎发高烧的时候，病人也会痉，当 筋抽起来时，眼睛都瞪得很大，你如果跟病人说：「不要难过，眼睛 闭起来吧。」他不会管你的，他眼睛就是瞪很大，不但瞪很大，而且 眼珠子还往上跑这是很危险的，表示病毒已经进入脑部了。诸位，到 这种阶段我们经方都可以治，用针灸、用经方，治疗起来都不会很难 的，而经方用的急救药物反而更便宜。\n\n      『又色青为痛』你看到病人的脸色发青，他说：『我肚子痛得脸 色发青。』痛就是青色。\n\n     『色黑为劳』你看那个人脸上黑黑暗暗的，就 是『劳症』，这是中医的观念，色黑为劳症，我上次有讲过一些关于 劳症。还有相书上面讲，色黑是无欲，已经没有性欲了，无法行房事。\n\n     『气色赤为风』脸上红赤代表有风。\n\n    『色黄者便难，色鲜明者有留饮。』 色黄者便难诸位都知道，因为脾主运化，发黄表示脾脏有问题，大便  就跟着会有问题。这个便难不一定说是大便不通，下利也是属于大便  不正常。\n\n    『气色鲜明者，有留饮。』我们人身上有水饮梗在胸腔里面， 或者是梗在下焦，只要身体内某处有留饮时，一般脸色都是光光亮亮  的，你说：『人家脸色气色真好！』其实人家是有留饮，或是胸腔里面  有积水，所以我们要区分清楚。当脸上光光亮亮，但脸上整个光是散  的，平常我们正常的人，光色是从皮肤下面隐隐发出来的，如同珍珠  一般，所谓鲜明就是脸肿起来，脸颊是虚胖，代表身上有留饮。当身上有留饮的时候，此留饮到底是在胸腔里面？还是心脏有积水？还是  在脾脏？还是在组织上面？还是腹部有积水？ 中医都有一套辨症的  方式。在这里张仲景开始先给大家一个很简单的概念。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-26T09:35:23.000Z', '2025-02-26T09:35:23.000Z', '2025-02-26T09:35:23.000Z', '3、问曰：病人有气色见于面部，愿问其说 ？ 师曰：鼻头色青，腹中痛，苦冷者死；鼻头色微黑者，有水气； 色黄者，胸上有寒 ； 色白者，亡血也 ；设微赤，非时者死。其目正圆者，痉，不治。 又色青为痛， 色黑为劳， 色赤为风， 色黄者，便难， 色鲜明者，有留饮。', '2025-02-26T09:35:23.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Bu49kBLazyb', 4, '{"title":"4","description":"<p>4、师曰：病人语声寂寂然，喜惊呼者 ，骨节间病；语声喑喑然不彻者 ，心膈间病 ；语声啾啾然细而长者 ，头中痛。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003004,"note":"       中医会让人比较诟病的地方，就是什么叫做『寂寂然』、『喑喑然』、 『啾啾然』？ \n\n    『无病之人，语声如平时，虽高下疾徐不同，决无特异 之处。寒湿在骨节间，发为酸痛。』在这句话旁边大家就写上附子汤证。骨节间发为酸痛就是寒湿，体内寒引起的下利，我们要用甘草干姜汤。骨节痛的部分，因为是虚寒、寒湿在肌肉关节里面造成的痛， 我们就用$f{附子汤}。\n\n        寒湿在骨节中间，病人之所以不想讲话，是因 为当寒湿很盛的时候人会很虚弱，元气都没了，讲话声音就会很细， 病人也不能转动，一转动就会很痛，\n\n      『喜惊呼者』，因为病人不能动， 一动就痛，这种病就是没有练易筋经造成的，这就是属于骨节间的病。 我们只要一听到病人说：『啊！你不要动我』一动他就痛，就表示他 骨节间有病，这就叫寒湿在骨节中间，\n\n       如果『语声喑喑然，不彻心者， 你看他说：『心膈间为肺，湿痰阻于肺窍，故语声喑喑然不能澈。』寒 痰在嘴巴里面，讲话不能大声，一大声就要咳、喘不过气来，因为有 痰在，如果是热实，就是大小陷胸汤证，记不记得伤寒论中的大陷胸 汤与小陷胸汤，轻症时，像一般抽烟抽很多的咳喘，重症时，如抽鸦 片、以前抽大烟等，抽多了造成胸腔里面黄痰很多，这是皂荚丸证， 抽烟抽得多我们也可以用小陷胸汤。如果是热实结胸，这是因为病人 有太阳伤寒表症时，结果被人误下造成，整个痰堵在胸腔里面，此时 就是大陷胸汤证了。如果是寒实，我们就要用三物小白散。\n\n       『语声啾 啾然细而长者，头中痛。』头痛的人，他讲话声音不能大，一大声他就头痛欲裂，需要小声讲。你问他说：「先生你讲话大声一点好不好？ 」 「我不能大声啊，我一讲大声头就痛。」此时你先看看他的相，如果长的嘴巴尖尖的、唇不闭齿，舌头又尖尖的，此人善言人之是非，就不要帮他治。他本来就喜欢讲人家是非，为了不要让他再讲所以不帮他治疗，因为他一讲大声头就会痛，这个是老天爷给他的天惩。我就  不教你如何治他的头痛，你让他来找我治，你看我怎么修理这种喜爱  搬弄是非的人。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '4、师曰：病人语声寂寂然，喜惊呼者 ，骨节间病；语声喑喑然不彻者 ，心膈间病 ；语声啾啾然细而长者 ，头中痛。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PIsWjrB2K3W', 4, '{"title":"5","description":"<p>5、师曰 ：息摇肩者，心中坚 ；息引胸中上气者 ，咳 ；息张口短 气者 ，肺痿吐沫。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003005,"note":"      这就是我们中医的望诊法，看病人呼吸的动作来决定病在哪里。 金匮讲的症状比较多。如果一个人没办法呼吸，必须要摇肩才能感觉 到吸满一 口气，这叫做『悬饮』，就是肺里面有积水，就是十枣汤证， 后面还会再介绍到悬饮。你不要回家去煮十个枣子给他吃就完了，不知道的人还真的会去吃那十个枣子！\n\n     如果是『息引胸中上气者』，「啊！ 我不能深呼吸！」 一吸气就往上冲，就要咳嗽，这就表示胸腔里面有 痰，大部分我们看到如果胸腔有痰，又兼有表症时，像是表寒里寒时 就用小青龙汤，如果是表寒里热就是大青龙汤证，我们会依此来决定 怎么使用。如果咳嗽时只有『黄痰』，就是没有表症只有咳嗽的人， 我们会用到皂荚丸。皂荚丸是去胸腔里面烟油、烟痰最好的，吃下去 之后第二天大小便出来，大便出来都黑黑的，痰都从大便排出来。\n\n      『息张口短气者，肺痿唾沫。』什么叫张口短气？ 因为病人靠鼻子吸气都 不行了，表示病人的肺已经整个缩小了。肺本来很大，结果它缩小变 成两个像气不足般的汽球，中医叫肺痿，西医叫肺萎缩。当肺脏萎缩 变小后，由于空间容纳不足，病人很想深呼吸一 口，可是吸不进啊！ 因为肺缩小，症状就是一直吐涎沫，表示肺脏已经萎缩掉了。『息张口短气者，肺痿吐沫。』在我们后面会介绍到射干麻黄汤证，因为肺 必须要靠麻黄把它打开来，后面会再跟诸位介绍。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '5、师曰 ：息摇肩者，心中坚 ；息引胸中上气者 ，咳 ；息张口短 气者 ，肺痿吐沫。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I4005pRZRBY', 4, '{"title":"6","description":"<p>6、师曰：吸而微数，其病在中焦实也。当下之则愈。虚者不治。 在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸  动摇振振 ，不治。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003006,"note":"     如果是『吸而微数，其病在中焦实也。』如果是因为食物堵在肠 胃里面，这就叫『中焦实』。因为食物堵到了，造成病人呼吸很快， 气下不去是因为我们上焦本是受气，下焦是纳气，所以我们时常要练 习气纳丹田，气应该要纳到下焦里面。气因为能够直接到下焦，所以 我们正常人的下焦应该是热的，因为氧化的过程不单单在胸，还要一直往下走，有丹田在使得我们男人的精很热，小便很热，这都是因为下焦能够纳气。当你有食物堵在中焦，造成气下不去，遇到这种情形， 如果是中焦实，很简单，用承气汤把它攻出来就好了。\n\n     如果肠胃是$m{{虚者}，很难治，表示阻隔不在肠胃里面，可能长了别的东西，很严重。\n\n      如果是『在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸动摇振 振，不治。』像这种如果是上膈堵到，更接近于鼻子，于是就会呼吸 更急促，如果病在下焦，就是肾脏功能有问题，诸位会发现到病人一 直吸一直吸，因为下焦主纳气，下焦生病已经不能纳气了，所以病人 就一直在吸，吸完还是纳不了气，就会有这种奇怪的现象。所以我们知道，如果吸气吸的很长，就是这个人肾脏有问题，打坐的除外，打坐是吸气吐气都很长，因为打坐的心法就是在练呼吸之间不让耳朵听到声音。这种就比较难治，并不是不治，只是病比较深了。有实证时， 病都比较好治，只要把实去掉就好了，虚症就比较难治。\n\n    『呼吸动摇振振，不治。』这种就是很危险的症状，一般来说我们看到癌症末期 的时候都可以看到，『呼吸动摇振振，其人必大肉痿陷，大骨枯槁。 午后微热，死在旦夕。虽使扁鹊复生，无能为役矣。』诸位看癌症末 期，癌细胞把人身上的营养都收走，人都变成很瘦，大骨枯槁，脸都黑黑的，然后午后还微热。为什么午后微热？就是我们人的胃气只剩 下一点点，只有在午后热出来一下下，就是快要死了，病人只剩一点 元气了。一般来说遇到这种情形，就赶快把遗言交代一下。这是望诊。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '6、师曰：吸而微数，其病在中焦实也。当下之则愈。虚者不治。 在上焦者其吸促；在下焦者其吸远，此皆难治。呼吸 动摇振振 ，不治。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rudS8dCcU4o', 4, '{"title":"7","description":"<p>7、师曰：寸口脉动者，因其王时而动，四时各随其色，非其时， 色脉皆当病。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003007,"note":"      这里是说我们中医要求必须要脉色相符。一般正常人的脉象「春、 夏、长夏、秋、冬」，春季正常的脉是弦脉，夏天的脉是洪脉，长夏的脉是缓脉，秋天的脉是浮脉，冬天的脉是沉脉，这是四季正常时应 该有的脉象，从我们寸口部位的脉来决定。\n\n      所以寸口是代表胸腔，上焦阳气之位。你摸病人寸口脉时，当你的指头轻轻的触碰到皮肤的表 面时，一摸到皮肤就摸到脉，这就是浮脉。如果当时正好是秋天就是正常人的脉，如果你在秋天摸到洪脉我们春夏秋冬是相生的，木火土 金水。秋天脉应该是摸到浮脉，结果摸到洪脉，脉形壮大，脉来得很洪，就是秋季却摸到夏天的脉，这就叫做相克的脉，如果你是秋天摸 到缓脉或者沉脉，这是相生的脉。相生的脉出现表示很容易治疗，相克的脉就难治了。\n\n       还有除了脉象以外，我们还要注意病人的气色。春天应该看到青色，夏天应该看到红色，长夏的时候看到黄色，秋天看到白色，冬天看到黑色，这是正常的四季的颜色。在冬天的时候你看到病人的气色，比较黑一点是好的，但是如果摸他的脉却是洪脉，脉不符合季节，就叫做色脉不符。\n\n     张仲景就是这个意思，不需要全部讲完，大家可以依此类推，张仲景的观念讲究临症施治，所以没有办法开立一个处方，就能够应付所有色脉不合的现象。\n\n     当冬季时节到了， 有病人脸上出现异常红色时，就表示这个人有心脏病，不然就是刚吃完当归生姜羊肉汤，否则冬季是不该有脸色红的，\n\n     如果是夏天，看到 这个人脸黑黑的，表示这个人有肾脏病，因为夏天脸色应该比较红润， 怎么会看到黑色的呢？这就是气色和季节不符，夏天时你如果到洗肾 中心的门口一看，一票全部都是黑的，所以如果看到脸全部都是黑的， 就是尿毒了。如果有个人他是陪尿毒病人来洗肾的，而这个人的印堂 是黑色的，表示这个人将要出车祸死掉了。所以死有很多种方法，我们不用摸脉，一看就知道此人将死于意外的。\n\n     人死之前两个礼拜可以 看到气色，这就是为什么要讲望气。出事前绝对是可以一看就知道了， 我一再跟诸位讲过，人平常不管是白天或是晚上，刹那之间看到一个人脸上暗暗的，好像是整棵树瞬间枯掉。有时候是头发没有出油，整个头发都膨起来。这表示是没有病，是意外、横祸，或者是凶杀、横 死，出事前都可以看到这种气色。\n\n      当看到这种气色时，马上把黄历翻开来看一看，离今天最近的节或者是气是哪天。比如说现在来看的话十月五号是立冬，国历的十月十五是农历的九月二十八，十月五号是立冬，立冬当天开始算起第七天，到七天时异动之间就会发生事故， 因为色出现的时候不见得是当场出现，你当场就看到，可能是两个礼 拜中间的某一天被你看到，所以在下一个节或气时就会出事，这个部分中医学就没有办法帮他避灾了，但是可以用易经来起一课看看吉凶如何，这部分学者最好自己找方法来解决。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '7、师曰：寸口脉动者，因其王时而动，四时各随其色，非其时， 色脉皆当病。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bOyvVwEV6E4', 4, '{"title":"8","description":"<p>8、问曰：有未至而至，有至而不至，有至而不去，有至而太过， 何谓也？</p>\n<p></p>\n<p>      师曰： 冬至之后， 甲子夜半，少阳起，少阳之时， 阳始生， 天得温和，此为未至而至也； 以得甲子，而天未温和者，此为至而不至也； 以得甲子而天大寒不解，此为至而不去也 ；以得甲子而天温如盛夏五六月时，此为至而太过也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003008,"note":"    『师曰：冬至之后，甲子夜半，少阳起』这是正常的时节，我们 在二十四个节气里面，有十二个节、十二个气，加起来一共有二十四个节气。\n\n    从冬至那一天开始算，离冬至最近的甲子日，那天晚上的半夜子时就是大地阳气回头之起时。地气回温之初始时，是少阳生，这是正常的时节。 所以『阳始生，天得温和』。\n\n       如果在这个时候，刚刚在地下的阳一生出来，天气就开始转温了。实际上这时天气应该还寒 的，因为阳是生在地下，应该没有感觉，结果在冬至之后，第一个甲子日那天如果感觉到天气热起来，这就是不该热而热，叫做$n{未至而至}， 这是因为『以得甲子，天未温而和者』。\n\n      但是如果甲子日那一天，天气『为至而不至，反而更冷，这就是$n{该至而不至}。气以得甲子日而天大寒不解，此为至而不去』整个都冰封起来了，这是以甲子日那一天为主的计算法。\n\n    『而天温如盛夏五六月时，此为至而太过也。』如果甲子日那一天应该是要很冷的，结果变成大热，这叫做「冬行夏令」， 在我们人身上就会产生很多出乎意料的问题。节气如此改变时。就称 为气『太过』。\n\n      太过的节气会造成什么问题呢？举个例给大家听，金匮里就讲了，譬如说夏天的时侯我们该要流汗，冬天的时候没有汗， 因为汗由小便排掉。结果你在冬天的时候汗大量流失，而这大汗的原因呢，可能你是做苦力的，或者其它的原因造成你的身体丧失了很多汗。冬天应该是收藏，结果你在冬令的节气里面汗失了很多，到了来年春天的时候得到温病。我跟大家讲过了，温病就是当身体津液伤到时，同时间得到感冒于是就变成温病。所以一般小孩子，运动量很大， 一天到晚都在流汗，于是一得到感冒就是葛根汤证，还来不及使用桂 枝汤或是麻黄汤之类，一看就知道是葛根汤证。起因就是因为病人得 病当时是在身体津液丧失过多之下得到的病。\n\n     所以张仲景在这段里面 说「出方是临症来开立的」，我们看病人是太阳、阳明还是少阳，看病人是津液丧失得病的，或者是有表寒而病。张仲景的意思简单地说 就是节气的变化出现太过与不及时，人都容易得到病的。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '8、问曰：有未至而至，有至而不至，有至而不去，有至而太过， 何谓也？ 师曰： 冬至之后， 甲子夜半，少阳起，少阳之时， 阳始生， 天得温和，此为未至而至也； 以得甲子，而天未温和者，此为至而不至也； 以得甲子而天大寒不解，此为至而不去也 ；以得甲子而天温如盛夏五六月时，此为至而太过也。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LHfvbZ5srYM', 4, '{"title":"9","description":"<p>9、师曰：病人脉，浮者在前，其病在表；浮者在后，其病在里， 腰痛背强不能行 ，必短气而极也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003009,"note":"      这一条辨讲的是如何运用脉诊来做诊断依据。我们脉上面有寸、 关、尺。如果是寸脉-指的就是上焦，就是表。寸脉是浮，代表病在表。如果是尺脉浮起来的话，而尺是指下焦指的是里，我们就可以知 道病是在里，『腰痛背强不能行，必短气而极也。』像是腰痛无法走路， 呼吸短促等里病。\n\n      平常我们要检查病人的脉，查浮脉的时候一定是摸寸的脉，因为肺主皮毛。寸脉浮起来就是感冒了，就是麻黄汤证，桂枝汤证，或是葛根汤证。如果寸脉的浮脉透过关再透到尺部时，脉形一直向下透下来，就表示说病由上而往下，表示表热已经传入里了，太阳表热有时会传少阳，有时又会进入阳明。会进入里是因为失治造成，或是病人 本身一向肠胃就不是很好的缘故，如果进入中焦肝胆部位就会出现少阳证，有时会从太阳一直进入阳明成为里实热之证。\n\n      如果跑到膀胱里 面去，就会造成小便不利，如何知道病已经进入膀胱了？ 当病人出现 腰背强时，代表病毒是顺着皮肤表面上在走，当它顺着脊髓的足太阳 膀胱经一直下去跑到我们的肾脏里面，再进入膀胱泌尿系统时，就会 『短气而极』，此时小便就会淋痢刺痛不顺畅了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '9、师曰：病人脉，浮者在前，其病在表；浮者在后，其病在里， 腰痛背强不能行 ，必短气而极也。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wlfbcEpDSt9', 4, '{"title":"10","description":"<p>10、问曰：经云 ：厥阳独行 ，何谓也？</p>\n<p></p>\n<p>       师曰 ：此为有阳无阴 ，故称厥阳。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003010,"note":"    『厥阳独行』，这个怎么解释？什么叫做厥阳独行？这句话是来 自内经。\n\n     张仲景说『此为有阳无阴，故称厥阳。』就是纯阳没有阴的。 我们身体里面，阴阳是交合互相支援的，如果哪一天阴没有了，只剩 下纯阳就是很危险的症状。阴阳。一定要相辅相成的。诸位看曹颖甫 讲的『油灯将灭，火必大明。』他形容的非常好，他说『故昔人有甘 温清大热之法。内经所谓劳者温之也，然补血养阴正不可少。』像这 种情形，我们看到外表显现的是阳症，而事实上病人是因为体内的阴 严重不足才看到了纯阳症。\n\n      比如你看到病人是阳症，出现热、眼睛红 赤、病人口渴、脉数，你看到的症状都是阳症，实际上他之所以会那 么热是因为里面阴虚掉了，这个就叫做『厥阳独行』，我们北派中医 就要利用甘、温之法来治。病人吃了甘温的药反而真正能够清除此大 热，这就是用甘温清大热的正确时机。你如果说：「老师，此人是壮热，我们应该用苦寒的药才对。」此时如果开苦寒的药给病人，想去除病家的燥热，结果药吃下去后病人却死了，因为苦寒或寒凉的药会把阴降得更低。因此我们辨症的时候一定要看清楚，病人的热是真热 还是假热。\n\n     大家也可以用很简单的辨症法来做区分，可以要求病人「你 舌头伸出来我看看！」 一伸出来，干干燥燥，舌胎都翻起来了，此时 你就不用想说此人到底是真热假热？ 当然是真热，看舌头最清楚，如果你还在怀疑说：「我再检查看看，到底对不对？ 」会失去治病的时机。像我们练习打坐就是要阳气能够潜入阴中，使阴阳互动互生，这 就是为什么我们在打坐的时候，津液自舌头下方的地方一直冒出来， 这就表示阴阳是和谐的，表示你身体是正常的。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '10、问曰：经云 ：厥阳独行 ，何谓也？ 师曰 ：此为有阳无阴 ，故称厥阳。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J5rn4rvvKlC', 4, '{"title":"11","description":"<p>11、问曰：寸脉洪大而滑，，洪则为实、滑则为气 ，实气相抟 ，血气入藏即死 ，入府即愈 ，此为卒厥 ，何谓也？</p>\n<p></p>\n<p>      师曰：唇口青身冷，为入藏，即死；如身和汗自出，为入腑， 即愈。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003011,"note":"     『寸脉洪大而滑』，寸脉指的是上焦，就是上焦受病了。\n\n     『洪则为 实』实就是血实，血实的时候代表血液充满在血管里面，整个血管都膨胀起来，脉是又洪又实，实就是脉很重、很硬。\n\n    『滑则为气』如果 是滑脉，滑讲的是气实，就是气充饱了，像气球一样，鼓胀得很厉害。 如果气和血两个在血管里面流动的时候太强盛了，\n\n   『实气相抟，血气入藏即死』这就类似是高血压，脑溢血的现象。我们的气是在血管外 的网膜上面走，血在血管里面走。如果气和血通通是实的时候，血管 会绷起来，里面的血太过充满，一下子就破裂掉了。如果入脏，这个 脏指的就是「脑」，也就是入脑，就是脑溢血，就很危险了。\n\n     如果按 照张仲景的意思，这个时候反正是死症，就可以开脑，把瘀血拿出来， 说不定还可以救，这是他的观念。如果是入脑，就会死亡。如果是入腑，就是进入三焦，进入消化系统，就会好的。\n\n   『此为卒厥』，就是突然发生昏迷的现象，如何区分 呢？张仲景就说了：『唇口青身冷，为入藏』当我们看病人外表时， 如何知道病是入脏还是入腑？如果这个病人的嘴唇发青，又身冷就表 示入脏了。嘴唇为什么发青？是因为脑部缺氧，血里面已经没有氧气 了，此时血的颜色就会变黑，于是嘴唇的颜色就会发青，身体就冷掉 了，『入脏』是死症。如果是『气血相抟』，血往上冲，脉很实的时候， 此时病人就会『身和汗自出』自己流汗出来，表示热有地方宣泄。像 高血压的病人，热没有地方宣泄，就危险了。\n\n       我的逻辑是：假设降血 压的药有用，你可没有像孙运璇那么高的官，连前行政院长孙运璇都 中风了，你还不中风吗？我的意思是想告诉你，你绝对没有他一样每 天都有医护人员在旁边照顾，每天提醒他吃药控制血压，护士二十四 小时的照顾，还给他吃控制心脏的药，结果又如何？还是中风了。\n\n       中医的观念里面是血气相抟血太热，造成血热的原因是什么？ 中 医观念里面是「血里面的水不够了」。而西医所有降血压的药都跟利尿剂有关，你不相信你吃一颗看看，吃完后小便量很多，血压因此下降了，可是西药降到的是形，第二次再回来的时候血会更热。我讲「热」 就是膨胀得很快，胀得很快，越来越强。所以大家吃高血压药来降血  压时，心里想的是可以预防中风，结果后来还是昏厥，还是中风了。 诸位你要相信，你绝对不会有孙运璇大，孙运璇都这样于倒下去了， 你该记取教训，不要再走同一条路，要换条路走。\n\n       我们在中风之前是有预兆的，前面已经说过了，我就不再细说了。像如果你的手前三个 手指头持续的麻，两个月以内你就有机会得到中风。如果脚前面足阳 明胃经从足三里到解溪那一带会麻时，表示两个礼拜以内就有机会中 风。\n\n       中风之前遇到这种麻的现象，请赶快灸足三里。灸到有疤痕让它 起水泡，这个时候我们再看他还有什么症状，如果脉很洪大，病人燥 是白虎汤证。白虎汤吃下去，把津液补足，血里面的水份经过补足后， 血压就正常了，血管就不会爆满了，所以你吃了降血压药根本是逼着 血往上冲，所以吃西医的降血压药，结果还是照样中风就是因为这样。 你也可以反面过来思考，真理就是正面看是这样子，反面看也是对的。 你跑到西医院去问已经中风病人，你问他：「先生你中风之前有没有 吃降血压药？ 」「有啊！」「那你为什么还会中风？ 』『当时因为正在打 麻将，听牌是单钓二饼，结果被我以海底捞月方式自摸，当时太兴奋， 所以就中风了。』因为人的情绪是无法掌握的，有时会突然很兴奋。\n\n        降血压药只能控制到形，没有办法控制到心神，而一个人的喜怒忧思 悲恐都会造成你血液循环加速。所以病人如果开始吃降血压的药来控 制血压时，连情绪都不能随意的波动，必须要像和尚一般的心如止水 才可以的。 \n\n      但是如果你能够控制你的情绪像无欲的出家人一般的话， 基本上你是不需要血压药，因为你的血压一定很稳定。 需要血压药代 表你的情绪不稳，可能是你的太太或者是你的家人跟你吵架，或者是 你的佣人偷了你一支名贵的手表或者偷了你的钱，你一气之下就中风 了，诸位可以去问，一定是这样子。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '2025-02-28T01:01:45.000Z', '11、问曰：寸脉洪大而滑，，洪则为实、滑则为气 ，实气相抟 ，血气入藏即死 ，入府即愈 ，此为卒厥 ，何谓也？ 师曰：唇口青身冷，为入藏，即死；如身和汗自出，为入腑， 即愈。', '2025-02-28T01:01:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HqVbGVtb7WY', 4, '{"title":"12","description":"<p>12、问曰：脉脱入藏即死 ，入府即愈 ，何谓也？</p>\n<p></p>\n<p>       师曰 ：非为一病 ，百病皆然。譬如浸淫疮，从口起流向四肢 者，可治；从四肢流来入口者，不可治。病在外者可 治 ，入里者难治。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003012,"note":"    『问曰：脉脱入藏即死，入府即愈，何谓也？ 』什么叫脉脱？就 是没有脉了。反关脉是例外的。如果你摸病人的脉：「哎呀，老师， 他没有脉！」但是他却好好坐在你前面，此时你应该要摸摸外侧这边，他的脉如果跑到列缺到偏历一带，这叫做「反关脉」。\n\n      反关脉的人非 富即贵，坐在你面前的是大富大贵之人。他怕医师勒索他的钱，他一 定穿着破破烂烂的来。你看完之后：「嗯！先生，这个药很贵喔，大 概要两百万。」「小意思！」这是逃不过我们行家的眼睛，一般中医都被形绑到了，我们千万不要被形绑到。所以你不要说：「老师！他脉 脱则死！」，人家他是大富大贵的人，所以遇到脉脱时，你要前后多摸 一下。\n \n        师曰「不是一种病是这样子，而是所有的病都是这样子」。举例说明，譬如说浸淫疮，我们身上的疮，不管是疮家或是你有麻木的 感觉，如果这个麻木或者这个疮像是破伤风之类的，下管是什么疾病， 如果病毒浸入身体的方向，由四肢末梢往身体方向侵入，就表示很危险。若由身体往四肢方面走就是病在退。「譬如浸淫疮，从口起流向四肢者，可治；从四肢流来入口者，不可治。病在外者可治，入里者难治。」表面上是看到这样的症状，后面会向诸位介绍到斑疹伤寒。 比方说过去西医碰到因为斑疹伤寒而死亡的是要将尸体烧毁的。我们 北派还是有方法可以治，南派是治不好的，斑疹伤寒开始的时候先发疹子，刚开始发一两颗没有感觉，一个礼拜后病人壮熟，然后全身发 疹子发透，发到四肢末梢去，传染性很强。一般西医遇到这种情形就 马上将这个病人隔离起来，然后把所有病人的房子衣物等都烧掉。\n\n       前面这段是讲杂病的一个基本概念，后面才分科分类。如果『以痈疽言』就是身体里面化脓了，或者是里面长东西。如果是长了肿瘤 或者是里面化脓时，『肿痛色红者』都可以治。如果是『平陷色白不甚痛者』都是难治，所以我们需要看病人肿起来的部位，表面上看是红肿的，这种症状我们不用担心。如果表面是平平的，颜色是白的， 还凹一个洞下去，这就是坏病。红就是发炎，就是热，所以有发炎的 现象出现，基本上都是很好治疗的，西医也知道很好治，这表示你的免疫系统很强，你有抵抗力才会发炎。如果不发炎，表面上苍白的而且不怎么痛然后慢慢凹下去，这就是癌症，是很危险的症状，非常不好治。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T04:00:34.000Z', '2025-02-28T04:00:34.000Z', '2025-02-28T04:00:34.000Z', '12、问曰：脉脱入藏即死 ，入府即愈 ，何谓也？ 师曰 ：非为一病 ，百病皆然。譬如浸淫疮，从口起流向四肢 者，可治；从四肢流来入口者，不可治。病在外者可 治 ，入里者难治。', '2025-02-28T04:00:34.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zw1O6eU12zB', 4, '{"title":"13","description":"<p>13、问曰： 阳病十八 ，何谓也？ 师曰： 头痛 ，项腰脊臂脚掣痛。</p>\n<p></p>\n<p>      阴病十八 ，何谓也？</p>\n<p></p>\n<p>     师曰： 欬上气喘哕咽肠鸣胀满心痛拘急。 五藏病各有十八， 合为九十病；人又有六微，微有十八病，合为一百八 病。五劳七伤六极 ，妇人三六病，不在其中。清邪居上 ，浊邪居下 ，大邪中表，小邪中里，谷饦之邪，从 口入者 ，宿食也。 五邪中人 ，各有法度 ，风中于前， 寒中于后，湿伤于下 ，雾伤于上，风令脉浮 ，寒令脉 急 ，雾伤皮腠，湿流关节 ，食伤脾胃，极寒伤经，极热伤络。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003013,"note":"       为什么张仲景要一句话讲完这一切？『从口入者，宿食也』，就 是吃到不干净的食物而生病。\n\n     『五邪中人，各有法度』，五邪就是我们 讲的风寒暑湿燥热。临证上我们中医在治病的时候，依照一个观念就 是「阴阳表里虚实寒热」。比如说我们看到寒湿在关节上，我们开的 药就是能够去寒去湿的药，这样才能去掉关节内的寒湿。如果寒湿是 在身体里面，我们开去寒去湿的药就必须让它能够停留在身体里面。 如果是谈论病，张仲景没有讲的这么详细。谈论病干嘛呢？西医是最 喜欢弄一个病名出来，你没什么病时，就想办法给你一个病名。「医 生先生，我现在得到的是斑疹伤寒怎么办呢？ 」「没办法，只有把你 烧死掉，然后把你的一切物品通通都烧掉。」西医立的疾病名词很多， 中医不立名，只看症。临症在治疗的时候我们没有这么复杂的，我们 不管是什么病，我们只在乎症的变化。","videoMemo":"（1）哕：音“月”，即呃逆。\n\n（2）咽：音“噎”，即哽咽。\n\n（3）六微：是指六腑之病。\n\n（4）五劳：是指五脏之劳，包括肺劳、心劳、肝劳、脾劳，肾劳。\n\n（5）七伤：指食伤、忧伤、饮伤、房室伤、饥伤、劳伤、经络营卫气伤。\n\n（6）六极：指气极、血极、筋极、骨极、肌极、精极，极，作“疲”字解，是疲极劳损的意思。\n\n（7）妇人三十六病：指十二症、九痛、七害、五伤、三痼。\n\n（8）（问曰：阳病十八），……不在其中：把各种疾病总起来分为两类：阳病和阴病。所谓阳病，是指人体躯壳以外的病证，头、项、腰、脊、臂、脚等六者，病兼上下而在外，故通谓之阳病；所谓阴病，是指人体躯壳以内的病证，咳、上气、喘、哕、咽、肠鸣、胀满、心痛、拘急等九者，病兼脏腑而在内，故通谓之阴病。在外的阳病中，有营病、卫病，营卫交病的不同，这是一病而有三，其三六得一十八病，所以说“阳病十八”；在里的阴病中，有虚病、实病的区别，这是一病而有二，其二九得一十八病，所以说“阴病十八”。另外，除阳病和阴病以外，还有五脏之病和六微之病，也就是邪气中於脏腑，气血失调所引起的脏腑病证。五脏之病和六微之病都各具有十八，其皆为风、寒、暑、湿、燥、火等六淫之邪所中。然脏腑之受邪，又各有气分、血分、气血并受之三端，其六而三之，则为十八病，以十八之数推算，则五脏合得九十病，六微合得一百八病。至於五劳七伤六极，是起居饮食情志所生，妇科三十六病，是月经产乳带下之疾，均非六淫外感所致，所以说不在其中。\n\n（9）清邪居上，……食也：根据病邪的性质定立不同名目。清邪：谓雾露之邪，是本之於天，故居於上部。浊邪：为水湿之邪，是本之於地，故居於下部。大邪：即指漫风之邪，漫风虽大而力散，故中於表分。小邪：即是户牖隙风，隙风虽小而力锐，故中於里分，䅽饪之邪：䅽读“馨”(xin)，即为饮食之邪，饮食从口而入，进入中焦，故伤於脾胃。\n\n（10）五邪中人，……脾胃：已知其邪气有清浊大小之不同，人身有上下表里之区别，同时邪气袭人所中部位，也有一定规律可循，这就是所谓“各有法度”。如风为阳邪而中於午前；寒为阴邪而中於午后；湿气重浊而伤於下部；雾气轻清而中於上部；胃主纳食，脾主运化，故饮食不节，则伤脾胃。\n\n（11）极寒伤经，极热伤络，经脉在里为阴，络脉在外为阳，寒气归阴，所以寒极则伤经；热气归阳，所以热极则伤络。","fangList":[],"bieMing":""}}', '2025-02-28T04:00:34.000Z', '2025-02-28T04:00:34.000Z', '2025-02-28T04:00:34.000Z', '13、问曰： 阳病十八 ，何谓也？ 师曰： 头痛 ，项腰脊臂脚掣痛。 阴病十八 ，何谓也？ 师曰： 欬上气喘哕咽肠鸣胀满心痛拘急。 五藏病各有十八， 合为九十病；人又有六微，微有十八病，合为一百八 病。五劳七伤六极 ，妇人三六病，不在其中。清邪居上 ，浊邪居下 ，大邪中表，小邪中里，谷饦之邪，从 口入者 ，宿食也。 五邪中人 ，各有法度 ，风中于前， 寒中于后，湿伤于下 ，雾伤于上，风令脉浮 ，寒令脉 急 ，雾伤皮腠，湿流关节 ，食伤脾胃，极寒伤经，极热伤络。', '2025-02-28T04:00:34.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p7aFXrZ3nfh', 4, '{"title":"14","description":"<p>14、问曰 ：病有急当救里救表者 ，何谓也？</p>\n<p></p>\n<p>     师曰：病医下之，续得下利清谷不止 ，身体疼痛者 ，急当救里 ；后身体疼痛 ，清便自调者，急当救表也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003014,"note":"      什么时候要先救里，什么时候要先救表？『师曰：病医下之，续 得下利清谷下止，身体疼痛者，急当救里；后身体疼痛，清便自调者， 急当救表也。』各位读过伤寒论后都知道，当被攻下以后，这个人已 经里虚掉了，又继续在下利，下利代表肠胃的津液都跑光了。\n\n      此时如果病人有表症时，我们开发表药给病人，发表的药就是利 用肠胃的津液来流汗。结果病家肠胃已经空虚，正在下利中，你还跟 他说：「我先用发表的药试看看。」 一剂下去结果造成病人表也虚了， 于是病人更虚，所以吃完你的桂枝汤后就躺在那边不能动了。于是你 对老师说，「老师，桂枝汤有这么厉害！」结果自此以后桂枝汤就不敢用了，南派中医就是这样想，所以看到麻桂如见蛇蝎般，只因为辨症不清而痛失名方。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '14、问曰 ：病有急当救里救表者 ，何谓也？ 师曰：病医下之，续得下利清谷不止 ，身体疼痛者 ，急当救里 ；后身体疼痛 ，清便自调者，急当救表也。', '2025-02-28T07:44:09.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZtO9UlnBRE0', 4, '{"title":"15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也","description":"<p>15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003015,"note":"     『病痼疾』，就是本来就有的老病，『加以卒病』新病又来了，这 时一定要先治他的新病，再去治他的痼疾。金匮还没有正式开始，这 是我们中医治病的基本原则。","videoMemo":"本条为论新久同病的先后治疗原则。\n\n（1）痼疾：是痼久难治的旧病，痼，音“固”。\n\n（2）卒病：卒然而得的新病。\n\n（3）当先治其卒病，后乃治其痼疾也：旧病加新病，如何治疗？同样，也是要首先分析疾病的先后缓急，然后才施以相应的治疗措施。由于旧病病势较缓，病根深固而难以速愈，新病病势较急，病情轻浅而易以祛除，不治则病势发展加重。所以在旧病新病同时存在的情况下，先治其新病，后治其旧病。新病除，旧病解，则疾病痊愈。\n\n先治新病，后治旧病，这是治疗的一般原则。但是，临床上，新病和旧病往往是相互影响的，所以在先治新病的同时，某些情况下要兼顾旧病，而不可偏颇。如一味治其新病，则会产生变证。例如，久患淋病之人，又感受了外感邪气，如果只先治外感而发汗，忘记了“淋家不可发汗”的禁戒，就会引起便血的变证。","fangList":[],"bieMing":""}}', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '15、夫病痼疾，加以卒病，当先治其卒病，后乃治其痼疾也。', '2025-02-28T07:44:09.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u2JFt4HNaBt', 4, '{"title":"16","description":"<p>16、师曰 ：五藏病各有得者，愈 ；五藏病各有所恶，各随其所不喜者为病。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003016,"note":"       譬如说：心脏本身是很热的脏，如果病人的症状就是恶热，这就好治疗，反之如果心脏病人会恶寒，就是病了。\n\n        肝，本身就是比较寒的脏，所以厥阴篇里面肝脏最冷的，肝就恶寒，所恶的一定跟它的属性是相同的，就可以治好。\n\n       脾脏就是指湿，脾脏本来就是湿的脏，湿太盛了也下行。\n\n       肺脏本来是燥的病，如果太燥了，肺脏也会受不了。\n\n      这个条辨还有一个重点，我们在开药给病人吃的时候有两个现象。一 个现象诸位学过了，吃下去药后头会昏，人会昏昏的，代表中病了； 还有一种状况，中药之所以叫做药，不叫做食物，就是因为它难吃。 你什么时候听过中药好吃的对不对？好吃的一般我们都叫做食物。不叫做药。而当你拿很苦的药给病人吃的时候，病人居然说「哇！这个 药真好吃！」于是一直吃下去，这也是药到病除的现象了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '16、师曰 ：五藏病各有得者，愈 ；五藏病各有所恶，各随其所不喜者为病。', '2025-02-28T07:44:09.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kx6jjaeDN10', 4, '{"title":"17、病者素不应食 ，而反暴思之 ，必发热也","description":"<p>17、病者素不应食 ，而反暴思之 ，必发热也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003017,"note":"      这就是所谓的「除中」，本来病患已经不吃食物了，突然之间又吃的很多，这时病人会发热。「除中」就是胃气没有了，这时候突然 会吃东西，就是很危险的症状。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '17、病者素不应食 ，而反暴思之 ，必发热也。', '2025-02-28T07:44:09.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W1pODAcF0uT', 4, '{"title":"18","description":"<p>18、夫诸病在藏，欲攻之 ，当随其所得而攻之，如渴者舆$f{猪苓汤} ，余皆仿此。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905003018,"note":"       他这举例了『如渴者与猪苓汤，余皆仿此。』所以大家将来要做 像牛顿一样的发明家，诸病就在里面。脏就是藏在里面，不一定是脏， 是病藏在里面，譬如说藏在大肠里面你用承气汤，张仲景就是这个意 思。要『随其所得而攻之』。猪苓汤是一个很好的利尿剂，我在前面 伤寒论已经跟各位介绍过如何使用此汤了。好，我们现在开始进入正 式的金匮。","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '2025-02-28T07:44:09.000Z', '18、夫诸病在藏，欲攻之 ，当随其所得而攻之，如渴者舆$f{猪苓汤} ，余皆仿此。', '2025-02-28T07:44:09.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'q2P6KdHdm5U');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EMb6Oeryd4u', 4, '{"title":"1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉","description":"<p>1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉。太阳病发 热汗出 ，而不恶寒 ，名曰柔痉。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004001,"note":"        同样是痉，中医分两个。一个是刚，一个是柔。刚，简单讲是无 汗。柔就是有汗。张仲景开的两个方子，一个是葛根汤，一个是栝萎 桂枝汤。得到痉病的时候就这两个处方。后面我们会讲到，我们一个 条辨一个条辨看下去。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '1、太阳病，发热 、无汗 、反恶寒者 ，名曰刚痉。太阳病发 热汗出 ，而不恶寒 ，名曰柔痉。', '2025-02-28T08:48:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rtx64oVqvNh', 4, '{"title":"2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治","description":"<p>2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004002,"note":"       诸位记不记得我们在读伤寒论太阳篇时，遇到太阳病如果是发热 脉浮而缓，就是桂枝汤证。\n\n    如果浮而紧，就是麻黄汤证。如果是太阳 病发热，项背强几几然，就是葛根汤证。现在是太阳病在发热的时候， 一摸到病人的脉，不浮、沉又细，代表里虚寒了。沉脉代表是里症， 细脉代表里寒很盛。身体里面的寒很盛，代表我们整个脏腑功能都变 差了，中医叫做寒太盛，这个时候容易造成痉病，难治。痉病的成因 就是水不足，当人身上的水分不够了，就会产生筋挛，开始壮热、大 热。\n\n       当里寒很盛的时候，我们水喝到胃里面去它不会补充水，因为里 寒很盛，水一下去就被排掉了，水分补充不到时就会出现问题，这就 是痉病的成因。所有的痉病不管是刚痉、柔痉，包括后面还有一个大 承气汤证。诸位在阳明篇就学过大承气汤证，所有的这几个证，通通 是因为伤到津液引起的，就是津液不足了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '2、太阳病 ，发热 ，脉沉而细者 ，名曰痉 ，为难治。', '2025-02-28T08:48:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n4EhI1qGYqT', 4, '{"title":"3、太阳病 ，发汗太多 ， 因致痉","description":"<p>3、太阳病 ，发汗太多 ， 因致痉。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004003,"note":"      也就是表汗流太多，有的时候出汗的原因是小孩子太皮，还有医 生开的发汗药开太强造成的。\n\n      比如说你看到一位小孩子生病，一看： 「老师，他是葛根汤证。」结果你把葛根汤的葛根、麻黄、桂枝开的 很强、你忘了开生姜、甘草、大枣。这一剂下去以后就开始抽筋，晚 上像开始发癫痫一样，整个身体都角弓反张起来，这是你造成的痉病， 发汗不能太过。\n\n       所以说我们在开给病人吃发汗药的时候，张仲景特别 提醒说：『不要尽剂』就是你第一碗喝下去：「嗯，没感觉。」再喝第 二碗。「嗯，发汗了！」就停下来，不要再喝了。老妈妈舍不得药，认 为倒掉太可惜了于是：「反正中药温和无所谓嘛！」于是就喝下去，结 果发痉，害我们更忙，因为津液伤到了。\n\n   「太阳病，发汗太多，因致痉。」就是我们在伤寒论介绍过的真武汤证。发汗太多的话，就是真武汤证。\n\n     如果发汗太多还没有成痉：「老师，我开麻黄桂枝下去，病 人发汗很多但还没有成痉。」这时候赶快用桂枝加附子汤，就是桂枝 汤加炮附子来收表，如果已经变成痉病，就很危险了，赶快用真武汤。 如果是『发热必拘急』，手脚都筋挛起来，痉病已经成形了，这时候 就是附子汤证。诸多此类的痉都是因为津液枯竭造成的。\n\n     所谓痉的症状，就是抽筋，整个身体都拘挛起来，然后病人整个身体向后弯过去， 胸腔张的很大，肚子整个凹下去，然后嘴巴咬得很紧，眼睛往上吊， 这就是痉。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '2025-02-28T08:48:31.000Z', '3、太阳病 ，发汗太多 ， 因致痉。', '2025-02-28T08:48:31.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sr2gfk4L5nk', 4, '{"title":"4、夫风病 ，下之则痉 ，复发汗 ，必拘急","description":"<p>4、夫风病 ，下之则痉 ，复发汗 ，必拘急。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004004,"note":"       得到太阳表风病的时候，我们讲『$f{桂枝汤}』是去风，如果你没有 开去风的药，反而先开攻下药物，开攻下药物就是所谓的承气汤。攻下的药会把肠胃里面的营养排出去， 胃是生血之源，结果被排掉后， 这成血的源头没了，已经因为误攻下，使得血的源头没了，这个时候 你又开发汗的药，于是病人又发热，这种就会造成拘急症状出现了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '4、夫风病 ，下之则痉 ，复发汗 ，必拘急。', '2025-02-28T09:34:43.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('013RZAdi9DZ', 4, '{"title":"5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉","description":"<p>5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004005,"note":"       张仲景在伤寒论有讲过，有几种状况是不能发汗的。疮家本来身上就生有很多脓疮，会生疮的人基本上本身就是血不足了，血足的话怎么会有疮呢？我们的抵抗力是藏在血液里面，血足就没疮，血不足才是疮家。这个时候你给他发汗药，于是变成水也不够了，结果血就更不够，病人反而会虚掉，血没有办法去滋养我们的肌肉、筋脉，也会造成痉。\n\n     遇到这种疮家得痉的话怎么办呢？就是张仲景在伤寒论介绍的，『$f{芍药甘草附子汤}证』。芍药这个药，在这里跟诸位再讲一次， 如果血中有湿阻时，就是用芍药的时机。芍药分白芍与赤芍二种，实际上真正我们在用时这两个是相通的。\n\n       如果硬要严格去区分的话，赤芍比较着重在外面，疮家用的，白芍比较着重在里面，治疗脾脏用的，实际上这两个功能差不多。\n\n       如果血中有湿阻，什么叫做血中有湿阻？就是皮表生疮流脓流出黄水、脓水这样滴滴答答黏黏的出来，这个就是湿。湿堵在血里面造成血液循 环不流畅，这个时候用芍药甘草附子汤，就要重用芍药甘草。你说： 「老师，芍药用二钱。」这种剂量只能清清牙齿，芍药要用一两以上才够，大剂的下去救他，你们不要开太轻，这是一般我开的芍药甘草附子汤。 如果疮家遇到南派的话，很可能会开像浮萍、薄荷、陈皮等， 很清凉的药给你吃，我们北派开芍药甘草附子汤就好。\n\n      常常有人半夜 如果『腿不得伸』，腿在抽筋，就是该使用芍药甘草附子汤，张仲景在伤寒论是这样讲的。如果是疮家的人，疮流脓化脓水出来又痒又发 炎时，光是芍药甘草附子汤就只能去他的痛，还要加些固表药物，湿才会去掉，同时要加一些解毒的药，寒凉的药在里面。因为病人有发 炎，西医讲发炎，就是中医讲的热，所以要加一些去热的药，像黄芩、 黄连此时都可以用的。所以黄芩黄连常常被我们混合芍药一起用，可以去病的湿热阻隔。反过来，如果遇到女孩子的白带很多，是不是也会用芍药？芍药对腹痛最好，所以四物汤里面一定要重用芍药，南派就是用四物汤重用芍药用对了，其他的都还不对。后面还有很多方子 要给诸位看。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '5、疮家 ，虽身疼痛 ，不可发汗，，汗出则痉。', '2025-02-28T09:34:43.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SJln9tYJctf', 4, '{"title":"6","description":"<p>6、病者，身热足寒，颈项强急，恶寒，时头热，面赤目赤， 独头动摇 ，卒口噤 ，背反张者，痉病也。若发其汗 ，其脉如蛇。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004006,"note":"      为什么会发生这种现象？ 当我们得到表症时。也就是病毒刚进入 我们的皮肤表面时，毛孔会因此闭起来，就不会流汗了。没有流汗我 们需要用药去发汗，发掉「病毒」就是所谓的解表。一般身发热时， 我们有两种去热的方法。一种是利用发汗来解，一种是利用小便来解。 如果小便很通畅，这个热就有地方宣泄，如果小便也没有了，这个热就会亢在里面，如往下走，小便又出不来，想走皮肤表面时又出不来， 于是就闷在里面。\n\n     世界上所有的热都是往上走，你有没有听过热往下走？热往下走就不会有火山爆发，热气球会升上去而不是冷气球，孔明灯也是利用热气才上的去，所以热的性就是往上走，当热冲到头上来后，整个人就会呈现出脑膜炎的症状。头在晃，眼睛红赤的，此时病人的津液已经很枯竭了，你又给他发汗药，一发汗，就造成血里面的水更不够了，于是脉就变弯了，你摸到的脉，脉就这样子扭曲的， 因为脉里面的水分不够，就会变成这个样子，这是很危险的，前面谈到现在就是告诉我们发汗要有方法，一定要确定病人可以发汗再使用发汗的药，就不会有问题。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '6、病者，身热足寒，颈项强急，恶寒，时头热，面赤目赤， 独头动摇 ，卒口噤 ，背反张者，痉病也。若发其汗 ，其脉如蛇。', '2025-02-28T09:34:43.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IJYatadwcXs', 4, '{"title":"7、暴腹胀大者，为欲解","description":"<p>7、暴腹胀大者，为欲解。脉如故，反伏弦者，痉，夫痉脉， 按之紧如弦 ，直上下行。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004007,"note":"      接到前面这个病，当『其脉如蛇』，如果病人突然腹部胀大起来， 『为欲解。』『脉如故，反伏弦者，痉。』为什么会胀大？平常本该在 上面的热，当热宣泄不出去时，有时热会反而往下走，突然出现烧退， 热会阻在中焦这里，于是造成腹部整个膨胀起来，此时代表湿热已经 进入中焦了，没有在上面。热一旦进入中焦，表示这个病一定会好， 为什么？ 因为热极必返，所以这热会慢慢往下走。『脉如故，反伏弦 者，痉。』但如果脉还是没有变动，还是很弦，表示还会再发痉病。\n\n       所以如果遇到发痉的病时，我们要将湿热往下导引，后面会介绍一些方法。『夫痉脉，按之紧如弦，直上下行。』你摸到痉病的脉时就是所 谓脑膜炎的脉，此时必有高热，这时脉跳起来会很硬，然后上下直行 的。因为血太热会伤到津，血里面要有一定的水分，血失去津液时就 会过热，如此就会伤到我们的经络，伤到我们的血脉神经，所以太热 也不行。就好像我们将生肉丢在滚水里面一煮就白掉了，太热会伤到 肌肉。如果将猪血拿起来倒在汤里面一下子就煮熟了，所以太热也会 伤到血。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '2025-02-28T09:34:43.000Z', '7、暴腹胀大者，为欲解。脉如故，反伏弦者，痉，夫痉脉， 按之紧如弦 ，直上下行。', '2025-02-28T09:34:43.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JsqrxMKZ2tE', 4, '{"title":"8、痉病有灸疮 ，难治","description":"<p>8、痉病有灸疮 ，难治。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004008,"note":"        有些人每天都在烧艾绒，看艾草没有烧完就让它继续烧，只是为 了节省一点不要浪费，暴殄天物，结果因此起了一个灸疮。在这种状 况之下发生痉病，就很难治，所以一旦有灸疮就要赶快把它弄好。如 果得到痉病又同时『灸疮』，就很『难治』。张仲景这里没有出方，后 世很多医生就想到很多方子。\n\n       有灸疮或者是疮家发高热时，我们要如 何才能把高热退掉？还有脑膜炎到了后期西医都束手无策时，此时中 医该怎么做呢？我们刚才讲过，痉病本身的成因就是因为血管里面的 水份不够造成的。发痉的时候病人角弓反张，全身拘急起来，根本无 法抓住病人。如果你是西医，在这个时候硬替他打点滴进去，葡萄糖 注射液在这个时候产生效果，一下子把血里面的水补足了。虽然不是 从肠胃进去，但是补足之后，体温就退了。\n\n      可是西医往往在这种状况 下，他是没有办法替病家打葡萄糖，因为病人会乱动，手足燥扰，只 能眼看着他死掉。所以大家要记得，如果你有葡萄糖在旁边，你又知 道他是津液伤到了，才会发高热『但热不寒』，这个时候如果你能将 葡萄糖打进去也是好的，做为急救用有何不可。\n\n        还有一种方法，就是 遇到有灸疮的人，过去一些医家有的用蝉衣。明末清初一个名医，姓 傅，叫做傅青主，在他的方剂里面，「男人科」，专门看男人的那种病。 过去医家有分科，男人科里面有一个方子，就是用蝉衣还有黄酒。蝉 就是我们的「知了」，你收集一堆，拿个一钱左右，不要生病的时候 再去收集，中药行就有得买。你把它的头和足去掉，只留身体就可以了，把它磨碎以后，跟黄酒两碗混合在一起，不要掺水，然后煮成一 碗，这个时候一口气喝下去。 此时病人发汗很奇怪，这两个药在身体 里面时，脑膜炎的高熟就会退掉，这是专门用在疮家又得到痉病时， 像小孩子有时候头或身上长有疖子，也是一种疮家。\n\n      本来要给病人发 汗，结果一看「唉唷！疮家不可汗！」而病人已经在发痉了，此时再 给他发汗药是不是更痉？这个时候我们就用这个方剂。孩子在发汗出 来后热会退掉，汗出来时摸他全身，会有黏答答的感觉。如果是打点 滴来退热的话，就会从背后一直到脚上面，整个发起白白一粒一粒的 疹子，摸上去感觉很粗糙，大概点滴打两个小时以后也会有这种现象， 热就退掉了，脑膜炎病毒都跑出来，跑到皮肤表面上来。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '8、痉病有灸疮 ，难治。', '2025-03-01T01:38:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fjunUnrKVdQ', 4, '{"title":"9","description":"<p>9、太阳病其证备 ，身体强 ，几几然 ，脉反沉迟 ，此为痉， $f{栝篓桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004009,"note":"『太阳病其证备』当所有太阳病的症状都有了，如果病人却『身体强，几几然，脉反沉迟，此为痉』。如果不是『脉反沉迟者』而是 『$m{浮紧}』就是伤寒论中的$f{葛根汤}证，项背强几几—葛根汤。如果『脉反沉迟，此为痉』。\n\n      病人表现的外症与太阳症一样，唯脉症不同，这 就是$f{栝蒌桂枝汤}证了，诸位在上面写一个『柔痉』。柔痉是有汗，当病人表虚的时候一定会有汗。如果表实，病人必是无汗。表实的话我们要用$f{葛根汤}，病人发痉病，就是现代所谓脑膜炎之类的病，西药麻黄素也有发汗去热的功能，可是西医知道要去热，但他们没有区分无 汗跟有汗。\n\n       张仲景把痉病分无汗跟有汗，无汗的话是表实，这要用葛根汤来去除表实，当病人表虚掉时，葛根汤就不行用了，有汗我们必须要用栝蒌桂枝汤。\n\n       栝蒌根桂枝汤，就是桂枝汤加栝蒌根而已。栝蒌根在神农本草经 里面，是一个专门生津止渴，能够解经热—热在血脉神经里面时用的药。对西医来说，就是：「这个可以降血糖。」所以糖尿病的人我们常常会用栝蒌根。\n\n       过去北派的医师讨论过：「这个栝蒌根既然能生津解渴，栝蒌根跟葛根的性应该是差不多。」因为葛根汤是用桂枝汤加麻黄再加葛根而成的，如果把麻黄拿掉就只是桂枝汤加葛根而已。那就不一定非要用栝蒌根用葛根也可以，实际上这两味药稍有不同，完全相同的话通通用葛根算了，葛根专门是治疗项背强几几然使用的，就是可以升提我们太阳经的表寒水。\n\n      我们人身上有水和血，汗流出去的时候应该要从背后流出去，结果有一天它没有流出去，因为风寒进来将太阳寒水束住了，项背中于风，所以我们中医有一句话叫做「神仙也怕脑后风」。哪天你坐在那边打麻将，背后面对着风吹，打完一圈牌就变成葛根汤了，再两圈牌就成为麻黄汤了，病情会越来越强，这就是神仙也怕脑后风。这个风寒进来，表被束到了，造成应该要流出体外的汗没有流出去，水停在皮表跟肌理之间。\n\n      因为它已经离开汗腺 了，所以无法回头，你叫水往哪里走？没有办法，水性本是向下的， 所以它就慢慢渗到肌肉里面去，渗到背上，背就变的很硬很紧，这是 因为汗水陷在肌里，所造成的几几然症状。\n\n      此时就要靠葛根把它升提起来然后发散出去。葛根汤里面有加麻黄，目的就是当陷在肌理中的 汗被葛根升提离开肌肉后，碰到麻黄将毛孔（玄府）打开，于是汗就流出来表就解了。\n\n      栝蒌根就不是这样，栝蒌根就好像直接把水倒在血里面去，因为那血脉神经是全身性的，葛根只是专门针对项背这一带， 两个都是生津，但是葛根着重于升津，栝蒌根偏向于生津。栝蒌根二两，你不要真的开二两，六钱就足够了。桂枝三钱，芍药三钱，桂枝芍药等量一样，吃完药以后喝热稀饭，来帮助药力发散，如同喝桂枝汤后就要『啜热粥发之』。就是因为栝蒌根能够清除我们身上所有血脉神经的热。所以糖尿病的病人，临床上看时，都是因为有热在血脉神经里面造成的问题，就是血太浓，血里面水分不够了，这栝蒌根下去血糖就会下降，因此栝蒌根很好用的。","videoMemo":"","fangList":["栝篓桂枝汤"],"bieMing":""}}', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '9、太阳病其证备 ，身体强 ，几几然 ，脉反沉迟 ，此为痉， $f{栝篓桂枝汤}主之。', '2025-03-01T01:38:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KEkiZwPp1U3', 4, '{"title":"10","description":"<p>10、太阳病 ，无汗，小便反少 ，气上胸 ， 口噤不得语 ，欲作刚痉 ，$f{葛根汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004010,"note":"       前段说的是有汗，就是表虚掉了，所以我们必须用$f{栝蒌桂枝汤}去解。现在是无汗，没有汗的时候，小便反少。我刚刚讲过，如果一个人没有汗，小便很多。你说：「老师啊！我的体质很奇怪喔，我就是长年不出汗。」「你小便多吗？ 」「我一天十几次小便。」这就与流汗是 一样的，汗水跟小便是同源。如果小便也少了，又没有汗，这个热是不是就闷在身体里面呢？于是就会发刚痉。\n\n      这个时候病毒就会进入我 们的脊髓神经，跑到脑部去，于是就开始发痉。而$n{刚痉}跟$m{柔痉}是不一 样的，一个是柔痉$m{有汗}。一个是刚痉$n{无汗}，记住我的话。\n\n     临症上看就是这样子， 有汗，$f{栝蒌桂枝汤}，无汗，$f{葛根汤}，千万不要弄错。这时病人的病情是非常紧急，所以绝对不能在此时出错，更且我们开的是经方，病人服后是一剂就知，生死是立竿见影的，所以我一再跟大家讲，你只要记得，有汗就是桂枝汤，有汗同时又有柔痉时就加入栝蒌根，讲的这样明白再记不住，我也没有办法了。\n\n       由于这种症状的发生是因为热在 体内没有办法宣泄出去，于是热就只能往上冲，结果热到病人整个脑部，造成头上壮热难耐。气上冲胸口就是整个胸部都胀起来，肚子却很小，也因为热气往上冲，\n\n     于是『口噤不得语』，就是病人的牙齿咬得很紧的意思。当病人发痉病的时候，要注意预防病人会把舌头咬断 掉，所以一定要把病人的舌头撑开来，千万不要让病人咬到自己的舌头。\n\n    『欲作刚痉』，这也是葛根汤证。欲作刚痉跟已经刚痉都是葛根 汤证，欲作刚痉之时「老师他还没作刚痉啊！那就下吃葛根汤了！等到出现刚痉后再吃。」你如果是这样想，就大错特错了。刚痉时当然 是要立刻给病人吃葛根汤，千万不要有疑虑。「老师，欲作才是！」张 仲景是说欲作时可用，那刚痉时该怎么办呢？不能看着病人等死，还是要用葛根汤的。\n\n      使用葛根汤时要特别注意剂量该用多少，必须要重用葛根，才是真正的葛根汤，如果葛根是四钱，桂枝、炙甘草、芍药都是二钱，这时候麻黄是三钱，桂枝芍药都是减量，重用葛根、再来是麻黄、再来才是桂枝的剂量，你如果说：『老师！剂量开太过了！』 葛根汤的剂量是有原因的，因为麻黄要靠桂枝才会到达皮表，之后麻黄再把皮肤毛孔打开来汗就出来了，如果麻黄开得少，桂枝开得多于麻黄，结果桂枝到了肌理后，麻黄还在后面，汗就发不出来。所以麻黄的剂量一定要开的重于桂枝的剂量，同时要再加强葛根的剂量，如果葛根开二钱，麻黄开四钱，结果病人喝药后就无法将体内的津液提 升到太阳经上，仲景先师重用葛根的剂量， 目的就是要让葛根先行， 开出最大剂量的就是葛根。葛根下去把肌肉里面的水先发出来，发出。 来以后还没有到皮肤表面，这时麻黄就跟着来了，麻黄一到，毛孔就开了，加上桂枝跟着过来，将肌理中的积汗一推就把这些积汗通通顶出来了。这就是仲师的四三二一黄金比例。 \n\n        如果你开了二三四，葛根还没有去清，桂枝已经先去了，桂枝顶了半天汗没有出来，病人就会头昏。『怎么发汗发不出来？ 』好不容易麻黄到了，流一点点汗出来，结果表汗去了些，但是囤积在肌肉里面的汗，还是没有尽去，就会造成汗流出来，后项却还是几几然的， 病人还是有壮热。所以仲师开立处方的时候，他的技巧很多是出在剂量上面，更厉害的是我们临床上去看时，他的这个剂量病人喝下去后， 可以把病人得病的病毒与残留的余毒一起排出体外，而不会伤害到好的津液。\n\n      然后他还设计一个方子，这个津液发出去的时候因为是从肠胃里面发出去的，发完津液以后如果小便没了，就代表水没有回到胃里面来，我们水出去是要回头的，不是要让体内的水全部出去，如果是这样，葛根汤下去就完了，因为病人脱水了，为了让正常的津液不受损耗，所以后面加有生姜、甘草、大枣，这样设计处方的目的，就是预防万一水发散太过，无法回头，这些药可以刺激肠胃产生津液， 还有也可以吃五苓散来收敛表水，使水马上回到肠胃里面来。所以经方的设计方式，不单是处方内容简单，药物选用是俯拾可得，连剂量都设计得完美无缺。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '2025-03-01T01:38:28.000Z', '10、太阳病 ，无汗，小便反少 ，气上胸 ， 口噤不得语 ，欲作刚痉 ，$f{葛根汤}主之。', '2025-03-01T01:38:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E9IO1dzSlDJ', 4, '{"title":"11","description":"<p>11、痉为病 ，胸满口噤 ，卧不着席 ，脚挛急 ，必齘齿 ，可与$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004011,"note":"       这个就是我们前面介绍过的，有种脑膜炎的症状必须使用大承气 汤来治，如果你问说：「老师，到底他是括蒌桂枝汤？还是葛根汤？ 还是大承气汤？ 」这就要靠辨症来做决定，病人得到的症状是什么？ 『胸满口噤、卧不着席』「老师，他说的都一样？ 」，$n{唯有脚挛急，必齘 xiè齿}不一样。\n\n    什么叫『齘齿』？ 就是牙齿咬到绷得很紧，还有 一个检查的方法，就是你把病人的嘴巴拉开来一看，他舌苔上面黄黄 的。还有再问问旁边的人：「他几天没大便了？ 」如果病人的亲人说 病人本身就有严重的便秘，就是大承气汤证了，大承气汤，诸位都学 过了。你说：「老师，到了这种阶段『卧不着席』大承气太峻了。我 们用调味承气，小承气。」这就是医师不明病情发展，无法确定病人 的需要，会耽误病人，这个时候救急需要『急下存阴』。这就是脑膜 炎发病除了是我们身上血里面的水不够之外，还有一种就是大便堵在肠子里面。如果大便的臭气跑到心脏这边来，就变成奔豚，就是桂枝加桂汤。如果跑到脑部去了，给西医检查，西医会说「无菌性的脑膜 炎」。为什么？西医只能查到细菌或是病毒感染，查不到大便的臭气， 他也不会闻一下，结果很多人因为失治而死掉。\n\n        我告诉你们大承气厉害到什么程度，大承气喝下去以后，病人大便还没有出来，烧就已经退了，小孩子就已经开始玩耍了。大概这种现象在喝完药后的二十分钟到半个小时就可以看到了，如果病人没有这种现象，一定是你开错处方。治病，时机很重要，当病人急需要时， 你还在那边怀疑犹豫，是不可以的。刚刚讲的痉病到现在，就是三个 处方在治疗，经方家治疗脑膜炎看似简单，我们只有三个处方在使用， 无汗有汗就分两个，西医没有分的，然而病人死在西医手上的却很多。 大承气汤证还有一个直接的确诊方法，就是利用腹诊。","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2025-03-01T02:15:22.000Z', '2025-03-01T02:15:22.000Z', '2025-03-01T02:15:22.000Z', '11、痉为病 ，胸满口噤 ，卧不着席 ，脚挛急 ，必齘齿 ，可与$f{大承气汤}。', '2025-03-01T02:15:22.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('57dbrHVhZp2', 4, '{"title":"12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹","description":"<p>12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹。湿痹之候 ，小便不利 ，大便反快 ，但当利其小便。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004012,"note":"        中湿就是中焦里湿很盛，叫中湿，也叫做湿痹。湿痹的症候有哪 些呢？怎么知道有湿痹？\n\n       病人的主症，第一个是小便不利，大便反快。 这个时候当利小便。\n\n      为什么会有湿在身体里面呢？ 中湿之人从哪里来 的？这有两种情形。\n\n      一种是天气太热造成的，我们在逛街买东西时， 却热的一身汗，流汗时是没有心情看的，看到什么东西都不喜欢。为 了避免流汗，于是就跑到冷气间里面。在外面逛街很热，流汗流很多， 突然进入冷气间，表一下子被冷气束到了，于是汗水停在体内没有出 去，长年累月以后体内就生湿了，然后再慢慢的渗到关节里面，这是 第一种。\n\n      第二种，发生于劳力之人，夏天时工作造成身体很热，到了 晚上，天气很凉快，工人吃完饭洗个冷水澡后，就躺在外边乘凉，晚 上半夜的时候又当风，因此体内的湿就无法散出体外，这也会生湿。 还有就是妈妈们容易得到中湿，妈妈在全家人都睡了以后，还在那边 洗衣服弄得一身汗，汗出以后再去洗澡，之后休息一下，这时就当风而坐，风吹到身体感觉得很凉快，此时她的汗还是继续在出来，于是造成寒气束到表，这也是会造成湿气停在体内。这两种状况其实是一 样，只是来源不一样，结果都造成湿渗在身体里面。\n\n        当湿渗在关节里面，这湿又没有办法渗出去时，湿气就会慢慢的 囤积起来，如果过多的湿停在关节中间，关节就会痛，累积在肌肉里面，肌肉就会酸。\n\n       这种渗在关节里面的湿，会跟外面的气候相呼应， 气候一变冷的时候，湿就会反应说：「我在这里」，所谓同气相求，此时病人就会感觉到酸痛了，去湿要靠温化才能去除。因此病人一接近热，就感觉酸痛减轻了。\n\n      所以风湿关节炎发生酸痛的时候只要一接近热，一烤火就会很舒服，气候一变，要开始下雨了或者外面环境一改变病人马上就感觉开始酸痛了，这是因为湿跟环境相通所造成的。\n\n     湿， 性很黏腻，很浑浊，堵到三焦以后小便就没有办法正常的排出去了， 为什么会这样呢？ 当湿渗在三焦里面会影响到脾脏，当三焦油网里面都是湿时，三焦是决渎之官，水道出焉。\n\n     结果水就跑到大肠里面去了， 这个原本是要从小便排出的水，结果排出下去，于是就从大肠走，结果大便拉出来都是稀的。\n\n    遇到这种情形，就是中医所认定的湿痹症侯， 这个时候我们当利他的小便。如何利小便呢，像五苓散，真武汤等。 简单区分这种治湿的方法，我们平常在治湿的时候，如果遇到湿停在皮肤表面，四肢关节上面我们是发汗来解。如果湿是在身体里面的话， 我们是利小便来解。后面会介绍到几个发汗的方子还有利小便的方 子。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '12、太阳病，关节疼痛而烦，脉沉而细者，此名中湿，亦名湿痹。湿痹之候 ，小便不利 ，大便反快 ，但当利其小便。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NznyQPFwbSt', 4, '{"title":"13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也","description":"<p>13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004013,"note":"       平常中湿很盛的人，有时候并没有病痛的。我常常要求病人说「你 将舌头伸出来让我看看」一看，舌苔呈现很厚，我不管你是黄的厚还是白的厚，也就是说不管你是寒湿还是热湿，反正都是湿！这个时候 你可能没有病，坐在那边好好的，可是你已经有湿在身体里面了，遇到这种情形的时候这种人就叫做湿家。\n\n     湿家得到病如果『 一身尽疼， 发热，身色如熏黄也』。这个是属于阴黄。\n\n     当我们得到太阳证后，如果你没有湿，就很正常的出现太阳症候，也就是单纯的$f{桂枝汤}证。湿家在得到太阳病之前，本来体内就有湿囤积，当表受邪后，里热要出 去，就是中医讲的阳，西医讲的免疫系统，想要出去跟病邪相抗，结果被湿挡到了，病毒因为湿阻而无法进入体内，于是就会停在湿的外 面，我们的阳气被阻在里面，正气与邪气站在两边，中间给湿阻到了。 这个时候热散不出，我们体内的热是因为被表症激发起来的热，结果热发不出去，造成熏黄。\n\n       这时我们就要用麻黄汤加白术。麻黄加术汤 在后面会开方子给大家，此处我们先不讲方子。麻黄加术汤吃下去了以后，这个处方专门用在阴黄证。\n\n       我们中医将黄区分为阴黄与阳黄， 阴黄是黎黑的，就是看起来病人是黑黑黄黄的，这就是湿家，「舌头 伸出来！」舌苔很黄表示体内很热。那是因为湿停留在四肢的肌肉上 面，这个时候我们要用?黄加术汤来发表。\n\n       麻黄加术汤吃下去以后病 人是出微汗，就是微微出一点点汗，然后你摸他的汗，是黏答答的如果是湿在关节里面，你要是想把湿从小便排出去，这距离就会太远了， 不可能做到的，只有直接从表来用汗解。我们身上很多管道可以被利 用来排除病邪，而仲师也都考虑到了「这个离毛孔比较近，我们就叫病从毛孔出去。」麻黄加术汤，是专门给病人出现阴黄的时候用的。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '13、湿家之为病 ，一身尽疼 ，发热 ，身色如熏黄也。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7Ib6Spqdqgb', 4, '{"title":"14","description":"<p>14、湿家 ，其人但头汗出 ，背强欲得被覆向火 ，若下之早， 则哕 ，或胸满，，小便不利 ，舌上如胎者 ，以丹田有热 ，胸上有寒 ，渴欲得饮而不能饮 ，则口燥烦也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004014,"note":"       这个湿家，但头汗出的现象很待别。因为我跟我妈妈在一起的时间不多，有一次我妈妈得到葛根汤证，当时我刚好去钓鱼回来，室内比较黑暗，一进门我爸说：「你妈妈感冒发烧你去看看她。」当时我进 到房间摸我妈的脉，再加上一问，就知道她得到葛根汤证。我说：「我去拿药。」我到诊所去拿药。吃下去葛根汤以后就好了，第二天脸变桃子脸，那种脸是不用去拉皮的，整个脸就像刚整形过美容拉皮，皱纹都没有了，整个脸肥肥的很大一个，就是变成大头小身体，她原来头就很大，现在头更大！然后脸红红的像桃子一样，我说：「你舌头伸出来我看看」，一看那舌头是黄黄厚厚的，湿家！湿家之人我们开葛根汤下去取汗的时候，发汗后不单是把表邪去掉，原来停在中焦的 湿，也同时被我发到脸上面来了。\n\n        葛根把中湿带到整个脸上面，如果 湿是在下焦，我们利小便就好了，如果湿在皮肤表面，我们发汗就好 了，但是湿在中焦就会造成但头汗出的现象，她平时头上就容易出汗， 汗会像雨水一样滴下来，时常看她头发整个都湿的。半夜又加上室内光线较暗，于是我没有注意看，这疏失是在我身上。结果她的葛根汤 证是没了，可是中焦的湿被我发到脸上去，所以给湿家发汗的时候要 特别小心。\n\n       张仲景立方的时候开出桂枝汤加白术茯苓，就怕遇到病人 原本是湿家。如果病人是湿和热都有的话，除了加入白术茯苓之外， 你还需要增加一些去热的药，像黄芩、黄连之类。如果遇到寒湿就要 加白术、附子，就是将术附汤，加在桂枝汤里面。当时我如果开的是 葛根汤加白术、茯苓就不会发生这种情况了。\n\n       平素就有背项强的人，同时又有里寒湿。里寒湿很盛的人一旦遇 到温热就会感觉很舒服，所以他会想比较靠近火，烤一烤很舒服。先生你如果有很重的风湿你烤一烤会很舒服的。如果遇到这种病人，你用攻下法，因为湿家的病人，本来就是肠胃的功能不是很正常，脾胃比较寒的人，就是蠕动比较缓的、吸收不好的才容易成湿，这是最早期湿家的表症。湿如果进入肝脏了，就要用乌梅丸。此条是说，一般 我们遇到脾胃比较寒湿的病人，如果使用攻下的药来攻，而攻下的药都是属于寒凉的药，寒药再遇到胃气的寒，就会变成哕，打嗝，变成茯苓四逆汤证了。\n\n        如果遇到胸腔素有寒之人，或者是舌上苔很厚的病家，此时开攻 下的药物就会造成病人胸满，小便不利，病人并没有因为你攻大肠而症状好转，他的病变是在三焦淋巴系统里面，结果你去攻大肠，这是如同鸡同鸭讲，这个药跟症完全不对。\n\n      舌上如有厚苔者，苔很黄浊， 『以丹田有热，胸上有寒』如果遇到这种情形，下寒上热的病人，『渴欲得饮而不能饮』嘴巴很口渴想喝也喝不下去，就是『则口燥烦也。』 这种都是只有湿才会造成的。湿在身体里面的时候，你就常常会有恶 心的感觉，就已经表示你有湿囤积在体内，如果这个湿停在四肢关节上时，就会造成酸痛，湿停在不同的地方，病人就会出现各种不同的症状。\n\n        造成这种症状的原因有可能是工作的环境或者是医生的误诊， 就像我这样子一剂葛根汤，就让我妈变成上热下寒，脸红的像个桃子 脸，下面小便变少，必须赶快去解热，否则会口渴不能饮，这是因为 湿家本来就有停水很久没有去，然后才成为湿的，例如我们平常喝水到胃里面，胃是最热的，水一下去就变成气上来了。如果胃寒掉了水就会停在那边，停久了就变成湿。因为湿最早是出自水饮，所以素有积湿的人如果湿是停在上焦，会让胸腔里面很寒喝不下水，因为里面 水湿已经很多了，所以根本就喝不下去，于是病人就出现『口燥烦』， 就是又心烦又口渴又想喝水，喝水又喝下下去的奇怪现象。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '14、湿家 ，其人但头汗出 ，背强欲得被覆向火 ，若下之早， 则哕 ，或胸满，，小便不利 ，舌上如胎者 ，以丹田有热 ，胸上有寒 ，渴欲得饮而不能饮 ，则口燥烦也。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('526ImNzfMH6', 4, '{"title":"15","description":"<p>15、湿家下之，额上汗出，微喘，小便利者，死；若下利不止者 ，亦死。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004015,"note":"       湿家不可攻下，对于湿家我们要去湿的唯一选择就是利用温化来 利小便将湿排除，记住这个原则。如果使用攻下法，会造成额上微汗 出，也就是有一点点汗出来，不是大汗淋漓，如果是微汗出代表阳已经绝。因为病人被攻下以后造成他的阳气没了，就会出现此一状况。 \n\n       我们所谓阳气，我再重复跟大家讲一次，就是我们吃在胃里面的营养食物，本应该提供营养给我们身体用的，结果这个食物被湿堵到了， 你应该去湿才对，结果你去攻下，一攻下后肠胃里面的营养没有了， 本来病人已经没有吸收到营养，又被你攻掉，肠胃的津液更少了，这就比较危险。如果攻下了以后，病人出现小便利，就是小便一直不断的出来，照理说湿家的话小便应该不利的；现在反而小便利了，这就是阳已经虚脱了。如果下利下止者，就是里阴脱了。所以当一个人被吊死时，在断气的刹那间，小便大便会一起出来，小便出来叫做阳脱， 大便出来就叫阴脱，这就是阴阳两脱之症，见到这些症状时表示病人已经死了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '15、湿家下之，额上汗出，微喘，小便利者，死；若下利不止者 ，亦死。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S0VKtgVXKJS', 4, '{"title":"16、风湿相抟（应为『抟 tuán』非『搏』，后文同此）","description":"<p>16、风湿相抟（应为『抟 tuán』非『搏』，后文同此），一身尽疼痛，法当汗出而解，值天阴雨不止，医云：此可发其汗， 汗之病不愈者，何也？</p>\n<p></p>\n<p>       盖发其汗 ，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，但微微似欲汗出者，风湿俱去也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004016,"note":"      这段话的意思是当天气阴雨不止，空气很潮湿时，此时医师开出发大汗的药物给病人服用之后，这会让风气去了，但是湿气还是存在。\n\n       为什么会如此呢？ 因为当病人发汗时毛孔会张开来，正好遇到气候是阴雨绵绵，这会让湿又跑回身体里面去。『\n\n      若治风湿者，但微微似欲汗出者，风湿俱去也。』所以我们开给风湿病人吃发表的药时，病人应该是出现全身微汗表示病去，而不是大汗淋漓，因为大汗表示迅速出汗，而湿行是很慢的，因此会造成风去了，而湿还是停在身体里面， 如果是微汗出而且摸上去有很黏的感觉，才表示湿出来了，所以我们 运动完得到的汗，跟我们洗完澡以后得到的汗摸起来是不一样的，运动完的汗是黏黏的，很湿，因为你动了，湿就出来。洗澡后流的汗， 滑滑的，就不会这样，这两个是不一样的汗出。\n\n      大家现在看金匮就晓得，仲师虽然分出很多篇，但是基本上方子还是以桂枝汤为主，中医治疗风与湿，如果只是单纯的表风，就是太阳中风，光用桂枝汤就可以去掉了，但是如果我们要治疗风湿的时候就不同了，我们也是用发汗法，张仲景在这里就特别提出来，发汗要发汗得很有技巧。你如果发汗汗太多，结果汗出来，风跑掉了，湿还没跑掉，因为病人不单单 是风症。\n\n     『但风气去，湿气在』所以不会好。『若治风湿者，但微微似 欲汗出者，风湿俱去也。』这个病人感觉到说好像要出大汗，结果你 一摸病人感觉只是出了微微一层汗，这才是完全的发出来了、所以处 方的剂量要控制得很好，这是中医治疗风湿的一个标准的原则。过去大家学的伤寒论讲的都是纯表风，桂枝汤就是去风的，遇到风湿病人时该怎么处理呢？后面会区分出几种状况，分别使用几种不同的处 方，处方为什么要区分呢？ 因为湿出现在不同的位置上，所以要使用不同的处方。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '16、风湿相抟（应为『抟 tuán』非『搏』，后文同此），一身尽疼痛，法当汗出而解，值天阴雨不止，医云：此可发其汗， 汗之病不愈者，何也？ 盖发其汗 ，汗大出者，但风气去，湿气在，是故不愈也。若治风湿者，但微微似欲汗出者，风湿俱去也。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z58fBFqBJL9', 4, '{"title":"17","description":"<p>17、湿家，病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大， 自能饮食，腹中和无病，病在头中寒湿 ，故鼻塞 ，内药鼻中则愈。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004017,"note":"     『湿家，病身上疼。发热面黄而喘，头痛鼻塞而烦』。我们在刚开始时如何就知道这个病人是属于湿家？很简单「舌头伸出来我看 看。」 一看，此人舌头黄黄的，厚厚的，舌苔很黏厚，嘴巴里面口水 很多、很黏，这就是属于湿家。\n\n       如果病人是『面黄而喘，头痛鼻塞而烦，其脉大自能饮食，腹中和，无病。』这自能饮食，就表示腹中和， 就是代表说中焦下焦没有病，\n\n     『病在头中寒湿。』有这种症状的话我们就知道，病人的湿是在脑和鼻子的中间，就是眼睛额头之间，湿在这 个地方就会产生鼻塞的现象。由于湿的性很黏腻，所以会把鼻子堵到， 病人会喘得呼吸不过来，只好用嘴巴来呼吸。遇到这种情形时我们知 道湿是存在鼻子里面，类似西医说的鼻窦炎，鼻蓄脓等等使用很多名辞。\n\n     『内药鼻中则愈。』仲师认为此时药要直接放到鼻子里面去，效果最好。因为病人只有湿累积在鼻子里面，我们只需要去鼻子里的湿就 可以了。如果用嘴巴将药喝下去，结果药跑到肚子里去，治疗上就会慢许多，不如直接从鼻子将药喷进去。所以我们在治疗鼻窦炎时，除 了下针之外，平常不需要使用内服处方，应该使用喷剂。如果我们用 针治，穴道可以选用迎香穴，如果是鼻子有流脓，鼻水、鼻涕很多， 我们就灸上星，这也是鼻科的大穴。百会、前顶都可以用来治疗鼻病。 背后的风池、肺俞等穴也可以治鼻病，因为肺开窍在鼻子。\n\n       迎香穴这两个穴道你针扎下去的时候，如果当场鼻塞的现象没有 通畅，表示没有扎到迎香，所以如果针下去没有感觉你不要怀疑针灸术不对，而是你太差了，是针下的不对。如果帮病人扎迎香扎完后效 果不彰，可以加针和髎去辅助迎香，这是手阳明大肠经的穴道。足少阳胆经的风池穴，督脉上的上星、前顶、百会等通通可以下针帮助治 疗，膀胱经上的肺俞，用俞募穴互相配合来治疗也很好的。你也可以 配些辛辣的喷鼻药，直接喷到鼻子里面。如果是一般的流鼻水，鼻水像水龙头一样流出来，就不需要用喷鼻药。回家你们大家自己用菖蒲 粉就可以，选用石菖蒲就很好用。菖蒲长在石头上的就叫做石菖蒲， 菖蒲如果长在水里面的就叫做水菖蒲。石菖蒲我们可以拿来喷鼻子的，喷进去以后会感觉到很呛鼻，于是就会一直打喷嚏，水就跟着一 起流出来，直到流干为止，辛夷花也有这种效果。\n\n       如果是脓鼻涕的话力量就不够强了，需要将矾石跟麝香二药配在 一起，专门用来治疗鼻窦炎，效果非常好。当然喷的中间很难过，药散在鼻腔里是很辛辣的，病人会一直打喷嚏，但是宁可难过一下也不 要开刀，你知道为什么不要开刀？ 因为到现在为止还没有人的鼻窦炎 是因为开刀而开好的。许多病人在开完刀后，人都还躺在病床上，鼻子又塞了，没有用的，主要原因是西医不知道湿的源头在哪里。喷鼻药能够让鼻窦部位变得很干燥，因为麝香跟矾石的交互作用。\n\n       而水菖蒲呢，过去在用水菖蒲的时候，是把菖蒲先风干，晒干，等到干了以 后就放在仓库里面储存起来。大多是什么时候用，大家你知道吗？是用在水肿。病人水肿肿到皮肤都变透明的，整个皮肤都因此绷的很紧。 这个时候我们把干燥的水菖蒲拿出来，用火烧，菖蒲像稻草一样，烧 过以后会变成灰，再将灰混合些麻油涂在皮肤上。涂上去以后让病人躺下，等一下病人就会开始小便，积水就会被排出来。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '17、湿家，病身疼发热，面黄而喘，头痛鼻塞而烦，其脉大， 自能饮食，腹中和无病，病在头中寒湿 ，故鼻塞 ，内药鼻中则愈。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZaO2TJzRQUW', 4, '{"title":"18","description":"<p>18、湿家 ，身烦疼，可与$f{麻黄加术汤}，发其汗为宜 ，慎不可以火攻之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004018,"note":"        麻黄加术汤用在哪里呢？ 当你检查到病人的寒湿是停留在皮表上面的时候，就会用到麻黄加术汤。\n\n      「老师，如何查到寒湿在表？ 」 这的确是个问题，仲师就讲了你看「湿家，身烦疼，可与麻黄加术汤，发其汗为宜，」因为本来病人就有湿在里面，平常的湿运动流汗后就好了，湿在身体里面平常是没有什么感觉的，一旦得到麻黄汤证，寒将表束住了，就会产生痛，原因是身体上的湿没有办法从皮肤表面散 出来，这个湿是源自肺再到皮肤表面，当皮肤表面上受到寒时，要让病人的毛孔打开来去寒，一定要靠麻黄汤，而麻黄汤一下去就会发汗， 但是如果遇到湿家，张仲景前面有讲过，湿家发汗时会让风去湿没去， 对不对？所以要加白术在里面。白术是去湿的，麻黄汤是去表寒用的。\n\n      如果是里寒湿就不要靠这个药，这样大家就会区分出来了，所以查到病人有表寒湿的话一定是无汗的现象，当病人已经有麻黄汤证，我们知道需要发汗，但是如果你遇到病人是麻黄汤证，全身骨节酸痛，然 后你又发觉他湿很盛；这时你就不要单纯的开个麻黄汤，要加白术在里面。麻黄加术汤还有个地方也需要使用，就是黄，皮肤发黄的时候， 黄，暗黄、阴黄的时候我们也会用到麻黄加术汤，为什么？ 因为我们人本身的肺里面是湿热的，湿在上焦在肺里面的时候，肺本身是体热宣泄的地方，当肺里面湿太盛时，热就闷在里面出不来，热出不去了 后，肺本身主气，正常人的皮肤也在呼吸的，当肺里面的津液出不去， 外面的气又进不来，就是因为被湿挡到了，湿慢慢的就闷在里面，于 是造成湿热闷在肺里面没有办法发散出来，结果病人就会发黄，这个 时候也是麻黄加术汤证。","videoMemo":"","fangList":["麻黄加术汤"],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '18、湿家 ，身烦疼，可与$f{麻黄加术汤}，发其汗为宜 ，慎不可以火攻之。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('obrR64TEf6D', 4, '{"title":"19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿","description":"<p>19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004019,"note":"     如果到了黄昏的时候病情会加重，这个中医就叫作风湿。这个病是因为伤于『汗出当风』。所以流了汗千万不要正面吹到风，或者是 『久伤取冷所致也』，就是你时常坐在很潮湿的地方，这种情形发生于坐在牢里面的人最多了，从牢里面出来的人得到风湿，大部分都是麻杏薏甘汤证，或者外岛当兵回来得到风湿的，也是麻杏薏甘汤证。 这种症是湿已经渗到关节里面去了，引起的痛，也是属于寒湿的一种。\n\n        麻杏薏甘汤和麻黄加术汤这两个治疗风湿处方，症状看起来很类 似，但是有个差异，临床上看的时候最清楚，麻黄加术汤就是痛，皮 肤表痛，麻杏薏甘汤有个特徵，病人的痛是在关节中，特别是皮肤表 面上黑黑的，所以当中医看到病人皮肤特别干燥又兼有风湿关节痛 时，就是麻杏薏甘汤证了。\n\n        这两个症有一个区别，就是湿所在的位置 不一样。一个是在皮肤表皮之下，一个在表皮的第二层的地方。\n\n       为什 么要用薏仁？ 因为薏仁能够进入中焦，能够进入脾脏，薏仁能够去湿。 「老师，中焦的湿白术也可以去除，为什么一定要选用薏仁？ 」这就 是我常常讲的，张仲景用麻杏薏甘汤的薏仁有两个功能，第一个，凡是仁剂一定可以通利大便，可以让湿往下焦走。薏仁还有一个特殊的功能，它能够收表湿，治疗皮表太湿所引起的皮肤病。像有的小孩子 皮肤化脓，长了很多疮在上面。疮生出来后就产生很多脓水，此时我 们就可以加薏仁进去，因为薏仁能够收敛表湿。所以皮肤科的药我们常常用薏仁，还有连翘，记不记得麻黄连翘赤小豆汤证，伤寒论中有 介绍过。\n\n        薏仁就是平常吃的四神汤。你有没有听过有人吃薏仁死掉， 没有对不对还有人把它拿来当饭吃。因为它的淀粉质很多，所以对肠胃功能很好，又好吸收，一般来说湿在中焦的人平常肠胃消化都不是很好，你把麻黄汤里面的桂枝拿掉改成薏仁，就是麻杏薏甘汤。如果是麻黄、杏仁、桂枝、甘草的话就是麻黄汤，而麻黄汤会发汗发太快， 结果造成风去了湿还是没去，如果把桂枝拿掉，因为桂枝可以提升麻黄到表上，麻黄如果没有桂枝的话，麻黄就无法到表，所以吃下去之 后也只是发出微微的一层汗。很细的一层汗，比例按照书上看就可以 了。这是麻杏薏甘汤跟麻黄加术汤不同之处。\n\n       还有一个，麻杏薏甘汤常常使用于当气候要变之前：「老师、外面气候阴雨了。」只要一遇到阴天，关节就开始酸了，就是麻杏薏甘汤了。因为它治疗的湿是在第二层，这湿会跟环境相感应，空气中湿度一增加病家就知道，因为直接接触于表，湿在表就会难过。薏仁在后面治湿的处方中会用到很多， 有时也用在治疗肠子里面的湿，后面我还要讲到薏苡附子败酱散，所以有很多特殊的用途。","videoMemo":"","fangList":["麻黄杏仁薏苡甘草汤"],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '19、病者 ，一身尽疼，发热 ， 日晡所剧者 ，名风湿。此病伤于汗出当风，或久伤取冷所致也，可与$f{麻黄杏仁薏苡甘草汤}。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FW0PHlVH9Qr', 4, '{"title":"20","description":"<p>20、风湿 ，脉浮 ，身重 ，汗出恶风者 ，$f{防己黄耆汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004020,"note":"       麻黄加术汤跟麻杏薏甘汤这两个处方都因为病人无汗，才会用到麻黄。现在讲到的防己黄耆汤呢，大家看，第一是脉浮。「老师啊，  浮脉代表病在表。」代表太阳中风，病在表，此时如果感觉到身体有  很沉重感时，身重代表湿盛。湿盛的人一定感到全身很沉重。劳症的人也会常常感觉身体很重，因为湿在血管里面积累造成的。 这种人打高尔夫球，打完一个球洞的时候他就全身不能动了，为什么？ 因为身重，所以病人很容易疲劳，就是湿很盛之人。\n\n        此处仲师写的脉浮代表风，身重代表湿。『汗出恶风者』汗出来代表表虚了，表虚了才会流汗，此时风吹来时就很难过，这就是防己黄耆汤证了。大家看看处方内容，其中有防己、炙甘草、白术、黄耆，由于这是表虚的时候产生的风湿的症状。\n\n        防己跟白术，白术能去湿我们就不要再重复讲了，当病在皮肤表面上的时候就是麻黄加术汤证，进入肌肉时候变成麻杏薏甘汤证，进入血脉、血管的外围的时候就是防己黄耆汤证了。湿在不同位置上仲师用的剂量深浅就不一样，张仲景真的很厉害。如果在血管的外面，还没有进入血管，进入血管里面就是桂枝芍药知母汤证。 \n\n        在血管外面时病人呈现的现象就是表虚掉了，因为湿不在表。为什么会表虚掉？ 因为我们的血脉带来我们的免疫系统的营养，我们的（气）能量，结果能量没有达到皮肤表面，当然会表虚，所以会流失掉很多 津液。这个时候我们要用防己，防己能够排除血管外面膜中的湿，防己长得样子像车轮一样，中间一个洞，呈放射状，防己因为长成这个样子，所以防己就会绕着血管外面走，它能够去血管外面的湿。\n\n       为什么要用黄耆呢？ 因为黄耆本身功能是补气的。它跟附子不一样。炮附子是固表的，一吃下去，汗就停止流了。所以我们遇到桂枝汤证的病 人，如果被医师开发表药太多，造成病人汗漏不止，呈现出脱水的时 候，此时我们就用桂枝汤加炮附子，不用黄耆，黄耆是补气的药，将病人的气加强起来固表，而炮附子很猛烈，能很迅速的将毛孔收敛起 来、所以炮附子是紧急的时候使用的。随便给炮附子，会使本来的风湿需要发汗来发掉湿，结果炮附子一下去，病人就会从防己黄耆汤证， 变成麻黄加术汤证，湿跑到肌肉外面但是无法出表，因为被炮附子固到了。当你晓得这个病在这里的时候，我们一剂防己黄耆汤下去，病 人也会得汗则解。\n\n      白术甘草去里湿，主要的症状是身重，就是全身关 节重。因为湿性是沉着、黏着的，所以就会停留在关节里面，或是停 留在身体下腹部位。因为湿都在里面，就会附着在血管的旁边，这就 是里湿了，所以从这三个汤方可以看得很清楚如何使用它们的时机。\n\n      麻黄加术汤，专治寒湿在表。寒湿在肌肉上面就是麻杏薏甘汤。如果到了血脉神经上面的话就变成防己黄耆汤。此时主要的症状就是表虚 了，表虚的话一定会有汗这时我们就会到用防己黄耆汤。\n\n这是告诉我们如何依据症状去区分它？如何去使用它。","videoMemo":"","fangList":["防己黄耆汤"],"bieMing":""}}', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '2025-03-01T04:03:20.000Z', '20、风湿 ，脉浮 ，身重 ，汗出恶风者 ，$f{防己黄耆汤}主之。', '2025-03-01T04:03:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gVw6CSZu2UJ', 4, '{"title":"21","description":"<p>21、伤寒八九日，风湿搏相 ，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利 ，$f{去桂枝加白术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004021,"note":"        诸位在伤寒论是不是也读到过这一段，仲师就是要再提醒我们， 什么是湿？如果单纯只是有湿症，病家就会抱怨身体不能转侧，不呕， 代表没有少阳证，不渴，代表没有阳明证。\n\n       此处的『脉浮虚而涩者』 这里讲解的就比伤寒论更深入一些。脉浮虚，浮代表病在表，意指表虚，涩脉，代表血不足，如果是芤脉，根本就是已经失血了。这条辨就是说当我们知道病人有表虚，又同时见到病家有血不足的状态之 下，得到风湿时如何处理。\n\n       临床上我们在用药时，这个方中牵涉到一个药叫做白芍，一般南派的医生的观念认为说：「芍药，补血的。」所 以四物汤里面会用到芍药。而经方家的观念不是这样的，芍药性酸， 主收敛又能活阴血。所以芍药可以攻瘀、活血。所以芍药能够止腹痛， 如果病人出现血虚时，我们经方家是绝对不会去用芍药的，因为芍药味酸，而且带苦味，故主泻下。所以芍药在我们经方家使用时是被归类为攻血剂。\n\n        例如张仲景用芍药甘草汤，去治疗腿不得伸曲。如果我们把桂枝汤中的白芍拿掉，桂枝汤本来是要解除病在肌理时用的，现在用炮附子来代替芍药，是因为我们知道是寒湿停留在肌肉中，才造成病人身体烦疼，不能自转侧，而去寒就要靠附子。所以将桂枝汤中的白芍拿掉，改成炮附子、『附子三枚炮去皮』炮用。\n\n       经方中『阳旦所以用生附者，所以助里阳而泻在表之水气也』用熟附的话主要是取其『助表阳而温化其湿也』所以治湿，大部分我们是用苦温化湿法，我前面有跟诸位介绍过为什么要吃乌梅丸，因为乌梅丸就是苦，而且温，苦温能够泻肝胆的郁热，就是有湿阻在肝胆里面，酸的东西对肝非常的补。现在大家看到这个条辨以后就了解到， 因为病人是表虚，所以我们用桂枝，桂枝能走表，而里面的寒很盛时， 我们必须用附子去除寒，因此不需要用到芍药。\n\n      炙甘草、大枣、生姜 都能够温助里阳的。炮附子药性很热，能够让表阳旺起来。\n\n     如果遇到病人有『大便坚，小便自利』此时就把桂枝拿掉，加白术与附子，就是白术附子汤。为什么把桂枝换掉变成白术，同样的是风湿相抟，因为这二个处方都是去里湿用的；不同的状况就用不同的处方，当病人的舌苔又白又厚，然后摸到脉是虚而无力又涩，病人会流汗出，但是汗流出来照样身体很沉重，全身关节酸痛，这表示湿是积在肌肉之中， 此时就是桂枝附子汤证了。这个术附汤也是里湿很盛用的，里湿盛但却是在不同的位置。\n\n        病人的症状是『大便坚，小便自利』，这个大便坚的原因，是因为有湿隔在中焦，造成肠子里面的津液就不够了。这 个时候我们必须开个去湿的处方，而湿是我们身上非常难去除的一样东西，如果我们开一个处方直接攻下，有时候攻下的力量太快，结果湿没有去掉，反而让肠胃里面的营养都跑掉了。所以此时张仲景就主张用术附汤，看看术附汤里面的内容，就是白术、附子，还有生姜、 甘草、大枣。因此术附汤，就是能够直接进入脾脏将里湿逼进三焦油 网系统中。然后再到皮肤表面一路直接发出去。\n\n       术附汤喝下去的时候，诸位看，『上五味，以水三升，煮取一升， 去滓，分温三服。一服觉身痺。半日许再服。三服都尽，其人如冒状， 勿怪。即是术附并走皮中，逐水气』说明服后头会昏。\n\n      『商昼云：若药勿暝眩，厥疾弗瘳（chōu）。』吃了药，如果病人没有头昏，这个 病不会好。（注：服后头会昏）就表示药开得很恰当。\n\n        仲师说：『篇中大剂每分温三服，独于白术附子汤。特别讲到这个症状。』言一服觉身痺，痺者，麻木之谓。下面写到『凡服附子后，不独身麻，即口中额上俱麻，否则药未中病，即为无效』药就不会有效，这里说的就是 使用附子的剂量问题，有的人吃附子吃下去，处方只开了两钱三钱他吃下去没感觉，就是等于病人根本没有吃到附子，所以我们不是说要 病人他一定要吃得很多，不是这个意思，而是比如说一个汤剂，熬好 以后分成三碗，第一碗喝下去后，没有什么感觉，隔三个小时再喝第 二碗还是没有感觉，就代表药力没到。\n\n      如果说：「那我明天再喝」，这是不行的，因为药力还停在那边，只是没到而己，你必须要追击，那就再把第二碗喝下去，喝下去如果头昏就停药。如果喝到一半就开始麻，那一半就停掉。如果喝完第二碗还是没感觉，再等三个小时后还 是没感觉，你就让病人再喝第三碗。如果你停下来，到第二天才再喝 第三碗，等于是重新再来过一次了，重来的时候，表示之前的病并没有进展。\n\n       很多的医生不了解这一点，一看喝下去病情却没有进展，第二天就更换处方，这就错了。南方温病派的中医处方中的寒药热药，没有像经方这么强的，南方温病派使用的药，你吃到好坏都没感觉。如果我们开真正的经方，伤寒论、金匮中的方子，吃下去不是一就是零。 病人如果没有好，当天就会有反应。一定有相反，逆症的反应。\n\n         所以 如果病人吃了那么大剂下去没有感觉，代表你这个方子是正确的，只是剂量不够，或病人服的方法不对。吃下去全身开始好像中毒了，就是药力达到病灶了，可以停掉。如果你说：『老师我舍不得。』再熬， 再喝下去，就会太过了，因为那是药。不叫做食物，食物还可以撑下 去，药硬撑的喝下去，吐都吐不出来，怎么办？\n\n       特别在介绍术附汤时 要再提醒大家一次，术附汤的剂量是很重要的。白术一两，附子一枚， 如果平常我们$n{一枚生附重量差不多有一两二钱到三钱}。而经过$m{炮炙以 后，差下多只剩下三钱半，一枚生附子只剩三钱半重}。\n\n       所以如果将白术跟附子放在此地的剂量上来说的话，就等于要重用白术，然后靠附子把白术推到表面上。\n\n      为什么要重用白术？ 因为白术可以将脾脏里的湿，还有三焦湿和肌肉的湿，全部推到皮肤表面上出来，所以要重用。 附子差不多三钱半，炙甘草差不多二钱，生姜使用两片三片的就够了， 红枣约六个，这是桂枝附子汤跟白术附子汤两个区分的地方。当里寒湿出来以后，同时要预防肠胃津液会跟着耗损，所以在使用发表药的 同时要加草姜枣来补足丧失的津液。\n\n     被发出去的汗在皮肤表面上都是黏黏的，就是真正的湿，这些不要的湿要把它排出去，真正好的津液 还是慢慢会回流到身体肠胃里面来。肠子里面得到津液后，肠胃就开始蠕动，大便出来后，就不会那么硬了，张仲景这个条辨中立了两个 方子，就是怕一些医师看到病人有湿积，又同时看到病人大便很硬， 结果就去攻大便，本来里面就已经很寒很湿了，然后被你一攻下，病 人成为又虚又寒又湿，实际上他的大便不出来原因是因为湿堵在那边 了，使得肠胃的津液没有办法正常的分泌，才造成大便很硬。\n\n        当吃了 白术附子汤之后，寒湿就会从汗解，汗解完了以后，正常的津液就会回到肠胃中，这个时候大便就软掉了。如果需要攻下时，病人一定会 有烦躁，舌头很黄很焦的等症状。然后你再问他大便如何？如果他己经五天不大便了，此时如果你还给他白术附子汤吃，岂非在害人中， 此际就要赶快先将大便清出来，五天不大便，这个大便是很可怕的。 比如将一个便当放在太阳底下晒五天，你就知道会如何了。像曹颖甫， 唐容川等经方家对于生附、炮附使用上都如家常便饭般的在用的。而温病派呢，看到生附就逃走了。他们一直错误的在认定「生附怎么可以用？ 」他们不知道有多么好用。\n","videoMemo":"","fangList":["桂枝附子汤","去桂枝加白术汤"],"bieMing":""}}', '2025-03-01T07:40:50.000Z', '2025-03-01T07:40:50.000Z', '2025-03-01T07:40:50.000Z', '21、伤寒八九日，风湿搏相 ，身体疼烦，不能自转侧，不呕不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若大便坚，小便自利 ，$f{去桂枝加白术汤}主之。', '2025-03-01T07:40:50.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mBfj77Qo2wK', 4, '{"title":"22","description":"<p>22、风湿相抟，骨节疼烦 ，掣痛不得屈伸 ，近之则痛剧 ，汗出短气，小便不利，恶风不欲去衣 ，或身微肿，$f{甘草附子汤} 主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004022,"note":"     甘草附子汤证代表湿已经渗到关节里面去了，湿如果在内脏里面、在中焦里面、在上焦，诸位现在都会治了。\n\n     如果是湿在皮肤关节里面呢？如果靠白术附子汤，可以把肌肉里面的湿排出去，但是关节里面的湿还在，这个时候就要靠甘草附子汤。\n\n     甘草附子汤跟刚刚前面提到不一样的就是，它不是全身微肿，是湿停在关节的地方会肿得很大，这个时候，我们知道是湿渗在关节里面，使得病人呼痛。尚未碰到他，他就喊痛：「啊！你不要碰我！不要靠近我！」为什么？ 因为很痛，你一靠近他，他以为你要摸他，就会感觉更痛，关节表面整个红肿起来，这就是所谓的甘草附子汤证。 风寒与湿直接渗在关节里面造成的痛就是要靠这个方子。\n\n       如果给西医治，有些西医会用开刀方式， 把里面的湿拿出来。因为红肿又痛到受不了，脚都不能弯，于是病人就同意开刀。开刀时拿出来的都是黄水，拿完以后再缝起来，从此就 变成『鹤膝风』，膝盖就会肿成圆球般大，然后病人的小腿骨细细的， 多难看，我就治过这样病的，有位小孩子来看腿病，他膝盖就是有风湿病，才十岁啊！就被西医开刀开成这样子。来诊所的时候脚是这样弯起来拿着柺杖进来，进来时我看到他两观是黑的，我问病人说：「你有气喘？ 」「对啊」。我们治疗你这个风湿大约需要两个礼拜，而气喘一个礼拜就好了，恢复的更快。两个礼拜以后他外婆跑来找我，她说： 「我现在抓不到我的孙子了。」这就是中医经方的效果，我使用的处方就是甘草附子汤。\n\n      炙甘草，附子两枚。我们在用甘草附子汤的时候，附子跟白术差不多是等量。比如说：我们附子用五钱。白术就用五钱。甘草附子汤中附子下重手不要害怕，因为这个附子有桂枝在里面配合，此时附子一下去不会停在固定一处，桂枝会把附子带到关节去，附子就因为有桂枝而能渗透到四肢的关节里面去，附子走肾，所以能走骨节，打进关节里面要靠附子。然后白术进去收敛湿气，所以一定要重用桂枝。 你如果是你开了白术附子跟桂枝，忘了开炙甘草，结果造成风去，湿未去，因为炙甘草有减缓药力行走的速度，就好像跟其他药说「等一 下！桂枝你等一下，要等到湿通通清完，你们再一起走。」因此这处方的剂量非常严谨。\n\n       所以以后大家开处方的时候，比如说炙甘草二钱， 炮附子两钱，白术两钱，桂枝就四钱，桂枝要加倍。仲师又说上四味药。水来煮，比如说六碗水煮三碗，温服一升，一天吃三次，如果初服得到微汗，感觉很舒服了，病就解了，就不要再喝了，就能吃东西。\n\n     如果『汗出复烦者』就是流了汗以后病人还是很烦躁，风湿还是很痛， 就表示说病并没有去，那就再喝，『宜服六七合为妙。』就是再喝它就是了。\n\n     曹颖甫解释『身微肿，似当用麻黄以发汗，仲师弃而不用者， 正以湿邪陷入开节，利用缓攻也。』就是湿邪如果在表的话，我们要靠麻黄去发汗，湿邪在关节里面，此时用桂枝才是对症的，所以张仲景开治疗风湿的处方时，因为湿在不同的位置上，处方就不同，在$n{皮肤表面上的时候—麻黄加术汤}，$m{湿在肌肉里面—麻杏薏甘汤}，进入到 血脉旁边、在下焦、在我们的三焦网膜里面的时候、还有进入关节的时候通通不一样，所以经方里分出很多种的不同处方来治疗风湿。\n\n       西医学风湿就是风湿，就已经讲完了，真是很粗糙。如果说：「老师， 中医讲的不科学。」你就错了。我一直在跟诸位讲，什么叫真理？就 是由繁而简。繁进入简单的阶段，就代表他已经懂了。\n\n      比如我们在讲痉病的时候，就是西医所谓的脑膜炎，诸位知不知道西医光是讨论脑膜炎的书有多厚？张仲景两三个条辨就讲完了，而且不但讲完了，还治疗完了，处方也已经开完了，厉不厉害？所以我们大家要以身为中国人为荣。","videoMemo":"","fangList":["甘草附子汤"],"bieMing":""}}', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '22、风湿相抟，骨节疼烦 ，掣痛不得屈伸 ，近之则痛剧 ，汗出短气，小便不利，恶风不欲去衣 ，或身微肿，$f{甘草附子汤} 主之。', '2025-03-01T08:41:18.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('24lwGG1w4Vu', 4, '{"title":"23","description":"<p>23、太阳中暍，发热恶寒 ，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳 ，身即热 ， 口开前板齿燥 ；若发其汗 ，则恶寒甚 ；加温针 ，则发热甚； 数下之， 则淋甚。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004023,"note":"       什么叫中喝？就是中暑。在过去中暑的状况很多，现在中暑状况比较少，但是还是有。\n\n       为什么以前中暑比较多？ 因为以前哪有什么冷 气，我们现在是家家都有泠气，在外面很热时就进屋去吹冷气，所以中暑的现象比较少见，风疹的现象却比较多，讲到风疹，麻黄加术汤 就可以去掉风疹。因为麻黄汤专治寒湿在皮肤表面上，比如说你在洗完热水澡后，身体在流汗，一出来吹到冷空气，皮肤会很痒，或者洗完澡没什么感觉，躺在被窝里面被子一盖就很痒，这就是因为你汗水没有透发，汗水停留在皮肤表层下面，汗离开了汗腺，但是没有离开毛孔，就会停在毛孔、皮肤表面和汗腺中间的地方。\n\n        这个就是麻黄加术汤证。因为麻黄加术汤被设计成为刚好在这个接近皮表位置的湿， 服后发微汗，如果用麻黄汤发汗会太过，结果会伤到正常的津液。如果晚上吃麻黄汤，皮肤不痒啦！因为汗都发出来了所以不痒，但是早上起床后就变成大承气汤证。因为肠胃的津液都给麻黄汤发光了，不是麻黄汤证，却用麻黄汤必将太过，所以必须要知道方剂的主功能所在，开处方时才会很能运用自如，这种中暑虽然以前较多，现在比较少，但是还是会用到，要不然有一天走在沙漠里，你看到一个人中暑： 「惨了！这个人中暑了。」此时你就不会处理了。\n\n      关于中暑，张仲景立有两个方子，就可以治疗中暑。一个是白虎人参汤，一个是瓜蒂散。\n\n   『太阳中喝 』就是中暑了，『发热恶寒，身重 而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳， 身即热，口开前板齿燥：「前面板齿指两个大门牙很干燥。」若发其汗， 则恶寒甚；加温针，则发热甚；数下之，则淋甚。』会得到太阳中暑的人，就是因为他在大太阳底下运动或是做劳力工作的时候，身体出大汗津液丧失很多，就是在丧失津液的状况之下又得到表症，那么热的天就会得到表热，外面产生的热，再加上里面本来就很热，津液本来就不够了，这就叫做中暑。\n\n       所以表热和里热在相抗，病人就变成大热，大热的状况之下会出现病人发热、恶寒。\n\n     为什么会恶寒呢？ 因为 表水都没了，就是表虚掉了，所以病人会怕冷。所以这里的恶寒并不是直正像麻黄汤证的表寒，是因为里热太高了。\n\n    『身重而疼痛』，『脉弦细』这就代表病家的表虚掉了，\n\n    『芤迟』代表血也虚掉了。因为血 里面的水丧失很多，此时会有一个症状很特殊，就是小便完后头会这样摇一下，为什么会这样？ 因为病人水不够，当体内水不够的时候， 全身互相都有神经性的反射作用，在水不够的状态之下，你一小便， 头就会这样动一下，因为反射，这就是告诉你里水不足了。\n\n   『手足逆冷，小有劳』一动，身体会很热？\n\n  『前板齿燥』这个就是我们体内津液丧失过多了。\n\n    此时『若发其汗』你再发汗的话，病人就完了，『则恶寒甚』就会感觉身体寒冷。 \n\n   如果此时再加上『温针，则发热甚』。『数下之，则淋甚。』这里就是说如果此时你再去攻下，结果病人因为肠胃的津液已经没有了，小便 就会很浓浊，这就是病人已经处在极虚的状态之下：是坏症。\n\n    这段简言之，就是如果病人出现表热兼有里热的现象，就是中暑了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '23、太阳中暍，发热恶寒 ，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳 ，身即热 ， 口开前板齿燥 ；若发其汗 ，则恶寒甚 ；加温针 ，则发热甚； 数下之， 则淋甚。', '2025-03-01T08:41:18.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jtvUc4oXj1s', 4, '{"title":"24","description":"<p>24、太阳中热者 ，暍是也 ，汗出恶寒 ，身热而渴 ，$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004024,"note":"      『太阳中热者，喝是也』就是中暑了。\n\n     『汗出恶寒，身热而渴， 白虎加人参汤主之。』白虎人参汤本来的目的就是为了要补足血里面 丧失的津液，津液丧失就会有壮热的症状出现，临床上我们中医的白虎人参汤证，就是西医说的脑膜炎引发的高热现象，同时可见病人流 出许多汗，然后病人感觉身体较冷，但是体热却很高，大便又很正常， 又没有发痉，此时如果遇到发痉的病人，如果是刚痉就是—葛根汤证。\n\n     柔痉的话就是—瓜蒌桂枝汤证。如果都没有发痉，也不是承气汤证时， 那就是白虎人参汤证了。所以白虎人参汤一样可以治疗脑膜炎引起的高热。\n","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '24、太阳中热者 ，暍是也 ，汗出恶寒 ，身热而渴 ，$f{白虎加人参汤}主之。', '2025-03-01T08:41:18.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ECCkTZGkHJp', 4, '{"title":"25","description":"<p>25、太阳中暍，身热疼重 ，而脉微弱，此以夏月伤冷水，水行皮中所致也 ，一物$f{瓜蒂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905004025,"note":"       瓜蒂散是吐剂，当病人本身就有里热，因为中暑的病人平常运动就流汗流得很多，因此热经常是呈现浮在身体里面的状态。\n\n     这时没有表症，单纯是里热，此时病人因为有里热而将身体浸泡在冷水中，想去热，然后又饮用大量的冷水，结果外用浸泡冷水造成身体疼痛，喝下许多冷水在胃中又无法气化，加上体内又因为津液不足而很燥热难耐，此时就要用这瓜蒂散。\n\n       瓜蒂这个药，如果是喷在鼻子里面，会造成打喷嚏。如果是含在嘴巴里面，就会想吐。病人喝下就会吐出许多冷水，我们不用麻黄发汗为什么？ 因为他本来身体里面就有浮热，加上本身津液又已经伤到了，所以我们绝对不可以再用麻黄汤去给他发表。\n\n       也就是说这是因为病人津液不够了才产生的热，你再用麻黄汤发汗就会更伤津液，这个时候用瓜蒂散最好。诸位你有没有感觉到，每次你吐完的时候都会流汗。如果你不相信，等一下下课到旁边，我抠你喉咙让你吐，吐完后你再摸摸身体，就会发现身上都是汗。人吐会出汗，就是利用吐法让病人发汗，不要用药去发汗，因为病人津液已 经伤到。\n\n       如果表热跟里热加在一起，成为高热的时候人参瓜蒂散也没有用的，就要靠白虎人参汤下去救热，所以白虎人参汤喝下去病人也会流汗，热就会整个退掉。\n\n      如果病人没有表热，只是身体里面的浮热，感觉闷闷的，按脉又没有很浮，病人又感觉昏昏沉沉的，有一点发烧又不是很烧，你想想这怎么办？只有让他轻微的发一点汗，把热消掉就可以了，此时可用瓜蒂散下去，吐出水后，病家皮肤会发一点点表汗， 这个浮热就会离开身体。\n\n       所以病的深浅轻重张仲景都考虑的很清楚， 绝对不能让病人身体在有里虚的时候还在给他攻下，因此仲师就跟你说下利不止者死，他的目的就是提醒你，病人因为有里虚所以不能攻。 当病人身体很虚弱时，我们又需要去发此人的汗时，该怎么办呢？可以用一点点瓜蒂散来取吐得微汗，张仲景的意思就在这里。","videoMemo":"","fangList":["瓜蒂汤"],"bieMing":""}}', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '2025-03-01T08:41:18.000Z', '25、太阳中暍，身热疼重 ，而脉微弱，此以夏月伤冷水，水行皮中所致也 ，一物$f{瓜蒂汤}主之。', '2025-03-01T08:41:18.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'EFq5orwY5uR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dbw854k0cJV', 4, '{"title":"1","description":"<p>1、论曰：百合病者 ，百脉一宗 ，悉致其病也。意欲食 ，复不能食 ，常默默然 ，欲卧不能卧 ，欲行不能行，饮食或有美时 ，或有不欲闻食臭时 ，如寒无寒 ，如热无热 ， 口苦，小便赤，诸药不能治，得药则剧吐利 ，如有神灵者 ，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅淅然者，四十日愈；若溺快然， 但头眩者 ，二十日愈。其证或未病而预见 ，或病四五日而出 ，或病二十日或一月后见者 ，各随证治之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005001,"note":"        什么叫百合病？你看他上面写『其病也。意欲食，复不能食』 是想吃都不行，既吃不下，又不想吃。\n\n     『常默默然』病人都是安安静静的都不讲话。\n\n    『欲卧不能卧』想睡觉又睡不好，想要走路又没有力 气。\n\n    『饮食或有美时，或有不欲闻食臭时』有的时候很想吃，闻到食物的味道后又不想吃。\n\n   『如寒无寒』看起来好像很冷，你问他冷，他又说没有。\n\n   『如热无热， 口苦，小便赤』。嘴巴又有点苦，小便是黄色的， 看似热症其实又不是。\n\n   『诸药不能治，得药则剧吐利』服用各类的药 又不舒适。\n\n    有时候『如有神灵者』就是突然看到什么神仙怪物之类的异象。\n\n    摸他的脉，稍微有一点数。每次小便的时候就会头痛，『六十 日乃愈』这需要六十天才会好。\n\n  『若溺时头不痛，淅淅然者，四十日 愈；若溺快然，但头眩者，二十日愈。其证或未病而预见，或病四五 日而出，或病二十日或一月后见者，各随证治之。』你说仲师讲的是 什么呢？他讲的是神经衰弱症。\n\n        这个发生在很多的太太妈妈身上，她 们时常制造出许多世界上原本不存在的问题， 比方说，「媳妇重要还 是妈妈重要？ 」可是这不能讲出口，因为心知这是不对的，但是她还是要去表现出很多动作。儿子一回家，两个人拿两双拖鞋在那边，看 儿子会穿谁拿的。日久以后，就有忧，而忧能伤到肺。\n\n        每天在那边想一些有的没有，我常讲，世界上的问题本来都很简单，可是被人想复 杂了。所以很多人有神经衰弱，因此常常生病，生完病以后还是没好。 然后你给他吃小柴胡汤，他吃下去也吐。吃什么药都不好。如果病比较深时，病人小完便就会头痛，但是六十天后慢慢会好。这是病比较深的，因为忧能伤肺，肺主魄、肺藏魄。\n\n        我们的血里面有两样东西， 一个是魄，一个是魂。忧能伤肺，魄就没有办法存在血里面。所以『如 有神灵者』就是肺魄不守。魂不能归肝，就是当肝血伤到后，人会虚弱，在肺气肝血两虚的状态下，这种虚又不是真虚，你真的开补气、 补血的药给他，他身体又不接受，吃完后又将药物吐掉，怎么做都没 有办法帮助他。\n\n       当魂不守的时候，病人就不能睡觉。我们人的睡眠是魂要归肝，人才能睡着。神经衰弱、歇斯底里的人，如果是比较严重 的，他小便一小完「哇，头很痛啊!」为什么？ 因为他身上津液不足， 所以我们在大病之后会看到这种情形。还有一些妇人，一天到晚都在担心子女，或者是一天到晚在喝下午茶，然后专门议论人家长短，自 己没有中心主见，自己也不知道自己想要什么，这种人很多，大部分 都有神经衰弱。\n\n       这种状况之下，张仲景就说：「如果六十天，小便头会痛。」小便头痛，就是病比较重，六十天会好。\n\n      如果『若溺时头不痛，淅淅然者， 四十日愈』就是小便的时候，感觉到耳朵好像有东西在吹，这种感觉， 四十天会好，因为比较轻些。\n\n     如果小便很快、头眩者，二十天就会好。 这是大病之后我们可以看到的。\n\n     这个症候中医叫做『百合病』。因为『百合』就是什么样的症状都有，也可以说他什么样的症状都没有， 你说他没病，他去医院检查他真是没有病，然而他又全身不舒服，如果做到这种人的儿子，那你就要拜我为师了，学会如何使用百合地黄汤，喝下去就好了。\n\n     后面的百合地黄证又分几种，第一种是纯百合证。还有一种是， 本来是百合证，结果被你误汗，还被你误下、误吐，于是再区分为四个方子。\n\n     第一个是纯百合证。『百合病，不经吐下发汗，病形如初者，百合地黄汤主之。』这是最初的条辨，就是单纯的百合病，单纯的百合证就是百合地黄汤证。\n\n     如果百合病被发汗了，就是原本是百合病， 结果被医师误汗了，我们就用百合知母汤。\n\n     百合病如果被误攻下了， 就是百合滑石代赭汤。\n\n     百合病如果被误吐，就是百合鸡子汤。\n\n   「老师， 为什么这些条辨不放在前面去？ 」这不能怪仲师，因为以前是用竹简 做成书的，而门槛又很高，走过去的时候小徒弟不小心勾到门槛，一 摔倒，竹简散开来，怕师父骂。只有赶快收回去，结果就弄错了。现在我将介绍的第一个处方就是百合地黄汤。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-03T02:13:52.000Z', '2025-03-03T02:13:52.000Z', '2025-03-03T02:13:52.000Z', '1、论曰：百合病者 ，百脉一宗 ，悉致其病也。意欲食 ，复不能食 ，常默默然 ，欲卧不能卧 ，欲行不能行，饮食或有美时 ，或有不欲闻食臭时 ，如寒无寒 ，如热无热 ， 口苦，小便赤，诸药不能治，得药则剧吐利 ，如有神灵者 ，身形如和，其脉微数。每溺时头痛者，六十日乃愈；若溺时头不痛，淅淅然者，四十日愈；若溺快然， 但头眩者 ，二十日愈。其证或未病而预见 ，或病四五日而出 ，或病二十日或一月后见者 ，各随证治之。', '2025-03-03T02:13:52.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sF6pqp0QieP', 4, '{"title":"2","description":"<p>2、百合病，不经吐下发汗，病形如初者，$f{百合地黄汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005002,"note":"        百合七枚。诸位到中药店买百合，百合色白，入肺。百合也可以 拿来炒菜煮汤吃。张仲景为什么要用百合？这个百合滚了以后，你如果要煮百合桂圆汤，你最好先煮桂圆，先将桂圆煮熟了，等味道出来汤变浓了以后，再把百合丢下去。百合一放下去，水一滚就关火。你 说：「老师，滚久一点。」滚久了，百合就不见了，变成百合汁，黏黏稠稠的，百合一下就化掉了，所以百合是现在所有食物里面最好消化 的。张仲景一看这个人什么东西都吃不下去，必须找一种最好消化的食物，要比米饭还好消化的，如果连百合都不能消化，病人就危险了。\n\n       百合这个药的性有一点黏黏腻腻的，能够停在肠胃里面增加肠胃 的津液，也因此能够让大便排出去。百合里面淀粉质很多，又能补充 我们的营养。百合入肺，就是说百合这个药能够增加肺的津液。\n\n       为什 么要加生地黄？ 因为一个人情绪忧郁太久，会内生伏热，因为气被郁闷到，没有办法很正常的运转，于是热就会停在下焦，这个时候热会伤到血分，所以用生地黄来治。诸位看到药房里买的生地，你不要以为生地这个药会很明亮，我告诉你，它黏黏的，黑黑的。拿到白的就 是药房在骗你，拿到面粉做的给你。\n","videoMemo":"","fangList":["百合地黄汤"],"bieMing":""}}', '2025-03-03T02:27:43.000Z', '2025-03-03T02:27:43.000Z', '2025-03-03T02:27:43.000Z', '2、百合病，不经吐下发汗，病形如初者，$f{百合地黄汤}主之。', '2025-03-03T02:27:43.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g7qc6Q0X6mq', 4, '{"title":"3、百合病 ，发汗后者 ，$f{百合知母汤}主之","description":"<p>3、百合病 ，发汗后者 ，$f{百合知母汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005003,"note":"       百合病本来就是因为津液不够了，身体很虚，结果医生一看他发热，以为是太阳表症，于是给予发汗药，造成津液被伤到，就是肠胃的津液没了，肺的津液也没了，这个时候病人的身体是在很虚的状态之下，我们开很强的药下去病人身体会不接受，于是病人就会吐掉又拉掉，此时只有靠百合下去把肺的津液先补足，又因为它的黏性与容易消化，因此可以停留在肠胃中，然后靠知母去消除病家的烦躁，因 为知母是除烦的圣药，这就是白虎汤里面有知母的原因。\n\n       百合要拿来做药的话需要先用水来洗净百合，洗完以后再泡一个晚上，看到白的泡沫出来以后，然后再用泉水来煎，泉水就是阴水。中医认为阴水这 个水是未经过太阳晒过，所以它能够把虚热去掉。你说：「老师我真的去挖泉水来煮百合。」这也不必要了，因为自来水已经就是阴水了， 泡自来水就可以。","videoMemo":"","fangList":["百合知母汤"],"bieMing":""}}', '2025-03-03T05:36:06.000Z', '2025-03-03T05:36:06.000Z', '2025-03-03T05:36:06.000Z', '3、百合病 ，发汗后者 ，$f{百合知母汤}主之。', '2025-03-03T05:36:06.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bH0Vtvr4yU4', 4, '{"title":"4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之","description":"<p>4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005004,"note":"          百合病人被误攻下后，就要用百合滑石代赭汤。\n\n         诸位知道代赭石， 代赭石是涩剂，呈现紫色的，止肠痢用的。\n\n        为什么要加滑石？滑石是通利小便的。当病人被误攻下后产生下利不止时，如果要止利的话， 就要用涩剂，再加入利小便的药，把水从小便排出来，不要让水从大便走。因为如果水从大便走的话，身体的营养都会被排掉，小便一旦被排出后，这个利就会自动停止，同时百合会将丧失的津液再补回身体之内。","videoMemo":"","fangList":["百合滑石代赭汤"],"bieMing":""}}', '2025-03-05T09:17:28.000Z', '2025-03-05T09:17:28.000Z', '2025-03-05T09:17:28.000Z', '4、百合病 ，下之后者 ，$f{百合滑石代赭汤}主之。', '2025-03-05T09:17:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SKsrnHbQcDP', 4, '{"title":"5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之","description":"<p>5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005005,"note":"        百合病之人，如果被误吐，怎么办呢？吐了以后会伤到胃的津液， 我们就用鸡子黄，就是鸡蛋黄，蛋黄放在百合汤里面搅和以后，后面说煎五分，其实是不要煎的，一煎以后就变成蛋花汤了，就是百合蛋 花汤。我们是用鸡子黄，就是鸡蛋黄黏黏的下去到胃里面，如果被吐 后用这个鸡蛋黄去补胃因吐而失去的津液，此时所有的方子都不能 用，因为病家不受，这就是百合证。\n\n        临床上看的时候就是西医讲的神经衰弱症，看到都是百合证。有的时候扶病人在路上走，他会左右晃荡晃荡的这样子。家里面只要有一个人这样子就很累了，一天到晚在那边胡思乱想。\n\n        我们为什么不叫他神经衰弱，我们叫它做百合呢？ 因 为西医就是看不出来怎么回事，所以只好罵你神经病，可是又怕你受 的伤害很大，幼小的心灵受到伤害，他就说你是：「神经衰弱」，这样比较好听一点，其实就是在骂你神经病。\n\n        西医没什么药可以治疗神经衰弱。只有中药有，张仲景出了那么多方子，还预防到怕你这个神经 衰弱病人，因为吃坏肚子或被医生误治后，如何做补救都考虑到了。","videoMemo":"","fangList":["百合鸡子汤"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '5、百合病 ，吐之后者 ，$f{百合鸡子汤}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EKUzPaNcY5m', 4, '{"title":"6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之","description":"<p>6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005006,"note":"       如果百合病到了一个月都没有好，结果病人出现口渴，这个时候渴的处理方式就得用百合洗方，洗方就是我们想让百合的药力从皮肤毛孔渗进去。就是把百合泡水，泡了一个晚上以后来洗身，洗完以后吃煮饼。\n\n       这里所谓煮饼，指的是淡面，白的面，越清淡越好，不用加什么盐巴『勿以咸豉也』。\n\n       如果你加很重的盐巴进去，吃下去没有用， 因为咸会把水分散掉。用洗方的目的就是要我们不去攻，因为病家身体里面已经是虚的。虚掉的程度已经到连药都不接受了的阶段，所以我们尽量想别的方法让津液能够进入体内，你看张仲景考虑得多细腻。","videoMemo":"","fangList":["百合洗方"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '6、百合病 ，一月不解 ，变成渴者 ，$f{百合洗方}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZB1PiG3XMRh', 4, '{"title":"7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之","description":"<p>7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005007,"note":"       如果你用百合洗方，洗完了还是照样渴。渴的时候病人水喝下去就下利出去，或是小便流失掉了，反正就是身体不受，渴症本是很简单治的，像是用栝蒌根或是用白虎人参汤之类都可以治渴，如果服用后照样还渴，表示身体已经不受。\n\n        遇到这种渴不解者，我们就要栝蒌、 牡蛎并用。张仲景只有在这个方子中栝蒌牡蛎并用。『渴不解者』口渴的要死，喝水都不能够解渴。栝蒌根，诸位都很了解栝蒌根本身是 味苦又是性寒的药，能够生津止渴。牡蛎咸味、性寒，但是它能够把上焦因渴而造成的虚热导引到下焦来，让虚热从小便走掉，再利用栝蒌根来增加病人的津液，这几个都是百合病的变方。","videoMemo":"","fangList":["栝蒌牡蛎散"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '7、百合病 ，渴不解者 ，$f{栝蒌牡蛎散}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VdagtKmSrR7', 4, '{"title":"8、百合病变发热者 ，$f{百合滑石散}主之","description":"<p>8、百合病变发热者 ，$f{百合滑石散}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005008,"note":"      当百合病人如果变成发热，一直没有好，这个时候我们就要更换为百合滑石散。要靠滑石，把热从小便利掉。滑石本身是利尿剂。原因也有可能是病人本身有百合病又兼到有膀胱结石或者是肾结石。中医讲的热，诸位有一个观念就是『发热者』就是发炎，有破损了，才产生热。\n\n       这时百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。","videoMemo":"","fangList":["{百合滑石散"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '8、百合病变发热者 ，$f{百合滑石散}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S1pj4cxNojX', 4, '{"title":"9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之","description":"<p>9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之。 见阳攻阴 ，复发其汗 ，此为逆 ；见阴攻阳 ，乃复下之， 此亦为逆。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005009,"note":"         这个就是告诉你，所谓百合病，就是病家本身的津液已经虚掉， 身体是持续处在虚的状态之下。所以有时候当身体虚的时候，你看到的是热，好像是阳症，这时你不要开去热的药给他，要用滋阴法，我们要开些滋阴的药，来养阴液，然后再加些去热的药才可以。\n\n       但是你又不可以开太强的去热药，强力去热的药像石膏、知母、 黄苓、黄连，尤其像黄连是很强的去热药。这种病人本身就虚弱，你说他没病他又有病，说他有病他又没病。你如果开很热的药下去他受不了的。或者开很凉的药也受不了的，所以要在临证再决定用什么方法来治疗。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '9、百合病，见于阴者 ，以阳法救之；见于阳者 ，以阴法救之。 见阳攻阴 ，复发其汗 ，此为逆 ；见阴攻阳 ，乃复下之， 此亦为逆。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KtgWGap2K7s', 4, '{"title":"10","description":"<p>10、狐惑之为病，状如伤寒，默默欲眠 ， 目不得闭 ，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭 ，其面目乍赤 、乍黑、乍白，蚀于上部则声嚘，甘草赤、乍黑 、乍白 ，蚀于上部则声嚘 ，$f{甘草泻心汤}主之。蚀于下部则咽干， $f{苦参汤}洗之。蚀于肛者 ，$u{雄黄}熏之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005010,"note":"       狐惑病，就是寄生虫引起的病。这种虫，有的时候可能是血丝虫， 可能是肠子里面的蛔虫，有的时候可能是性病的毒。我们中医不管它 是什么病毒，我们只管如何辨症。\n\n      『状如伤寒』就是看起来很像伤寒， 看起来像麻黄汤证，病人会恶寒发热。\n\n      『默默欲眠』就是想睡觉目又不得闭，眼不得闭是因为病毒跑到肝脏里面去了。『卧起不安』\n\n        如果跑到喉咙上面就会『蚀于喉』，张仲景称为『惑』。\n\n       『蚀于阴』就是阴部长了性病，会看到阴部破损掉了，这些就是西医讲的性病。蚀于阴叫做狐病。\n\n        吃东西吃不下『恶闻食臭』，闻到食物味道胃里面就难过。 \n\n        有时候『乍赤、乍黑、乍白』脸色常常在变化，这种就是属于性病之类的疾病。\n\n       如果是蚀于上部，就是喉咙受到这种病毒侵害的时候，会连声音都变掉了，像有的梅毒病人到末期时连声音都改变了。如果是这样子的话，第一个蚀在喉部时，我们要用甘草泻心汤。蚀在下部则 咽干，用苦参汤洗之。如果是蚀在肛门的话，用雄黄来薰它。\n\n       甘草泻心汤，诸位过去都学过，有心下痞时就会用到甘草泻心汤， 还有就是用在治疗性病时也会用到甘草泻心汤。上次我在美国，讲心脏动脉血管堵塞案例时，当时我第一眼看到他，就知道是甘草泻心汤证。诸位看甘草泻心汤的方子，炙甘草、黄芩、干姜、人参、半夏、 黄连、大枣。这个处方里面没有大黄攻下的药，结果病人吃下去却上 了五、六十次厕所。因为体内所有阻塞住的浊物完全被排出来，我们中医是辨症论治，只因为病人东西吃不下去，胃里面难过，而选用甘车泻心汤来治疗，没想到结果竟然如此。\n\n       苦参汤，平常不要光用苦参来煮，我们还要加一些东西在里面。我们用苦参的时候，一般是用药汤来洗患处，洗阴部，洗男人的生殖器，苦参我们用四两，因为要煮汤水。还需要加一些槐木，再加一些狼牙草等一起煮，我们后面还会介绍。两个都差不多四两，用来清洗患处，阴部给性病腐蚀到的地方。 如果您不幸是零号，肛门受到的伤害会比较严重，这个时候就要用雄黄。将雄黄放在瓦片上，然后在下面生火加热，雄黄加热过后会变成砒霜。\n\n         过去铁匠师父打铁的时候不管他打的是马口铁或是打剑、打铁锹，无论打什么东西，如果想要提高铁的纯度，就要把铁里面杂质去掉，方法就是泡在砒霜水里面。一泡下去，铁中的杂质就会被去掉， 所以它对铁的腐蚀力量很强。你如果用铁锅在下面，雄黄在上面一烧 「啵!」铁锅就会出现一个洞，穿过去了。\n\n        所以我们平常烧雄黄一定 是用瓦片，就是屋上的瓦，你拿一块瓦放在一边先加热，然后用另外 两片瓦把它夹着，让中间有一个小孔。然后要薰的人拿着一块布，千 万不要去闻那个味道，那不是给你闻的，病人就蹲在上面，用布把身体盖好，头露出来，然后在后面的布弄一个小孔，再将雄黄倒上去， 此时一股青烟就会往上冒，你自己也不要闻那个烟，会中毒的，烟往 上冒燻到肛门，肛门腐烂掉的部位受到此烟一燻就会止痛，伤口就会恢复过来了。当然不一定是零号，别的原因造成肛门整个腐蚀掉通通 可以用。平常雄黄如果要加热用的时候，那个烟是又青又黑，闻了以 后就会感觉到好像有人勒到你的脖子，呼吸都会呼不过来，这表示你 中毒了。","videoMemo":"","fangList":["甘草泻心汤","苦参汤"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '10、狐惑之为病，状如伤寒，默默欲眠 ， 目不得闭 ，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭 ，其面目乍赤 、乍黑、乍白，蚀于上部则声嚘，甘草赤、乍黑 、乍白 ，蚀于上部则声嚘 ，$f{甘草泻心汤}主之。蚀于下部则咽干， $f{苦参汤}洗之。蚀于肛者 ，$u{雄黄}熏之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WAl6mIwBVz1', 4, '{"title":"11、病者脉数，无热微烦，默默但欲卧 ，汗出","description":"<p>11、病者脉数，无热微烦，默默但欲卧 ，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也， $f{赤小豆当归散}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005011,"note":"       『病者脉数，无热』就是摸到病人的脉很数，但是却没有发热， 这就是辨症。有热的话还好，代表病在表。\n\n        如果病人『微烦，默默但 欲卧，汗出。初得之三四日，目赤如鸠眼』看过鸠眼没有？就是眼睛 红红的，眼白部位全部是红色的，只有眼珠是黑色的。\n\n     『七八日， 目四皆黑』眼睛这里四周整个眼框都变成褐黑色的。如果病人能够吃， 表示脓已成，不管病人是腹膜炎、胆结石以后破裂掉了，或是盲肠炎失治，结果阑尾破掉了，变成腹膜炎。或者是外伤伤到了，身体里面 发炎，或是三焦网膜上发炎，我们身体内会产生一薄膜，会把这些炎 症固定在一个地方，这是我们人体的一个自动保护机制。在没有破又 快要破的时候会很痛，像急性盲肠炎，下腹部会很痛，如果来不及开刀，阑尾就会破裂掉，破掉后病人会说：「哎呀!不痛了。」于是可以 吃东西了。\n\n        这个时候时常连医师在检查，包括护士在内有时候都会产生误诊。西医看：「没有啊，病人不痛啦，都好啦。」病人送到医院后， 已经不痛了，其实是已经转腹膜炎了。实际上，你摸他肚子原来痛的地方，整个是滚烫的。此时中医一看就知道，张仲景就告诉你，你看病人眼睛周围是黑的，就代表里面已经化脓了，不痛的原因是因为已经破掉了。所以如果是我们中医看诊就不会错了，我们在阑尾点附近找寻压痛点，出现强烈压痛现象，就代表腹部有化脓了。\n\n      一看眼袋是黑的，就确定是里面发炎了。再一摸脉，脉是很数的，代表里面是热 的。病家没有表症，但是脉跳得很数，就代表里面有热，没有发烧就是没有表症，结果也表示里面已经化脓了，这种情形发生时，就是赤豆当归散。当归赤小豆散我们在使用的时候，这个当归是生用，赤小豆从药房买回来以后，需要把它放在水里面浸两三天，等到它发芽， 赤小豆要发芽后用。一般我都是先发一些芽以后冷冻储存起来，以备不时之需用。\n\n       为什么要发芽？ 因为我们脓成的时候，在身体里面、腹 膜里面它的渗透里很强，渗在四周旁边。如果直接用赤小豆来去脓的 话只能将中间的脓排除，四散在旁边的脓就没有办法清干净，所以仲师要让赤小豆发芽以后用，这就是技巧了。\n\n        当归本身就是入血分，能够把赤小豆带到血里面去，然后赤小豆 就可以去它的湿。大家看，脓已经成了就会湿湿黏黏，赤小豆能够同 时去湿去热，一旦化脓后就必然伤到血，所以要用当归造血，让新的 血过来，让它补病家丧失的血，当归赤小豆散是我们中药里面很有名的专门治疗腹膜炎用的处方。如果是给西医治疗腹膜炎，病人就只能 躺在病床上不要动，然后每天给你打抗生素，连动都下能动，一动就剧痛。\n\n          以前我一位学生就是护士，她就是得到腹膜炎躺在病床上躺了一个月，她说：「早知道就用当归赤小豆散，药房才卖十五块钱一付。」 平常你的诊所就要先将赤小豆发好芽，等到有病人得到腹膜炎后再去泡会太慢，然后是：「老师这个赤小豆孵不出来!」紧张死了。「老师这个病，是否一定要等到有脓的时候才可以用？ 」对!譬如说在先前  还没有化脓的时候，我们有尚未化脓的治法。这是脓成后专用的，如何分辨病人的脓已成就是要看症。所以当病人胃口很好，可以正常的吃饭，但是眼睛四周却黑黑的，然后摸病家的脉是数的，可是又没有表热，就表示已经化脓了。赤小豆我用的很多，不但能够去热而且能够解毒，腹膜炎产生的毒素它能够把它解掉，是治疗腹膜炎很有名的药，凡是遇到溼热的毒，张仲景通通会使用到赤小豆。","videoMemo":"","fangList":["赤小豆当归散"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '11、病者脉数，无热微烦，默默但欲卧 ，汗出。初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也， $f{赤小豆当归散}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dST0A9IV40x', 4, '{"title":"12","description":"<p>12、阳毒之为病 ，面赤斑斑如锦纹 ，咽喉痛 ，唾脓血 ，五日可治，七日不可治，${升麻鳖甲汤}主之。阴毒之为病，面目青， 身痛如被杖 ，咽喉痛 ，五日可治，七日不可治，${升麻鳖甲去雄黄蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905005012,"note":"        过去西医有一种病，名字叫做斑疹伤寒，中医就叫阳毒。这类阳毒常见于战争的时候，在战场上，还有牢狱里面，或在船舱里面，还有落后的地方，也常常会看到。\n\n       为什么会造成这样子？西医到现在只知道这个病毒传染的很快，世上比痲疯病传染的速度还要快的就是这个，被传染到就是死。西医到现在还不知道它真正的原因是什么，但是看到这个病的时候，第一个动作就是：赶快将病人隔离开来。\n\n        斑疹病发起来的时候，是从肚子这边开始发生，如果我们中医看到斑疹是红色的，十生一个死。如果看到这个斑疹是黑色的，十死一生，也就是说黑色的最危险。西医知道此病的传染力很强，没有任何西药可以治它。所以遇到这种状况的时候，赶快就把病人所有触碰过的东西通通集中起来，一把火烧掉。\n\n        如果这个传染病发现在战争的时候，久战的士兵身上被传染到的 时候，这感染会漫延得到很快，发病时是从身体肚子部位一直蔓延到 四肢上面，速度很快，之后一两个礼拜人就走了，此时它就被叫做「战争伤寒」。如果发生在监牢里面的时候就叫做「牢狱伤寒」。在船舶上： 「船舶伤寒」。想想看这些地方的共同点。第一个，病人都是表不固， 因为他们的饮食都不能很正常。第二个，都被局限在一定的范围，没有很自由的活动空间，也因此大部分都会得到这种病。\n\n          中医过去一个叫阳毒，一个叫阴毒。阳毒，主要症候是『面赤斑 斑如锦纹，咽喉痛』。阴阳毒都有咽喉痛、吐脓血。体内里面太热了就是阳毒，就是所谓的升麻鳖甲汤证。\n\n         如果你看到『面色青』『身痛 如被杖』好像被鞭子毒打一顿的样子。为什么会有这种感觉呢？ 因为 血都的流动速度减缓了，就是血将停止流了，由于病人血液循环不流畅，因此病人全身感觉到就好像被鞭子抽打般的疼痛。\n\n         如麻黄汤证也有身体疼痛的症状，这是因为表被寒束住，造成太阳寒水无法正常循 环全身，因此产生疼痛感一样，但是太阳症是表水不通，这里的阴毒是血液循环不通，二者完全不同。\n\n       临床上在用这里的处方时，有包括疱疹，就是所谓的带状疱疹。发生带状疱疹的地方就好像被鞭子打一 样，很疼痛，此时我们都可以用到这些方剂。 方剂里面有鳖甲、雄黄、 升麻，在本草里面有介绍过升麻，我上次说到麻黄升麻汤，升麻除了升提津液的作用，升麻也是解毒用，能解百毒。这个时候选用鳖甲是因为鳖甲本身并没有毒性，但是鳖甲的性很刚烈而且坚忍，又由于鳖 甲是入肝经，当鳖甲遇到当归时，由于鳖甲本身能直入血的最深处， 当归跟鳖甲混在一起的时候，就可以跑到肝里面去了，进入肝后肝脏 会变的很刚硬很坚强，而肝脏就不会受到病毒的损害。所以首先将病人的命先保住，张仲景很知道如何灵活运用鳖甲。\n\n        我们使用鳖甲的时候只要手指一片大，约三钱就可以了。然后发散病毒出去的就要靠几个解毒药，靠升麻、甘草，甘草本身就解百毒， 蜀椒的性很辛、很热，也能解湿毒，蜀椒和雄黄都是阳性的药，蜀椒入肺，我们后面将会介绍的大建中汤就会用到蜀椒，蜀椒是阳性的药， 所以走阳、走气、走气分、走表。斑疹伤寒这些病毒都在表上面，所 以他开的鳖甲当归先去固肝，不要让病人在毒未解除时先死掉，使用这些升麻、甘草、雄黄，都是解毒的药。你千万不要把雄黄加热以后吃下去，这会造成你不是死在阴毒，而是死在砒霜毒，人被毒死的时 候，其症状是舌头会伸出来，肥肥大大，舌苔是青色的，皮肤都是红 色的，这就是被毒死的。\n\n       如果是遇到阴毒，就是脸色发青、病人有高热，发起来的斑是黑黑的，这个时候我们晓得，这个毒是在血分不在气分，这个时候就要把蜀椒跟雄黄取出不用。\n\n       病人此时是不需要阳药，因为是病毒是在血分，就是血被凝固到了，所以此时需要将雄黄、蜀椒拿掉，雄黄、蜀椒被取出后就是升麻鳖甲当归甘草，就这四味药。临床上除了现在看到西医讲的斑疹伤寒，过去还有人在瘴疠区得到此类疾病，就是在我 国西南一带云南贵州这些地方的瘴气中得到这种病，其传染的速度非常之快。如果大家都会用这个处方，就可以救很多人。西医到现在完全没有办法治疗。\n\n        『升麻近人多以为升提之品』所以我们有麻黄升麻汤，有寒热互 结症状出现时，就是麻黄升麻汤。『在本经则主解百毒』在神农本草 经里面注『解百毒』。『甘草亦解毒』甘草也是解毒。『鳖甲善攻，当归和血』这两个，一个破它的血，一个和它的血。实际上当归和鳖甲， 最主要鳖甲的性是刚而且坚，护卫肝脏的，不要让这个病毒进去。当 然我们后面会介绍很多，大家会逐渐对伤寒谕的条辨更加了解，也同 时在读金匮的时候会更了解为什么会这样子。诸位再看下章的疟病。","videoMemo":"","fangList":["升麻鳖甲汤","升麻鳖甲汤去雄黄蜀椒"],"bieMing":""}}', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '2025-03-06T06:10:00.000Z', '12、阳毒之为病 ，面赤斑斑如锦纹 ，咽喉痛 ，唾脓血 ，五日可治，七日不可治，${升麻鳖甲汤}主之。阴毒之为病，面目青， 身痛如被杖 ，咽喉痛 ，五日可治，七日不可治，${升麻鳖甲去雄黄蜀椒}主之。', '2025-03-06T06:10:00.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'OeVFpYJ6TYW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NsQNogOruK2', 4, '{"title":"1","description":"<p>1、师曰：疟脉自弦 ，弦数者多热 ，弦迟者多寒 ，弦小紧者下之差 ，弦迟者可温之 ，弦紧者可发汗 、针灸也，浮大者 可吐之 ，弦数者 ，风发也， 以饮食消息止之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006001,"note":"       『师曰：疟脉自弦，弦数者多热』弦脉就是少阳的脉，我们摸到病人出现弦脉，大部份都有往来寒热，忽冷忽热的现象。不管是少阳证还是疟疾，只要是忽冷忽热就是，\n\n      『弦数者』数就表示热，\n\n     『弦迟者 多寒』脉迟者就是寒，但是弦脉是一样的，弦脉就是摸到的脉呈现细 细的直直的，像吉他、钢琴的弦一样，很细直。\n\n     『弦小紧者下之差』 当脉是弦而且紧，就代表是半表半里，如兼有阳明证时，必须攻下， 就是所谓的大柴胡汤证。\n\n      如果脉出现『弦迟者可温之』就是所谓的四逆汤证，四逆汤本身就是温中用的。\n\n     『弦紧者可发汗』如脉是弦而且紧，就要利用针灸了。\n\n      如果『浮大者可吐之』当脉出现浮大时，表示胃中有宿食不消，就得用吐法取吐解病。\n\n      如果是『弦数者』弦而且很数，代表说身体里面是往来寒热，但是数又代表热，是由风发的，这时要看他以『饮食消息止之』临症上，一般我们都是从脾胃上着手开始治疗。\n\n     所有的疟症治法，无论往来寒热，首先要强健病家的脾胃， 就是所谓的饮食消息，比如说病家食物吃太少，我们就开健脾整胃的药。如果吃东西会下利，我们就开止利的药，去调他肠胃就可以了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '1、师曰：疟脉自弦 ，弦数者多热 ，弦迟者多寒 ，弦小紧者下之差 ，弦迟者可温之 ，弦紧者可发汗 、针灸也，浮大者 可吐之 ，弦数者 ，风发也， 以饮食消息止之。', '2025-03-06T09:31:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QKMoNOP8EQw', 4, '{"title":"2、疟病结为癥瘕 ，如其不差 ，当云何","description":"<p>2、疟病结为癥瘕 ，如其不差 ，当云何？</p>\n<p></p>\n<p>       师曰：此名疟母， 急治之。 以月一日发 ，当以十五日愈 ；设不差 ，当月尽解， 宜$f{鳖甲煎丸}。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006002,"note":"       疟病之后如果结成一块停在腹中，症状如癥瘕，如果发生在三焦 淋巴系统里面，我们可以用小柴胡汤把它和解出来。\n\n       张仲景说：「结成一块的时候这叫做疟母。」就是长在肚子这边，像痞块样，绷起来硬梆梆的，必须赶快治，『以月一日发，当以十五日愈』一般来说半个月会好，如果没有好的话，应该『当月尽解』，此时当使用鳖里煎丸。伤寒论里面以麻黄升麻汤的汤剂内使用药物最多，金匮里面以鳖甲煎丸证的汤剂内使用药物最多。一般疟病会集中在一起成为疟母， 多发生在病愈之后。\n\n        一般来说疟会聚集在一个地方的只有寒疟会，热疟不会，热是会四散的，寒的疟才会凝固，凝聚在一个地方。\n\n       大家看处方内容，鳖甲， 这个我们刚刚介绍过，中间这个是鼠妇，鼠妇这个药本身是在妇科里面用的，专门治疗月经闭经，可以消血癥，就是有血块停留在子宫里造成阻塞，就会产生女子闭经，这时我们会用到鼠妇。\n\n       鼠妇是很毒的药，一般用量很小，这里是做成丸剂。石苇这个药在本草里面讲，专门治劳热，劳热就是虚热。平常我们都不会用到这个药，只有鳖甲煎丸，我们才会用到。紫葳这个药跟鼠妇是一样，也是专门治疗这种癥闭。\n\n      经方里面用来攻坚的药物，像鼠妇、紫葳这种药物就是在攻坚。 还有『方中用桃仁蟅虫蜣螂鼠妇之属』目的是要破除瘀血，因为疟母 在腹腔里会聚集在一处地方。\n\n       中医的观念里面是认为，这种疟病会突破我们的肠壁，当疟病在三焦油网、淋巴系统里面跑的时候，就会出现忽冷忽热的症状，如果突破出来，疟病就会凝聚在一起，就会影响我们的血液循环造成血管会破裂掉，血会瘀阻在一个地方，加上病人 痰会很多，造成里面整个都是血和痰混在一起，临症上看到就是这样， 所以会选用到很多祛痰的药。像这类瘀血，流出血管到了我们的组织 中间，又碰到痰，这痰本来就是很容易滋生病毒，病毒是最容易生存 在这种湿稠稠的地方，它最喜欢待在这样环境里面，再碰到瘀血停在 这里，瘀血又供给这些病毒营养，所以就形成一个很大的硬邦邦的块状物。\n\n       遇到这种情形，西医也是只有开刀进去把它挖出来。中医就是用鳖甲煎丸。鳖甲煎丸非常不好制做，因为很多药已经找不到了。葶苈是用来涤痰的，后面我们肺痈会介绍到葶苈子。\n\n      『君鳖甲以攻痞』 硬块，鳖甲不但可以护卫肝，而且也可以攻血。\n\n      『又参用小柴胡汤以清少阳』所以大部分疟疾我们都是小柴胡汤的加减。\n\n     『干姜桂枝以温脾，阿胶芍药以通血，大黄厚朴以调胃，赤硝瞿麦以利水而泄湿』赤硝，就是芒硝。这里用丸剂，要用丸剂就是能够取它的药缓力重。如果用汤剂，走得太快，没有办法完全让药渗到疟母的地方，由于这种症状我们看到并不是很多，临床上我们治疗这类病时，很可能我们不容易把这个鳖甲煎丸做成，所以实际上我们必须用针灸配合处方来治疗它。\n\n       一般我们看到这种堵在肚子里的气块，按照张仲景的陈述，病人 会往来寒热，所以我们选穴下针很重要。\n\n       我记得我在讲针灸的时候， 像外关穴可以通利三焦，血的**穴『委中穴』我讲过是专门治疗霍乱、 疟疾的穴位，然后利用小柴胡汤来做加减，你可以用加入一些攻血的药和攻痰的药在里面。现在药房还可以买到的像蜀漆就是很好的祛痰 的药，葶苈子是攻水的药。还有祛血攻血的药，像桃仁、红花，都可 以加在小柴胡汤里面供用。下针的话外关、委中穴就可以了。如果没 有这个鳖甲煎丸，我们可以用我们的方法来制作药丸，当然时间会拖 长一点，还是会好转的。","videoMemo":"","fangList":["鳖甲煎丸"],"bieMing":""}}', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2、疟病结为癥瘕 ，如其不差 ，当云何？ 师曰：此名疟母， 急治之。 以月一日发 ，当以十五日愈 ；设不差 ，当月尽解， 宜$f{鳖甲煎丸}。', '2025-03-06T09:31:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2qNKv6ZF83z', 4, '{"title":"3","description":"<p>3、师曰： 阴气孤绝，，阳气独发 ，则热而少气 、烦冤 ，手足热而欲呕，名曰瘅疟；若但热不寒者 ，邪气内藏于心，外舍分肉之间 ，令人消铄肌肉。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006003,"note":"       什么叫阴气孤绝呢？第一个，病人失津，就是津液丧失了。比如 说被吐、下、汗，使得津液都流光了。第二个，亡血，不但津液丧失 了，血也不足了，这种状况就是阴气完全没有了。这个时候就会出现 『阳气独发，则热而少气』，病人表面上看是发热，但是这种都是属于虚热。\n\n    『手足热而欲呕，名曰瘅疟』，这种疟，看起来像是阳明证， 属于但热不寒，是因为热闷在里面产生的。\n\n     『若但热不寒者，邪气内藏于心』就是在胃的地方，外面这个热，又潜伏在我们的肌肉关节中 间，一样是属于疟的一种。造成病人越来越瘦，上吐下泻，然后忽冷忽热，这就是疟毒，如果这种病毒停在胃里面，然后又停在我们的肌 肉中间，这就叫做瘅疟，\n\n    『令人消铄肌肉』。临床上遇到这种情形的时候，我们一定会用到小柴胡汤。「老师，病人是但热不寒，但是同时津液也伤到了，所以兼有失津。」此时小柴胡汤就需要加白虎之类， 这就是张仲景的想法。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '3、师曰： 阴气孤绝，，阳气独发 ，则热而少气 、烦冤 ，手足热而欲呕，名曰瘅疟；若但热不寒者 ，邪气内藏于心，外舍分肉之间 ，令人消铄肌肉。', '2025-03-06T09:31:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z7Hr74GEDnj', 4, '{"title":"4","description":"<p>4、温疟者 ，其脉如平，身无寒 ，但热 ，骨节烦疼 ， 时呕， $f{白虎加桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006004,"note":"        瘅疟和温疟不一样，温疟，你看『时呕』，『脉如平，身无寒，但热，骨节烦疼』就是说热是在肺里面，所以我们感觉到并没有在肠胃里面。前面条辨说的瘅疟，是发生在胃里面，所以是小柴胡汤加入白虎汤。\n\n       这里说的是治温疟的主方，石膏、知母、甘草、粳米这是白虎，加了桂枝。温疟的病本来是来自太阳经热，后来部分已经进入阳明成 热了，部分又进入肺。而瘅疟大部分还停留在肠胃里面。所以两个疟 看起来很类似，实际上，症状稍有不同，应该分开来看。\n\n        在临床上只要记得，但热不寒就是阳明证。然而到底该是白虎加 重还是桂枝加重，这个时候就要看他的太阳证有多少，太阳证少，阳明证多，就一定是加重使用白虎。如果是脉浮的话，就是太阳证多， 阳明证少，此时就用重用桂枝。","videoMemo":"","fangList":["白虎加桂枝汤"],"bieMing":""}}', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '4、温疟者 ，其脉如平，身无寒 ，但热 ，骨节烦疼 ， 时呕， $f{白虎加桂枝汤}主之。', '2025-03-06T09:31:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OQBmnhAxchD', 4, '{"title":"5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之","description":"<p>5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006005,"note":"        这个是寒痰所造成的饮症，平常我们的痰饮分为两种，大部分是属于热痰饮，像抽烟的人，或者是过去吸食鸦片的，大部分都是热痰， 吐出来很浓稠很黄的胶痰。\n\n        如果遇到寒痰堵到，寒疟讲的就是寒痰， 临床上看就是痰饮，中医叫做『牝疟』，是蜀漆散证。\n\n       蜀漆的另外一个名称又叫做常山苗，它祛痰的力量非常的强。吃下去的话浊痰会很容易的咳出来，而且是整块的出来。\n\n       云母石，把它打碎以后，先烧个两天两夜，先炙过烧过就是要去它的天然毒性。金石类的药物使用前都要炼过，炼过以后才能去掉它的毒性，把我们需要的药性留下来，就是取它们的阳性。这里的龙骨，实际上我认为是跟牡蛎弄错了，应该要用过牡蛎比较好。\n\n       因为这是寒疟，而牡蛎能够攻坚把胶痰打散， 所以蜀漆散这个药是专门治寒痰用的。\n\n       寒痰停于心胸之间，『心』讲的就是胃，就是心下腹部中间这一 带，大家看这个云母石，『云母石本经主治中风寒热，如在舟车，是 为止眩晕镇风阳之品』而牡蛎，中医用牡蛎来治咳逆，专门去痰水。 当痰哽在胸胃中间的时候，如果是热痰，我们可以用皂夹丸来祛痰。\n\n       寒痰的话要把痰从口中吐出来，蜀漆吃下去，病人的积痰是得吐则解的。牡蛎味咸，本身又能够止咳，能够降逆，所以应该不是用龙骨， 龙骨比较着重在潜阳，我们的桂枝汤加龙骨牡蛎就是如此，其中加了 云母石，云母石是一个镇晕眩的药，为什么要这样使用呢？ 因为如果 是水隔在中焦，也会造成头眩，这是苓桂术甘汤证。\n\n      如果中焦不是水隔到，是痰隔到了，苓桂术甘汤下去就没有效果，这个时候我们要先把痰去掉，不去掉病人头昏不会好。这种头昏，必须要靠云母石，专 门通利中膈，才能解决头昏的问题。所以寒痰隔在中焦的时候，病人 也会有眩晕的现象，这个时候就要靠云母石。你看，上三味把它捣为散来吞服，就是服药粉，不要煮成汤剂来吞服。\n\n        中医过去对疟证有一个观念，就是所有的疟都有痰，临床上看到 有往来寒热，无论是间日疟、隔日疟、一日疟都有，所以有句话叫做 『无痰不疟』。\n\n       因此不管病人的痰到底是寒痰还是热痰，当我们在决 定处方怎么设计时，无论是什么处方通通都会加入祛痰的药，也因为 痰所在的位置不太一样，我们加进去祛痰的药和处方就稍有区分，这些是在临床上检查病人后再决定如何使用。\n\n      像我在治疗心脏时，我们有一个病人，心包被痰哽到，无论怎么咳也咳不出来，就一直哽在里 边，造成连呼吸时胸口也会痛，查又不是心脏病，可是痰哽在这边又很难受。我就开了桂枝汤加蜀漆龙骨牡蛎救逆汤，当蜀漆下去后，一 下就咳出痰来，好大的一粒出来，连续咳出好几颗来，从此胸腔气闷 就四散开了。\n\n       临床上开处方时不能写蜀漆，写常山就可以了。蜀漆药房买不到， 就用常山苗来代替。其实蜀漆跟常山苗不一样，可是因为没有真正的蜀漆，所以现在都用常山苗来取代它，实际上两者是不一样的药物。\n","videoMemo":"","fangList":["蜀漆散"],"bieMing":""}}', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '2025-03-06T09:31:20.000Z', '5、疟多寒者 ，名曰牝疟 ，$f{蜀漆散}主之。', '2025-03-06T09:31:20.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sJSa2McJnib', 4, '{"title":"6、《补充》$f{牡蛎汤} 治牝疟","description":"<p>6、《补充》$f{牡蛎汤}   治牝疟</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006006,"note":"附《外台秘要》治牡疟。","videoMemo":"","fangList":["牡蛎汤"],"bieMing":""}}', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '6、《补充》$f{牡蛎汤} 治牝疟', '2025-03-07T02:01:41.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IiviH41di7A', 4, '{"title":"7","description":"<p>7、《补充》$f{柴胡去半夏加栝蒌汤}    治疟病以发渴者，亦治劳疟。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006007,"note":"附《外台秘要》柴胡去半夏加栝楼汤,治疟病发渴者，亦治劳疟。","videoMemo":"","fangList":["柴胡去半夏加栝蒌汤"],"bieMing":""}}', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '7、《补充》$f{柴胡去半夏加栝蒌汤} 治疟病以发渴者，亦治劳疟。', '2025-03-07T02:01:41.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vf35kOPaW0i', 4, '{"title":"8、《补充》$f{柴胡桂姜汤} 治疟寒多微有热，或但寒不热","description":"<p>8、《补充》$f{柴胡桂姜汤}    治疟寒多微有热，或但寒不热。（服一剂如神）</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905006008,"note":"","videoMemo":"","fangList":["柴胡桂姜汤"],"bieMing":""}}', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '2025-03-07T02:01:41.000Z', '8、《补充》$f{柴胡桂姜汤} 治疟寒多微有热，或但寒不热。（服一剂如神）', '2025-03-07T02:01:41.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Sb94nnnZSf2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RNe8ZL5xbu7', 4, '{"title":"1","description":"<p>1、夫风之为病 ，当半身不遂 ，或但臂不遂者，此为痹，脉微而数 ， 中风使然。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007001,"note":"       所谓痹的定义就是感觉是麻木不仁。中医有风痹，有血痹，后面都有介绍。血痹与虚劳的病脉放在一起。一般来说风痹，就是肌表麻 木不仁没有感觉，皮肤会变得很粗糙，有的人半身不遂，有的人但臂不遂，中医把这个所有中风归类为气血两虚。\n\n       如果我们气血很足，中风了，就是桂枝汤证或是麻黄汤证或是葛根汤证。\n\n       当病人本身气血两虚时得到中风时，就会有中风的症状了，所以中医在治疗中风时，我们都是把病人血补足，或是把气补足，一般都是在这个角度上面着手。 \n\n       现代许多人，认为吃降血压药就可以预防中风，但是现在许多人吃了降血压的药，结果还是中风，很多证据显示西药是无法预防你得到中风的，量血压并不代表可以帮你预防中风，因为血压是会受到心情影响的，我们不可以将之做依据来判断此人是否中风。\n\n        像『但臂不遂者』，这是虚劳。中医过去认为是房劳，房事太多， 或者是工作太操劳造成了气血两虚以后，有的人是直接瘫痪掉了，也有人是从背后上来，从督脉上来会造成整个手臂都麻掉了，中医通通归之为痹，是属于风痹。\n\n       脉是微脉，微脉代表血虚掉了，就是脉很细弱。\n\n      数脉代表风脉，所以病人是血虚又得到风的现象，这就是中风。\n\n      中风的时候可以针药供施来治疗，例如一个临床案例，用麻黄汤外加防风、党参、当归、川芎、熟地然后找针家来针手足三里、曲池、 委中、肩井、合谷、环跳、跗阳、丰隆、蠡沟等穴，病人有伤寒的现象，因为表有寒症，但是又同时兼有里虚，因此开麻黄汤的同时还需要加入很多补虚的药进去，像党参、当归、川芎、熟地都是补气补血 的药，防风能够补表，帮助麻黄来解风。\n\n       下针的话，我们有中风七大穴。以前很有名的经方家曹颖莆先生就是专用汤剂处方，需要针灸时是找另外针医来针的，过去很少有一个医师同时懂药又懂针。\n\n       遇到中风病人我们下针的手法，第一个原则，是先补健侧，第二 个动作是泻患侧，就是好的那边，我们用补的方法下针，用补的手法作捻转或是插提。坏的那边，用泻的手法进针，用泻的手法作捻转， 第三个原则是选穴，我们选的穴位是肩髃、曲池、外关这是手上三个中风大穴，脚上三个中风大穴是环跳、风市、阳陵泉。再加上背针， 就是针风府穴。\n\n        如果病人舌强不语，嘴巴不会讲话，就需要针百会穴， 这是针灸治疗中风时我们时常在扎的穴道，这些都是治疗中风的基本穴道。\n\n        其他穴道的选用，大家可以临症来做取捨。比如说加足三里，可以加强病家的胃气，灸足三里可以预防第二次的中风。因为中风本来就是气血两虚，气血两虚就是因为肠胃吸收不好才会有的症状，这个 时候我们针下足三里胃经的本穴，让病人的肠胃吸收变好，因此灸此穴就可以预防病人第二次的再中风。\n\n        出现中风先期症状时中医可以预 防，中风了以后我们去治疗也可以预防他第二次再中风。先期中风的是有先兆的，像我们手脚会麻，表示两个月以内会有机会中风，如果脚前面足三里，足阳明胃经会麻，两个礼拜以内就会中风。\n\n        中风前就已经有肌肤不仁的现象，这个时候就应该要开始动手了。如果这个时候脚麻或者手麻你跑去找西医，西医就要病人去看外科，检查看看你有没有风湿。或是去验血，验完血出来看到你在外面已经中风躺下去了，中医知道这是将要中风的预兆，并不是什么风湿关节炎引起的麻木。\n\n        临床在急救中风时，如果病人已经昏迷过去，我们的针法又不一 样。刚才讲的是用在治疗中风以后的穴位选取，急救的时候我们下针下百会、人中、十宣放血然后再扎涌泉，把病人当成脑溢血来治。如果病人在然谷穴那边有瘀青筋一块浮起来，就在然谷穴直接放血，百会也放血，十宣也放血，这是中风昏迷时的急救法。\n\n        如果这套针法针 下去病人还没醒过来怎么办？在内经里面有说明治法，大家记住要在病人左额角位的地方，拿剪刀把这块一寸方圆的头髮剪下来，拿火一烧，变成黑黑焦焦的，烧成粉。然后把针管拿出来，当成发焦散，把它直接吹到病人的耳朵里面去，人就会醒过来，这个是攻脑部瘀血的利器。一喷进去的时候，鼻子会出血，当鼻血一出来，脑部的瘀血就会整个跟着一起从鼻子出来。这是我们治疗植物人的绝佳治法。\n\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-07T04:02:47.000Z', '2025-03-07T04:02:47.000Z', '2025-03-07T04:02:47.000Z', '1、夫风之为病 ，当半身不遂 ，或但臂不遂者，此为痹，脉微而数 ， 中风使然。', '2025-03-07T04:02:47.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4OkmOjEnb0V', 4, '{"title":"2","description":"<p>2、寸口脉浮而紧，紧则为寒，浮则为虚 ，寒虚相抟 ，邪在皮肤 ，浮者血虚，络脉空虚，贼邪不泻 ，或左或右 ，邪气反 缓 ，正气即气即急 ，正气引邪 ，喎僻不遂。</p>\n<p></p>\n<p>       邪在于络 ，肌肤不仁 ；邪在于经，即重不胜 ；邪入于府 ，即不识人 ；邪入于藏 ，舌则难言 ，口吐涎沫。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007002,"note":"       『寸口脉浮而紧』。寸口脉代表胸、代表上焦、代表胸阳、代表 肺、代表心脏，这是寸口脉。寸口脉如果是浮而紧，\n\n      『紧则为寒，浮 则为虚』。浮脉再深入一层的观念，中医认为『气行脉外』『血行脉内』。 浮脉的意思是如果你摸上去感觉脉跳得很大，但是脉的里面很小，就 是说脉的外侧比较大，里面比较小。就是气比较旺，血衰掉了，正常 的脉是脉里面很洪大才对，你只摸到他的浮脉代表气脉，没有摸到血 脉，浮则为虚，就是血虚掉了。\n\n     『寒虚相抟』大家都知道紧脉就是寒脉，当寸脉是浮脉而且又是紧脉时，我们知道病人是寒虚相抟，这就代表邪在皮肤。\n\n    『浮者血虚』浮脉就是血虚。所谓『络脉空虚』我们人体皮肤最表面是孙络，再里面一层是络，再深的靠近我们筋骨血脉 旁边的就是经，经是最大条的。但是比较深的，再浅一点是络，在皮 肤表面上是孙络，好像树枝密密麻麻的一样。如果『络脉空虚』就是经的血还足够，但络脉的血不够，\n\n   『贼邪不泻，或左或右，邪气反缓， 正气即急，正气引邪，喎僻不遂。』这意思就是说，如果邪是在右边 的时候造成气血不通，左边的血是好的，结果左边的气血会把右边的 气血牵引过来，于是就造成右边瘫痪掉了。\n\n     『邪在于络』就是说风邪只是停留在络上面，不在经上面，病人感觉到的是『肌肤不仁』就是麻木不仁感。\n\n      如果『邪在于经』到了血脉神经很深的地方时，病人感觉到的是『即重不胜』，就是四肢感觉到很沉重。\n\n      如果邪跑到腑里面 去，主症是『不识人』。\n\n     血入腑，就是邪进入脑部，影响记性，必不识人。\n\n     如果『邪入于藏』藏就是属于心脏这个部分，我们藏神的，心开窍在舌，『舌则难言』就是讲不出话来，\n\n    『口吐涎沫』这是我们用外症、表面症状来判断这个病在哪里了，现在诸位了解我们中医有分中风在络上面，在经上面，在血脉，在腑里面，所以我们下手治症的时候治法都不太一样。\n\n      但是所有中风的病人除了在经、在脉、在络上面的这类中风，一年两年找中医治尚没有关系。但是如果病情入腑入脏后，已经半身不遂了，嘴巴讲不出话，这种情形一旦超过一个月后再来找我们就没有用了，可是西医往往就让病家两三个月后再来找我们，这时已经失去治病的时机，而这病是不会立即产生死亡的，因此造成许多病人长年卧榻的悲剧。\n\n     『世传中风不语用黄耆防风各数两，煎汤』用汤药的热气来薰病人全身，也就是利用黄耆跟防风的药气，这个汤叫做『黄风汤』。\n\n       经方的观念里面，处方的时候，是以养血补正气，来预防中风，黄耆可以固表，是非常好预防中风的药，防风也是补正气固表的。党参就是补气的。当归，川芎是能入血分的药，也都是很好的补血药，补气补血药物同在一方中，当病家的气血足了，就不会中风。\n\n      中医的观念和西医的观念是不一样的，西医是看片段的病况来做决定。所以只看到片段的『中风引起的脑淤血』，脑部出血了，于是就想尽办法事先将你血压降下来，希望不要让你脑部充血，可是他们不了解光降血压是 没有用的，只是降到形没有神，人不是植物，人都有喜怒忧思悲恐的， 情绪起伏大时，会造成你血往上走，药物只是降到形，所以没有用， 如果要吃西医降血压的药，想要有效的话，基本上你必须要去闭关， 到庙里去打坐，然后一个月、两个月都不要见到亲朋好友，从此以后 你就一直闭关在那边，才不会中风。\n\n       可是你如果有办法闭关远离亲人 的话，你也不需要降血压的药，因为你不会中风了。今天的课介绍完 以后诸位将有很多方剂可以使用，在治疗中风上帮忙很大。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-07T04:02:47.000Z', '2025-03-07T04:02:47.000Z', '2025-03-07T04:02:47.000Z', '2、寸口脉浮而紧，紧则为寒，浮则为虚 ，寒虚相抟 ，邪在皮肤 ，浮者血虚，络脉空虚，贼邪不泻 ，或左或右 ，邪气反 缓 ，正气即气即急 ，正气引邪 ，喎僻不遂。 邪在于络 ，肌肤不仁 ；邪在于经，即重不胜 ；邪入于府 ，即不识人 ；邪入于藏 ，舌则难言 ，口吐涎沫。', '2025-03-07T04:02:47.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TbMKbbdO221', 4, '{"title":"3","description":"<p>3、寸口脉迟而缓 ，迟则为寒 ，缓则为虚； 营缓则为亡血， 卫缓则为中风 ；邪气中经，则身痒而瘾疹；心气不足 ，邪气入中 ，则胸满而短气。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007003,"note":"      『寸口脉』如果『迟而缓』，脉跳得很慢、很迟，脉来一息一至、 二至，这是『迟则为寒』。寒都是很迟的脉，缓则为虚，缓的意思是 脉很弱，就是摸上去感觉脉跳起来的力量很弱，所以这是指又寒又虚 了。\n\n     『营缓则为亡血，卫缓则为中风』就是血脉缓的话就表示病人失血，气脉缓的话就表示病人中风了。\n\n    『邪气中经，则身痒而瘾疹；心 气不足，邪气入中，则胸满而短气』这个意思就是说，如果一个人是气虚掉，于是风邪等外感进入我们皮肤表面上，我们会感到皮肤身痒， 出瘾疹，就是发红疹。但是如果遇到本身是心气不足的病人时，邪气 就会进入病人内脏，而第一个受到影响的将会是肺，因为病人本就虚 了，寒进来就会束在肺上面，把肺缩小了，这个时候你想要大力呼吸， 它又无法大力呼吸，于是就会感觉到胸腔很胀满，气短。一般来说像 这种风疹，身痒而瘾疹，我们都是用麻黄加术汤来治疗。前面我们已 经介绍过此方，麻黄汤加白术在里面，专门用来治皮肤痒疹。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '3、寸口脉迟而缓 ，迟则为寒 ，缓则为虚； 营缓则为亡血， 卫缓则为中风 ；邪气中经，则身痒而瘾疹；心气不足 ，邪气入中 ，则胸满而短气。', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vGYFqtxHml5', 4, '{"title":"4","description":"<p>4、$f{防己地黄汤}   治病如狂状 ，妄行独语不休，无寒热，其脉浮。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007004,"note":"       当你摸到病人的脉很浮，表示病还停留在表，没有走里，所以同样是中风，如果出现脉很浮，代表风邪仍然在表上，这种中风很好治。 有的时候病人是气血两虚，摸脉时病人的脉沉得很深，这表示风在很里面，中医诊断中风可以从脉症中探知。\n\n     『病如狂状』就是还没有到发狂，看起来好像狂，也就是说病人的情绪很烦躁。\n\n     『妄行独语不休』就是一个人在那边到处走来走去， 自言自语，这种就是气血两虚的状态下引起的。\n\n      中医认为，风入肝，肝脏本身就是风脏。如果一个人中风，当风进入身体后，由于跟肝的属性是相同的，所以会直接连到肝，肝受到风干扰而出现问题时症状一定是『动』。\n\n      所以入肝就叫『诸风掉眩』也就是动症，病人会动来 动去，像西医说的柏金森氏病般在那边动个不停。柏金森氏病症状很特殊，病人一动一晃的不停，甚至于连眼珠子都在晃。我们知道动症起因是肝受到风的影响，所以连眼珠子都会晃动。\n\n       肝主怒，怒能伤肝， 本身肝有问题的话就会有暴怒的现象，所以出现『如狂状』。这种状 况之下，中医的基本观念，就是要把表邪去掉，同时将体内的气血补足，因为里面虚寒才造成这样子，治此病并不是从肝脏入手，所以仲师用防己地黄汤。\n\n      防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。\n\n        遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。如果你说：「老师啊，去风我们可以用很大剂的表药。」此处是行不通的，因为病人本来就虚，你不能开太强的发表药，一旦发汗发太过的话，会造成本来肠胃津液就不足的状况下，又再被发掉了。我们又需要再补足病人肠胃的津液，这是多此一举，如果是遇到比较强壮体格的人得到感冒，就是单纯的桂枝汤证。\n\n       可是现在是遇到的是中风的人，病人本来就是因为里虚所以才会中风，一般里虚不足的时候，我们需要补里虚的同时要解表，开的解表药一定不是像麻黄汤桂枝汤之类的强药，必定是选用比较缓和的药。\n\n      哪些药会比较缓和呢？像瓜蒂，取吐法后，病人也会因吐而流汗， 前面百合病也有跟大家介绍过，不需要用很强的麻黄汤等。比如说已经中风的病人，你给他喝麻黄汤，本来他的肠胃津液就已经虚掉，这 下肠胃津液就更干了。造成病人因表汗过多而表虚，里津不足里又虚 掉，这只会使病情更坏，所以开发表药时我们要看时机使用。","videoMemo":"","fangList":["防己地黄汤"],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '4、$f{防己地黄汤} 治病如狂状 ，妄行独语不休，无寒热，其脉浮。', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t1iWLhwj9t8', 4, '{"title":"5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者","description":"<p>5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007005,"note":"        侯氏黑散『治大风四肢烦重心中恶寒不足者』。『菊花、白术、防 风、桔梗、黄芩、细辛、干姜、人参、茯苓、当归、川芎、牡蛎、矾 石、桂枝』。\n\n        侯氏黑散这个方子绝对不是张仲景立的，一定是后人借他的名立进去的，此方的目的是填补。\n\n        为什么叫填补？这个方子的观 念是，病人身体里面虚掉了，结果造成表风进来补里虚的位置，就是当中风进来的时候和病人的里虚没有完全接在一起，中间就有很多间隙产生，间隙的产生是病人的气和血没有办法沟通，于是产生半身麻痺，这个侯氏黑散就是能够慢慢的把空虚的部分填补起来。\n\n       这是一些外面其他医生设计的药，不是仲师原方。我们临床上用的不多，我没有用过这个药来治疗中风。制作法是将这十四味杵为散状，就是弄成粉剂样。『方寸匕』就是一个汤匙的，一天吃一次，刚开始服前二十天用温的酒来喝，一切的鱼肉大蒜都不要吃，常吃冷的食物。吃了两个月以后即『药积腹中不下』，让药力慢慢的渗进去里虚的位置。要让药力停滞不下的话必须要冷食，一吃热食药力就下来了。所以要冷食目的就是让药不要跑掉，让药尽量囤在身体里面慢慢渗进去。实际上这种方子都没有我们后面的方子好用，后面会跟大家介绍外台秘要里的处方，那些方子还比较像张仲景立的方子，可能就是我国千年以 来，失落的经方。","videoMemo":"","fangList":["侯氏黑散"],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '5、$f{侯氏黑散}治大风四肢烦重心中恶寒不足者。', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KKdfQJcv899', 4, '{"title":"6、$f{风引汤}，治除热瘫痫","description":"<p>6、$f{风引汤}，治除热瘫痫</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007006,"note":"       像风引汤，我用的也是不多，我很怀疑这些方子都不是张仲景开 的。如果是张仲景处方的话，为什么要叫『侯氏黑散』？ 为什么不是叫做『张氏白散』呢？他一定会用张氏之名。\n\n      诸位再看风引汤，专治热瘫痫，就是热症中风，完全是里热症，里面很热的时候，又遇到表风。里面本身就虚，虚久后产生的虚热，此时表又受到风。我们除了开补虚的药，还要同时开去热的药，也还要再开去表风的药，药力一定区分为这三种，你看大黄是去里热实的，像干姜、龙骨、桂枝、牡蛎这种都是补里虚的，还要加上去热的药，像石膏，就是去热的药。\n\n       为什么要用寒水石、滑石、赤石脂、白石脂、紫石英这种涩剂，一般我们使用涩剂时，是因为石头的药都是比较涩，而病人身体里面有虚热的时候，大便时会有下利，肚子会痛，像肠鸣下利般，食物是不会停在肠胃里面。所以就需要加进去很多涩剂像赤石脂、紫石英、白石脂等。","videoMemo":"","fangList":["风引汤"],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '6、$f{风引汤}，治除热瘫痫', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EeiEUpfiHqZ', 4, '{"title":"7、$f{头风摩散方}","description":"<p>7、$f{头风摩散方}</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007007,"note":"       头风摩散，这个药专门是治疗偏头痛，头痛欲裂，然而一定要有热症在头上面出现时才用，像眼赤红，同时头痛又痛的很厉害。\n\n      这种状况之下我们用炮附子做粉跟盐合用，比如说你拿一茶匙的炮附子粉剂，然后拿一茶匙的盐巴，两个等量将之混合在一起，然后加入水和一和，直接涂在头痛的地方，这就是专门治疗强烈头痛的外敷药，这头风摩散，就比较像张仲景的处方。张仲景很少用到石类的药，像紫石英就很少用到。张仲景一般最多只使用到赤石脂、禹粮石这类石药。\n\n       接下来我跟大家介绍三个方剂，大家可以补注在这里，或是做在笔记里面，这第一个处方是从千金要方里面摘录出来的，这三个就比 较像经方了。\n\n      第一个，我们叫『千金三黄汤』千金三黄汤主症手足拘急，同时病人全身骨节痠痛，病人也会烦热，情绪烦躁。然后心乱恶寒怕冷，病人有这种症候，然后又终日不欲食，没有胃口。遇到这种情形的中风，大家就用$n{千金三黄汤}，千金三黄汤是$u{麻黄}、$u{黄耆}、$u{黄芩}，然后再加$u{独活}还有$u{细辛}。\n\n      像这种心乱恶寒，寒很盛的时候，我们可以用细辛来壮里阳。有虚热在上焦时，治烦热，就用黄芩。黄耆作用在固表虚，麻黄用来发病人的肺阳，可以将病人全身骨节痠痛去掉，独活 就是协助麻黄去发表汗，当麻黄遇到细辛时，细辛会把麻黄拉住。所以伤寒论少阴证时，我们使用麻黄附子细辛汤，病人吃了麻黄附子细辛汤反而不会流汗，只会让小便量增加，少阴证就得解了。\n\n     麻黄遇到细辛，细辛从下面把麻黄拉下来，于是就不会发表汗发太多，这些药配合在一起药就很强。如果你说：「老师！我们平常都喜欢加甘草。」 一旦加甘草下去就不叫三黄汤了，所以不可以随便加甘草。我们在急救中风时，病家已经都这样危急，结果你还在那边缓攻，甘草就是缓攻，所以外面南派的中医，什么药都加有甘草，这会害死人的。\n\n       第二个方子是很有名治疗中风的处方，方名叫做『$n{小续命汤}』， 平常我们看到中风，十之八九都是在小续命汤上面做加减，小续命汤源出于外台秘要。\n\n       这个处方里是麻黄桂枝并用，处方很大胆，这就很厉害了。平常中风如果我们会用到麻黄桂枝，一定是用在比较深度中风的病人才会用到麻黄桂枝。一般中风的人是不会用到麻黄桂枝的， 而这里会用到麻黄桂枝，一定是张仲景的原方才有可能，张仲景敢这样用因为还有加别的药在里面，用到麻黄时担心病人会汗发太多，所以一定会用到杏仁。杏仁跟麻黄并用，前面就已经出现在麻黄汤里， 麻黄跟杏仁用等量，就是说如果开了麻黄三钱，杏仁就开三钱来配合麻黄的量，这样就绝对不要担心肺的津液会被麻黄伤到，不要担心汗流太多。桂枝跟炙甘草，都是健脾整胃，把虚寒的脾胃补起来。这个时候如果我们加入当归川芎，只遇到病人血虚掉，就用当归来补血， 川芎是活血用的，川芎一下去，能够让我们补进去的血运送到全身四肢关节上去，所以用川芎。平常得到中风的病人，多半兼有痰涎壅塞 的现象，积在胸腔里面的痰，会使胸腔里面太热，所以最后再加了石膏，石膏在此是要去里热的。\n\n        「老师，此处为什么不用涤痰的药？ 」 我告诉大家，因为病人已经虚了，所以不加。过去的金元四大家，就是指金朝、元朝时期的名家。金元四大家所有的观念里面，谈到中风， 就是痰饮跟风火，就是风火相交，痰痈很多。所以他们开的药都是去火祛痰的药，我们北派很不赞成这样子，因为我们临床上看的时候摸 到病人的脉都是气血两虚，我们在补气补血的同时，还需要把病人寒与热一起排掉，因此一定会有去寒去热的药并用在同一处方里，所以你们会看到石膏跟干姜在一起合并使用。所以炙甘草、干姜来温补中 气，让他的肠胃的功能恢复起来，整个处方用起来，就是所谓的小续命汤。麻黄,杏仁,桂枝,炙甘草,干姜,当归,川芎,石膏\n\n       小续命汤的剂量该用多少呢，就要看病人有多重了。像比较强壮 的人，麻黄可以开到五钱以上，桂枝开八钱以上，遇到体型较瘦的， 麻黄可以开两钱，病人体格如果更小，麻黄用一钱，如此决定加减， 只要麻黄跟杏仁是等量在使用，就不会失津。在这个方子里面的炙甘草跟干姜是要去健中、健脾胃，所以甘草的量就会比较多，比如说甘草五钱，干姜三钱。当归我们一般使用的时候是五钱的量，当归和川芎我们可以等量使用。为什么等量使用？ 因为当归是补血的，川芎是活血的，它可以将当归带到全身四肢末梢去。你说：「老师，这个病人的血实在太虚了，我想当归用到一两。」当然可以，大剂的可以用一两，川芎也可以用到一两。石膏在这里用五钱就足够了，强壮的体格用五钱，平常用三钱就可以了。如果病人有壮热出现的时候，石膏就要加重。热的原因，就是阳往上走，阳往上走的症状，西医称为脑充血。就是浮阳停在脑部上面，无法下来。这时我们使用降热的药， 就要靠石膏了。\n\n       小续命汤证主要的症状跟刚刚千金三黄汤不一样，也同样是有手足不仁，但是兼有口不能言，这就比较重了。然后不知痛 处，你问他哪里痛？病人连痛处都不晓得在哪，此时病人的神志有点 不清楚了。同时出现四肢拘急，全身绷紧不得转侧。需要翻转时，都要靠家人帮忙翻转。很多中风病患躺在病床不能动，结果造成褥疮， 经久不愈。吃小续命汤的时候要注意一点，这个药吃下去以后，病人要采坐姿，坐在那边，得汗则解。\n\n      如果遇到说：「老师，他没汗啊？ 」 没汗就再吃，因为药没有到位，等到药到位了就会得汗，采坐姿，得汗就会好，可以停药了，这是我们最常用的治疗中风的方子，我常常  在这个方子里面做加减，这个处方非常好用。\n\n       临床上用这个处方几乎都可以将十之八九以上中风的病人救回来。\n\n      最后还有一个复方，就是前面诸位学过的『术附汤』。白术、附子、生姜、甘草、大枣，这五  味药组成的术附汤。我们在使用的时候，病人一定要有风症，风虚头眩，也是中风的现象，头昏，非常的昏眩，眼睛都不能张开，吃东西都没有味道了。这时我们要靠生姜甘草大枣去健脾胃，我们靠白术附  子，白术去通利他的三焦去湿，靠附子来去寒，这就是术附汤证。用汤剂的时候，我们用甘草或炙甘草都没有关系，病人有里虚的时候我们用炙甘草是最好。\n\n       所以以后大家遇到中风病患时，前面的侯氏黑散  你不需要使用，还是记住这三个方子更好用，尤其是小续命汤。小续命汤内容真像出自于张仲景的手法，过去从汉朝到现在，麻黄桂枝一起用在虚症上面，绝对是没人敢用，南派的看到麻桂如看到蛇蝎般，咸认为：「吃了会死掉。」当病进入脏后不借用麻桂是攻不出来的，像舌强不语，就表示病中脏了，进入人体很深的地方。这个时候要大剂的药攻下去才会对病情有所帮助，病人虚掉时我们使用很强力的药在里面，只要注意攻补兼施的药一起放在处方里面，就不会有问题，而 这个方子设计的非常的好，这个可能比你学别的还有用。\n","videoMemo":"","fangList":["头风摩散方"],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '7、$f{头风摩散方}', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bRO8db8Odee', 4, '{"title":"8","description":"<p>8、寸口脉沉而弱 ，沉即主骨 ，弱即主筋 ，沉即为肾 ，弱即为肝 ，汗出入水中 ，如水伤心 ，历节黄汗出 ，故曰历节。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007008,"note":"       『寸口脉沉而弱』寸脉位出现脉沉在骨边，表示病在骨，因为沉脉就是讲骨头有病，而肾脏就是主骨。弱脉出现，是主筋病。\n\n      『沉即  为肾，弱即为肝，汗出入水中，如水伤心，历节黄汗出，故曰历节。』 中医讲的历节，起因都是肝肾两虚，病在筋骨之间游荡，就叫做历节。\n\n       历节病在临床上看类似于西医说的痛风与风湿病。实际临床上大家可以看到有三种不同的症状。第一种，中医叫做风痹。风痹的主要症状  是麻又痛，连皮肤都会又痛又麻。第二是血痹，血痹的主要症状是『麻而不痛』，单纯只有麻的感觉，没有痛症。风痹有专治风痹的汤， 痹有专治血痹的汤，像黄耆五物汤就是治疗血痹的。第三种就是历节病，而历节的主要症状是『但痛不麻』，这是中医用外在的症状来区分的。\n\n         西医临床上看到很多痛风或是风湿都有这种症状。像你开『甘草附子汤』给病人的时候，而这处方只是治疗风痹，当风寒湿相混合在一起时，病人会有各种不同的症状出现，如果是只痛不麻的话，我们就把他当成历节在治疗，治历节的处方有乌头汤，或是大乌头煎等。 如果是血痹，就是黄耆五物汤证，血痹的主要症状就是麻，纯麻的感觉，那种麻是很顽固的麻，有的麻十几年来都在麻，黄耆五物汤专门  治疗麻的症状，麻是非常不易被治好的，而这是血痹特有的症状，也就是血虚。\n\n      现在讲的历节，它的起因中医认为是肝肾两虚，有一天肾脏的新陈代谢功能不是很好，它没有办法把废物排泄出去时，由于水生木，因此所有的脏东西会因此而进入肝脏，如果此时肝脏本身又虚 了，脏东西到了肝里面等待分解时，肝没有办法把它排出来，这个时候脏的物质就会沉积在身体里面，也就是所谓尿酸沉积在身体里面， 逐渐的沉积日久以后，就会囤积在骨头旁边，因为尿酸是呈结晶状， 挤在骨头旁边当然会很痛，痛起来的时候，就感觉脚好像放在油锅里 面，烫而且肿，那种滚烫的感觉很痛，脚背也肿起来，常常发生在脚 背还有脚关节的地方。最严重的痛会持续两个礼拜以上，一般痛一个 礼拜到两个礼拜慢慢就会消除掉。哪种人会得到这类的病呢？诸位看 下段的说明。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '2025-03-07T08:19:02.000Z', '8、寸口脉沉而弱 ，沉即主骨 ，弱即主筋 ，沉即为肾 ，弱即为肝 ，汗出入水中 ，如水伤心 ，历节黄汗出 ，故曰历节。', '2025-03-07T08:19:02.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fmCEqITncVb', 4, '{"title":"9、趺阳脉浮而滑，滑则谷气实，浮则汗自出","description":"<p>9、趺阳脉浮而滑，滑则谷气实，浮则汗自出。太阴脉浮而弱 ，弱则血不足 ，浮则为风 ，风血相抟 ， 即疼痛如掣。</p>\n<p>盛人脉涩小 ，短气 ，自汗出 ，历节疼 ，不可屈伸 ，此皆饮酒汗出当风所致。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007009,"note":"       『趺阳脉浮而滑』这讲的就是胃脉。第一种会得到历节的原因就  是，当汗流得很多时，立刻进到冷水里面，这会使得人体汗出不透， 跟前面说的黄汗是同源的。第二种引起中风历节的原因，是『趺阳脉』 就是所谐胃脉，在冲阳穴位的脉。\n\n       『浮而滑，滑则榖气实，浮则汗自出。』『谷气实』代表胃中有实，就是有宿食停在里面，此时就会摸到  趺阳脉不但滑，而且实。\n\n        这里的太阴脉讲的是我们的脾脏，如果是弱脉表示血虚，而脾主四肢，主肌肉，当脾脏功能不好时，固表能力就不够。这个时候风进 入体内，正好遇到此人血不足，而血不足的原因，可能肠胃吸收不是很好，生血的过程不是很好，这也会造成疼痛如掣。\n\n         还有一种疼痛， 就是『盛人脉涩小，短气，自汗出，历节疼，不可屈伸』什么叫盛人？ 这里的盛人，过去说的就是有钱人，家里环境很好的，每天都大口酒 大口肉的吃，然后妻妾又很多，\n\n      『脉涩小』是因为运动很少，养尊处优，于是脾阳不伸，没有办法到达四肢，肉很多只是外表看起来比较 实，其实是中干，因为这些都是吃很厚腻的食物产生出来的肥脂，并没有固表能力，都是肥油在里面，这个时候脉就比较短小，\n\n      『短气， 自汗出』。平常喝酒喝的很多的人，身体里面湿就会很盛。喝酒后感觉是身热，但是到身体里面就变成湿。因为平常没有运动，又近女色， 喝酒又喝得多，结果表虚掉里面又湿，这又是一个很容易得到历节病的原因。\n\n        现代人得到则是因为吃西药过多伤到肝肾，加上喝酒喝多了伤肝，近女色过多了又伤肾，这也是肝肾两虚的原因，这种『历节疼， 不可屈伸，此皆饮酒汗出当风所致。』所以本身身体是虚的，加上运动量又少，以致表虚掉，风就容易进来，然后风与湿混合在一起，就成为风湿。一般经常喝酒的人，我们时常用苍术泽泻来解酒，苍术很燥可以把体内的湿去掉，以上这些都是造成历节病的种种原因。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '9、趺阳脉浮而滑，滑则谷气实，浮则汗自出。太阴脉浮而弱 ，弱则血不足 ，浮则为风 ，风血相抟 ， 即疼痛如掣。 盛人脉涩小 ，短气 ，自汗出 ，历节疼 ，不可屈伸 ，此皆饮酒汗出当风所致。', '2025-03-08T01:58:07.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0WDTC88oEOS', 4, '{"title":"10","description":"<p>10、诸肢节疼痛 ，身体尪羸 ，脚肿如脱 ，头眩短气 ，温温欲吐 ，$f{桂枝芍药知母汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007010,"note":"        这个处方是治疗阴虚的主要处方之一，专门是用在阴虚的病人身 上。这段是说，只要病人身体很瘦弱，两个脚肿起来，这就是气血两虚的人。身体很瘦又全身关节痛。这一定是脾脏虚掉，脾主四肢，主肌肉。\n\n       『头眩短气』是因为血虚掉，头就没有办法受到正常的血的供 养，造成头会昏眩。短气的原因是因为里湿太盛，这种状况出在病人本身是虚，同时湿又很盛，又兼有寒。\n\n       『温温欲吐』这感觉就是胃里面很难过，想吐又吐不出来，就是温温欲吐。有这种症状的病人，多是在身体里面三焦油网部分受到湿的侵估，就会出现这种现象。\n\n        中医的名词是『胃中有伏热』，正常的热是应该沉在下面，寒在上面，所以热本身是被寒收敛在下面，热不该浮上来，有一天，病人里寒太盛， 这个热没有办法待在下焦，只好往上跑，于是热浮在上面，寒在下面， 变成上热下寒这个样子。也就是我们讲的三焦气虚的状态之下，三焦气会虚，就是因为脾胃本身无法正常吸收营养，影响到三焦也没有办 法完全运化营养，三焦无法运化时会让里湿更盛，加上脾阳不足，四肢关节就会空虚，里虚加上湿停滞太久，于是湿就逐渐累积于关节之中，造成四肢关节都会肿大疼痛。\n\n        我们治疗历节第一个处方，就是桂枝芍药知母汤。大家现在都该知道，桂枝芍药是健脾的，但是桂枝芍药知母汤中桂枝用四，芍药用三，桂枝稍微重一点， 目的是要让药走到四肢。甘草、麻黄、附子， 用麻黄跟着桂枝，是因为桂枝可把麻黄的药力推到皮肤表面上。白术是去湿用的，防风能祛风去痛，附子在此的目的是去寒。所以这个桂枝芍药知母汤里面白术、知母、防风等量大剂的用，甘草、麻黄、附子按照经方的比例等量用，但是稍微少一些，然后再重用生姜。开立 桂枝芍药知母汤处方时要记得，要重用生姜，平常我们生姜两片就好， 但是在这个处方中生姜要加重到五片，因为生姜到了胃里面去以后， 生姜产生的热是散开的，不像干姜是温中。这里是要把胃里面的胃阳散到三焦网膜上面，所以需要重用生姜。\n\n        临床上这个药方我时常在用， 什么样状况的病人用到最多的桂枝芍药知母汤呢？就是糖尿病的病 人，中医讲的是症状。\n\n        西医说糖尿病的病人有一种是得到了就会很胖， 越吃越胖。有一种呢，越来越瘦，体重直线下降，瘦的就是桂枝芍药 知母汤证，到最后阶段西药无法继续控制血糖后，病人到后来身体很瘦，但是脚却变成肥大。\n\n       中医认为「男怕脚肿，女怕头肿」，就是男人身体一直瘦，唯独脚肿起来，这是很危险的症状，此时就是桂枝芍药知母汤证。这种汤剂喝下去的时候，表面上看起来我们是在治疗历 节风，同时又兼治病人气血两虚的身体，我们用补虚去寒去湿的药， 还有固表的药同时一起来。这个处方因为桂枝的加重，比芍药加重一个比例，所以能够走表。这个药吃下去以后，病人关节痛就会减轻， 然后血糖降得很快，时常可见血糖从三百多降到一百多，过去我用过很多次，效果是立竿见影的。\n\n       『所谓不通则痛也。』不通的原因是因为里虚掉了，所以说『身体尪羸者，统血之藏久虚。』统血之脏就是脾脏，久虚掉就是脾脏没有办法统血，这个时候因为血没有办法充分供应到四肢肌肉上面，才造成全身关节都会痛。\n\n       『脚肿如脱者，寒湿下注』所以桂枝芍药知母汤是常被经方家用来补虚治湿于同时的处方。\n\n        诸位看看案例。有一个孕妇怀孕八个月，先生把她带来求诊，自述『病人身重，将腹中小儿压毙。』『把小孩子压死掉了以后，结果『妻病腹痛，乃求医』医生开药来帮忙堕胎。而此妇人，本来就是属于身体血虚的人，这个时候我们用攻下死胎的药物会导致血更虚，因为攻胎药大部分都是破血的药。病家体虚，结果湿毒留在腹里面不去，日久乃旁溢到四肢上面，结果造成病人肚子里面有死血，『寒湿并居』 造成『因病历节』。\n\n        中医的历节的观念，诸位记得『但痛不麻』只有痛，而关节都肿起来，时常可见整个手指头的关节，还有身上有关节 的地方都肿起来。尤其是妇人很多都有这问题。\n\n       『手足拘挛，入夜手足节骱剧痛』，痛风的病人就是中医讲的历节，大部分都是晚上发， 入夜的时候痛得最厉害，因为她是虚症，病又在阴，所以晚上的时候痛得最厉害，白天比较好，这是阴寒无疑。\n\n        如果用原方就是『每两折为二钱』再用『用熟附块四钱』，喝了两剂后如果没有感觉，就要改用生附，我要跟诸位讲这个例子的原因是当有一天遇到炮附子下去推不动病情的时候，就该把炮附改为生附，最严重的状况，我会生附、 炮附并用，炮附会走表，生附是温里。炮附吃下去以后，药马上就会到皮肤上面，关节就可以通畅无阻了，所以这样使用是非常的厉害。\n","videoMemo":"","fangList":["桂枝芍药知母汤"],"bieMing":""}}', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '10、诸肢节疼痛 ，身体尪羸 ，脚肿如脱 ，头眩短气 ，温温欲吐 ，$f{桂枝芍药知母汤}主之。', '2025-03-08T01:58:07.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O4rGqrNNwh7', 4, '{"title":"11、味酸则伤筋，筋伤则缓，名曰泄","description":"<p>11、味酸则伤筋，筋伤则缓，名曰泄。咸则伤骨，骨伤则痿，名曰枯 ；枯泄相抟 ，名曰断泄。营气不通 ，卫不独行 ，营卫俱微 ，三焦无所御，四属断绝 ，身体羸瘦，独足肿大 ，黄汗  出 ，胫冷 ，假令发热 ，使为历节也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007011,"note":"     『味酸则伤筋，筋伤则缓，名曰泄』就是如果长期都吃太酸的食物会伤筋，如果长期都吃太咸的食物会伤骨，\n\n     『骨伤则痿』就是四肢 会萎缩掉，这个名曰『枯』。如果是筋伤到，加上骨又伤到，就是『枯泄相抟』中医叫『断泄』。\n\n      『营气不通，卫不独行，营卫俱微』就是气血两虚，『三焦无所御，四属断绝』结果造成『身体羸瘦，独足肿大， 黄汗出，胫冷，假令发热，便为历节也。』所以说，如果没有发热， 只发黄汗，就是我们前面说的黄汗，它与此处说的历节的病因是一样 的。如果病人燥热，关节很热很痛，病人跟你陈述说脚好像放在油锅里面炸那么热，这就是但热不寒，一定是历节了，这些都是可以帮助我们了解历节的原因，是出在肝肾两虚的状态，寒湿下注下来，才会造成这样的，可以治疗历节的汤方就是现在要介绍的『乌头汤』。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '11、味酸则伤筋，筋伤则缓，名曰泄。咸则伤骨，骨伤则痿，名曰枯 ；枯泄相抟 ，名曰断泄。营气不通 ，卫不独行 ，营卫俱微 ，三焦无所御，四属断绝 ，身体羸瘦，独足肿大 ，黄汗 出 ，胫冷 ，假令发热 ，使为历节也。', '2025-03-08T01:58:07.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IFuc1lrFtBQ', 4, '{"title":"12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之","description":"<p>12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007012,"note":"       『病历节，不可屈伸，疼痛』痛的很厉害，病人没有抱怨麻木。 我们最常用的方子就是这乌头汤。乌头汤是治疗历节重症用的，还有另一个更重的处方，我们此处说的是乌头汤。\n\n        乌头汤内容是麻黄、芍 药、黄耆、炙甘草等量。诸位先看里面乌头的制法，乌头五枚，就是搅碎了以后『以蜜二升煎取一升即出乌头』。\n\n        乌头和附子在本草里面是同科的本草，本草经说乌头植物下面的根茎上，生了一些块茎附着 在根茎上面，就是『附子』。一般附子是三年采收，第四年的时候把茎拿下来用，就是『乌头』。如果到了五年以上，使用整个茎时，这个就叫做『天雄』。\n\n       天雄是壮阳药，在神农本草经里面是壮阳最强的 药物了。我们经方里面所选用的药物都是出自于神农本草经，当然我 们还有一些像阳起石等很多的壮阳药，但天雄是我们经方里面最强的。\n\n        现在要用乌头，乌头跟附子是同科的，也是很热的药，药本身的毒性非常之强，而去乌头的毒有两个方法，第一个，我们先把乌头放在锅子里面，放水二碗，然后煮成一碗，之后要把乌头渣滤掉，然后拿一碗蜂蜜，倒下去跟这乌头汁混合后一起再熬，熬成一碗之后就可以用了，这就是乌头蜜，此时乌头蜜的颜色是很暗的，而且很浓很甜， 鸟头汤是很甜的药。\n\n        如果遇到『酒客不喜甘』，病人平时就喜欢喝酒， 这种人在喝鸟头汤时，就会感觉很难过，还有中湿很盛的人也都不喜 欢吃甜的东西。其他像麻黄、芍药、黄耆、甘草等，千万不要给病人用三两，大部分都是三钱，如果痛得厉害的话就加重到五钱。麻黄、 芍药、黄耆、甘草都是等量的用。将这四味药以水六碗煮二碗，把药渣拿掉，留一碗在锅中，再放入鸟头蜜一汤匙，就是刚熬的鸟头蜜， 混和起来，再煮一次，煮成八分这样子，然后就可以喝。喝下去以后， 如果『不知』就是没感觉，就再喝。如果出现头昏、手麻就立刻停下 来，不可以尽剂，这就是鸟头汤的正确服用方法，像膝胫、足踝部位、 四肢关节肿胀疼痛等症状出现时皆可用。\n\n        乌头汤证是治疗寒湿历节的正治法，之所以要用麻黄不用桂枝就是因为桂枝力量不够，要靠麻黄的阳使药力透达到四肢上面，白芍可以让被寒湿堵到的四肢关节末稍要回流心脏的血液流回心脏，黄耆是 走表的药，能固表，不让外感的风再进来，炙甘草是因为怕麻黄喝下 去以后，会造成肠胃津液的丧失，所以甘草下去，可以立刻将肠胃津 液补足。\n\n        我们一般药在胃里面，等药力达到四肢时，必会耗时很久， 乌头很快的就可以把药运送到四肢上，乌头药性极热，所以去寒力很 强，可是如果光用乌头下去又有毒，跑的又快，所以用蜂蜜去缓它的 速性，蜂蜜不但可以把鸟头的毒解掉大部分，同时蜂蜜可以告诉乌头： 「你慢一点，你是很好的药，但是要慢一点，不要走的那么急，那么快。」这样速度减缓下来后，就可以把深入关节中的历节风湿去掉。","videoMemo":"","fangList":["乌头汤"],"bieMing":""}}', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '12、病历节 ，不可屈伸 ，疼痛 ，$f{乌头汤}主之。', '2025-03-08T01:58:07.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Pk5Vv6Pgnf', 4, '{"title":"13、$f{矾石汤}治脚气冲心","description":"<p>13、$f{矾石汤}治脚气冲心</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905007013,"note":"       矾石汤你千万不要拿起来喝，喝了后你身上的津液通通会沉淀下 来，血也沉淀了。\n\n       明矾怎么可以吃？矾石汤是『脚气冲心』用的。我 们平常有香港脚或是糖尿病等，造成脚溃烂掉或流脓，毒气一直往上冲很难过。这个时候你拿矾石，最好找到自然的矾石比较好，自然的矾石我们加热后烧出来还是白色，人工制造的矾石，与天然的成份都一样，但是烧出来颜色比较黑，这两个不太一样，选用自然的矾石比较好。这是泡脚汤。\n\n        明矾你用二两都没有关系，用浆水，就是用自来 水来煮过，煎三五沸，滚了以后化掉了就可以停火了，你不需要：「老师，三碗水熬成一碗。」那矾石就不见了。水滚一下化掉就可以用， 把脚浸泡下去就好了。矾石这个药性很干燥又涩，就是因为性燥又涩， 所以我做的麝香矾石散，可以喷到鼻子里，因为矾石是很干燥的燥剂， 可以将鼻窦中的湿涕清干，而脚有湿气会黏答答的，这时就可以用矾石汤来泡脚。如果是脚气，像湿很盛，我们可以内服桂枝芍药知母汤， 配合针灸针三皇穴，就是阴陵泉、地机、三阴交，同时针专门去掉脚湿肾经的水泉穴，扎完针后，将脚泡在矾石汤里面，如此治疗脚气效果非常好。包括香港脚，还有更严重的，像脚整个烂掉，毒气一直往上冲，都可以使用它。矾石能够收敛湿气，专门去湿解毒。如果只是感觉很轻微痒痒的，就不需要用到此方。","videoMemo":"","fangList":["矾石汤"],"bieMing":""}}', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '2025-03-08T01:58:07.000Z', '13、$f{矾石汤}治脚气冲心', '2025-03-08T01:58:07.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', '28xphHVXuPE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GxoeHEpvj3Z', 4, '{"title":"1","description":"<p>1、问曰 ：血痹之病 ，从何得之？</p>\n<p></p>\n<p>     师曰 ：夫尊荣人，骨弱 ，肌肤盛 ，重因疲劳汗出 ，卧不时动摇，加被微风 ，遂得之。但以脉自微涩在寸口，关上小紧 ，宜针引阳气 ，令脉和紧去则愈。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008001,"note":"      『血痹之病，从何得之？ 』张仲景就说：『夫尊荣人』就是家里面 养尊处优的有钱人，他只在乎如何享受，结果『骨弱，肌肤盛』就造成骨头很弱，肌肤很盛，因为他缺少运动。这个时候如果再加上『疲劳汗出』，其实这说的就是行房事后流汗当风，因阳虚而导致『卧不时动摇』睡在那边动来动去，再加上睡时又被微风吹到身体，这个时候得到的就是血痹。\n\n       『但以脉自微涩在寸口，关上小紧，宜针引阳气， 令脉和紧去则愈。』如果病人得到只是比较轻微的血痹，就是只发现寸口脉微涩，而寸口上有涩脉也代表血虚掉，因此这个人等于是气血、 精血两虚的时候得到了痹症，手臂肩膀都会麻，讲痹症就多是麻木， 少有痛症，我们可以用针灸治疗他。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '1、问曰 ：血痹之病 ，从何得之？ 师曰 ：夫尊荣人，骨弱 ，肌肤盛 ，重因疲劳汗出 ，卧不时动摇，加被微风 ，遂得之。但以脉自微涩在寸口，关上小紧 ，宜针引阳气 ，令脉和紧去则愈。', '2025-03-08T09:20:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vGAFwd1CC9V', 4, '{"title":"2","description":"<p>2、血痹 ，阴阳俱微 ，寸口关上微，尺中小紧，外证身体不仁 ，如风痹状 ，$f{黄耆桂枝五物汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008002,"note":"        血痹的症状，阴阳俱微，寸部与尺部的脉都很微弱，这是气血两虚的状态。\n\n      『寸口关上微』寸脉和关脉都是很微弱，『尺中小紧』代表阴血不足，尺代表阴，寸代表阳，尺中小紧表示下焦不足。\n\n     『外证』 可以看到是『身体不仁，如风痹状』身体不仁，没有讲痛，就是只有麻木，全身都有可能出现麻木。有时候手臂麻，有时候脚麻，不一定 的。\n\n    『黄耆桂枝五物汤主之。』黄耆桂枝五物汤的处方，就是把桂枝汤里面的甘草拿掉改成黄耆，同样是桂枝汤，你把甘草拿掉，换成黄耆， 就叫做黄耆桂枝五物汤。\n\n       这个处方的重点就是黄耆、芍药、桂枝是等量，生姜要加重，如果只加两片，就没有效了，麻还是会照麻。生姜加重到五片、六片，很辣，桂枝已经很辣了，这是因为要利用辛甘发散为阳，才能够让黄耆的药力从肠胃发散到四肢上去。气血两虚的症状会有麻痺的现象，用黄耆是因为它能够通透皮表，所以能够去麻。 桂枝汤之所以要有桂枝白芍就是要增加脾脏的功能。脾脏的功能强起来，气血就会兴盛。所以黄耆桂枝五物汤吃下去后胃口会开，胃口一 开吃了食物，血就被补足了。\n\n       伤寒论里经方的正治法，一般是不赞成给病人吃太多的补药，除非是病人很虚弱，我们才会给他，否则的话 我们都不会给病人补药，我们宁可将病人的脾胃强壮起来，让病人感觉饿，可以吃，然后让他的肠胃能够吸收食物，这是最好根治补虚的方法。治疗血痹，用的最多的就是这个处方。\n","videoMemo":"","fangList":["黄耆桂枝五物汤"],"bieMing":""}}', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '2、血痹 ，阴阳俱微 ，寸口关上微，尺中小紧，外证身体不仁 ，如风痹状 ，$f{黄耆桂枝五物汤}主之。', '2025-03-08T09:20:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2JjonKhHUkZ', 4, '{"title":"3、夫男子平人脉大为劳 ，脉极虚亦为劳","description":"<p>3、夫男子平人脉大为劳 ，脉极虚亦为劳。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008003,"note":"     『平人』，就是指正常人。人好好的看起来都没有病，结果摸他的脉却很数大，这就是劳症，如脉出现极虚也是劳症。脉大代表里面是中空的，所谓劳症就是正常人稍微劳动一下就感觉很累，所以不能动， 一动就累。\n\n        比方说一般人打高尔夫球连打三十六个洞，而此人打完第 一个洞就没力气了，必须睡一天，这就是劳症。平常很正常，胃口也很好，吃了很多食物，然而吃完还是很累，身体还是吃不胖，有劳症的人是不会胖的。如果减肥要成功，就想尽办法把你变成劳症，而劳症还不容易得到的，因为劳的原因很多，后面会跟诸位介绍。\n\n       多数时劳症表面上是看不出来的，因为他根本就是正常人，这段是说有两种状况我们可以从脉象上查觉到劳症，一个是脉大，一个是脉虚。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '2025-03-08T09:20:28.000Z', '3、夫男子平人脉大为劳 ，脉极虚亦为劳。', '2025-03-08T09:20:28.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QD3T357IRZP', 4, '{"title":"4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也","description":"<p>4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008004,"note":"      『男子面色薄主渴及亡血』，『卒』就是猝然之间，发生『喘悸』， 『脉浮者』就代表『里虚』，这是一种望诊。\n\n        所谓『男子面色薄』就是你看他的脸色很青冷。比如说，天气热时，我们应该脸红光满面， 而他看来白白的，面色苍薄。\n\n       和相书上的「郎君面」不一样。什么叫郎君面？就是脸看起来油光光的，没有皱纹。此人「没有涂油啊？怎 么脸油油？ 」，这就是郎君面，郎君面相的格局不好，不够脚踏实地。\n\n      此处的『面色薄。』跟郎君面是没有关系的，这个面色薄代表身体气血不足了。\n\n     『主渴』就是病人感觉到很口渴，这时不管此人是糖尿病引起的渴还是什么其他的病造成的渴，只要病人有渴的现象就代表津液不足，而虚的人为什么会渴呢？ 因为里阴虚掉了以后阳会更盛，有一些病人就是又虚又热，而实际上这个热是因为阴虚而来的虚热，不是实热。\n\n      实热的话我们就要用白虎汤或是承气汤来攻，主渴的虚热是不一样的，没有东西你怎么去攻？这个时候病人产生的虚热还是有很 高的温度，一样会把津液蒸发掉的，所以病人会口渴。遇到这种情形 时，我们补虚的药要开，去热的药也要开，如果只开了去实热的药， 结果大承气汤下去后，热是去掉了，但是虚会更盛，所以虚症是绝对 不可以用攻法。\n\n       如果病人是实热，就是实而且壮热，结果你开成去虚热的药，如 开了补药下去，于是实会更实，中医学就是要会看阴阳、表里、虚实、 寒热，也就只是这样辨症而已。\n\n       突然发生『喘悸』就是病人突发喘的时候，就表示是气不足。为什么会如此呢？ 当人体里虚掉的时候，肠胃功能一定不好，脾土就不能生金，肺里面的津液都是靠胰脏、脾脏来供应，脾脏吸收了营养再交给肺，当脾脏功能有问题时，病人就会卒喘，所以是气不足，才造成这样子。\n\n       悸，中医又叫做『血虚』，所以一个是气虚，一个是血虚。有动悸的症状就是心脏的力量不够，才会产生动悸，中医叫做血虚。\n\n     『脉浮』因为脉的外面就是气，你摸到是气脉，没有摸到血脉，阳就是气，血就是阴，血不够了，阳就浮上来，于是就会摸到脉很大很浮，实际上病人是血虚掉了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '4、男子面色薄主渴及亡血 ，卒喘悸 ，脉浮者 ，里虚也。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OXhU450NIyS', 4, '{"title":"5","description":"<p>5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白， 时目瞑 ，兼衄 ，少腹满 ，此为劳使之然。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008005,"note":"      这里提出劳症特有的几种症状，仲师将之分类出来。男子如有『脉虚沉弦』，虚脉就是你摸到脉的时候有一点点脉，稍微重按又没有了， 就叫做虚脉。或是脉很沉，要摸到骨边才有，重按又没有了。或是摸  到脉细细一根，其状如弦，这也是虚脉。\n\n        也就是说虚、沉、弦三种脉， 都代表里面气血两虚了。第一个情形是，病人并没有寒热现象。你问他：「会不会冷啊？会不会热？ 」他说：「没有。」\n\n        『短气里急』就是病人有时候走动一下就会呼吸很难过，然后肚子常常胀痛，\n\n        『小便不利』 小便次数多，量很少。\n\n        『面色白』苍白的气色。常常头会昏眩。\n\n          还有  『兼衄』就是时常会流鼻血。一般来说，像小便不利，这是肾脏功能出现问题了。\n\n         脸色白的话，代表脾脏功能有问题，因为我们脸上的气色是从脾胃功能来的。像流鼻血，是肝本身有问题。我们为什么要讨论这些症状呢？主要原因就是要告诉诸位，一般出现这种情况时，就表示此人的肝心脾肺肾五脏都虚掉了，可是你看他时又好像都很正  常，但却是五脏同时都虚掉了，这就是劳症，『此为劳使之然。』这是  肝心脾肺肾同时出现虚症时就会有这些症状。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '5、男子脉虚沉弦，无寒热，短气里急，小便不利，面色白， 时目瞑 ，兼衄 ，少腹满 ，此为劳使之然。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DQBVju4bRk1', 4, '{"title":"6","description":"<p>6、劳之为病，其脉浮大 ，手足烦，春夏剧，秋冬差 ，阴寒精自出 ，痠削不能行。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008006,"note":"        『劳之为病』有劳症的病人，得到病的时候『脉浮大』，加上『手足烦』手足会同时有烦燥的现象。\n\n        『春夏剧，秋冬差』这种烦燥在春 夏时节症状会加重，而到了秋冬就好了，主因是因为有劳症的人，本身就有阴虚，一般阳会浮起来。当春夏时气候比较热，于是身体里面的虚热跟外面的太阳的热碰在一起，病人就觉得很难过，冬天的话会比较好，因为外面冷，寒会制热。\n\n         还有劳症很严重的人，就会有『阴 寒精自出』的现象。\n\n        张仲景是用很简单的方式告诉诸位，得到劳症的人，大部分都是上热下寒，就是肚脐以上是热的，以下是寒的，肚脐是阴阳的分界点。 下面是阴寒，阴寒就代表没有动能，不会蠕动了，新陈代谢不好。上面却太热，太过亢了。正常人是阴在上面，阳在下面，这样子阳才不会浮起来，我们的动能才能潜藏，就是所谓的潜阳，中医观念上是阳不在乎多，但是在乎要能潜。所以如果病人阳热在上面，无法下潜， 这个热就会跑到四肢上去，此时身体的下焦却是阴寒聚集之处，就会造成『精自出』，\n\n        这时病人会有几种情形出现，男人的话，代表会遗精、梦交等，就是晚上作梦梦里面在交合。还有年龄大的人很多都会有精自出的现象，因为阳虚而没有办法控制，精就会自动遗漏出来， 这种症状非常痛苦，用中药治疗很快就会治好的。\n\n         还有『痠削不能行』，为什么会这样，因为下焦虚寒精就会自泄出来。女人没有精，一旦发生在女子身上时，白带就会很多，一直滴漏出来，这也会造成人虚掉，这种现象发生时，会影响到晚上都不能睡觉。因为肾脏主骨，病人的肾精遗漏过多，骨头就会有酸感。这里所『痠削不能行』就是病人感觉到的是骨头酸而不是肌肉酸，所以有人长年得到劳症没有治好，到头来就会变成遗精。这精一直出来，病 人会受不了的，当然会很难过，每天精神萎靡，我们有中药可以去固他的阳虚，也有中药可以补足他的阴虚等等。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '6、劳之为病，其脉浮大 ，手足烦，春夏剧，秋冬差 ，阴寒精自出 ，痠削不能行。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q9xBqKJNavZ', 4, '{"title":"7、男子脉浮弱而涩 ，为无子，精气清冷","description":"<p>7、男子脉浮弱而涩 ，为无子，精气清冷。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008007,"note":"       这里说如果是『脉浮弱』浮脉代表气脉，脉浮起来时表示气上浮， 就是意味病人的表虚掉了。涩脉代表血不足，也代表病人的精血不够， 代表里虚掉了，有这种现象的病人一定不会生子，因为『精气清冷』， 这种男人不容易生小孩，也就是说有劳症的人不容易怀孕，而我们中药里有处方可治，诸位看下面这个方子。\n\n       这个方子一剂知二剂已，有没有效，你们自己去试看看就晓得了。所以如果十七、八岁的小孩居然面色薄白，这就是他在刚开始发育的期间，生理的反应造成晚上睡觉时他会梦遗。如果只是偶而遗个一、两次是很正常的，没有多大关系，因为满则溢。但是如果很严重时，人就会虚掉，此时可见他脸上的气色整个是薄白的，精神萎靡不振，这就是桂枝龙骨牡蛎汤证了。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '7、男子脉浮弱而涩 ，为无子，精气清冷。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XDz9jTYHF01', 4, '{"title":"8","description":"<p>8、夫失精家，少腹弦急 ，阴头寒 ， 目眩 ，髮落，脉极虚芤迟 ，为清谷 ，亡血失精。脉得诸芤动微紧 ，男子失精 ，女子梦交 ，$f{桂枝龙骨牡蛎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008008,"note":"        举凡精不固与精不足都属于失精家，这就是所谓虚劳的病人，\n\n       『少腹弦急』这个弦急是因为肾阳伤到造成的，少腹里面感觉到好像有一 条筋在拉扯，这是因为水不能生木，肝主筋，今肝木无水来滋润，故筋急，而肝的筋是直接络在少腹。一般我们如果有少腹痛时，多因脾 脏过寒导致，此时经方家都会重用白芍来止腹痛。现在这个情形用白芍是没有用的，因为病人是『筋急』，这是因为肝虚掉了。\n\n     『阴头寒』就是甚至于会感觉到阴部前头都是冷冰的，此际必兼有头昏眩，『髮落』就是连头髮都掉下来。『脉极虚芤迟』代表说里面阴精极度伤到了。下利『清毂，亡血失精』，就是东西吃下去，肠胃里太寒导致吸收功能不好，于是吃下去的东西尚未消化，就通通拉出来了，这就是下利清谷。病家本来血就不够了，现在再加上津液一直往外漏，如此不但元气无法恢复，加上病人的津液又不断的丧失，无 疑是雪上加霜。\n\n       病人处在这种状态时，我们开立处方时，第一个就要顾虑到脾脏，让脾胃能够正常的吸收营养。第二个要去固肾脏，固他的元精。\n\n     虚劳的症状就是『脉得诸芤动微紧，男子失精，女子梦交』女人、男人都会有这种现象，这就是『桂枝龙骨牡蛎汤主之。』桂枝龙骨牡蛎汤内 容是桂枝、芍药、生姜等量用，也就是很简单的桂枝汤加龙骨牡蛎， 但是在这里把生姜加重，龙骨牡蛎也要加重，一般我在处方时用到桂枝龙骨牡蛎汤的时候，基本的剂量上是桂枝三钱、白芍三钱、生姜三 片起跳。\n\n       如果遇到很严重的失精家时，龙骨牡蛎就不会只用三钱，开个五钱、一两的都不为过。给病人吃多一点，只好不坏。而龙骨与牡蛎，牡蛎能够补骨能够滋肾阴，龙骨能够固敛肾阳，如此阴精就不会遗漏了。牡蛎的用途很多，像是但头汗出时，牡蛎能够把头汗降下来。 浮阳在上面是因为下焦阴虚，牡蛎能滋阴，所以牡蛎可以将此浮阳降下。牡蛎味咸，故又可以攻坚。\n\n       当我们三焦、淋巴系统不通利的时候， 比如说在淋巴腺上有长肿瘤，我们就可以靠牡蛎来攻坚。牡蛎又可以生精，不要让阳精往外泄时，需要靠龙骨来收敛阳。但已经泄出去的精要靠牡蛎去把它补回来，龙骨只是固涩精不外流用的，桂枝汤用来健脾胃促进营养的吸收，对于失精家我们经方家最常用的处方就是桂枝龙骨牡蛎汤，这也是专门用来治虚劳的处方。\n\n       尤其此方用于年轻人效果很明显，有的年轻人偶尔遗精还没有关系，可是严重的时候必须用药来帮助他们，这时桂枝龙骨牡蛎汤一剂下去，时常是第二天气色 就变回来了，为什么会如此快，因为年轻人还是纯阳之体。如果遇到七十几岁的老先生，你一剂下去是不会立即就看到效果，时常是石沉大海，吃下去没什么感觉，所以要连续好几剂才行。我之所以强调年轻人一服下去，马上就看得到明显的改变，换句话说就代表这个处方是对的，西医对这种病是绝对没有办法，又不能拿个橡皮筋把阴茎扎 起来，得到这病是很痛苦的。年龄大的人可能要吃好几剂，你也可以加重剂量给他们吃，没有关系。\n\n       这里跟大家提出来，我们如果再深入了解一点，病人失精，临床 上看有三种症状，我在此比较一下让大家更明瞭。第一种症状比较浅， 是有梦乃遗，就是做了梦以后才会遗精出来，这个病况最浅，一剂知 二剂己，就是一剂就好了。第二种比较重，无梦而遗，睡觉中间没有作梦，就会遗精出来，这就比较深了。第三种最重，醒时亦遗，这是 最深最重了，剂量要随症轻重而做些加减，基本上桂枝龙骨牡蛎汤是非常好用的一个方剂。","videoMemo":"","fangList":["桂枝龙骨牡蛎汤"],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '8、夫失精家，少腹弦急 ，阴头寒 ， 目眩 ，髮落，脉极虚芤迟 ，为清谷 ，亡血失精。脉得诸芤动微紧 ，男子失精 ，女子梦交 ，$f{桂枝龙骨牡蛎汤}主之。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7MqBeLmlYte', 4, '{"title":"9、男子平人脉虚弱细微者 ，喜盗汗也","description":"<p>9、男子平人脉虚弱细微者 ，喜盗汗也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008009,"note":"       你遇到一位正常的男人，一切都好好的，但是你摸他的脉时「咦？ 怎么脉重按就没有，那么虚、那么弱。」不仔细找还找不到，就代表此人的气虚掉了。\n\n      气一但虚掉，表就不固，不该流汗时却会流汗出来， 就是『喜盗汗也』，身体在很虚弱的状况之下才会有盗汗。所谓盗汗 的定义就是说，有时候醒到都会盗汗。你运动跑步后会流汗是正常的， 但是如果你坐着不动都会流汗，就是盗汗，有的人晚上睡觉时都会出一身汗。当然如果你作梦梦到有人追杀你，于是出一身冷汗，这没什么问题。\n\n      如果没事而早上起来的时候床上都是湿的，就是严重的盗汗， 这已经是代表气血两虚了，这个时候照样可以使用桂枝龙骨牡蛎汤， 不是只有用在失精家。中医的观念认为我们身体的津液、精、血这三样是同源的，所以可以用同样的治法来治，千万不要死脑筋说：「老师!失精家我记得如何治了，但是亡血家与失津者就不知道如何治 了。」其实都是一样的诊断，也是一样的治法。所以遇到盗汗很严重 的人，我们用桂枝龙骨牡蛎汤也一样可以将他治好。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '2025-03-10T08:57:21.000Z', '9、男子平人脉虚弱细微者 ，喜盗汗也。', '2025-03-10T08:57:21.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O3HABPciY2o', 4, '{"title":"10、人年五六十，其病脉大者，痹侠背行","description":"<p>10、人年五六十，其病脉大者，痹侠背行。若肠鸣马刀侠瘿者 ， 皆为劳得之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008010,"note":"        五、六十岁以后的人，如果被摸到脉是大的，也代表是劳症，这 种中年以后得到劳症的人会有哪些症状出现呢？就是『痹侠背行』。 因为督脉是诸阳之会，中年以后本身气血开始衰了，结果又有劳症在身上，会让整个脊椎骨，就是整个督脉，一直麻木下来，跟西医讲的 「脊髓神经麻痺 」很类似。\n\n        而中医是说病人的整个脊髓都麻掉，由于 督脉是诸阳之会，当阳虚时，就会产生这种症状，所以劳症我们要赶 快治好，不要等到五、六十岁以后再治疗就更麻烦，有时劳病人还会跟有『肠鸣』的症状。\n\n        什么叫『马刀侠瘿者』？ 马刀是弯型的，像个蚌壳一样弯的，而这个外面像马刀形状的坚节，在腋下淋巴节聚集的地方，可以摸到一块块的肿疖，侠瘿就是甲状腺腺体都肿起来了。中医说：「劳症要不早治好的话，等到五、六十岁就会有这种现象。」所以这种病起因就是因为劳症没有治好后而得到的。\n\n        因为劳症的人大部分都是虚热症，虚热在上方一直蒸热，直到津液干掉，当我们人体的正常水份被消耗掉以后，就会造成许多坚块慢慢的累积在三焦系统里，而腋下部位是胸阳刚出来的地方，下巴就是指甲状腺，如果阻塞到就会成为硬块，中医就叫做『瘰历』，如果已经破掉了，流脓出来的话，中医有另外一个名称，叫做『鼠瘻 』。\n\n       为什么叫鼠瘻？ 因为它整个像老鼠一样，很大，绷起来了，已经不规则，然后破个洞，一直流脓出来。这种症状归其原因，中医认为是因为长期有劳症未被治好而得到的。所以很多这种病过去没有被认定是疾病，因为西医学根本没有劳症之说，凡有劳症的人去检查身体，千篇一律都是「很好啊， 你没有病。」「可是我每天都很累啊？ 」「你没有病啊？ 」这种对话是 很常见的。实际上此时中医就已经认为有症状了，摸他的脉就可以知道，还有看一些外症也可以知道。\n\n       『外证见马刀侠瘿，则脉见弦大，时医以为小柴胡证，其实不然。 马刀之状，若长形小蚌，生于腋下，坚硬如石。』『成脓溃烂』，这个 中医就叫做鼠瘻。『侠瘿生于颈项，连连如贯珠。』『初起用旱烟?中烟 油涂之』过去是用旱烟?里面的烟油涂之，三天就好了。\n\n        内服的药，多施以小柴胡汤，如果遇到坚块很大时，就没有什么用了。但是我们可以用小柴胡汤来做一个加减，后面会跟诸位介绍， 有很多特殊攻坚的药，可以加进去，尤其像是牡蛎就非常好用，凡是 堵在淋巴系统内的肿瘤都可以用它来攻坚。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '10、人年五六十，其病脉大者，痹侠背行。若肠鸣马刀侠瘿者 ， 皆为劳得之。', '2025-03-11T04:01:29.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vegsj3UoBWU', 4, '{"title":"11","description":"<p>11、脉沉小迟，名脱气，其人疾行则喘喝，手足逆寒，腹满， 甚则溏泄 ，食不消化也。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008011,"note":"       如果一个病人的脉出现沉、小、迟，来的很慢，一息才一至、两至，中医叫做『脱』，就是元气虚脱，是很危险的症状，病人稍微走 快一点就会喘，这是虚劳至极的现象。\n\n       手脚冰冷，『腹满，甚则溏泄， 食不消化也』这种症状也都表示病人是在极度虚弱的状态之下。大家 看到后就可以知道此处的手脚冰冷、腹满、溏泄等，就是四逆汤证， 是很危险的。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '11、脉沉小迟，名脱气，其人疾行则喘喝，手足逆寒，腹满， 甚则溏泄 ，食不消化也。', '2025-03-11T04:01:29.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VAnwykl7Tgi', 4, '{"title":"12","description":"<p>12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚， 虚寒相抟 ，此名为革 ，妇人则半产漏下 ，男子则亡血失精。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008012,"note":"     『脉弦而大，弦则为减，大则为芤』，脉摸到弦脉，大部分都是有水饮的脉，就是身体里面有水气。大脉，就是脉形中间是空的，这是失血的脉，\n\n     『减则为寒』就是水饮脉出现表示是里寒。\n\n     『芤则为虚， 虚寒相抟，此名为革』如果遇到病人的脉是沉、弦、小、细，这种的 脉型中医称做『革脉』。\n\n       如果是妇人被摸到这种脉就会『半产漏下』， 就是很容易流产。如果是男人，就表示此人『亡血失精』，这种就是利用脉症来做辨症。\n\n       所以有的人说：「老师我没有病啊!你看我精神很 好，上课啊，什么都很好，可是我一怀孕就流产，外表看起来却还是很壮的。」这种成因就是虚寒相抟，这时候我们开补虚的药，还有去寒的药加在一起就可以了。\n\n      中医如何分辨病人是气虚还是血虚呢？简单说如果病人脉浮大，就是血虚，如果是脉微细，就是气虚。遇到气虚时我们要开补气的药，像黄耆、人参、党参这类就是补气的药。补血的药像当归、川芎等，这都是补血的药。去寒的药也要开在里面， 像干姜、附子这类去寒的药，这是我们用脉症来做区分。而一般亡血失精的人可以用天雄散来治疗，切忌使用寒凉滋阴之类的药物。\n\n       天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。\n\n       如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。天雄散就是用散剂，『天雄三两炮』如果散剂的话我们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上有一点失去方义，其实是可以用牡蛎的。将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。\n\n       吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠一些药把它带到它该去的地方。\n\n        你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。\n\n        阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。阳虚和阴虚治法不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。阳虚的人脸色一定晃白，因为阴寒很盛，舌苔也是白的。\n\n        阴虚的人阳会亢在上面，会看到黄色舌苔。或者是脸色红润一点，或是眼睛红肿，可以看到血丝都蹦出来。天雄散，大家可以在旁边写上『里阳虚』。后面是当看到表阳虚时，我们就用小建中汤。这里是里阳虚，因此天雄散里面的药通通是走里的药，还有一个药叫做锁阳，也是属于壮阳的药。\n\n如果每天练易筋经之类的气功，是不需要这些壮阳的药，保证你 很壮。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '12、脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚， 虚寒相抟 ，此名为革 ，妇人则半产漏下 ，男子则亡血失精。', '2025-03-11T04:01:29.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HR1H3x1R2C1', 4, '{"title":"13","description":"<p>13、虚劳里急，悸衄腹中痛，梦失精，四肢痠疼，手足烦热，， 咽干口燥 ，$f{小建中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008013,"note":"       『虚劳里急』有虚劳症的病人都会有腹急痛的症状，\n\n        『衄』就是 流鼻血，吐血。悸，就是心动悸。\n\n        『腹中痛』，肚子痛。『梦失精，四肢痠疼，手足烦热，咽干口燥，小建中汤主之。』小建中汤本身专门是用在病人有表阳虚的时候。\n\n         伤寒论里面从头到尾就只有两个补虚的方子，里阴虚时，张仲景用炙甘草汤来补之，表阳虚时用小建中汤来补之。产生表阳虚是因为病人心脏的血量不足而造成的，由于肠胃吸收功能不好，没有办法将食物化生成血运送到心脏里面，这个时候就会出现心动悸的现象。当人阳虚的时候，里阳会浮上来，所以我们看 到好像有热在上面，实际上是里寒很盛，才逼着阳往外出。阳虚的时 候，阳会浮上来，没有办法继续停在中焦、下焦这边，当然血会逆经， 于是就会从鼻子流血出来。\n\n        『腹中痛』指肚子痛，这是肠胃里面消化不好。如果里阳虚，做梦就会失精、无法固守。表阳虚的时候太阳寒水也不能固阳，会造成肌理津液丧失。\n\n        『四肢痠疼，手足烦热，咽干口燥』，看到病人好像是热症，因为有咽干口燥，实际上是阳虚，而不是实热。所以我们遇到 不管是桂枝汤证或是麻黄汤证，可能是大青龙、小青龙汤证时，凡遇到有表阳虚时，就先要把肚子痛治好，也就是要先使用小建中汤。\n\n         如果遇到病人出现脉结代时，无论是什么病症，我们应该先把里阴补足， 这就是使用炙甘草汤的时机了。\n\n         炙甘草汤服下去以后，要等到病人的脉恢复正常后，再去看他还有什么其它症状再去治疗。\n\n          经方中医只有分阳虚跟阴虚，当看到虚症病人又有桂枝汤证时，我们知道光是开桂枝汤给病人是没有效的。\n\n          所以常常小孩子发烧开葛根汤给他们吃，结果两个孩子中，一个好了， 一个却没好，这不是你开错处方，而是这个小孩在得到感冒前，原本身体就已经虚掉了。此子必然平常就不太喜欢吃东西，因为肠胃消化不是很好，这个时候我们应该先用小建中汤将他的表阳虚补足。补足后，肠胃功能就会恢复正常，此时吃任何食物都会变得很好吃，体力加强以后，感冒自然而然就好了。\n\n          所以本来都是葛根汤证的，结果一个小孩子吃了葛根汤以后好了，另外一个就要给他小建中汤才可以治 好同样的感冒，这就是这条辨的重点所在。小建中汤也时常被用在治 疗肺病上，上次我跟诸位介绍，治肝，我们时常用苦温化湿法，像乌梅丸、吴茱萸汤等，最浅的治肝处方就是小建中汤了。\n\n          所以遇到肝病 的病人，我们给病人吃小建中汤就是怕肝木克到土，就是肝肿大压迫到脾脏，小建中汤能够健脾阳。所以说如果我们将小建中汤放在减肥药里面，结果效果正好相反，它不是减肥药，而是增胖药，因为它建脾阳功能非常强。所以从这里可以知道，我们开减肥药时绝对不会用 到小建中汤，这是常识，药性是相反的。综合上述可知小建中汤是经 方中医们专门用来治疗劳症里的『虚劳里急』特有症状时所使用的。","videoMemo":"","fangList":["小建中汤"],"bieMing":""}}', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '2025-03-11T04:01:29.000Z', '13、虚劳里急，悸衄腹中痛，梦失精，四肢痠疼，手足烦热，， 咽干口燥 ，$f{小建中汤}主之。', '2025-03-11T04:01:29.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0S0EjYwmgMc', 4, '{"title":"14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之","description":"<p>14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008014,"note":"        这黄耆建中汤就是小建中汤里加黄耆。我们有『黄耆建中汤』还有『当归建中汤』，为什么要加黄耆？ 因为黄耆入气分，属于气药。\n\n        黄耆跟当归，这两个是一个补气一个补血。很多人都误解以为人参是 主气，实际上人参是补足肠胃津液用的。我一直跟大家说心下痞症就是指肠胃炎，张仲景在所有治疗肠胃科的药里面都放人参进去，就是 担心病人发汗过多，使得肠胃津液丧失时，这时就要在桂枝汤中加点人参进去，来把津液补足。\n\n        而实际上我们遇到病家气不足时，就要靠黄耆来补足气。黄耆建中汤证本身除了病家必有的小建中汤证以外， 还要加上气虚的症状。小建中汤症最明显的症候是肚子痛，因为肠胃虚寒掉。\n\n        仲师说：『虚劳里急，诸不足』，就是全身都出现不足的症状时，同时有那么多的虚症，要怎么加药进去呢？仲师之意是只要加黄耆一味药就好了。而当归建中汤是用在同样有里急、有腹痛、同样有阳虚，可是在阳虚的同时这个病人的血也虚掉了。\n\n        当归建中汤与黄耆建中汤还有另外一个主要的辨症，就是用两手同时摸病家的脉，由于人体$m{左边主血}，$n{右边主气}，当左手的脉变细小无力时，就是当归建中汤证。如果是右手的脉很弱时，就要用黄耆建中汤，如果两手的脉同时都弱了，就不必如此细分，直接开小建中汤给病人就可以了。\n\n       诸位看『黄耆建中汤是小建中汤内加黄耆』，就是要重用黄耆，大家开小建中汤的时候千万不要忘掉白芍量是桂枝的两倍。\n\n     『若气短胸满者加生姜』，气短胸满的原因是因为我们的小建中汤喝下去了以后，如果遇到病人中焦原来就有积水在，妨碍到气机流行， 建中汤的目的是要将中气建立起来，可是肠胃里还有积水未退，此时就要加重生姜，因为生姜有散去肠胃积水的功能。后面还有枳实桂枝生姜汤证等，治疗胸痞时都会用到生姜。\n\n     『腹满者去枣加茯苓一两半』， 腹满是因为有湿聚在肚子里面，小建中汤是治里寒就是肠胃虚掉的时候用的。当人的肠胃虚掉后，湿就一定会停积下来，如果湿没有去掉， 日久就变成留饮，就是水越来越多了。留饮再没有去掉的话，就变成溢，就是水满出来了。张仲景说有湿的时候还可以用小建中汤，如果变成留饮，小建中汤就没有用了，需要加一点茯苓进去，茯苓可以把 这个湿排出来。如果变成溢饮的话，张仲景就会用十枣汤，因为水太 多而且已经进入肺了，此时唯有十枣汤才可以把积水排出来。\n\n     『疗肺虚损不足，补气加半夏三两』半夏在这里有一点要注意，后面会再跟大家再重新强调，张仲景用$m{半夏的原则}是，只要$n{有渴就把半夏拿掉}。 病人没有渴症时，就会用到半夏。\n\n       我们在治疗湿症时，光是开燥剂去湿是不够的，因为里面仍有许多浊痰未去，所以说我们都会加半夏入内，因为半夏可以把浊痰同时清掉，这时候半夏不需要加很多。因为病人已经有渴症了。如果这个时候你没有加半夏把这个浊痰去掉，就会造成湿去浊痰没去。也就是本来停在湿里面的脏痰没有排掉，只有湿被排掉，以后日子久了，病人就会开始慢慢咳嗽，胸腔里面就会出现痰饮咳嗽，痰的产生其实是之前没有被排掉，遗留下来的问题，所以痰看起来并不是很干净的痰。\n","videoMemo":"","fangList":["黄耆建中汤"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '14、虚劳里急 ，诸不足 ，$f{黄耆建中汤}主之。', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vogY83SIxEB', 4, '{"title":"15","description":"<p>15、虚劳腰痛 ，少腹拘急 ，小便不利者 ，$f{八味肾气丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008015,"note":"         『八味肾气丸』又名『金匮肾气丸』，又名『桂附八味丸』。主治所有的虚劳不足，此处讲的都是指肾阳不足和肾水不足。\n\n          如果是肾水不足，我们就用六味地黄丸。水就是阴，水是津液，我们的内脏本身都有一定的津液在里面，如果肾太干燥了，我们就用六味地黄丸。「老师你怎么知道肾水干燥？ 」你可以看病人的头髮，头髮干干的，或是有耳鸣等都代表肾气不能固守，就是肾水不足，这时候就要用六味地黄丸。但是六味地黄丸要记得它的剂量。\n\n        八味肾气丸，仲师原来并没有写方子在这里，而是写在妇人杂病篇里面，我在这里先跟大家解释 一次，后面就可以加快速度了。\n\n       金匮肾气丸也就是肾气丸，大家看地黄的剂量是八，山药、山茱萸四，泽泻、丹皮、茯苓三，桂枝、炮附是一。诸位把下面的桂枝跟炮附子先去掉，上面的六味就叫做六味地黄丸。\n六味地黄丸里面要重用地黄，所以它才被称为地黄丸，跟山药、 山茱萸还有泽泻、丹皮、茯苓，这些药是三补三泻的合用处方。所谓三个补，就是地黄、山茱萸、山药，山药就是淮山，也叫『薯蓣』， 下段我会介绍薯蓣丸，讲的就是淮山，这是三个补药。三泻是指泽泻、 丹皮还有茯苓。这六味药配合得非常好，但是剂量要弄清楚，一般药房制作时都是等量在用，这是外行话，稍微研究一下也知道不是用等量。张仲景用补药时的剂量都会比较重些，而此处用的最重是地黄， 因为它能补肾阴。\n\n        尤其是地黄生用的时候会直接入血分，补阴的力量非常强，而当归是补脾胃的血，还有妇科血虚时用的，跟地黄的药性不一样，地黄是补肾脏这一带的阴血。山茱萸这个药是补肝脏的，滋养肝的阴虚。淮山就是山药，主要是要增润脾脏津液用的，这几个药用在一起是希望同时能够把脾肾肝的阴津壮起来，能够嘉惠到肾脏。 就好像麦门冬，麦门冬可以润肺，如果肠胃里面太燥了，我们可以再加一点甘草、生姜、红枣下去把肠胃润起来。\n\n        中药里面有很多药都可以配合使用，这三个药合用的目的就是要滋润肾脏的阴。同时也要注意三泻，因为中医的观念里面认为说『补能恋邪』，如果光吃补药， 没有加入清除的药，于补到的同时也会固守肾脏里面的浊物排不出 去，肾脏里面本来就有很多浊物，日久会变成肾结石之类的实积，堆在里面无法排出去，因为考虑到这个，所以仲师加了泽泻、丹皮、茯 苓进去。泽泻本身能利肾疏肝，能够把这二个脏洗得很干净。\n\n       丹皮的作用是活血化瘀，所以大家吃了六味地黄丸后感觉到大便变得很通 畅，原因就是有丹皮在里面，像金匮的肠痈篇会介绍到『大黄牡丹皮汤』重用到丹皮，大家学过以后从此遇到急性盲肠炎就不用上西医院开刀了，如果大家以为急性盲肠炎开刀就会好，你就错了，实际上开完刀还是有问题在里面的，等到我讲到肠痈篇时会再跟大家做详细的解释，听完后从此你就不会再去开刀了，丹皮活血化瘀的力量很强。\n\n         茯苓可以利湿，把浊湿从小便消导出来，这就是茯苓之功。伏苓能够利中焦，泽泻能够走下焦、走肾脏、走肝脏。这六味药搭配在一起， 补泻兼具是很完美的组合，所以使用上就百无禁忌了，因为里面没有加入热性的药。有一种状况下需要用到桂附，当肾阳不足时我们要把肾阳补起来，就一定要用到阳药，炮附子本身可以温补肾阳，将肾阳壮起来。\n\n      为什么要用桂枝呢？这是因为加强肾脏功能的同时，必须要强化心脏，如此才能够将肾阳补回。心脏、肾脏之间本身有大动脉连系着，要让心脏血往下走肾水往上走，也就是要将心阳往下降，肾阴 往上升，心肾相通的这个部分就要靠桂枝了。\n\n       后面妇科篇里面有许多地方我们也会用到桂枝，太阳病处方中用到桂枝的地方也最多，像桂枝汤，很多医师开完桂枝汤给病人后，病情恢复就好了，没有深入去 想过它。经过我看过各家的注解以后，我发现到，张仲景非常优秀， 他高明在他已经了解到桂枝实际上可以壮心阳，就是让心脏强起来， 可是桂枝的壮心跟附子的壮心是不一样的。附子的壮心是能够让心脏 搏动的很快，于是使得心脏产生的热力能够透达到四肢末梢去。桂枝的壮心不是这样，桂枝也可以壮心能够让心脏跳起来，但是却是让心 脏产生的胸阳往下走。\n\n       桂枝味厚入血分，气辛香主发散，为阳药，也因为如此所以妇科里我们常常用到桂枝，就是因为它能够让上焦的血化生成乳液变成乳汁后，靠着桂枝的作用，将之导入冲脉，进入下焦后变成月经排出来。所以我们退奶的药里面一定会加桂枝进去。所以所谓的桂枝可以将胸阳往下导，就是将乳汁往下导，这乳汁经过小肠的火一烤，马上就变成月经了，介绍妇科时我还会再强调一下。\n\n       我们身上的津液来源在内经中说是来自心脏，实际上津液的来源是肠胃，但是肠胃的津液能够通达到四肢皮肤表面上，就是靠心脏帮助的力量。所以说桂枝服下去以后，心脏功能会被加强起来，于是津液马上就跑到四肢上去，否则身体要如何才能把肠胃的津液送达到皮 肤表面上去呢？肠胃本身并没有办法走表，必须要加强心脏的功能才行做到，因此必须要有桂枝。只要桂枝一服下去，津液马上就会发散到四肢、发散到身上，病人就开始流汗。\n\n        桂枝要同时配合芍药等量的使用，主要原因是如果病家汗水发出去太多，结果却不能回头，就会产生其他问题。张仲景很聪明，坏的排出去后，好的还要再回来，就好像派部队出去作战，部队打完了仗后，部队还是要回来的。这部队回来就要靠白芍把它通通收敛回来，所以白芍性酸主收敛，在本草经里面主要功能就是收敛，收敛就是收藏的意思。\n\n       一般我们补虚用六味地黄丸就好了，如果病人有虚热或者是实热，此时如果用桂附八味丸，病人就会更热，吃完后，嘴脣会干裂， 口中燥渴，又便秘等这些症状出现。就表示里热过剩。所以如果遇到纯阳虚的病人，此时你看到的都是阴寒的症状，这时你开桂附八味丸给病人；效果就会非常好。\n\n       但是如果是有虚热，像本来病家就有口燥咽干的现象，这是表阳虚，不是里阳虚，这个时候你开桂附一下去， 吃了喉咙就会痛，所以使用桂附时必须要先看清楚哪些人才可以用， 像是因肾阳不足而腰酸背痛的人、年龄大的人、虚寒的人桂附就非常的好用，张仲景使用桂附第一个地方是用在虚劳症里面诸不足的时候 用的。还有一个地方也在用，像下消糖尿病，当男子不能挺举时，张仲景处方也是以桂附八味丸为主来做加减。所以在金匮里有几个地方 我们可以看到仲师在使用桂附八味丸，此药的名称很多，但是药的内容都是一样的，这是治疗虚劳里急的药方中一个常用处方。\n","videoMemo":"","fangList":["八味肾气丸"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '15、虚劳腰痛 ，少腹拘急 ，小便不利者 ，$f{八味肾气丸}主之。', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5mmDCzhMmnA', 4, '{"title":"16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之","description":"<p>16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008016,"note":"      薯蓣就是淮山，也就是山药，薯蓣丸现在很少人制作，有几个药方如射干麻黄汤、乌梅丸、薯蓣丸都是属于方剂内容很多的药，张仲景很少开那么多的药在同一方中使用。\n\n     此处为什么开那么多药在一个方子之内呢？就是他认为平时就容易生病的人，本就是虚劳不足，所以没事就常常感冒发烧，当这次感冒好了，不多时又感冒了。遇到这种情形的病家就适合用薯蓣丸。薯蓣丸制造过程非常的麻烦，像里面的药如薯蓣、人参、白术、茯苓、甘草、当归、干地黄、芍药、川芎、 麦门冬、干姜、阿胶、大枣、桔梗、杏仁、桂枝如此多的放在一方内， 再加上神麯、豆黄卷、柴胡、白蔹都是同属于发散少阳三焦油网用的， 其他的药诸位都知道了，它是桂枝汤、各种建中汤、理中汤通通把它混在一起，是一个复方。\n\n      实际上我们不需要去做这个药，因为平常就在吃六味地黄丸，体内虚劳补足以后就可以了，病家有桂枝汤证出现时，我们就用桂枝汤来发表。出现柴胡汤证时、就用柴胡汤来和解。 时常用一些解表药，一段时间以后，病人就不会有虚劳里不足的症状 了。所以现在用的不多，这个药方，大家可以放在旁边做参考，现在几乎没有用这个药，我甚至怀疑此方不是出自张仲景原方，而是有人假借他的名声，把此方放置在这里目的是想更能说服人使用它，当然 现在已不可考了。","videoMemo":"","fangList":["薯蓣丸"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '16、虚劳诸不足 ，风起百疾 ，$f{薯蓣丸}主之。', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LkqnXMeQqRd', 4, '{"title":"17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之","description":"<p>17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008017,"note":"       酸枣仁汤多是用在一般老年人身上，睡觉只能睡两三个小时后就 醒过来，然后再也睡不着，这就是虚劳不能眠的症状，此时就可以用酸枣仁汤。\n\n       酸枣仁汤中有甘草、知母、茯苓、川芎等药在内，川芎这个药，本身是活血药，可以入血分，酸枣仁最主要的作用是养肝，酸味的药入肝，能够在肝里面养血。肝血足的时候，我们身体血的存量就会增加，于是就没有人会睡不着了，虚劳不足的人常常晚上担忧受怕，因此肝血就会受到耗损，当肝血不足时，它能把肝血补足。由于血还要同时供应给全身用，这就要靠川芎，有了川芎，血就会入脑再回归到肝里面，还有像妇人的经血跟肝脏也有十足的关系。所以在妇科治症里，常常都会加些川芎在处方里，像四物汤里面也都会有川芎。 \n\n       为什么要用甘草、知母呢？ 因为虚烦的人，一定会有热在上焦，因此 白虎汤里用到知母，就是专门作为除烦去热用的。如果只是热、渴、 不烦，就是石膏症。\n\n       如果是烦，就是知母，知母本来就是清胃热除烦用的。到底怎么才叫做烦呢？就是你看了此人觉得很讨厌，你想帮他又帮助不了他，实在不知怎么应付他，跟他讲什么都没用时，这就是烦躁。\n\n        酸枣仁汤中会使用甘草，是因为有虚热的人，肠胃消化就不会很好，必然会有很多食物的残渣停在胃里面，此时就要甘草来化解宿食产生的毒素。酸枣仁完全入肝脏，对于老年人虚劳不得卧的症状，帮助最大。\n\n      还有就是生产后有时也会有虚劳症状，还有就是开完刀以后也会有，大都是因为失血过多，于是造成的失眠。像身体比较强壮的，心胸又开朗，两眉间分的很开，或是眉毛很高的人，这种人开完刀照样睡。因为他天生就是不会忧烦的人。而两眉毛靠得很近的，或五官都挤在一起的人，不开刀时就已经睡不着了，开完刀后更睡不着，因为心事太多造成的。所以人在越虚的状况之下就越是睡不着，此刻大家就要想到用『酸枣仁汤』，喝下去会很好睡的。这酸枣仁汤也是『病后调摄之方治也』，所以大病以后睡不着的人，大部分都是酸枣仁汤证。","videoMemo":"","fangList":["酸枣仁汤"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '17、虚劳虚烦不得眠 ，$f{酸枣仁汤}主之。', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('osO704z7Eh9', 4, '{"title":"18","description":"<p>18、五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤 ，经络荣卫气伤 ， 内有干血 ，肌肤甲错 ，两目黯黑， 缓中补虚 ，$f{大黄蟅虫丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008018,"note":"       虚劳里还有一种症状， 比较麻烦严重的就是『五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤』，这段可以知道做运动要慢慢做，不要做成劳动，成为劳伤。\n\n     『经络荣卫气伤，内有干血』， 造成『肌肤甲错』。『肌肤甲错，两目黯黑，缓中补虚，大黄蟅虫丸主 之』。大家可以将『肌肤甲错』写成第一，将『两目黯黑』写成第二， 有这两个主要症状，就代表说体内有干血。张仲景说的『内有干血』 内指的是在肝里，只要体内有干血，不管是在哪个位置上，病家都会两眼圈黑黑的，还有『肌肤甲错』，就是皮肤上面出现脱皮，掉下白 色粉末状的皮屑，一拍就好像干面包屑一样掉下来。有时候出现在妇人小腿上面，也有的人生在背后面，皮肤会像蛇皮一样脱落下来。只要冬天一到，就开始脱皮，春天夏天就此较好，这就是所谓的『肌肤甲错』。\n\n       张仲景写『内有干血』这是非常高明的解释词句、因为临床上看的时候，体外症状都一样，在身体结构学上， 比如说胃、脾脏、 肾脏、肝脏、赡、小肠、膀胱，所有的脏，它的下方都是静脉血管聚集最多的地方，上面就是动脉。而病人的内有干血，有时候堵在这边， 有时候堵在那边都不一样，还有一种状况是内脏都没堵，全部的瘀血都是积在下腹腔内，我讲的是曲骨位，下焦腹膜的地方，有时囤积许多瘀血在此，而这是在脏腑之外网膜之内，血瘀在这里以后，慢慢的就会累积起来，这些瘀血是来自内伤，像五劳七伤之类。\n\n       仲师前面写 的『食伤忧伤』，如忧伤，饮伤，房室伤，肌伤，劳伤等都是伤，有时候是被打伤造成的瘀血，而这些体内的瘀伤，我们在身体外面可以看到一些症状。比如说，人虚掉的时候反而会流鼻血，血会因阳虚而逆经走，外症就是流鼻血，流鼻血就是表面上可以看到的症状。但如果是在身体里面血离经的时候，就没法看到身体里面是哪里出血，可是身体里面有出血，并不是像大动脉血管出血那么危险，只是一些脏腑下面的血自静脉中渗出来。\n\n        渗出来的血到血管外面以后，会到三焦网膜，或者停在腹膜的下方，或者在脏的下方，此时张仲景就判断是内有干血，他没办法讲出是在何处出血，因为每个人都不一样，但是无论干血停在哪里，你只要看到体外的这些症状，如眼睛周围黑黑的， 或是皮肤干燥，一到冬天就开始脱皮等等，都表示内有干血了，此时就要吃些『缓中补虚』的药物了。\n\n       这个大黄蟅虫丸有攻、有补，是攻补俱兼的药物，大家看看处方内容，大黄、黄芩、甘草、桃仁、杏仁、芍药，干地黄是补血的，芍药敛血，所以病人有肚子痛，或者是需要破血时，我们一定会用到芍药，病人如果有劳伤在，身体里面就会有瘀血，此时一定会有内热的现象出现，治疗内热我们需要加一点去热的药在里面，比如说阴虚内热，当你遇到病人正好是六味地黄丸证，而此丸剂是补阴用的，此时增加补阴的药就不会有反作用。\n\n       但是如果要用到桂附八味丸，病人同时又有热症出现时，你就要在桂附八味丸里面加一点黄芩、黄连，就是去热的药跟补虚的药同时使用如此就不会热了，大黄在此的作用是通瘀，后面的药像蟅虫、水蛭、蛴螬、虻虫，这些都是攻瘀破血的药。 \n\n       过去中医称这种病，叫做『干血劳』，主因是身体里有干的瘀血， 日久而成劳症。这个药是丸药，采用丸药的缓性，让药物慢慢进入人体 内，把已经成为血块的瘀血慢慢让它化掉，化成血水以后，就可以渗透进肠壁管里，或者是进入膀胱。由小便或是大便排出来。\n\n       此方里用 的干漆是毒药，干漆是漆树的树皮『 一两烧令尽』，干漆拿起来是黏答答的，如果用手这样摸它，再张开时手指就黏住了，干漆必须要烧过才能用，烧的时候要使用瓦片或是铁板之类放在火上来烧的。将干漆放在上面一烤，就会有青烟冒起来，此时千万不要去闻它，很毒的。 \n\n       虻虫、水蛭在伤寒论时都说过了。\n\n      跻螬，过去我们用的跻螬，有人认为就是『地鳖虫』，也有人认为是刚生出来的蝉，身体还在壳里面， 还没有蜕掉外壳的蝉，蜕掉后外壳就是蝉蜕，蝉蜕是我们拿来治疟疾与皮肤病用的。如果它在壳里面就还会蠕动，这时就有人把它当成蛴螬来用。\n\n        还有人找它的方式是将我们以前灶里面的大锅子，翻转过来底下一票黑黑的虫，长的像蟑螂一样跑得很快，这就是蛴螬，又名叫地鳖虫，而谈到蟅虫时，也是这个说法。所以地鳌虫也有人说就是蟅虫。过去蛴螬跟蟅虫两种药，在本草里面扯不清楚，但是都是会咬血的虫。\n\n        在这里大家看看就好，因为这是汉朝留下来的药方，我们有时 候到这个药房去买蟅虫时，药房说就是地鳖虫，有时候我们要买蛴螬， 药房就会说没有统一使用的蛴螬。实际上临床用的时候我们不需要用这些药，因为张仲景不懂针灸，他不了解针灸的效果有多好。现代我们需要使用虫剂时，不要说蟅虫跟蛴螬不容易弄到，光是虻虫、水蛭， 你想弄到真正的虻虫、水蛭都很难了。\n\n       此时遇到有干血的时候怎么处理呢？大家记住，当病人身体里面有干血时、在膈俞上面会有压痛点， 因为隔俞是血的会穴，所以第七椎有压痛点出现时，我们就知道此人体内有干血劳，这是第一个症侯。第二个，如果病人是男子，你问他： 「你过去做什么的？ 」「我是练功夫的。」就可能有内伤在体内。再问 他：「你呼吸时会不会有痛，出现在固定的一个部位？ 」因为有干血的地方一定有痛，表示里面有瘀血。\n\n       得到干血劳的多半是女子，而且大部分的女子都是在左腹下方这一带痛，因为人的左边是血，右边是气。\n\n       如果是在肚子左侧，我们可以用灸治，因为脾主腹，可以在脾的募穴『章门』灸，然后在小肠的募穴『关元穴』再灸，近取穴部份完全用灸治，不需要扎针，热灸产生的热一下去，干血就化掉了，任何东西碰到热就化掉。脚下我们可以下针，有干血的人，三阴交一定会有压痛点，而血海可以消导瘀血止痛经。背上第七椎不要扎针，也是用灸的，灸他的膈俞，让血液循环加速，这是我们针灸并治干血劳的方法。\n\n        如果是胸腔有内伤，不要扎三阴交跟血海，需要用公孙与内关， 来打通病人的冲脉跟阴维脉。公孙与内关可以行气来治内伤的部分， 然后使用小柴胡汤加桃仁、红花。这是治疗胸腔有瘀血的活血化瘀法。 \n\n       下焦部位的瘀血，就是指肚脐以下，如果是妇人科，就不需要用这些药，可以选用大剂的白芍，如白芍一两、炙甘草一两，这样用药可以强到连双腿的静脉曲张都可以把它收敛起来，然后再加一些和解的药 进去，像川芎等，这是我们经方家时常在使用的治疗干血劳的方法。 \n\n       因为这大黄蟅虫丸的处方，我们历代经方家一直到现在，代代都认为它不合用，因为找不齐药。以前在大陆上也不容易找到这些药，再加上还有一些名称上的错误，产生的原因我想是因为方言造成的，中国人的方言繁多是举世皆知的。\n\n      使用白芍、川芎就可以活血化瘀，但是一定会加当归，加当归的目的是把不足的血再补足，然后靠白芍来破血，绝对不能开很大剂的破血药，否则会造成瘀血被攻出来，但是却停留在组织外面而没有排出来，于是内脏被药物伤到，所以此处用白芍，再用当归、川芎，然后加些炙甘草下去，让瘀血慢慢的被和解出来。其他破血的部分我们可以用针灸来行气活血，这是临床上用的最简单的方剂。\n\n       当然这个要用大剂的才有用，比方说川芎是一两，当归就是一两，可以大剂的用。如果你问说：「老师，可以加桃仁吗？ 」 当然可以加桃仁，桃仁跟红花不一样，红花破血的力量很强，桃仁比较着重走三焦，但是桃仁的油脂很多，所以女子吃多了就会长青春痘， 这是它唯一的缺点。红花比较着重在血分里面走，破瘀血的力量很强， 所以红花不能吃多，重用红花时可以堕胎。我们如果遇到妇女胎死腹中，我们才会大剂的使用红花，也就是一两、二两的开。如果你开大剂破血的药，却不同时开些补血的药，病人一吃身体就会虚掉，因为它会把好的血也同时破坏掉。\n\n        中医使用很多虫类来做为药物，像虻虫、水蛭、蛴螬、蟅虫这些 虫的天性就是会咬破血，可以用做攻瘀血的药。瘀血干掉时我们靠白芍、干漆、桃仁，来把它破出来的。咬破血块的部分就是要靠虫的药， 当然像这个虻虫、水蛭、蛴螬、蟅虫是不会受到野生动物保护法的保护，使用它们没有什么关系，只是非常不容易取得真正的药材。大家看看这里有二个也是很好用的处方。\n\n","videoMemo":"","fangList":["大黄蟅虫丸"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '18、五劳极虚羸瘦，腹满不能饮食，食伤忧伤饮伤房室伤飢伤劳伤 ，经络荣卫气伤 ， 内有干血 ，肌肤甲错 ，两目黯黑， 缓中补虚 ，$f{大黄蟅虫丸}主之。', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ppJcqpl1ham', 4, '{"title":"19","description":"<p>19、方剂补充《千金翼》$f{灸甘草汤}  治虚劳不足汗出而闷，脉结悸，行动如常， 不出百日，危急者十一日死。</p>\n<p></p>\n<p>    《肘后》$f{獭肝散}</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905008019,"note":"","videoMemo":"","fangList":["灸甘草汤","獭肝散"],"bieMing":""}}', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '2025-03-12T04:42:42.000Z', '19、方剂补充《千金翼》$f{灸甘草汤} 治虚劳不足汗出而闷，脉结悸，行动如常， 不出百日，危急者十一日死。 《肘后》$f{獭肝散}', '2025-03-12T04:42:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'Cea3eDc6G5J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G6j4cEpz2Mg', 4, '{"title":"1","description":"<p>1、问曰：热在上焦者 ， 因咳为肺痿 ，肺痿之病 ，从何得之？</p>\n<p> </p>\n<p>     师曰 ：或从汗出，或从呕吐 ，或从消渴，小便利数 ，或从便 难 ，又被快药下利 ，重亡津液 ，故得之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009001,"note":"       在讲这个之前，大家要先了解，光是说出一个热在上焦，你马上要连想到「寒在上焦怎么办？ 」也就是我们后面要介绍的大建中汤证， 如果是寒在中焦就是小建中汤证，寒在下焦就是桂附八味丸证，慢慢的要让大家都能够很熟练的运用这些经方。\n\n       现在这里说的是热症，我们要求病人说：「先生，请您将舌头伸出来让我看看。」这个舌头的诊断方式是这样的，我们将舌头分成三段来看，舌头最里面就是上焦，舌头的中央是中焦，舌尖的部位就是下焦。如果你舌头最里面黄黄的，就代表上焦有热，如果是中间黄黄的，就是中焦有热，如果黄苔出现又厚又黏就是湿热重症，如果是舌头前面的舌苔很黄厚，就是有溼热在下焦。这个湿热在下焦很可能就是膀胱炎、尿道炎、或者是肛门痔疮等等，这些是舌诊的一部份，舌头上一看，就可以知道热在哪里。\n\n        脉诊中的寸、关、尺也是代表上、 中、下焦的不同位置。如果你摸到一个病人的脉，寸脉跳得很数，但是尺脉却摸不到，这就表示病人是下寒上热，知道病人有下寒，我们就要开去下寒的药像附子、细辛就是了。\n\n      上热我们就要开去热的药，把去上热的药和去下寒的药合并在一个处方中，就是治上热下寒最好用的处方了，这个就是我们经方家开处方的技巧。\n\n      张仲景也要求我们用这种开方技巧才行治病，现在看到病人得到肺痿，表示是上焦太热了。热在上焦，是因为汗发掉以后，热没有去， 还是停留在肺中，日久就造成肺痿。\n\n      举例说像大青龙汤证与麻黄汤证， 大青龙汤是有表寒里热的症状同时出现时用的，如果你开错，应该要开大青龙的，结果你只看到病人表寒很重，没注意到病人同时有里热症，于是就开出麻黄汤，结果麻黄汤吃下去后，表寒是解掉了，但是里热却还在，当肺里面没有津液供给时，肺里面就会过热，这种就是由于汗出过多而造成肺痿。\n\n       第二种情形是『或从呕吐』，有时候呕吐吐太多，土来不及生金，使得中焦津液丧失。土必须要生金，因为肺的津液来源是靠中焦给的，如果肠胃的津液因吐而没有了，这也会造成肺太热，中医讲的热就是『炎』，就是发炎了。\n\n       第三种情形是『或从消渴』，消前面有讲过，就是水喝下去就从小便出来，人体根本不吸收，当然没有办法把水气化给肺，简单讲就是肺的源头没了。肺里的水是从肠胃来的，所以当你被汗、或被吐、 或者从消渴，还有『小便利数』『或从便难』等。\n\n        当病人小便利数， 水都排掉了，当然会大便难，因为津液已经自小便被排除掉了，无论是以上哪一个原因，结论都是因为肺里津液不够了、才产生肺痿，张仲景的意思就是这样。\n\n       当病人本来就有大便难的问题时后，然后『又被快药下利』，就是本来就大便很难，津液不足了，结果医师没看到病人是因为津液不足而便秘，于是选用承气汤来攻下，攻下去以后， 如果病家津液自己流回胃中，就不会有口渴现象，如果病人口渴，代表说病人津液丧失了，这时赶快用白虎汤，去帮助病人补足所丧失的 津液，如果你来不及，是隔了一个礼拜去看他，这时病人就可能转成肺痈了。\n\n        我们开处方给病人时，一定要断症精准，很多现在所谓的肺炎， 就是我们这里讲的肺痈，其实都是因为医师失治才造成的问题。肺炎就是因为感冒没有好，拖延时日才引发的，如果一个人得到感冒，碰到我们经方家，一剂汤药就可以解决，但是也只有我们经方家可以做得到，一般温病派的中医是不行的。\n\n      他们看到病人得到感冒，明明就是麻黄汤证，这汗要靠麻黄才能发表发出来，结果他开出像连翘金银花板篮根之类的药，这是很平和的药。再加上开一点像栀子、柴胡之类一些的药，于是就寄望病家能因此而发汗。然后又怕病人不发汗， 还要求病人用被子将病人全身盖住。如果汗仍不出来，就再加一点葱 在里面给你发汗，弄了半天病人还是不发汗。当表寒强时，非要靠麻黄才能将汗发出来，结果因为不知用麻黄而导致病人不发汗。\n\n       很多肺病的起因，都是最初得到感冒时，医师失治没有将感冒治好，结果日久就转成肺炎。如果现在到处都是经方家的话，大家这辈子就再也遇不到肺炎的病人，我们诊所治疗感冒时都是使用桂枝、葛根、麻黄等汤剂，一剂病就去掉了，当然以后就不会有什么大病，我 一直在鼓励病人以后小病就来找我们，不要耽误时机。一个医院或是诊所看病，应该是病人越来看，病就越轻才对，哪有说越看病越多？ 病情变得越重？西医希望每个人都要有一张病床，这是天方夜谭，这 是什么医学？大家都生病都躺在那边，然后官员说请世界各国来看一 看，我们国家有多照顾百姓，因为每个人都有一张病床，这不是笑话 是什么？\n\n        感冒病毒本来只进入表，停留在皮肤上面，如果用汗法，一发汗它就跑出来。可是如果你来不及发汗，它就已经进入肺里面去了，这就是肺炎的原因之一。还有一种是，病毒一部分进入肺里面，一部分停在皮表上，这时我们就要表里并解，我们会需要用到小青龙汤或大青龙汤来将表症与里症同时去掉，结果医师开错药，又开成去表的药， 没有同时解里，于是表去掉了，里面的病毒还停在肺脏没有去掉，一段时间后就转成肺炎了。\n\n       仲师讲了半天意思就是因为『重亡津液，故 得之。』大家看到此处就会想：「老师，这样子看来后面的处方我们虽然还没看到，张仲景一定想了很多补足津液的方式去治疗。」对的! 西医补足津液的方式就是打点滴，可是打点滴的津液不是从病人胃里面进去的，会有一时之效。中医经方家会用白虎汤来补充失去的津液， 尤其遇到出现高热的会更有效。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '1、问曰：热在上焦者 ， 因咳为肺痿 ，肺痿之病 ，从何得之？ 师曰 ：或从汗出，或从呕吐 ，或从消渴，小便利数 ，或从便 难 ，又被快药下利 ，重亡津液 ，故得之。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kt5jrLaFT2W', 4, '{"title":"2","description":"<p>2、问曰： 寸口脉数 ，其人咳， 口中反有浊唾涎沫者何？</p>\n<p>      师曰：为肺痿之病。若口中辟辟燥咳 ，即胸中隐隐痛，脉反滑数，此为肺痈 ，咳唾脓血。脉数虚者为肺痿 ，数实者为肺痈。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009002,"note":"       『寸口脉数，其人咳』，寸口就是讲胸阳上焦的部位，此处的脉如果跳得很数，就代表胸里面很热，数脉就是热脉。\n\n       『其人咳』有咳 嗽，如果有咳嗽同时『口中反有浊唾涎沫者』，吐出来很浓的痰，『师曰：为肺痿之病』，这一种就叫做肺脏萎缩的病。\n\n        浓痰实际上就是肺里面的黏液，我们的气管里面有很多黏膜，黏膜上有很多黏液在。当病人肺里面太热的时候，这黏液的浓稠度就会增加，造成有很多痰液停留在里面，越来越满。\n\n       如果看到吐出很多黏液来，而且很污浊，这表示病人肺的组织已经发炎坏死掉，所以才咳出这些浊痰，一般肺炎病久了都会有这种现象出现，这就叫做肺痿。\n\n        肺痿有时表症看不很清楚时，就需要将衣服拉起来看，如果看到病人肋骨骨缝中间的肉都陷下去，这就是肺脏已经萎缩掉，结果造成肋骨突出来，而肋骨中间的凹缝就变得很深，你的指头可能都可以放到肋 骨里面去。所谓『胸高』，就是息很高，永远是这样绷张的状态之下， 肋骨旁边的肉整个凹下去，可以看到排骨的排列，肋骨本身是不会真的凹下去，我指的是中间的肉，衣服拉开来后看到像洗衣板一样的样 子就对了，临床上可看到左边会比右边来的较饱满？如果是左边凹下去，这表示心脏没力了，因为心脏在左边之故，右胸代表是肺，如果整侧都凹下去，这时候你再看他右耳，耳朵中间点的左右两侧是肺点， 一看耳中肺点出现红红的颜色，红就代表有热。\n\n        临床上要会变通，看 耳朵也可以帮助诊断，我们有很多检查方法可以使用，大家千万不要忘掉。\n\n        张仲景说如果『口中辟辟燥咳，即胸中隐隐痛，脉反滑数，此为肺痈』。肺里面化脓的情形有二种，第一种是正准备化脓，另一种是已经化脓。如何利用症状去区分病人是已经化脓还是准备化脓。由于已经化脓和准备化脓，这二种通通属于肺痈，也就是里面有痈脓了， 这种病情的主要症状就是嘴巴里面一直在咳，可见脓血被咳出来，肺里面也一直发出咻咻的声音出来，然后嘴巴里面很燥、很渴，胸里面会隐隐作痛，这个时候寸口脉也是数脉，但是兼有滑脉。\n\n      『咳唾脓血。 脉数虚者为肺痿，数实者为肺痈。』，同样是数，如果是实热的话，就是肺痈。所谓实就是，不但数，重按都按得到脉，就是里面已经化脓 了。如果是肺痿，是虚症，重接后脉就没了，因为是虚脉，『脉数虚者为肺痿』。简言之实热的话就是肺痈，虚热的话就是肺痿，仲师就是这个意思。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2、问曰： 寸口脉数 ，其人咳， 口中反有浊唾涎沫者何？ 师曰：为肺痿之病。若口中辟辟燥咳 ，即胸中隐隐痛，脉反滑数，此为肺痈 ，咳唾脓血。脉数虚者为肺痿 ，数实者为肺痈。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NUOo26n7J6q', 4, '{"title":"3","description":"<p>3、问曰：病咳逆，脉之，何以知其为肺痈？ 当有脓血吐之则死， 其脉何类？</p>\n<p></p>\n<p>    师曰：寸口脉浮而数，浮则为风 ，数则为热；浮则汗出 ，数则恶寒，风中于卫，呼气不入；热过于营，吸而不出。 风伤皮毛，热伤血脉。风舍于肺，其人则咳 ， 口干喘满 ；咽燥不渴多吐浊沫 ，时时振寒。热之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009003,"note":"     『脉浮而数』如果摸到病人寸脉位，脉浮而数，浮就是风，病人  有表风，数就是热，而浮，也代表有表虚，故有汗出。\n\n    『数则恶寒，  风中于卫，呼气不入；热过于营，吸而不出。风伤皮毛，热伤血脉。 风舍于肺，其人则咳，口干喘满；咽燥不渴多吐浊沫，时时振寒。热 之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。』 这里讲的就是肺脓疡，就是肺化脓、肺痈的原因。会得到肺痈是因为  当病人有表症时，没有及早被治好，才会发生的疾病，如果一开始病  毒在表上就被去除掉，也就没有肺痈的问题。\n\n       西医对病毒的归类。看起来讲的好像很详细，实际上归类并不详细的。西方医学说肝病的人  是滤过性病毒、急性肝炎也是滤过性病毒，感冒也是滤过性病毒，肠炎也是滤过性病毒感染，脑膜炎也是滤过性病毒跑到脑里面造成的， 反正西医都是用滤过性病毒一个病名就将所有疾病都一起带过去。而实际上归类并无法帮忙治病，因为只知道有病毒存在，可是西医不晓 得怎么去掉它们，只想到要如何去杀死它们。\n\n       中医在看诊时遇到这种情形，最重要的观念就是我们事先就知道，这是因为胸腔里面的瘀热没有发散出去所造成的疾病，热闷在里面，就会越来越热，于是就化脓了，简单讲就是这样。所以我们遇到感冒的时候，一定要赶快把病人肺里的热同时一起去掉，否则以后就会有这些后遗症出现。\n\n       肺是诸阳之会，全身所有的阳通通会聚到这里，我们嘴巴里面会有口水升上来，就是肠胃的津液经过肺以后，再到了口中。如果肺有问题的时候，口就会很干，因为肺本身已经很热，津液到肺后就被气化掉了。\n\n       胸阳的地方本来就很热的，现在加上病热没有被排掉，热就会成为壮热，这就是仲师最重要的观念所在。\n\n       如果肺里面太热时，病人就会『口干喘满；咽燥』。如果病人此时反而不渴，就是肺里面已经化脓了，此时肺里面会有很多黏液停在里面，所以病人不觉得口渴。\n\n      如果病人是咽燥口渴，兼有壮热时，这是最标准的阳明经证，表示是因为血里面的水不够了才造成的壮热，这时候我们就要靠人参白虎汤 下去，这就不是因为肺里面的津液不足造成的病，这条辨里讲的是肺里面津液不足时，病人会有的病象，所以渴是一个主要区分的症状， 阳明证必有渴。\n\n      吐浊沫出来就是肺的气管里面的黏液一直排出来，『时时振寒。热之所过，血为之凝滞』就是太热了，血太热也会成为瘀血， 所以也不动了。这个时候，停留在肺里面的病毒就会慢慢的把肺里面的一些肺泡、一些组织逐渐的腐蚀掉，当组织坏死掉后就会化脓。\n\n      刚开始的时候『吐如米粥』，吐出来的痰像白米粥一样。所谓米粥，就是肺炎的病人吐一口痰在地上，过了两、三个小时后，这口痰会变的好大一团泡沫，因为里面都是病毒。『脓成则死』就是吐出来的痰， 像血块一样，掉在水里面就沉下去了。\n\n       浮在水上都没有毒，这是物性， 这痰会沉到水底，表示这毒有多厉害。如果你说：「老师，仲师说脓成则死，我们就不要治，等等看病人会不会死？ 」张仲景虽然如此说， 但是还是出方来治疗。所以现在大家了解到，当肺中积热过久，没有办法完全去掉的时候，有一天就会转化成这样子，这在现代西方医学来说就是肺癌了。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '3、问曰：病咳逆，脉之，何以知其为肺痈？ 当有脓血吐之则死， 其脉何类？ 师曰：寸口脉浮而数，浮则为风 ，数则为热；浮则汗出 ，数则恶寒，风中于卫，呼气不入；热过于营，吸而不出。 风伤皮毛，热伤血脉。风舍于肺，其人则咳 ， 口干喘满 ；咽燥不渴多吐浊沫 ，时时振寒。热之所过，血为之凝滞，蓄积痈脓，吐如米粥。始萌可救，脓成则死。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s0VxVMkUNrk', 4, '{"title":"4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚","description":"<p>4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009004,"note":"       这根本已经是死症。为什么是死症呢？脸孔浮肿起来，代表我们 讲的『阳已虚』。\n\n       阳虚掉后阳气就会整个往上走，到了肺上面还无治 疗时，阳气就会整个冲到头面上来，造成脸浮肿起来。\n\n     『肩息』代表病人的呼吸系统已经不行了，心肺即将衰竭，必须要摇动肩膀才能够深吸一 口气，因为呼吸变困难了。\n\n       如果此时病人脉变成很浮、很大、 很壮的时候，就代表阳脱了。我们人体里的动能与人体的精神即将要 离开身体时就会出现这些现象，这都是不治之症。\n\n       如果『又加利』， 病人大小便都失禁，表示阴又虚掉了；阳虚掉后造成阴再虚掉，当然就是死症。所以当我们看到一个病人阳气在上面，脸都红红的，下面还是在下利，这都是很危险的症状，代表五脏六俯已经不受食物或是药物。为什么说这种一定死症？ 因为此时所有的动能都往上走，病人 连肠胃的蠕动都没有了，这个时候病人喝东西下去立刻就下利出去， 你想这样子可不可怕？这不是快死掉了吗？心肺、脾胃通通衰竭下去，都已经没有功能了。\n","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '4、上气，面浮肿，肩息，其脉浮大，不治，又加利，尤甚。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0JndWt3F3ZZ', 4, '{"title":"5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈","description":"<p>5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009005,"note":"       如果病人出现『喘而燥』，就称为『肺胀』。中医所谓的肺胀临床看就是西医讲的肺气肿。肺气肿的原因很多，比如我们居住在工厂附 近，又刚好是棉花工厂，或刚好住在地毯工厂旁边，棉絮很多，或是住在空气污浊的地方，像是煤炭工厂旁边等，以前很多矿工得到肺气肿，都是因为空气里面不干净才得到。\n\n        还有老师们写黑板产生的粉笔灰，老师吸多了也会造成肺气肿。此处的肺胀就是现代的肺气肿，肺胀主要症状是持续着吸的状态，没有办法呼。\n\n       吸入后病人的肺可以张开。却不会缩小将空气挤压出来，于是就胀在那个地方，所以吸气就会变得很短。\n\n       张仲景出二方来治疗；第一是当病人肺胀到还可以平卧时，这是一个处方。如果已经不能平卧了，就用另外一个处方。实际上虽说只是短短的一篇，但是他却写的很详细，后面在介绍风水篇时会详加介绍给诸位听。","videoMemo":"","fangList":[],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '5、上气喘而躁者 ，此为肺胀 ，欲作风水 ，发汗则愈。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4suPAtjrVyc', 4, '{"title":"6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数","description":"<p>6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数。  所以然者，以上虚不能制下故也。此为肺中冷，必眩多涎唾，$f{甘草干姜汤}以温之 ；若服汤已渴者 ，属消渴。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009006,"note":"        肺痿现在诸位都有观念了，简言之就是肺虚。肺痈就是肺实，虚则补之，实则泻之。\n\n        如果是肺痿，『吐涎沫而不咳』，表示肺萎缩掉， 病人一直只吐涎沫而不咳嗽。\n\n     『其人不渴』，诸位看不渴就是寒，热的话就是渴。\n\n     『不渴，必遗尿』，因为肺是管津液，肺在上焦，当肺虚掉 时就不能治水，因为金生水，我们的肺实际上跟我们的膀胱是相通的。 所以有的时候咳嗽没好，一咳嗽，小便就跟着出来，这就是肺可以治水的表现，是治小便的水。\n\n     当肺虚掉后就不能再治水了，于是小便就会遗尿。有时我们看病时，病人抱怨说：「我小便失禁。」中医一看， 此君是下焦寒造成的，就是真武汤证，如果看到是上焦寒，真武汤就没有用了，因为不对症，病人明明是上寒，你给他壮下热，所以就没有用，吃真武汤只是让下焦阳更壮而已，跟天雄散一样，吃了很壮， 可是病人还是照样会遗尿，因为是肺寒引起的遗尿，这就是所谓的『以上虚。不能制下』，上焦肺气虚，所以不能制下，『此为肺中冷，必眩』， 肺中如果有寒时，第一个症状就是头昏。第二个症状，口吐很多涎沫， 这个涎沫都不是浓浊的，是白白的如泡沫状。可以让病人把舌头伸出 来看，舌苔的前半段是苍白的，肺家寒症就是这种舌苔。\n\n    『甘草干姜 汤以温之；若服汤已渴者，属消渴。』甘草干姜汤在这里又出现了， 炙甘草与干姜，是治疗上焦虚寒时用的。还有有一种情况也是属于肺家虚寒，有寄生虫在内，我们后面会介绍到大建中汤证，大建中汤也是肺家虚寒的一种，但是是有虫的症状。如果单纯只是肺的虚寒，甘草干姜汤就可以解决了。\n\n       张仲景不单是名医，而且心慈，大家想想看甘草、干姜这二味药， 你说要花多少钱买？这厉不厉害呢？西医看到 X 光照片说：「哎呀! 肺脏已经萎缩掉了，空间变小了。」然后你问该怎么办，答案是「没办法」。其实用甘草跟干姜就可以治好了，可是他们不会去用的。「这两味药怎么可能会治好？ 」如此病人就完了。\n\n        如果是肺痿，上虚吐涎沫、头晕眩的时候，就有小便遗尿。张仲景的上虚不能治水有两种情形。\n\n        一种是『厥』，就是如果遇到病人有昏迷的现象，这类肺病都很危险的，时常是一发病就走掉了。如果遇到厥盛，就是有昏迷的现象的时候，要加倍用干姜。如果是『痿』比较严重的时候，就是没有昏迷的现象，炙甘草要加倍的用。\n\n      『甘草干姜汤方为专治肺痿』而设，中医分寒热来决定如何选用药物。虚寒时我们就要用温药。厥，除了讲昏迷的现象以外，手脚冰冷很严重也是属于厥症，此时干姜就要加倍用，如果没有手脚冰冷，甘草加倍就好 了。","videoMemo":"","fangList":["甘草干姜汤"],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '6、肺痿 ，吐涎沬而不咳者 ，其人不渴 ，必遗尿 ，小便数。 所以然者，以上虚不能制下故也。此为肺中冷，必眩多涎唾，$f{甘草干姜汤}以温之 ；若服汤已渴者 ，属消渴。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YgFcS1oXIBv', 4, '{"title":"7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之","description":"<p>7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009007,"note":"       射干麻黄汤是小青龙的变方，跟小青龙很类似。小青龙汤专门治 疗气喘『寒喘』用，射干麻黄汤专门治疗『寒饮』用。\n\n       肺里面寒，如果是虚寒，就用甘草干姜汤。\n\n      如果是寒中带点『水饮』就是射干麻黄汤证。\n\n      什么叫做饮呢？饮就是已经有积水了，也就是我们所说的实症， 如果只是饮，就是还没有溢出来的水气，跟『溢饮』不同，只是『水饮』，表示病人肺里水气很多，就好像一个碗里面有很多水气但是眼睛看不到。\n\n      如果肺里面已经有积水，这时射干麻黄汤就没用了，因为用此药的时机已过。只是水饮的阶段，尚未成溢饮，这个时候我们肺的气泡旁边充满了很多水，不是肺膜里面有水，也不是肺里面有积水， 遇到这种情形就是射干麻黄汤证。\n\n       此时病人主要症状是呼吸时，可以听到喉咙里面有水的声音，咕噜咕噜样的水声，张仲景形容说喉中像水鸡声般，表示这类水饮尚未成为溢饮。\n\n       怎么知道有溢饮呢？有溢饮时眼袋都会肿起来，脸会有浮肿，这就是溢饮了，此时整个胸腔里面都是水，溢饮不单单是水在肺里，甚至胸膜肋膜里面都会有积水，一 般西医只能直接在肋膜上抽水，但是抽完后水又会再来，肺里面有积水光靠抽水是没有用的，只能应急，不能根治。\n\n       像肋膜有积水就是所谓的溢饮，溢饮时射干麻黄汤是没有用的。越重的病出现时，经方家用的药反而就越少，溢饮是十枣汤证，此药吃下去三个小时之内就可以将积水清除干净。这里说的是寒饮在肺里面产生的咳嗽，就是射干麻黄汤证。\n\n       大家看此方是将小青龙汤里的芍药与甘草取出，留下麻黄、 生姜、细辛、大枣、半夏、五味子，加入射干、紫苑、款冬花，款冬花这个药，本身就是专门止咳用的，尤其是水饮的咳嗽，大部分都会用到款冬花。\n\n       如果是有痰的咳嗽，我们会用杏仁，杏仁只能祛痰无法 去水，要把水去掉，必须使用款冬花。溢饮的状况之下，肺的气泡会呈现出持续扩张不收缩的状态，扩张就造成『咳而上气』，才会喘不 过气来，因为里面有积水，要把里面的水排掉，就要靠射干。射干能够排水，紫苑能够降逆、下气，就是能让肺泡收缩起来，五味子能够把里面的水气整个排下去，这几个药一直都是配在一起用的。\n\n     细辛是 去寒咳用的，因为病人里寒很盛。肺里面的寒会盛，原因很简单，是 因为肠胃的功能不好了，才会这样，这时候加入生姜、红枣是因为肺 里面有留饮的时候基本上都是来自胸膈，胸膈有湿气下去，就会造成 水气上下不交，于是水气就会慢慢累积起来，日久就变成留饮留在中焦一带，因此水气才会停留在肺里面。生姜能够把横膈这一带的水气 发散掉，所以生姜可以止呕散水。\n\n       如果是脾胃中寒，我们就要靠干姜。 生姜发散，能够将中膈水气去掉，让上下焦能够通利，药性跟干姜是不同的。大家仔细看，射甘麻黄汤中的生姜剂量，看用的有多重就了 解仲师的想法了。平常生姜二片就够了，而这里仲师特别加重生姜的量，其目的是除了止呕以外，还要打散中焦水气用的。\n\n        此处用麻黄是因为它能够让肺扩张，让表寒发表发掉，就是让很多病毒被发汗发掉。所以说张仲景是个预防医学家，一点都不为过。\n\n        留饮留在身体里面，如果不赶快把它去掉的话，造成肺里面的水气过多，于是病毒很容易滋生在里面，日久就会产生别的病变，反而更危险。\n\n        所以仲师用麻黄下去把将水气发表发出去，利用最近的路线将病毒发出去，所以这个方子对『咳而上气』，类似西医讲的『肋膜炎』 或胸腔里有很深的咳嗽，或带有水气的寒性气喘特别有用。\n\n      有浊痰的咳嗽与热性气喘就没有用了。如果射干麻黄汤服下去，病人发汗，小 便也排出来，结果还是没有好，还有但坐不得卧，就是当你还在熬药的时候，病人的病情已经变成十枣汤证。如果你认为药不对了，需要赶快转用十枣汤，其实诸位也不要心急，病情不会变化得如此之快。 就是因为预防病情再进一步，造成失治，所以会再加入半夏来去水。\n","videoMemo":"","fangList":["射干麻黄汤"],"bieMing":""}}', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '2025-03-12T09:33:42.000Z', '7、咳而上气 ，喉中水鸡声 ，$f{射干麻黄汤}主之。', '2025-03-12T09:33:42.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b6JHJ1z30Yb', 4, '{"title":"8","description":"<p>8、咳逆上气 ，时时吐浊 ，但坐不得眠 ，$f{皂荚丸}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009008,"note":"       『咳逆上气，时时唾浊，但坐不得眠』，病人这是已经到了但坐 不得眠的阶段了，『皂荚丸主之』。\n\n         刚刚讲的是水饮停留在肺里面，而皂夹丸证是浓痰、浊痰停积肺中造成的但坐不得卧。皂夹丸平常用到的不多，以现代来说，只有像遇到抽烟抽得很重的人才会用到皂夹丸。 \n\n        在民国初年时，抽鸦片的人用的最多。那种胶痰吐出来，硬硬的一块， 整块黄黄黏黏的，就是热痰、浊痰之类，此类的痰只有皂夹丸才能去掉。\n\n      不要开错方子，千万不是：「老师，咳出来有痰，我们用射干麻 黄汤。」结果原本是热痰，被你弄成胶痰，因为水被排掉痰却没去， 于是痰就变得干干硬硬的，所以辨症不能出错，本来是一个很简单的麻杏甘石汤，结果被你用射甘麻黄汤一发表，汗被发掉，结果变成皂夹丸证。\n\n        过去我们有个方子叫桂枝汤去芍药加皂夹，此方证常出现在当小孩子的运动量很大，流汗流得很多，而小孩子原本就有心脏病，所以有胸满的症状，当出现桂枝汤证时，病人咳嗽又有痰，此时痰已经是浓痰了，就是因为津液已经被他的好动先发散掉，现在因为有胸满， 所以我们不能加芍药，芍药会增加胸满，遇到心脏病人必须将芍药拿掉，要去浓痰，只好加一枚皂夹，一起熬在汤剂里面，一剂下去就可以全部清除掉，所以大家只要看到黄痰都可以使用皂夹。如果皂夹是加在桂枝汤里面，由于桂枝汤里本来就有大枣，此时大枣就要加重一点，因为大枣可以缓和皂荚的硷性，否则就会伤胃。\n\n         皂夹丸制作方式是，『八两刮去皮酥炙』。酥炙就是说先把它烤焦， 再把皂夹表面皮被烤黑的部分刮掉再入药。『枣膏和汤服三丸， 日三 夜一服』，一天吃四次，这个都是要饭后吃，睡觉前再吃。吃皂夹丸的时候，因为它是硷性的药，到胃里面会跟胃酸中和掉，这个时候需要熬得很浓的红枣汤，来配合吞服这皂荚丸，就不怕伤到胃。\n\n         为什么要饭后吃？所有要入胸膈的药、入上焦的药都让病人饭后吃，使药能停留在上焦，这样就可以清出很多的黄胶痰，从大便排出去。所以如果你到医院去看病人，才走到门口就听到病人的咳嗽声或是呼吸声是像有人在拉锯子一样。你问：「老师，他是水饮还是痰饮？ 」你只要将门打开来一看，病人床边还摆着一包烟，就知道是『痰饮』，如果病人从不抽烟，多是水饮。痰声跟水声是完全不一样的，痰声好像在拉锯子般，水饮声是「咕噜咕噜」的像鸡在叫，你可以听的很清楚， 很好区分的。\n\n","videoMemo":"","fangList":["皂荚丸"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '8、咳逆上气 ，时时吐浊 ，但坐不得眠 ，$f{皂荚丸}主之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ChjmAI4qAR', 4, '{"title":"9、咳而脉浮者，$f{厚朴麻黄汤}主之","description":"<p>9、咳而脉浮者，$f{厚朴麻黄汤}主之。咳而脉沉者，$f{泽漆汤}主 之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009009,"note":"       这里把两个处方放在一起，其实这两个都是治疗肺气肿的处方， 如果，『咳而脉浮者，厚朴麻黄汤主之。』『咳而脉沉者』浮指病在表， 沉指病在里，如果单纯是有痰饮在肺里，没有表症，我们就用泽漆汤。\n\n        如果同时有表症与里症，我们在祛痰的同时就要发表。所以厚朴麻黄汤中，有加厚朴、麻黄、石膏。把麻黄石膏杏仁放在一起就是麻杏甘石，不要放甘草，如果只为解除肺热，用麻杏甘石汤就可以了。此处因为有水在里面，而甘草会蓄水，所以我们只用半夏去利水。用干姜、细辛是因为里寒很盛，选用小麦这个毂类是因为肠胃的津液不足，我们就用小麦，这是有表症兼有里症就会用到此方。\n\n        这个时候为什么不用生姜、甘草、大枣，是因为他的病在肺在里面，我们加发表的药， 使用麻黄时就已经有杏仁在里面，这个时候你不需要再加甜腻的药在里面，因为甘的药会增加痰水，所以用一点小麦，把胃里面津液补足就好，淡淡的没有味道下去就可以了。\n\n       如果此时用甜味的药，很多药会跟着甜味跑，于是药就跑到脾胃里面，脾主甘，脾脏要是吃到甜的， 就会一直吸收，于是药力就会被分散掉。此处的五味子是敛咳用的。 所以厚朴麻黄汤，本身不但能够开胃和表，最主要是使用于当肺有病又兼有表症时用的。\n\n        泽漆汤是用在没有表症，只有里症时用的，此时是有肺水在里面造成的肺气肿。\n\n       用半夏是治水，里面有紫参，紫参可以用紫根取代， 有另外版本是用紫菀，是专门『开郁结』，紫根本身并不能够利水， 而是当肺有气郁在这里使用。\n\n       这里的气郁和水积不太一样，如果是水积到的话，呼吸会有水声。没有水声，只是胸口很闷，紫根能够让胸口郁气散开来。\n \n      生姜能够去饮，白前能够宣肺。\n\n      白前这个药，类似麻黄，但是没有麻黄这么强。\n\n      麻黄可以从肺一直开到皮表毛孔上去，而 白前是直接停在肺上面，将肺脏打开来，使肺的气不会那么闷。\n\n      甘草是安脾脏用，黄芩能去上热，能够泻热、泻肺热。\n\n     人参可以补气、补 肺的。\n\n      这个处方叫泽漆汤，当然是以它为主力，泽漆又叫做『大戟』。 \n\n     大家记得十枣汤里面，有三味药，甘遂、芫花、大戟。张仲景说脉沉， 就是到了悬饮阶段，这是十枣汤证，此时脉就变的很弦。弦就是水脉， 代表水已经从肺组织里溢出来了。我们的肺跟我们的胸孔膜是叠在一 起的，那里有很多间隙，就是我们中医说的『水巢』，这就是积水的地方。水会积到这里，就是因为肺泡有水堵到，这个时候就要靠大戟 了，泽漆汤也可以叫做大戟汤。\n\n       简言之肺里面有积水，如果是在气管上面诸位就可以看到射干麻黄汤证，主症是呼吸有水鸡声。如果是在肺泡里面，我们就用泽漆汤， 因为泽漆汤，能够清除这里的水饮，让肺气往下降，同时此方又可以和胃，把肠胃的功能补足，同时把肺水清掉，又能将肺气往下降。\n\n       这个泽漆汤证的主要症状是咳、脉沉，沉脉代表有水积在肺泡里面。连续几个处方都治咳，而且都有水积之症，所以大家要记得其深浅不一， 而要用不同的处方。\n\n       所以泽漆汤又比射干麻黄汤来的更强，来的更重。 泽漆汤的后面说，『三升以东流水五斗煮取一斗五升』，你千万不要去找东流水，你拿罗盘来测，从东方来的水叫东流水，不需要这么麻烦的。这是中国以前的阴阳五行的学说误导人的，反正都是水，无所谓 的。\n\n      这个泽漆汤服下去后，大部分的水会从嘴巴吐出来，还有小便利出来。十枣汤吃下去后，小便都来不及利了，水会从大肠一路泻出来， 水一去掉，胃口就大开了。和胃的药像生姜、甘草、人参、桂枝能够行阳，能够和胃的。\n\n     降逆的药像半夏能够利水，又能把肺气往下降。 其它的像白前开肺。有水以后就有炎，所以张仲景常常用黄芩，用黄芩就是因为肺里面有不正常的水溢出在外面，不在水道系统里面，这种环境都是最容易让病毒滋生在里面，所以他每次一剂药方开出后， 都会加一些消炎药在里面。黄芩这种是属于消炎药，中医讲的『去热药』，与西医讲的消炎药是同样意思，免得说把病治好了以后，结果肺里面还遗留些病毒在里面。\n\n       张仲景会知道这样做，都是靠临床经验出来的。所以做为一位好医师要会瞻前顾后，自己处方自己心里面要了解，治疗这病后又跑出其他的病来，就是处方不够周密完善，就是有一部分问题你没有考虑到所造成的。","videoMemo":"","fangList":["厚朴麻黄汤","泽漆汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '9、咳而脉浮者，$f{厚朴麻黄汤}主之。咳而脉沉者，$f{泽漆汤}主 之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T2wborV1seT', 4, '{"title":"10","description":"<p>10、火逆上气 ，咽喉不利 ，止逆下气者 ，$f{麦门冬汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009010,"note":"      诸位在麦门冬汤旁边写一个『肺痿，虚热用之』。肺痿是寒症， 诸位都知道要用甘草干姜汤。如果肺痿是虚热，就是麦门冬汤证。虚热，也会有肺痿，肺痿如果是因寒引起，可以看到病人口吐涎沫，嘴巴不渴，这就是寒症，我们要用甘草干姜汤。如果是虚热，代表肺的津液没了，二者的病因是相同的。\n\n       当肺里面的津液变的很干燥的时候 肺会收缩起来，同样的原因，但是一个是寒一个是热，都会造成肺火上逆的现象，这种状态之下，肺因为津液干燥，『火逆上气、咽喉不 利』，肺萎缩也会使横膈膜缩上来，横膈一被牵动就会影响到我们吞东西。\n\n        我们中医认为半夏、生姜能够止呕，就是半夏一下去，横隔就往下降，能够让你吞东西就不会恶心。\n\n     『咽喉不利』就是吞嚥食物都 有困难，喝水都喝不下去，此时『止逆』的同时；也需要把这个肺痿去掉，就是麦门冬汤证了。\n\n     此方内有人参、甘草、粳米、大枣就是要 补足肠胃的津液。张仲景认为，肺痿虚热的原因很简单，就是开始于肠胃的津液不足，病人可能是发汗发太多了，导致肠胃津液的不足， 所以第一个动作就是先把肠胃津液补足。\n\n        这里加入半夏，前面有讲过燥不能用半夏，现在这里燥要用半夏， 原因是避免病人还有浊痰在肺里面，靠半夏把肺里面与横膈膜清除干净以后，使得新生出来肠胃的津液才能去补肺，交给肺的同时加入麦门冬，麦门冬是中药里面非常好的润肺的药物，当肺的津液不够时， 我们要靠麦门冬来润肺。\n\n        肺萎缩掉后气会上逆，要让胸隔下降，就要靠半夏，把胸膈降下来。加了粳米下去是因为得了重病的人一定一段时间没有吃东西，所以光把肠胃的津液补足是不够的，还同时要给病 人一点营养。\n\n        张仲景真的很聪明，他加粳米下去，所以他连病因都考虑到了。吃了麦门冬汤就算病人有几天都没吃饭，也可以将营养补足。 如果你光是麦门冬汤没有加粳米，病人吃完后，肚子会很饿，而且已经好几天没有吃东西，病人是不懂得病后需要调养。\n\n      张仲景就是怕碰到病人才恢复，肠胃功能还没有完全很好的时候，就开始大吃特吃一 些很难消化的东西，结果就发生肠胃发炎、下利等等。当肠胃功能尚未恢复正常时，吃到不干净的东西，排又排不掉，于是会在肠胃里腐烂掉，自然会变成肠炎。仲师就是怕这样子，所以说干脆用粳米给病 人吃下去，吃完药也不很饿，逐渐的吃进一点清淡的食物，让体力慢慢的恢复。\n","videoMemo":"","fangList":["麦门冬汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '10、火逆上气 ，咽喉不利 ，止逆下气者 ，$f{麦门冬汤}主之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ne8nmlgWni6', 4, '{"title":"11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之","description":"<p>11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之。 </p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009011,"note":"       葶苈大枣泻肺汤是用在肺痈初期时，或是在肺痈进行到中期时都是葶苈大枣泻肺汤证。\n\n       如果已经成脓，此汤就来不及了。葶苈子是属于苦寒的药，涤痰效果很好，属于涤痰的峻药。肺痈一般来说就是肺里面化脓了，类似西医讲的肺脓疡。越重的病，经方用的药反而越简 单。\n\n        先把红枣汤熬好以后，再把葶苈子放在红枣汤里面，再熬一下， 就成药了，然后一次喝下去，葶苈子喝下去的时候病人会吐，因为葶苈子是属于催吐药。\n\n        临床上看的时候，病人喉咙很小，而葶苈子一下去病人一咳，就吐出痰一大块，很腥臭的痰。葶苈子可以将这些脓痰清除干净。病人吃了不想吐都不行一直到吐完为止。强壮的人，用五 钱，瘦子的话，用三钱就可以了。使用时机是已经快要成脓，但是还没有成脓的状态之下的时候用的。\n\n       如果出现『咳而胸满』，再加上咳嗽喘息，然后又有振寒、发冷的现象，表示里面已经化脓。\n\n      脓的范围已经把整个肺包住了，而肺是诸阳之会，因此阳气就没有办法达到皮肤表面上面，所以病人会怕冷，实际上怕冷是病邪挡到了，像麻黄汤证，寒束到表也会有恶寒现象，脓成后也会有怕冷的现象。\n\n       如果你误解以为这里的恶寒是麻黄汤证，于是开麻黄汤给病人，这下就不得了 了，会有更糟的现象出现。病人有的症状，如脉跳得很快，喉咙很干燥，如果是麻黄汤证的话病人不会有咽干，因为肺里面化脓了，很热， 才造成喉咙很干燥。\n\n       当喉咙干燥时表示病人津液不够，此时还用麻黄汤来让病人发表，让病家丧失津液，一定不合理。所以大家要看清楚， 麻黄汤证必有全身骨节痠痛，无咽干的症状，而脓胸没有这些症状， 就只是恶寒而已，千万不要跟麻黄汤证弄混，麻黄汤证完全是用发表 药，后面的桔梗汤是里药。\n\n        病人嘴巴不口渴的时候，又吐出很臭的脓痰，像脓血一样，并不是浊痰。\n\n       皂夹丸吐出来痰很黄很黏的，像胶一样。\n\n      这个脓痰是很浓稠的痰，如果此时不治好，再一段时间，就会吐得像米汁一样，就已经真正成脓了，这时就是西医说的肺癌了。\n\n      如果吐的很浊很臭的，还是要用葶蘑子来攻它，就是葶苈大枣泻肺汤证，如果已经全部成脓，吐出来的痰全部都会像米水一样，白白的颜色呈泡沫状，这就完全进入肺痈了，这个时候就是张仲景所说的桔梗甘草汤证，桔梗甘草汤由两味药组成，用桔梗与甘草二味药而已。\n\n       上次在介绍伤寒论的时候我就 跟大家讲过，经方中有两个排脓汤，第一个，就是这里的桔梗甘草汤， 是专门治疗肺痈用的。第二个排脓汤是当归赤小豆散主治中焦腹膜炎，就是胆结石造成胆管破裂，变成腹膜炎，还有盲肠炎治疗太慢转变成腹膜炎，这是下焦腹膜炎，讲到肠痈篇我再跟各位详细介绍当归赤小豆散的用法。\n","videoMemo":"","fangList":["葶苈大枣泻肺汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '11、肺痈 ，喘不得卧 ，$f{葶苈大枣泻肺汤}主之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B5UTsgl1SVL', 4, '{"title":"12","description":"<p>12、咳而胸满 ，振寒，脉数咽干 ，不渴 ，时出浊唾腥臭 ，久久吐脓如米粥者 ，为肺痈，，$f{桔梗汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009012,"note":"       使用桔梗甘草汤时，比例上桔梗要用一，甘草用二，病人已经化脓，仲师说过脓成则死，这是很危险的时候，绝对不可以用轻剂量一 钱二钱的用，必须用重剂到桔梗一两，甘草二两，加重剂量给病人吃， 排脓汤吃下去，就能够把脓清出来，此时煮法是放进六碗水煮成二碗， 分温再服，病人服后会吐脓血就对了。\n\n        因为肺的组织整个都烂掉了， 就会吐血出来。一般西医遇到肺有脓时就直接去抽脓，病人会很难过。 中医的排脓汤喝下去以后，脓也会被排出来，之后就转成麦门冬汤证了，当病人转成麦门冬汤证后，就表示快要好了。\n\n       多数时我看到大部分的都会转为麦门冬汤证，如果不是麦门冬汤，而是射干麻黄汤证， 就用射干麻黄汤，你需要临症决定，不过不太可能是射干麻黄汤证， 大部分都是麦门冬汤。\n\n       肺脓被排出去以后，同时因为肺的组织也腐烂 掉很多，使得肺整个萎缩上来，这就是标准的麦门冬汤证了。千万要记得，如果你的麦门冬汤里面没有加半夏，就不叫麦门冬汤，以前为了加不加半夏而吵翻，像经方家曹颖甫、唐容川等意见都不一样，他们在吵的就是半夏的使用时机。\n\n        反对者的重点是：「渴怎么可以用半 夏？ 」其实用半夏是取其有降逆之性，可以让胸脯、横膈膜稍微降下来，肺气才有机会重新扩张，这里不靠半夏是不行的。排脓汤从肺结核到脓胸等，我们都可以使用。我们北派经方家，遇到越重的病，我 们用的药就越少，药味少，剂量重，就是经方的特色。\n\n        如果是实寒，所谓的实寒也可以讲寒实。所谓实，就代表有东西挡到，脓胸的痛是热挡到造成的。\n\n       如果是寒堵到而结实，就是三物小白散证。诸位看这个处方名字很好听，叫做三物小白散，事实上最凶的就是它，此药是桔梗、贝母、跟巴豆三味药所组成。因为桔梗、贝 母、巴豆都是白色的，所以名白散。因为这个药很强，只需要吃一点点剂量就好了，所以用小来做名称，这就是三物小白散名字的起因了。\n\n         堵到上焦的寒实。就是三物小白散证。如果是堵在下焦的寒实，就是大黄附子细辛汤证。如果上焦是实热，就是我们的桔梗甘草汤证。\n\n        如果是痰堵在中焦造成的实，就是我们的大陷胸汤证，大家千万不要弄错。如果肺已经化脓，你还使用大陷胸汤就失治了，这时就要靠桔梗甘草汤。\n\n       经方大师曹颖甫，有一次治一个上海浦东陈姓病人，其症状 『胸中痛，咯痰腥臭如米粒』，咳出来一粒粒白色状的痰，其实就是肺结核。初诊时他一看：「糟糕，已经变成脓胸了。」就是已经变成肺脓疡了，这个时候，他用桔梗一两，甘草五钱。其实甘草用得太轻了， 甘草应该用到二两，甘草是解百毒的，又可以和中，但他用的太轻了。 五剂下去胸痛止，止了以后，二诊，他发现肺里面还有许多尚未被清除的像白米的痰，于是用葶苈大枣泻肺汤来去痰水，如果在一开始时就重用甘草，可能就不需要用到葶萨大枣泻肺汤，『五剂而如米粒之脓尽』。第三诊再用千金苇茎汤，因为病人咳出黄浊的痰，于是『五剂而腥臭尽』。\n\n        然而『岂知病根未拔，九月初十日复来』看到腥臭又跟以前一样，这时候再用桔梗甘草汤加冬瓜仁、昆布、海藻、大小蓟来消毒，用犀黄丸九钱，就是犀角地黄丸，犀角是南派用药，所以曹颖甫还是受到南方温病派的一些影响，这里寒凉的药就是犀角，其实还不如用石膏来得更好。\n\n        这里要讲就是这干金苇茎汤了，千金苇茎汤是出自千金要方一书，此书是唐朝名医孙思邈所写的，当他写完千金要方以后，他才看到：「咦？汉朝有个叫张仲景写了伤寒杂病论，写 的很好。」当他看完伤寒杂病论一书后，受到极深的刺激，于是赶快再补写一个千金翼方，就是希望他之前写的千金要方像长了羽翼。\n\n         孙思邈的干金苇茎汤方有四味药，苇茎、薏仁、桃仁、冬瓜仁这四味药。 苇茎就是芦苇的茎，薏仁去湿、桃仁去热活血，能够将痰攻下，冬瓜仁可以宣肺。\n\n        因为病家没有表症，我们用的药就比较缓，像白前、冬瓜仁等比较缓的药来发汗。如果病人没有表症且病人的肺里面都是脓，而你随便就用麻黄来发表的话，结果脓胸一定更严重，因为肺被麻黄打开了。 \n\n       西医遇到结核病时是没有办法的，病人恍惚、面黄肌瘦，整个人都瘦掉了。如果你要瘦很简单，你找个肺结核病人，等他一咳，再打 个喷嚏出来，你赶快去多吸几口，于是就得到肺结核，以后人就瘦掉、 就黄掉了，再也胖不起来了。\n\n      病人的脉是大脉，脉形中间是空的，也就是劳脉，这是结核病的脉诊，结核病西医是无治的。\n\n     我们辨症的方式很简单，看是虚热在里面？还是实热在里面？还是虚寒在里面。只此几个辨症，而就这几方子加减而已。吃对处方，药一下去很快就好转了，同时我们可以在这些方子里面做加减。西医叫结核病人有三黄： 小便黄、皮肤黄、还有眼睛黄。\n\n       黄是脾脏的原色，我们除了用入肺的 药以外，还要有健脾的药一起开在里面，黄就会退掉。病人胃口大开， 精神就恢复了，结核病是可以治疗的，只是你要治他，也要离他远一 点，不然他吐口痰在你家的烟灰缸里，过一段时间，菸灰缸里就有满满的一泡痰在那里。他只吐一小口痰，就变的很大块，因为里面有结 核菌在里面。","videoMemo":"","fangList":["桔梗汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '12、咳而胸满 ，振寒，脉数咽干 ，不渴 ，时出浊唾腥臭 ，久久吐脓如米粥者 ，为肺痈，，$f{桔梗汤}主之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ktLLKKrXauI', 4, '{"title":"13","description":"<p>13、咳而上气 ，此为肺胀 ，其人喘 ， 目如脱状 ，脉浮大者， $f{越婢加半夏汤}主之。肺胀，咳而上 气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009013,"note":"          肺胀就是肺气肿，前面说的是肺脓疡、肺痿。\n\n          肺胀，『其人喘』 喘得很厉害，『目如脱状，脉浮大者，越婢加半夏汤主之。』同样是『咳 而上气』，咳而上气就是肺胀的主要症状，病人的胸腔胀起来，持续的呈现只能在吸气的状态之下，这就是肺气胀。\n\n      肺胀气的时候如果病人是『烦躁而喘，脉浮者，心下有水，小青龙加石膏汤主之。』这里有两个方子在治疗肺气胀，就是肺氧肿。越婢汤里有麻黄、石膏，诸 位知道肺胀在里面的时候，热会很重，当热很盛的时候我们会用麻黄、 石膏，这两味大家最热了。\n\n        这里为什么张仲景要加半夏？越婢汤还特 别要加半夏，就是因为病人肺胀的原因是来自中焦脾胃，中焦脾胃受到痰阻，没有办法把津液完全交给肺，于是肺就胀起来，这个时候我们要将中焦横膈地方的痰去掉，所以要加入半夏。\n\n       读到金匮这里后我 们就看懂神农本草经里面一再写到半夏能够降逆，这个什么叫做 『逆』？ 就是有痰阻在横膈膜上，肺气无法下降，于是造成气逆。\n\n       平常我们呼吸的时候横膈膜下降，吐气的时候横隔膜上升，这是正常的， 结果病人无时无刻不管吸气吐气横膈膜都绷紧在上面下不来，此时只有半夏能够把横隔膜往下降，半夏的功能就在这里。\n\n        现在我们大家应该了解到神农本草经里在讲半夏能降逆的意思 了，越婢汤可以加半夏，小青龙汤呢？也有半夏，都用到半夏。主要原因就是『咳而上气，烦躁而喘，脉浮者，心下有水』，心下有水气 的话，病人咳嗽的时候喉咙一定会痒，这叫做水气，你一咳它就散一 下，所以喉咙里面会很痒。\n\n         如果『咳而上气』没有痒，眼睛瞪的很大， 变成圆圆的，黑珠子在中间，这叫做『目如脱状』好像眼珠子要掉出来了的感觉。黑珠在下白区在上面包着，如果这个人没有咳而上气、 没有气喘，这种眼睛叫『暴光』。暴光的人非常的凶，而且恶，这种人做过牢，一般从牢里出来的眼睛都是暴光的。如果他说。「我告诉 你我没有做过牢喔，我是好人喔。」他越告诉你他是好人，然后眼睛 就越暴光，人就越坏。\n\n       像释迦摩尼佛看你时的眼睛是瞇瞇眼，这是好的。眼睛瞪着这么 大干嘛，这是暴光。我们眼睛如果是这样子，叫下三白。这样子，叫上三白。法官在办案子时问犯人说：「你有没有杀人啊？ 」「我没有杀 人!」白珠子在上面或是在下面的，都是杀人犯的眼睛。杀过人以后眼睛都会充满血丝，一看就知他是兇手，眼露凶光。这种除外，如果他没有咳而上气，就是坏人，不是病，干万不要误以为说：「老师， 他是越婢加半夏汤证。」看相跟看病都分不出来，也就不用当医师了。 \n\n     『目如脱状』，『脉浮大』一定是寸脉浮大，为什么会浮？这代表病在肺里面太热了，我们用麻黄就是要开表解热，石膏清里热，石膏是最凉的药，能够清上焦的热。所以气喘咳嗽，不用麻黄的话病人是不会好的。大家看张仲景，多少方子都用到麻黄，后面的小青龙还是以麻黄为主，许多地方大部分都在用麻黄。\n\n        温病派的医生，就是现在外面的中医，麻黄都不敢开，因为担心麻黄太强了，所以药房里面麻黄都用不掉，只有我们经方家在用，但是我们是很少数的中医，所以用量 也很有限。\n\n       小青龙加石膏，小青龙汤里面有麻黄、姜、辛、五、草、 半，但是就没有石膏在内，因为小青龙汤证是表寒里寒，舌头伸出来， 舌苔是白厚的，表示里寒很盛，里寒是不会口渴的，小青龙汤证就无口渴，咳嗽时喉咙很痒。\n\n       大青龙汤证咳嗽也会痒，但是嘴巴很渴，舌苔很黄。而小青龙汤证除了有里寒还有表寒，就是病人有恶寒现象， 所以小青龙汤证的脉一定比较浮紧。除了小青龙汤证的表寒里寒以 外，如果病人同时有肺胀的状态，就是有表寒的状态之下持续有肺气胀、肺气肿的现象存在，我们就要用小青龙加石膏。\n\n        平常是不会得到肺气肿的，大都是外来的因素造成，比方说住在排废气的工厂旁边或 者做矿工的或是水泥工等，这类居住环境都容易引起肺气肿，还有我们抽烟也会容易肺气肿，这时可以在小青笼汤里面加点石膏就可以治疗肺气胀了。\n\n       小青龙汤加石膏，能够清上焦的热，石膏除了清热以外， 最主要是清除肺里面的浊。肺里面太脏了，当肺里面因为有淤积的浊 物，才产生的热的时候，我们一定要靠石膏，石膏就是白虎。还有的人有内伤，像是车祸撞伤，断掉的肋骨插到肺脏里面去以后，把肋骨接回去，结果还是有肺气肿。所以肺受到伤害也会有肺气肿，造成肺持续的扩张，这时都可以用到这个药方。\n\n        大家一定要会区分病人到底是越婢汤加半夏证还是小青龙汤加石膏证，后面要介绍的奔豚气病又会重新再介绍一遍。我们有大便引起的奔豚，有水在下面往上冲起来引起的奔豚，就不是伤寒论讲的这么简单了。\n\n        奔豚完了以后讲胸痹，治疗心脏病，胸痛，心脏病。 胸痹讲完的话心脏病你都会治疗了，就剩下一种绞心痛。\n\n        绞心痛西医已经不治了。遇到真正的心脏病时，西医根本无法治疗，可是我们还是可以治疗。绞心痛有一种就是真正的心脏病，就是瓣膜堵塞或先天生下来已经有缺陷，这种状况我们没办法将病人完全治好，但是可以治到不发心脏病的阶段，其他的通通可以治疗，在胸痹篇里面都会介绍给大家。\n","videoMemo":"","fangList":["越婢加半夏汤","小青龙加石膏汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '13、咳而上气 ，此为肺胀 ，其人喘 ， 目如脱状 ，脉浮大者， $f{越婢加半夏汤}主之。肺胀，咳而上 气，烦躁而喘，脉浮者，心下有水，$f{小青龙加石膏汤}主之。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jMB2HzIbT7n', 4, '{"title":"14、方剂补充《千金》$f{甘草汤} 方 治喉痛","description":"<p>14、方剂补充《千金》$f{甘草汤} 方  治喉痛</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009014,"note":"","videoMemo":"","fangList":["甘草汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '14、方剂补充《千金》$f{甘草汤} 方 治喉痛', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DYBn4082yxq', 4, '{"title":"15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫","description":"<p>15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫。</p>","content_format":"html","_microfeed":{"bookId":"Kcb7X2K5LTh","receiptNo":905009015,"note":"","videoMemo":"","fangList":["桂枝去芍药加皂荚汤"],"bieMing":""}}', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '2025-03-13T09:17:45.000Z', '15、《千金》$f{桂枝去芍药加皂荚汤}方 治肺痿吐涎沫。', '2025-03-13T09:17:45.000Z', 1, NULL, 'Kcb7X2K5LTh', 'section', 'vwKZ0zYFmM8');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tAJXX2q35te', 1, '{"title":"四逆加人参汤","description":"<p>$u{甘草}$w{二两 (炙)}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{干姜}$w{一两半}、$u{人参}$w{三两}。</p>\n<p></p>\n<p>       右四味，以水三升，煮取一升二合，去滓，分温再服。</p>\n<p></p>\n<p>四逆汤内加人参一两，余依四逆汤服法（上三味，呚咀，微火煮取一升二合，去滓，分温再服。强人可大附子一枚，干姜三两。）  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":1,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","附子","干姜","人参"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (生用去皮破八片)","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两半","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":null,"suffix":null,"showName":"人参","extraProcess":null}]}}', '2025-02-26T04:24:01.000Z', '2025-02-26T04:24:01.000Z', '2025-02-26T04:24:01.000Z', '$u{甘草}$w{二两 (炙)}、$u{附子}$w{一枚 (生用去皮破八片)}、$u{干姜}$w{一两半}、$u{人参}$w{三两}。 右四味，以水三升，煮取一升二合，去滓，分温再服。 四逆汤内加人参一两，余依四逆汤服法（上三味，呚咀，微火煮取一升二合，去滓，分温再服。强人可大附子一枚，干姜三两。）', '2025-02-26T04:24:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5WuoLlRQSXX', 1, '{"title":"理中丸","description":"<p>$u{人参}    $u{干姜}    $u{甘草}$w{炙}    $u{白术}$w{各三两}</p>\n<p></p>\n<p>    上四味，捣筛为末，蜜和为丸，如鸡子黄大，以沸汤数合，和一丸研碎，温服之。日三四服，夜一服，腹中未热，益至三四丸，然不及汤，汤法以四物依两数切，用水八升，煮取三升，去渣，温服一升，日三服，</p>\n<p></p>\n<p>     若脐上筑者，肾气动也，去术加桂四两。</p>\n<p></p>\n<p>     吐多者，去术 加生姜三两。</p>\n<p></p>\n<p>     下多者，还用术。</p>\n<p></p>\n<p>     悸者，加茯苓二两。</p>\n<p></p>\n<p>      渴欲得水者，加术，足前成四两半。</p>\n<p></p>\n<p>       腹中痛者，加人参，足前成四两半。</p>\n<p></p>\n<p>       寒者，加干姜，足前成四两半。</p>\n<p></p>\n<p>       腹满者，去术加附子一枚。</p>\n<p></p>\n<p>    服汤后如食顷，饮热粥一升许，微自温，勿揭衣被。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":2,"yaoCount":4,"drinkNum":3,"yaoList":["人参","干姜","甘草","白术"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":null,"weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":null,"weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"各三两","weight":null,"suffix":null,"showName":"白术","extraProcess":null}]}}', '2025-02-26T04:31:05.000Z', '2025-02-26T04:31:05.000Z', '2025-02-26T04:31:05.000Z', '$u{人参} $u{干姜} $u{甘草}$w{炙} $u{白术}$w{各三两} 上四味，捣筛为末，蜜和为丸，如鸡子黄大，以沸汤数合，和一丸研碎，温服之。日三四服，夜一服，腹中未热，益至三四丸，然不及汤，汤法以四物依两数切，用水八升，煮取三升，去渣，温服一升，日三服， 若脐上筑者，肾气动也，去术加桂四两。 吐多者，去术 加生姜三两。 下多者，还用术。 悸者，加茯苓二两。 渴欲得水者，加术，足前成四两半。 腹中痛者，加人参，足前成四两半。 寒者，加干姜，足前成四两半。 腹满者，去术加附子一枚。 服汤后如食顷，饮热粥一升许，微自温，勿揭衣被。', '2025-02-26T04:31:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A1b4Mc3aQsj', 1, '{"title":"通脉四逆加猪胆汁汤","description":"<p>$u{甘草}$w{二两、炙}    $u{干姜}$w{一两半}    $u{附子}$w{一枚、生用去皮破八片}  $u{猪胆汁}$w{半合}</p>\n<p></p>\n<p>    上四味，以水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来，无猪胆，以羊胆代之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":3,"yaoCount":4,"drinkNum":2,"yaoList":["甘草","干姜","附子","猪胆汁"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"二两、炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"一两半","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚、生用去皮破八片","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"KIP0kUQVkZG","amount":"半合","weight":null,"suffix":null,"showName":"猪胆汁","extraProcess":null}]}}', '2025-02-26T06:37:08.000Z', '2025-02-26T06:37:08.000Z', '2025-02-26T06:37:08.000Z', '$u{甘草}$w{二两、炙} $u{干姜}$w{一两半} $u{附子}$w{一枚、生用去皮破八片} $u{猪胆汁}$w{半合} 上四味，以水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来，无猪胆，以羊胆代之。', '2025-02-26T06:37:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XD6Pr2Vizek', 1, '{"title":"栝篓桂枝汤","description":"<p>$u{栝蒌根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p></p>\n<p>        上六味，以水九升，煮取三升，分温三服，取微汗。汗不出，食顷，啜热粥发之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":4,"yaoCount":6,"drinkNum":3,"yaoList":["栝蒌根","桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"pyZLleBsXOb","amount":"二两","weight":null,"suffix":null,"showName":"栝蒌根","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2025-03-01T01:43:36.000Z', '2025-03-01T01:43:36.000Z', '2025-03-01T01:43:36.000Z', '$u{栝蒌根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} 上六味，以水九升，煮取三升，分温三服，取微汗。汗不出，食顷，啜热粥发之。', '2025-03-01T01:43:36.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2vLI52GzwG2', 1, '{"title":"麻黄加术汤","description":"<p>$u{麻黄}$w{三两（去节） }，$u{桂枝}$w{二两 }，$u{甘草}$w{一两  }，$u{白术}$w{四两  }，$u{杏仁}$w{七十个（去皮尖）}</p>\n<p></p>\n<p>      右五味，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓，温服八合，覆取微汗</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":5,"yaoCount":5,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","白术","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两（去节）","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"七十个（去皮尖）","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null}]}}', '2025-03-01T03:34:59.000Z', '2025-03-01T03:34:59.000Z', '2025-03-01T03:34:59.000Z', '$u{麻黄}$w{三两（去节） }，$u{桂枝}$w{二两 }，$u{甘草}$w{一两 }，$u{白术}$w{四两 }，$u{杏仁}$w{七十个（去皮尖）} 右五味，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓，温服八合，覆取微汗', '2025-03-01T03:34:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MFnhRzG3Rma', 1, '{"title":"麻黄杏仁薏苡甘草汤","description":"<p>$u{麻黄}$w{半两}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖}</p>\n<p></p>\n<p>\t上锉麻豆大，每服四钱匕， 匕者茶匙也，四钱匕者四茶匙也。水一盏半，煮八分，去滓，温服，有微汗，避风。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":6,"yaoCount":4,"drinkNum":1,"yaoList":["麻黄","甘草","薏苡仁","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"半两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一两，炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"rOi0RaqbWeB","amount":"半两","weight":null,"suffix":null,"showName":"薏苡仁","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"十个，去皮尖","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null}]}}', '2025-03-01T03:46:05.000Z', '2025-03-01T03:46:05.000Z', '2025-03-01T03:46:05.000Z', '$u{麻黄}$w{半两}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖} 上锉麻豆大，每服四钱匕， 匕者茶匙也，四钱匕者四茶匙也。水一盏半，煮八分，去滓，温服，有微汗，避风。', '2025-03-01T03:46:05.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VJtbKaM2xoF', 1, '{"title":"防己黄耆汤","description":"<p>$u{ 防己}$w{一两 }，$u{ 甘草}$w{半两（炙）  }，$u{白术}$w{七钱半 }，$u{黄芪}$w{一两一分  }</p>\n<p></p>\n<p>       上锉麻豆大，每抄五钱匕，生姜四片，大枣一枚，水盏半，煎八分，去滓温服，</p>\n<p></p>\n<p>      喘者 加$u{麻黄}$w{半两}，</p>\n<p>     胃中不和者，加$u{芍药}$w{三分}，</p>\n<p>     气上冲者，加$u{桂枝}$w{三分}，</p>\n<p>    下有陈寒者，加$u{细辛}$w{三分}。 </p>\n<p></p>\n<p>    服后当如虫行皮中， 自腰下如冰，后坐被上，又以一被绕腰下，温令微汗差。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":7,"yaoCount":4,"drinkNum":1,"yaoList":["防己","甘草","白术","黄芪"],"fangList":[],"fangYaoList":[{"yaoId":"M9HezPeSGkC","amount":"一两","weight":null,"suffix":null,"showName":"防己","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"半两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"七钱半","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"一两一分","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null}]}}', '2025-03-01T03:55:43.000Z', '2025-03-01T03:55:43.000Z', '2025-03-01T03:55:43.000Z', '$u{ 防己}$w{一两 }，$u{ 甘草}$w{半两（炙） }，$u{白术}$w{七钱半 }，$u{黄芪}$w{一两一分 } 上锉麻豆大，每抄五钱匕，生姜四片，大枣一枚，水盏半，煎八分，去滓温服， 喘者 加$u{麻黄}$w{半两}， 胃中不和者，加$u{芍药}$w{三分}， 气上冲者，加$u{桂枝}$w{三分}， 下有陈寒者，加$u{细辛}$w{三分}。 服后当如虫行皮中， 自腰下如冰，后坐被上，又以一被绕腰下，温令微汗差。', '2025-03-01T03:55:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('moCdibLQiN2', 1, '{"title":"去桂枝加白术汤","description":"<p>$u{附子}$w{一枚、炮、去皮、破}    $u{白术}$w{二两}    $u{生姜}$w{一两半、切}    $u{大枣}$w{六枚、擘}    $u{甘草}$w{二两、炙}</p>\n<p></p>\n<p>上五味，以水三升，煮取一升，去滓，分温三服。一服觉身痺，半日许再服，三服都 尽，其人如冒状，勿怪即是术附并走皮中，逐水气，未得除故耳。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":8,"yaoCount":5,"drinkNum":3,"yaoList":["附子","白术","生姜","大枣","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"一枚、炮、去皮、破","weight":null,"suffix":null,"showName":"附子","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"一两半、切","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"六枚、擘","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两、炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2025-03-01T07:42:41.000Z', '2025-03-01T07:42:41.000Z', '2025-03-01T07:42:41.000Z', '$u{附子}$w{一枚、炮、去皮、破} $u{白术}$w{二两} $u{生姜}$w{一两半、切} $u{大枣}$w{六枚、擘} $u{甘草}$w{二两、炙} 上五味，以水三升，煮取一升，去滓，分温三服。一服觉身痺，半日许再服，三服都 尽，其人如冒状，勿怪即是术附并走皮中，逐水气，未得除故耳。', '2025-03-01T07:42:41.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nPSPhneNcRX', 1, '{"title":"瓜蒂汤","description":"<p>$u{瓜蒂}$w{二十个}</p>\n<p></p>\n<p>     右剉，以水一升，煮取五合，去滓，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":9,"yaoCount":1,"drinkNum":1,"yaoList":["瓜蒂"],"fangList":[],"fangYaoList":[{"yaoId":"zdySy9e78kG","amount":"二十个","weight":null,"suffix":"","showName":"瓜蒂","extraProcess":""}]}}', '2025-03-01T08:43:30.000Z', '2025-03-01T08:43:30.000Z', '2025-03-01T08:43:30.000Z', '$u{瓜蒂}$w{二十个} 右剉，以水一升，煮取五合，去滓，顿服。', '2025-03-01T08:43:30.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mSAhLRU6E5B', 1, '{"title":"百合地黄汤","description":"<p>       $u{百合}$w{七枚}、$u{地黄汁}$w{一升}。</p>\n<p></p>\n<p>       上先煎百合如前法，内地黄汁，煎取一升五合，分温再服。中病勿更服。大便当如漆。</p>\n<p></p>\n<p>        仲师用生地黄汁，大家看『先煎百合如前法，内地黄汁』地黄汁 再煮一下，不要煮太久。我们既然要生用，地黄汁用一两或二两都没 有关系，平常百合我们用一两二两也没有关系，我一般开这个处方时 剂量都是上两的。如果是『分温再服』，差不多两个是等量。</p>\n<p></p>\n<p>       如果『中病』就是喝到了、头昏了、嘴巴麻了，就停药。</p>\n<p></p>\n<p>     『大便当如漆』有时候排出颜色黑黑的大便来，这就是虚热，伏热在里面被排出来。这种病人，你给他下法、吐法、汗法都不对症，此时就用百合，百合最好 消化，跟生地黄在一起。生地黄取汁的时候是先泡过，我们把它泡在滚水里面，泡透了以后，再挤汁出来，生用。</p>\n<p></p>\n<p>       因为生地黄本身入肾， 肾阴不足的时候，要用生地黄。我们的六味地黄丸就是使用生地黄， 它入肾阴，滋肾阴，肾阴足的话肝就足了，水就会生木。水可以生木 后，就不会但卧，就是想卧下却又睡不着。当百合入肺后，就不会如见神灵状。因为百合下去后肺的津液就会被补的很充足，病人的魄就 会很快的安静下来。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":10,"yaoCount":2,"drinkNum":2,"yaoList":["百合","地黄汁"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":null,"amount":"一升","weight":null,"suffix":null,"showName":"地黄汁","extraProcess":null}]}}', '2025-03-03T05:39:08.000Z', '2025-03-03T05:39:08.000Z', '2025-03-03T05:39:08.000Z', '$u{百合}$w{七枚}、$u{地黄汁}$w{一升}。 上先煎百合如前法，内地黄汁，煎取一升五合，分温再服。中病勿更服。大便当如漆。 仲师用生地黄汁，大家看『先煎百合如前法，内地黄汁』地黄汁 再煮一下，不要煮太久。我们既然要生用，地黄汁用一两或二两都没 有关系，平常百合我们用一两二两也没有关系，我一般开这个处方时 剂量都是上两的。如果是『分温再服』，差不多两个是等量。 如果『中病』就是喝到了、头昏了、嘴巴麻了，就停药。 『大便当如漆』有时候排出颜色黑黑的大便来，这就是虚热，伏热在里面被排出来。这种病人，你给他下法、吐法、汗法都不对症，此时就用百合，百合最好 消化，跟生地黄在一起。生地黄取汁的时候是先泡过，我们把它泡在滚水里面，泡透了以后，再挤汁出来，生用。 因为生地黄本身入肾， 肾阴不足的时候，要用生地黄。我们的六味地黄丸就是使用生地黄， 它入肾阴，滋肾阴，肾阴足的话肝就足了，水就会生木。水可以生木 后，就不会但卧，就是想卧下却又睡不着。当百合入肺后，就不会如见神灵状。因为百合下去后肺的津液就会被补的很充足，病人的魄就 会很快的安静下来。', '2025-03-03T05:39:08.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZrTWfVnZBEQ', 1, '{"title":"百合知母汤","description":"<p>$u{百合}$w{七枚}、$u{知母}$w{三两}。</p>\n<p></p>\n<p>     上先以水洗百合，渍一宿当白沫出，去其水，别以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升；后合煎一升五合，分温再服。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":11,"yaoCount":2,"drinkNum":2,"yaoList":["百合","知母"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"七枚","weight":null,"suffix":"","showName":"知母","extraProcess":"擘"},{"yaoId":"4lJokf6uHXR","amount":"三两","weight":null,"suffix":"","showName":"百合","extraProcess":"切"}]}}', '2025-03-03T05:45:46.000Z', '2025-03-03T05:45:46.000Z', '2025-03-03T05:45:46.000Z', '$u{百合}$w{七枚}、$u{知母}$w{三两}。 上先以水洗百合，渍一宿当白沫出，去其水，别以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升；后合煎一升五合，分温再服。', '2025-03-03T05:45:46.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ean6r6B7x3N', 1, '{"title":"百合滑石代赭汤","description":"<p>$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。</p>\n<p></p>\n<p>上先煎百合如前法，别以泉水二升，滑石代赭取一升，去滓后合和重煎，取一升五合， 分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":12,"yaoCount":3,"drinkNum":2,"yaoList":["百合","滑石","代赭石"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"u6WaDjpcWhR","amount":"三两","weight":null,"suffix":null,"showName":"滑石","extraProcess":null},{"yaoId":"woIsPez0Ouc","amount":"如弹丸大 (碎棉裹)","weight":null,"suffix":null,"showName":"代赭石","extraProcess":null}]}}', '2025-03-05T09:16:06.000Z', '2025-03-05T09:16:06.000Z', '2025-03-05T09:16:06.000Z', '$u{百合}$w{七枚}、$u{滑石}$w{三两}、$u{代赭石}$w{如弹丸大 (碎棉裹)}。 上先煎百合如前法，别以泉水二升，滑石代赭取一升，去滓后合和重煎，取一升五合， 分温再服。', '2025-03-05T09:16:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q27pDOTndpF', 1, '{"title":"百合鸡子汤","description":"<p>$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚}</p>\n<p>\t$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":13,"yaoCount":2,"drinkNum":2,"yaoList":["百合","鸡子黄"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"七枚，擘","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"wDdw8s8LVWE","amount":"一枚","weight":null,"suffix":null,"showName":"鸡子黄","extraProcess":null}]}}', '2025-03-06T03:22:28.000Z', '2025-03-06T03:22:28.000Z', '2025-03-06T03:22:28.000Z', '$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚} $s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。', '2025-03-06T03:22:28.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wqc34V7aFZh', 1, '{"title":"百合洗方","description":"<p>$u{百合}$w{一升}。</p>\n<p></p>\n<p>         右一味，以水一斗，渍之一宿，以洗身，洗已，食煮饼，勿以$m{盐豉}也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":14,"yaoCount":1,"drinkNum":1,"yaoList":["百合"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"一升","weight":null,"suffix":null,"showName":"百合","extraProcess":null}]}}', '2025-03-06T03:27:20.000Z', '2025-03-06T03:27:20.000Z', '2025-03-06T03:27:20.000Z', '$u{百合}$w{一升}。 右一味，以水一斗，渍之一宿，以洗身，洗已，食煮饼，勿以$m{盐豉}也。', '2025-03-06T03:27:20.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('780qZgFfw36', 1, '{"title":"栝蒌牡蛎散","description":"<p>$u{括蒌根}、$u{牡蛎 (熬) }$w{各等分}。</p>\n<p></p>\n<p>            右二味，捣为散，白饮和服方寸匙，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":15,"yaoCount":2,"drinkNum":3,"yaoList":["括蒌根","牡蛎 (熬)"],"fangList":[],"fangYaoList":[{"yaoId":"pyZLleBsXOb","amount":null,"weight":null,"suffix":null,"showName":"括蒌根","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"各等分","weight":null,"suffix":null,"showName":"牡蛎 (熬)","extraProcess":null}]}}', '2025-03-06T03:28:49.000Z', '2025-03-06T03:28:49.000Z', '2025-03-06T03:28:49.000Z', '$u{括蒌根}、$u{牡蛎 (熬) }$w{各等分}。 右二味，捣为散，白饮和服方寸匙，日三服。', '2025-03-06T03:28:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CEm5iAHJ7YP', 1, '{"title":"百合滑石散","description":"<p>$u{百合$w{一两 (炙)}、$u{滑石$w{二两}。</p>\n<p></p>\n<p>        右二味，为散，饮服方寸匙，日三服，当微利，热除则止后服。</p>\n<p></p>\n<p>     百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":16,"yaoCount":2,"drinkNum":3,"yaoList":["百合","滑石"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"一两 (炙)","weight":null,"suffix":null,"showName":"百合","extraProcess":null},{"yaoId":"u6WaDjpcWhR","amount":"二两","weight":null,"suffix":null,"showName":"滑石","extraProcess":null}]}}', '2025-03-06T03:31:36.000Z', '2025-03-06T03:31:36.000Z', '2025-03-06T03:31:36.000Z', '$u{百合$w{一两 (炙)}、$u{滑石$w{二两}。 右二味，为散，饮服方寸匙，日三服，当微利，热除则止后服。 百合用炙过，就是用火烧过，或是在锅子里面干炒过。 比例是用百合一两，滑石就要用三两，将这两味药捣成散剂来服。『方 寸匕』就是一个汤匙而已，一天吃三次。如果吃了百合滑石散后有点 下利时就可以停药，因为表示药到了。', '2025-03-06T03:31:36.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CHerP5I9f0e', 1, '{"title":"苦参汤","description":"<p>$u{苦参}$w{一斤}。</p>\n<p></p>\n<p>          右一味，以水一斗，煮取七升，去滓，薰洗，日三次。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":17,"yaoCount":1,"drinkNum":3,"yaoList":["苦参"],"fangList":[],"fangYaoList":[{"yaoId":"udN4qy4NAcw","amount":"一斤","weight":null,"suffix":null,"showName":"苦参","extraProcess":null}]}}', '2025-03-06T03:44:34.000Z', '2025-03-06T03:44:34.000Z', '2025-03-06T03:44:34.000Z', '$u{苦参}$w{一斤}。 右一味，以水一斗，煮取七升，去滓，薰洗，日三次。', '2025-03-06T03:44:34.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Wo4JupqoRK', 1, '{"title":"赤小豆当归散","description":"<p>$u{赤小豆}$w{三升 (浸令毛出曝干)}、$u{当归}$w{十两}。</p>\n<p></p>\n<p>          右二味，杵为散，浆水服方寸匙，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":18,"yaoCount":2,"drinkNum":3,"yaoList":["赤小豆","当归"],"fangList":[],"fangYaoList":[{"yaoId":"xoqRCmUZylQ","amount":"三升 (浸令毛出曝干)","weight":null,"suffix":null,"showName":"赤小豆","extraProcess":null},{"yaoId":"JFnirDnffR9","amount":"十两","weight":null,"suffix":null,"showName":"当归","extraProcess":null}]}}', '2025-03-06T03:58:13.000Z', '2025-03-06T03:58:13.000Z', '2025-03-06T03:58:13.000Z', '$u{赤小豆}$w{三升 (浸令毛出曝干)}、$u{当归}$w{十两}。 右二味，杵为散，浆水服方寸匙，日三服。', '2025-03-06T03:58:13.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZrlWR0b1nfz', 1, '{"title":"升麻鳖甲汤","description":"<p>$u{升麻}$w{二两}、$u{蜀椒}$w{一两 (炒去汗)}、$u{雄黄}$w{半两 (研)}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。</p>\n<p></p>\n<p>       上六味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":19,"yaoCount":6,"drinkNum":2,"yaoList":["升麻","蜀椒","雄黄","当归","甘草","鳖甲"],"fangList":[],"fangYaoList":[{"yaoId":"dgPXrO7Zcb7","amount":"二两","weight":null,"suffix":null,"showName":"升麻","extraProcess":null},{"yaoId":"03dIYYkyQRn","amount":"一两 (炒去汗)","weight":null,"suffix":null,"showName":"蜀椒","extraProcess":null},{"yaoId":"Ul8euTuPbq0","amount":"半两 (研)","weight":null,"suffix":null,"showName":"雄黄","extraProcess":null},{"yaoId":"JFnirDnffR9","amount":"二两","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"14GklrlZE7t","amount":"手指大一片 (炙)","weight":null,"suffix":null,"showName":"鳖甲","extraProcess":null}]}}', '2025-03-06T05:58:12.000Z', '2025-03-06T05:58:12.000Z', '2025-03-06T05:58:12.000Z', '$u{升麻}$w{二两}、$u{蜀椒}$w{一两 (炒去汗)}、$u{雄黄}$w{半两 (研)}、$u{当归}$w{二两}、$u{甘草}$w{二两}、$u{鳖甲}$w{手指大一片 (炙)}。 上六味，以水四升，煮取一升，顿服之，老小再服，取汗。肘后千金方阳毒用升麻汤， 无鳖甲有桂；阴毒用甘草汤，无雄黄。', '2025-03-06T05:58:12.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
