INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o690tI9Vw71', 1, '{"title":"鳖甲煎丸","description":"<p>$u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧、即 射干}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{桂枝}$w{三分}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{紫葳}$w{三分 即凌霄 }，$u{半夏}$w{三分}，$u{阿胶}$w{三分，炙}，$u{葶苈}$w{一分，熬}，$u{人参}$w{一分}，$u{瞿麦}$w{二分}，$u{䗪虫}$w{五分，熬}，$u{牡丹}$w{五分，去心}，$u{芍药}$w{五分}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分，去皮尖， 研}</p>\n<p>\t$s{上二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":21,"yaoCount":23,"drinkNum":50,"yaoList":["鳖甲","乌扇","黄芩","柴胡","鼠妇","干姜","大黄","桂枝","石苇","厚朴","紫葳","半夏","阿胶","葶苈","人参","瞿麦","䗪虫","牡丹","芍药","蜂窠","赤硝","蜣螂","桃仁"],"fangList":[],"fangYaoList":[{"yaoId":"14GklrlZE7t","amount":"十二分，炙","weight":null,"suffix":null,"showName":"鳖甲","extraProcess":null},{"yaoId":null,"amount":"三分，烧、即 射干","weight":null,"suffix":null,"showName":"乌扇","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"三分","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"JMfcgoRTH0J","amount":"六分","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"xg7IDhYbYBc","amount":"三分，熬","weight":null,"suffix":null,"showName":"鼠妇","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三分","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"To31b37bc6Z","amount":"三分","weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"BFmkWqxUMUs","amount":"三分，去毛","weight":null,"suffix":null,"showName":"石苇","extraProcess":null},{"yaoId":"8714SID7nWu","amount":"三分"