.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s44z4pC56iQ', 1, '{"title":"白虎加桂枝汤","description":"<p>$u{知母$w{六两}、$u{石膏$w{一斤}、$u{甘草$w{二两(炙)}、$u{粳米$w{二合}、$u{桂枝$w{三两}</p>\n<p></p>\n<p>         上五味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":22,"yaoCount":5,"drinkNum":3,"yaoList":["知母","石膏","甘草","粳米","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"六两","weight":null,"suffix":null,"showName":"知母","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两(炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"2gRWUBY7CiY","amount":"二合","weight":null,"suffix":null,"showName":"粳米","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null}]}}', '2025-03-06T09:23:25.000Z', '2025-03-06T09:23:25.000Z', '2025-03-06T09:23:25.000Z', '$u{知母$w{六两}、$u{石膏$w{一斤}、$u{甘草$w{二两(炙)}、$u{粳米$w{二合}、$u{桂枝$w{三两} 上五味，以水一斗，煮米熟，汤成去滓，温服一升，日三服。', '2025-03-06T09:23:25.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z1fz3UAZgxY', 1, '{"title":"蜀漆散","description":"<p>$u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}</p>\n<p></p>\n<p>\t$s{上三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":23,"yaoCount":3,"drinkNum":1,"yaoList":["蜀漆","云母","龙骨"],"fangList":[],"fangYaoList":[{"yaoId":"gFgG38KNuFm","amount":"烧去腥","weight":null,"suffix":null,"showName":"蜀漆","extraProcess":null},{"yaoId":"MN2tqTw73w6","amount":"烧二日夜","weight":null,"suffix":null,"showName":"云母","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"等分","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null}]}}', '2025-03-06T09:27:06.000Z', '2025-03-06T09:27:06.000Z', '2025-03-06T09:27:06.000Z', '$u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分} $s{上三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', '2025-03-06T09:27:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BbqMgpk5aBx', 1, '{"title":"牡蛎汤","description":"<p>$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}</p>\n<p></p>\n<p>上四味，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":24,"yaoCount":4,"drinkNum":2,"yaoList":["牡蛎","麻黄","甘草","蜀漆"],"fangList":[],"fangYaoList":[{"yaoId":"MDfiJ4S7u0U","amount":"四两，熬","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"四两，去节","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"gFgG38KNuFm","amount":"三两","weight":null,"suffix":null,"showName":"蜀漆","extraProcess":null}]}}', '2025-03-07T01:57:09.000Z', '2025-03-07T01:57:09.000Z', '2025-03-07T01:57:09.000Z', '$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两} 上四味，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', '2025-03-07T01:57:09.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O33oU2E3WyE', 1, '{"title":"柴胡去半夏加栝蒌汤","description":"<p>$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝蒌根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚}</p>\n<p></p>\n<p>\t上七味，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":25,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","人参","黄芩","甘草","栝蒌根","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"八两","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":null,"weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":null,"weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"各三两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":null,"suffix":null,"showName":"栝蒌根","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"二两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2025-03-07T01:58:39.000Z', '2025-03-07T01:58:39.000Z', '2025-03-07T01:58:39.000Z', '$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝蒌根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚} 上七味，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。', '2025-03-07T01:58:39.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0kdRtQCyqid', 1, '{"title":"柴胡桂姜汤","description":"<p>$u{柴胡}$w{半斤}、$u{桂枝}$w{三两、去皮}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{甘草}$w{三两(炙)}、$u{牡蛎}$w{三两(熬)}。</p>\n<p></p>\n<p>           上七味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服，初服微烦，再服，汗出便愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":26,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","桂枝","干姜","括蒌根","黄芩","甘草","牡蛎"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":null,"suffix":null,"showName":"柴胡","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两、去皮","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":null,"suffix":null,"showName":"括蒌根","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两(炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"三两(熬)","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null}]}}', '2025-03-07T02:01:28.000Z', '2025-03-07T02:01:28.000Z', '2025-03-07T02:01:28.000Z', '$u{柴胡}$w{半斤}、$u{桂枝}$w{三两、去皮}、$u{干姜}$w{二两}、$u{括蒌根}$w{四两}、$u{黄芩}$w{三两}、$u{甘草}$w{三两(炙)}、$u{牡蛎}$w{三两(熬)}。 上七味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服，初服微烦，再服，汗出便愈。', '2025-03-07T02:01:28.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('URs6PxZ9YMJ', 1, '{"title":"防己地黄汤","description":"<p>$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。</p>\n<p>\t$s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。</p>\n<p></p>\n<p>      防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。</p>\n<p></p>\n<p>        遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":27,"yaoCount":6,"drinkNum":2,"yaoList":["防己","桂枝","防风","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"M9HezPeSGkC","amount":"一分","weight":null,"suffix":null,"showName":"防己","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"blvt71sB8Zu","amount":"三分","weight":null,"suffix":null,"showName":"防风","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"一分","weight":null,"suffix":null,"showName":"甘草","extraProcess":null}]}}', '2025-03-07T07:15:17.000Z', '2025-03-07T07:15:17.000Z', '2025-03-07T07:15:17.000Z', '$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。 $s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。 防己、甘草、桂枝、防风这些药的比例，防己、甘 草是一，桂枝是三。你不要开一分、三分，这种轻剂量治疗牙齿中风可以用，治疗中风的人需要大剂的药，使用三钱五钱一剂都不为过， 比例要知道。同时像防己本身能够去湿，中气不足的时候用甘草。桂枝和甘草补中，都能够补中阳不足，让脾脏开始运化。防己和防风， 都能够去风。这处方是遇到病人的风邪直接进在皮表，停在经上面的 时候使用的，是最浅的处方。这四味药先用酒泡过，泡完以后再绞它的汁用，汁里面就有药跟酒在里面。生地黄，也要大剂的用，剂量用两，差不多用到二两到三两才够量。 遇到体格比较大的病人，使用四两以上都没关系。地黄生的时候是黏答答的、黑黑的，你把它放在锅里蒸熟，好像蒸米一样，隔水蒸， 不要浸水。蒸熟了以后把它拿起来绞汁。把生地黄绞成生地黄汁，然后跟刚刚前面已经绞成汁的四味药，混合在一起，喝下这个汁，才是 真正的防己地黄汤。地黄汁必须是绞汁的，把它蒸熟的，不是煮熟的， 利用地黄来补病家的血不足。靠桂枝甘草来健中，来加强病人的肠胃功能，然后开一点防己防风去风。', '2025-03-07T07:15:17.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kau3JorzPWs', 1, '{"title":"侯氏黑散","description":"<p>$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。</p>\n<p></p>\n<p>\t$s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":28,"yaoCount":15,"drinkNum":60,"yaoList":["菊花","白术","细辛","茯苓","牡蛎","桔梗","防风","人参","矾石","黄芩","当归","干姜","芎䓖","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"8ZuiC9ADA2V","amount":"四十分","weight":null,"suffix":null,"showName":"菊花","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"十分","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"三分","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三分","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"三分","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"t7DkIvGNO8b","amount":"八分","weight":null,"suffix":null,"showName":"桔梗","extraProcess":null},{"yaoId":"blvt71sB8Zu","amount":"十分","weight":null,"suffix":null,"showName":"防风","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"三分","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"ozDrmO1Ighz","amount":"三分","weight":null,"suffix":null,"showName":"矾石","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":"五分","weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"JFnirDnffR9","amount":"三分","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"三分","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"Sfmcy2PNzjm","amount":"三分","weight":null,"suffix":null,"showName":"芎䓖","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null}]}}', '2025-03-07T07:26:56.000Z', '2025-03-07T07:26:56.000Z', '2025-03-07T07:26:56.000Z', '$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。 $s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。', '2025-03-07T07:26:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B68R4bpTMUR', 1, '{"title":"风引汤","description":"<p>$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。</p>\n<p>\t$s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治大人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":29,"yaoCount":12,"drinkNum":60,"yaoList":["大黄","干姜","龙骨","桂枝","甘草","牡蛎","寒水石","滑石","赤石脂","白石脂","紫石英","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":null,"weight":null,"suffix":null,"showName":"大黄","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":null,"weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"各四两","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":null,"weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"各二两","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":null,"weight":null,"suffix":null,"showName":"寒水石","extraProcess":null},{"yaoId":"u6WaDjpcWhR","amount":null,"weight":null,"suffix":null,"showName":"滑石","extraProcess":null},{"yaoId":"1rOkrjGOCab","amount":null,"weight":null,"suffix":null,"showName":"赤石脂","extraProcess":null},{"yaoId":"cSR0rsnZv7C","amount":null,"weight":null,"suffix":null,"showName":"白石脂","extraProcess":null},{"yaoId":"KeCSoielG2F","amount":null,"weight":null,"suffix":null,"showName":"紫石英","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"各六两","weight":null,"suffix":null,"showName":"石膏","extraProcess":null}]}}', '2025-03-07T07:29:06.000Z', '2025-03-07T07:29:06.000Z', '2025-03-07T07:29:06.000Z', '$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。 $s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治大人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}', '2025-03-07T07:29:06.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DTtg56aEVCH', 1, '{"title":"头风摩散方","description":"<p>$u{大附子}$w{一枚，炮}，$u{盐}$w{等分}</p>\n<p>\t$s{上二味}，为散，沐了，以方寸匕，摩疾上，令药力行。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":30,"yaoCount":2,"drinkNum":10,"yaoList":["大附子","盐"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"一枚，炮","weight":null,"suffix":null,"showName":"大附子","extraProcess":null},{"yaoId":"DThHnTLC5ju","amount":"等分","weight":null,"suffix":null,"showName":"盐","extraProcess":null}]}}', '2025-03-07T07:33:35.000Z', '2025-03-07T07:33:35.000Z', '2025-03-07T07:33:35.000Z', '$u{大附子}$w{一枚，炮}，$u{盐}$w{等分} $s{上二味}，为散，沐了，以方寸匕，摩疾上，令药力行。', '2025-03-07T07:33:35.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1JNgO1ebeoY', 1, '{"title":"桂枝芍药知母汤","description":"<p>$u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{四两,炮}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮}</p>\n<p>\t$s{右九味}，以水七升，煮取二升，温服七合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":31,"yaoCount":9,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","麻黄","生姜","白术","知母","防风","附子"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"四两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"二两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"四两,炮","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"PeV28d5T6et","amount":"四两","weight":null,"suffix":null,"showName":"知母","extraProcess":null},{"yaoId":"blvt71sB8Zu","amount":"四两","weight":null,"suffix":null,"showName":"防风","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"二枚，炮","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2025-03-08T01:24:59.000Z', '2025-03-08T01:24:59.000Z', '2025-03-08T01:24:59.000Z', '$u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{四两,炮}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮} $s{右九味}，以水七升，煮取二升，温服七合，日三服。', '2025-03-08T01:24:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qWZa6sMHbIm', 1, '{"title":"乌头汤","description":"<p>$m{5味} 治脚气疼痛，不可屈伸。</p>\n<p>\t$u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头}</p>\n<p></p>\n<p>\t$s{上五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":32,"yaoCount":2,"drinkNum":3,"yaoList":["麻黄","芍药","黄芪","甘草","川乌","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":null,"weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":null,"weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"各三两","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"三两，炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":null,"amount":"五枚，㕮咀，以","weight":null,"suffix":null,"showName":"川乌","extraProcess":null},{"yaoId":"IHSagd4ikNY","amount":null,"weight":null,"suffix":null,"showName":"蜜","extraProcess":null}]}}', '2025-03-08T01:40:00.000Z', '2025-03-08T01:40:00.000Z', '2025-03-08T01:40:00.000Z', '$m{5味} 治脚气疼痛，不可屈伸。 $u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头} $s{上五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。', '2025-03-08T01:40:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HfWkZgLriRe', 1, '{"title":"矾石汤","description":"<p>$u{矾石}$w{二两}</p>\n<p>\t$s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":33,"yaoCount":1,"drinkNum":1,"yaoList":["矾石"],"fangList":[],"fangYaoList":[{"yaoId":"ozDrmO1Ighz","amount":"二两","weight":null,"suffix":null,"showName":"矾石","extraProcess":null}]}}', '2025-03-08T01:50:03.000Z', '2025-03-08T01:50:03.000Z', '2025-03-08T01:50:03.000Z', '$u{矾石}$w{二两} $s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。', '2025-03-08T01:50:03.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('us24aBgJCro', 1, '{"title":"黄耆桂枝五物汤","description":"<p>$u{黄耆}$w{三两}、$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{六两}、$u{大枣}$w{十二枚}。</p>\n<p></p>\n<p>       上五味，以水六升，煮取二升，温服七合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":34,"yaoCount":5,"drinkNum":3,"yaoList":["黄耆","桂枝","芍药","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"i7j1zMcc48a","amount":"三两","weight":null,"suffix":null,"showName":"黄耆","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"六两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2025-03-08T09:15:19.000Z', '2025-03-08T09:15:19.000Z', '2025-03-08T09:15:19.000Z', '$u{黄耆}$w{三两}、$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{生姜}$w{六两}、$u{大枣}$w{十二枚}。 上五味，以水六升，煮取二升，温服七合，日三服。', '2025-03-08T09:15:19.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8u7j2bGEaRw', 1, '{"title":"桂枝龙骨牡蛎汤","description":"<p>$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}、$u{龙骨}$w{三两}、$u{牡蛎}$w{三两}。</p>\n<p></p>\n<p>        右七味，以水七升，煮取三升，去滓，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":35,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","龙骨","牡蛎"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两（炙）","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"三两","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null},{"yaoId":"MDfiJ4S7u0U","amount":"三两","weight":null,"suffix":null,"showName":"牡蛎","extraProcess":null}]}}', '2025-03-10T08:48:57.000Z', '2025-03-10T08:48:57.000Z', '2025-03-10T08:48:57.000Z', '$u{桂枝}$w{三两}、$u{芍药}$w{三两}、$u{甘草}$w{二两（炙）}、$u{生姜}$w{三两}、$u{大枣}$w{十二枚}、$u{龙骨}$w{三两}、$u{牡蛎}$w{三两}。 右七味，以水七升，煮取三升，去滓，分温三服。', '2025-03-10T08:48:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F08aGgxE9I0', 1, '{"title":"天雄散","description":"<p>$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。</p>\n<p></p>\n<p>        右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。</p>\n<p></p>\n<p>     天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。</p>\n<p></p>\n<p>      天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到 这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。</p>\n<p></p>\n<p>      天雄散就是用散剂，『天雄三两炮』如果散剂的话我 们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上 有一点失去方义，其实是可以用牡蛎的。</p>\n<p></p>\n<p>      将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。</p>\n<p></p>\n<p>       这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没 有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些 鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这 种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠 一些药把它带到它该去的地方。</p>\n<p></p>\n<p>       你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这 几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。</p>\n<p></p>\n<p>        如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。</p>\n<p></p>\n<p>        阳虚和阴虚治法 不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为 上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":36,"yaoCount":4,"drinkNum":3,"yaoList":["天雄","白术","桂枝","龙骨"],"fangList":[],"fangYaoList":[{"yaoId":"E5qbjuyOeWF","amount":"三两（炮）","weight":null,"suffix":null,"showName":"天雄","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"八两","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"vL3tFGA7NwL","amount":"三两","weight":null,"suffix":null,"showName":"龙骨","extraProcess":null}]}}', '2025-03-11T03:57:10.000Z', '2025-03-11T03:57:10.000Z', '2025-03-11T03:57:10.000Z', '$u{天雄}$w{三两（炮）}、$u{白术}$w{八两}、$u{桂枝}$w{六两}、$u{龙骨}$w{三两}。 右四味，杵为散，酒服半钱匙，日三服，不知稍增，以知为度。 天雄散是治疗阳虚的，不是治阴虚。阳虚就是代表身体里面阴寒很盛，这时是看不到热症的，如果是阴虚的话，就可以看到热症，但是看到的是虚热。如果病人是失精家，再遇到这种表里都寒的时候， 就是要用天雄散的时机。 天雄的意思就是吃下去天天都雄壮威武，故名叫天雄，天雄药力比附子强很多，附子是三年收成，而它是五年才 收成。你到药房去买天雄，药房会告诉你天雄就是附子，一定会得到 这个答案的。按照神农本草经，三年、四年、五年都不一样，第五年 采收才是天雄。 天雄散就是用散剂，『天雄三两炮』如果散剂的话我 们可以用这个比例，三两就三两没有关系，白术八两、桂枝六两、龙骨三两。经方里面写的是龙骨，但实际用的是牡蛎，牡蛎可能比龙骨还更恰当一点。如果你将龙骨牡蛎都放进去用，也没有关系，原文上 有一点失去方义，其实是可以用牡蛎的。 将这四味药杵为散，用酒服， 半个汤匙，『半钱匕』就是我们平常喝汤的汤匙平匙量。一天吃三次， 饭前空腹吃。吃完了以后，如果没感觉到改变，就是还有亡血失精， 这个时候就要增加剂量。 这个药在经方里面，是属于很强的补阳药， 主治症状还包含阳不举，如果服了天雄散后仍然不举，表示天雄散没 有用了，此时我们就需要用到像阳起石，肉蓰蓉等，还可以再加一些 鹿茸，这几味都是我们中药里面一般的壮阳的药。但是如果你光吃这 种药，结果就是全身汗毛都举起来了，就是那个地方不举，所以要靠 一些药把它带到它该去的地方。 你如果将这壮阳复方放在天雄散里面一起吃，效果就非常的好，还可以放到桂枝龙骨牡蛎汤里面也可以。 这类药千万不要单味的用，要用复方，它才会进入到我们肾脏去。这 几个药都是等量的比例在用的，也可以把鹿茸拿去泡酒，然后一边喝鹿茸酒，一边服天雄散也可以，这些都是中药里面比较强的壮阳药， 一般是阳虚时才会用到。 如果阳没有虚而是阴虚，吃这类壮阳药，就会越吃越热，反而没有用。阴虚的话，病人一定会看到阳亢的症状， 所谓阳亢就是上焦热下面是寒的，也是属于失精家。 阳虚和阴虚治法 不一样，阳虚是看不到阳症，只看到阴症，比如你问病人说会不会口 渴？病人回答说不渴时，就是阳虚了。如果是阴虚，就会很渴，因为 上面的阳热是虚热，所以只要问病人口渴不渴大概就晓得了。', '2025-03-11T03:57:10.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I4NP0MAuiW6', 1, '{"title":"黄耆建中汤","description":"<p>$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。</p>\n<p></p>\n<p>      右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。</p>\n<p></p>\n<p>     气短，胸满者，加生姜一两；</p>\n<p>     腹满者，去大枣，加茯苓一两半；</p>\n<p>     大便秘结者，去大枣，加枳实一两半；</p>\n<p>    疗肺虚 损不足 ，补气加半夏三两。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":37,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","胶饴","黄芪"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两 (炙)","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"三两（切）","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚（劈）","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":null,"suffix":null,"showName":"胶饴","extraProcess":null},{"yaoId":"i7j1zMcc48a","amount":"一两半","weight":null,"suffix":null,"showName":"黄芪","extraProcess":null}]}}', '2025-03-12T02:10:07.000Z', '2025-03-12T02:10:07.000Z', '2025-03-12T02:10:07.000Z', '$u{桂枝}$w{三两}、$u{芍药}$w{六两}、$u{甘草}$w{二两 (炙)}、$u{生姜}$w{三两（切）}、$u{大枣}$w{十二枚（劈）}、$u{胶饴}$w{一升}}、$u{黄芪}$w{一两半}。 右七味，以水七升，煮取三升，去滓，内胶饴，更上微火消解，温服一升，日三服。 气短，胸满者，加生姜一两； 腹满者，去大枣，加茯苓一两半； 大便秘结者，去大枣，加枳实一两半； 疗肺虚 损不足 ，补气加半夏三两。', '2025-03-12T02:10:07.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ssLOH5lvlV', 1, '{"title":"八味肾气丸","description":"<p>$u{干地黄}$w{八两}、$u{山药}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。</p>\n<p></p>\n<p>          上八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":38,"yaoCount":8,"drinkNum":15,"yaoList":["干地黄","山药","山茱萸","泽泻","牡丹皮","茯苓","桂枝","附子"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"八两","weight":null,"suffix":null,"showName":"干地黄","extraProcess":null},{"yaoId":null,"amount":"四两","weight":null,"suffix":null,"showName":"山药","extraProcess":null},{"yaoId":"ASxxg5RfLMb","amount":"四两","weight":null,"suffix":null,"showName":"山茱萸","extraProcess":null},{"yaoId":"TvTXZli2dE7","amount":"三两","weight":null,"suffix":null,"showName":"泽泻","extraProcess":null},{"yaoId":"nP2w4ZP4Yic","amount":"三两","weight":null,"suffix":null,"showName":"牡丹皮","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"jT011T7yIVO","amount":"一枚 (炮)","weight":null,"suffix":null,"showName":"附子","extraProcess":null}]}}', '2025-03-12T03:09:49.000Z', '2025-03-12T03:09:49.000Z', '2025-03-12T03:09:49.000Z', '$u{干地黄}$w{八两}、$u{山药}$w{四两}、$u{山茱萸}$w{四两}、$u{泽泻}$w{三两}、$u{牡丹皮}$w{三两}、$u{茯苓}$w{三两}、$u{桂枝}$w{一两}、$u{附子}$w{一枚 (炮)}。 上八味，末之，炼蜜和丸，如梧子大，$n{酒}下十五丸，渐加至二十五丸，日再服，白饮下亦可。', '2025-03-12T03:09:49.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BjQ4oEHsXAm', 1, '{"title":"薯蓣丸","description":"<p>$u{薯蓣}$w{三十分}，$u{人参}$w{七分}，$u{白术}$w{六分}，$u{茯苓}$w{五分}，$u{甘草}$w{二十八分}，$u{当归}$w{十分}，$u{干地黄}$w{十分}，$u{芍药}$w{六分}，</p>\n<p>$u{芎藭}$w{六分}，$u{麦门冬}$w{六分}，$u{阿胶}$w{七分}，$u{干姜}$w{三分}，$u{大枣}$w{百枚为膏}，$u{桔梗}$w{五分}，$u{杏仁}$w{六分}，$u{桂枝}$w{十分}，</p>\n<p>$u{防风}$w{六分}，$u{神曲}$w{十分}，$u{豆黄}$w{卷十分}，$u{柴胡}$w{五分}，$u{白蔹}$w{二分}</p>\n<p></p>\n<p>\t$s{上二十一味}，末之，炼$u{蜜}和丸，如弹子大。空腹$u{酒}服一丸，一百丸为剂。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":39,"yaoCount":23,"drinkNum":100,"yaoList":["薯蓣","人参","白术","茯苓","甘草","当归","干地黄","芍药","芎藭","麦门冬","阿胶","干姜","大枣","桔梗","杏仁","桂枝","防风","神曲","豆黄","柴胡","白蔹"],"fangList":[],"fangYaoList":[{"yaoId":"n7KV9vTrthx","amount":"三十分","weight":null,"suffix":null,"showName":"薯蓣","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"七分","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"UIYZOmiE2xW","amount":"六分","weight":null,"suffix":null,"showName":"白术","extraProcess":null},{"yaoId":"VHE7Y68l232","amount":"五分","weight":null,"suffix":null,"showName":"茯苓","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二十八分","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"JFnirDnffR9","amount":"十分","weight":null,"suffix":null,"showName":"当归","extraProcess":null},{"yaoId":null,"amount":"十分","weight":null,"suffix":null,"showName":"干地黄","extraProcess":null},{"yaoId":"Ro0664U6sTQ","amount":"六分","weight":null,"suffix":null,"showName":"芍药","extraProcess":null},{"yaoId":null,"amount":"六分","weight":null,"suffix":null,"showName":"芎藭","extraProcess":null},{"yaoId":"DDXydmiFQLK","amount":"六分","weight":null,"suffix":null,"showName":"麦门冬","extraProcess":null},{"yaoId":"T3B7gaA2R03","amount":"七分","weight":null,"suffix":null,"showName":"阿胶","extraProcess":n