INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RUE42KrsEYL', 1, '{"title":"灸甘草汤","description":"<p>  $u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，</p>\n<p>$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}</p>\n<p></p>\n<p>上九味，以酒七升，水八升，先煮八味，取三升，去滓，内胶消尽，温服一升， 日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":41,"yaoCount":9,"drinkNum":3,"yaoList":["甘草","桂枝","生姜","麦门冬","麻仁","人参","阿胶","大枣","生地黄"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"四两，炙","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":null,"weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"各三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"DDXydmiFQLK","amount":"半升","weight":null,"suffix":null,"showName":"麦门冬","extraProcess":null},{"yaoId":null,"amount":"半升","weight":null,"suffix":null,"showName":"麻仁","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":null,"weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"T3B7gaA2R03","amount":"各二两","weight":null,"suffix":null,"showName":"阿胶","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"三十枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":null,"amount":"一斤","weight":null,"suffix":null,"showName":"生地黄","extraProcess":null}]}}', '2025-03-12T04:41:31.000Z', '2025-03-12T04:41:31.000Z', '2025-03-12T04:41:31.000Z', '$u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}， $u{大枣}$w{三十枚}，$u{生地黄}$w{一斤} 上九味，以酒七升，水八升，先煮八味，取三升，去滓，内胶消尽，温服一升， 日三服。', '2025-03-12T04:41:31.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
