INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AchC0y3EtGQ', 1, '{"title":"射干麻黄汤","description":"<p> $u{射干}$w{三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{半升}</p>\n<p>\t$s{上九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":43,"yaoCount":9,"drinkNum":3,"yaoList":["射干","麻黄","生姜","细辛","紫菀","款冬花","五味子","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"PEcY2j6wjoH","amount":"三两","weight":null,"suffix":null,"showName":"射干","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":null,"weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"iNByjKej50u","amount":null,"weight":null,"suffix":null,"showName":"紫菀","extraProcess":null},{"yaoId":"CPNE5J4Tnwm","amount":"各三两","weight":null,"suffix":null,"showName":"款冬花","extraProcess":null},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":null,"suffix":null,"showName":"五味子","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"七枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null}]}}', '2025-03-12T09:27:38.000Z', '2025-03-12T09:27:38.000Z', '2025-03-12T09:27:38.000Z', '$u{射干}$w{三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{半升} $s{上九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。', '2025-03-12T09:27:38.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('drxKWdW8PgG', 1, '{"title":"皂荚丸","description":"<p>$u{皂荚}$w{八两，刮去皮，用酥炙}</p>\n<p>\t$s{上一味}，末之，$u{蜜}丸梧子大。以枣膏和汤服三丸，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":44,"yaoCount":3,"drinkNum":4,"yaoList":["皂荚"],"fangList":[],"fangYaoList":[{"yaoId":"hmJnKWK15KJ","amount":"八两，刮去皮，用酥炙","weight":null,"suffix":null,"showName":"皂荚","extraProcess":null}]}}', '2025-03-13T07:54:47.000Z', '2025-03-13T07:54:47.000Z', '2025-03-13T07:54:47.000Z', '$u{皂荚}$w{八两，刮去皮，用酥炙} $s{上一味}，末之，$u{蜜}丸梧子大。以枣膏和汤服三丸，日三、夜一服。', '2025-03-13T07:54:47.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FS3NzwJjTaD', 1, '{"title":"泽漆汤","description":"<p>$u{半夏}$w{半升}，$u{紫参}$w{五两。一本紫菀}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两},</p>\n<p>$u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}，</p>\n<p>\t$s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":45,"yaoCount":9,"drinkNum":5,"yaoList":["半夏","紫参","生姜","白前","甘草","黄芩","人参","桂枝","泽漆"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"ErucDpix02e","amount":"五两。一本紫菀","weight":null,"suffix":null,"showName":"紫参","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"LoZ0ORbfbD5","amount":"五两","weight":null,"suffix":null,"showName":"白前","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":null,"weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"fd3riAoOlLa","amount":null,"weight":null,"suffix":null,"showName":"黄芩","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":null,"weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"7S7n1dzieYK","amount":"各三两","weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"Rw6Mqj3o4qB","amount":"三斤，以东流水五斗，煮取一斗五升","weight":null,"suffix":null,"showName":"泽漆","extraProcess":null}]}}', '2025-03-13T08:05:09.000Z', '2025-03-13T08:05:09.000Z', '2025-03-13T08:05:09.000Z', '$u{半夏}$w{半升}，$u{紫参}$w{五两。一本紫菀}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两}, $u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}， $s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。', '2025-03-13T08:05:09.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u5cNGjpLs6X', 1, '{"title":"厚朴麻黄汤","description":"<p>$u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升}</p>\n<p></p>\n<p>\t$s{上九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":46,"yaoCount":9,"drinkNum":3,"yaoList":["厚朴","麻黄","石膏","杏仁","半夏","干姜","细辛","小麦","五味子"],"fangList":[],"fangYaoList":[{"yaoId":"8714SID7nWu","amount":"五两","weight":null,"suffix":null,"showName":"厚朴","extraProcess":null},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":null,"suffix":null,"showName":"麻黄","extraProcess":null},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大","weight":null,"suffix":null,"showName":"石膏","extraProcess":null},{"yaoId":"Hs7PKqMqKRj","amount":"半升","weight":null,"suffix":null,"showName":"杏仁","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":null,"suffix":null,"showName":"干姜","extraProcess":null},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":null,"suffix":null,"showName":"细辛","extraProcess":null},{"yaoId":"CdBvjhzVtG6","amount":"一升","weight":null,"suffix":null,"showName":"小麦","extraProcess":null},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":null,"suffix":null,"showName":"五味子","extraProcess":null}]}}', '2025-03-13T08:07:10.000Z', '2025-03-13T08:07:10.000Z', '2025-03-13T08:07:10.000Z', '$u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升} $s{上九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。', '2025-03-13T08:07:10.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lddpwO90m1O', 1, '{"title":"麦门冬汤","description":"<p>$u{麦门冬}$w{七升}，$u{半夏}$w{一升}，$u{人参}$w{二两}，$u{甘草}$w{二两}，$u{粳米}$w{三合}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{上六味}，以水一斗二升，煮取六升。温服一升，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":47,"yaoCount":6,"drinkNum":4,"yaoList":["麦门冬","半夏","人参","甘草","粳米","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"DDXydmiFQLK","amount":"七升","weight":null,"suffix":null,"showName":"麦门冬","extraProcess":null},{"yaoId":"axI8tfBmKAx","amount":"一升","weight":null,"suffix":null,"showName":"半夏","extraProcess":null},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":null,"suffix":null,"showName":"人参","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"2gRWUBY7CiY","amount":"三合","weight":null,"suffix":null,"showName":"粳米","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2025-03-13T08:25:45.000Z', '2025-03-13T08:25:45.000Z', '2025-03-13T08:25:45.000Z', '$u{麦门冬}$w{七升}，$u{半夏}$w{一升}，$u{人参}$w{二两}，$u{甘草}$w{二两}，$u{粳米}$w{三合}，$u{大枣}$w{十二枚} $s{上六味}，以水一斗二升，煮取六升。温服一升，日三、夜一服。', '2025-03-13T08:25:45.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('idGoIyh8eEY', 1, '{"title":"葶苈大枣泻肺汤","description":"<p>$u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":48,"yaoCount":2,"drinkNum":1,"yaoList":["葶苈","大枣"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"熬令黄色，捣丸如弹丸大","weight":null,"suffix":null,"showName":"葶苈","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十二枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null}]}}', '2025-03-13T08:49:58.000Z', '2025-03-13T08:49:58.000Z', '2025-03-13T08:49:58.000Z', '$u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚} $s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。', '2025-03-13T08:49:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('slQ0JqH9xI7', 1, '{"title":"桂枝去芍药加皂荚汤","description":"<p>\t$u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦}</p>\n<p>\t$s{上五味}，以水七升，微微火煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"Kcb7X2K5LTh","no":49,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","生姜","甘草","大枣","皂荚"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":null,"weight":null,"suffix":null,"showName":"桂枝","extraProcess":null},{"yaoId":"VcvhqvKkSct","amount":"各三两","weight":null,"suffix":null,"showName":"生姜","extraProcess":null},{"yaoId":"vVJUANA6k8h","amount":"二两","weight":null,"suffix":null,"showName":"甘草","extraProcess":null},{"yaoId":"JZ9gTmGblYB","amount":"十枚","weight":null,"suffix":null,"showName":"大枣","extraProcess":null},{"yaoId":"hmJnKWK15KJ","amount":"一枚，去皮子，炙焦","weight":null,"suffix":null,"showName":"皂荚","extraProcess":null}]}}', '2025-03-13T09:17:33.000Z', '2025-03-13T09:17:33.000Z', '2025-03-13T09:17:33.000Z', '$u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦} $s{上五味}，以水七升，微微火煮取三升，分温三服。', '2025-03-13T09:17:33.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vVJUANA6k8h', 1, '{"title":"甘草","description":"<p>1、$u{甘草}</p>\r\n<p>$q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。</p>\r\n<p>$q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":0,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '1、$u{甘草} $q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。 $q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7S7n1dzieYK', 1, '{"title":"桂枝","description":"<p>2、$u{桂枝}</p>\n<p>$q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。</p>\n<p></p>\n<p>$q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。</p>\n<p></p>\n<p>$q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":1,"yaoNames":"","aliases":[{"bieming":"桂","name":"桂枝"},{"bieming":"桂心","name":"桂枝"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2、$u{桂枝} $q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。 $q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。 $q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。 $q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。 $q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VcvhqvKkSct', 1, '{"title":"生姜","description":"<p>3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。]</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":2,"yaoNames":"","aliases":[{"bieming":"生姜汁","name":"生姜"},{"bieming":"姜","name":"生姜"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。] $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JZ9gTmGblYB', 1, '{"title":"大枣","description":"<p>4、$u{大枣}</p>\r\n<p>$q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。</p>\r\n<p>$q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":3,"yaoNames":"","aliases":[{"bieming":"枣","name":"大枣"},{"bieming":"枣膏","name":"大枣"},{"bieming":"枣肉","name":"大枣"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '4、$u{大枣} $q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。 $q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('axI8tfBmKAx', 1, '{"title":"半夏","description":"<p>5、$u{半夏}</p>\r\n<p>$q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。</p>\r\n<p>$q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":4,"yaoNames":"地文,水玉,守,示姑","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '5、$u{半夏} $q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。 $q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ro0664U6sTQ', 1, '{"title":"芍药","description":"<p>6、$u{芍药}</p>\r\n<p>$q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。</p>\r\n<p>$q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":5,"yaoNames":"白木,余容,犁食,解仓,铤","aliases":[{"bieming":"白芍药","name":"芍药"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '6、$u{芍药} $q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。 $q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0p1dUWRsS6D', 1, '{"title":"干姜","description":"<p>7、$u{干姜}</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":6,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '7、$u{干姜} $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VHE7Y68l232', 1, '{"title":"茯苓","description":"<p>8、$u{茯苓}</p>\r\n<p>$q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":7,"yaoNames":"伏菟","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '8、$u{茯苓} $q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。 $q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GIXSHBaFv0L', 1, '{"title":"人参","description":"<p>9、$u{人参}</p>\r\n<p>$q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。</p>\r\n<p>$q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":8,"yaoNames":"人衔,鬼盖,神草,人微,土精,血参","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '9、$u{人参} $q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。 $q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jT011T7yIVO', 1, '{"title":"附子","description":"<p>10、$u{附子}</p>\r\n<p>$q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。</p>\r\n<p>$q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":9,"yaoNames":"茛","aliases":[{"bieming":"大附子","name":"附子"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '10、$u{附子} $q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。 $q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UIYZOmiE2xW', 1, '{"title":"白术","description":"<p>11、$u{白术}（术）</p>\r\n<p>$q{《神农本草经》}：【术】味苦。温。主治风寒湿痹。死肌。痉。疸。止汗。除热。消食。作煎饵。久服轻身。延年。不饥。一名山蓟。生郑山山谷。</p>\r\n<p>$q{《名医别录》}：【术】味甘。无毒。主治大风在身面。风眩头痛。目泪出。消痰水。逐皮间风水结肿。除心下急满。及霍乱。吐下不止。利腰脐间血。益津液。暖胃。消谷。嗜食。一名山姜。一名山连。生郑山汉中南郑。二月三月八月九月采根。暴干。（防风地榆为之使。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":10,"yaoNames":"山蓟,山精","aliases":[{"bieming":"术","name":"白术"},{"bieming":"朮","name":"白术"},{"bieming":"白朮","name":"白术"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '11、$u{白术}（术） $q{《神农本草经》}：【术】味苦。温。主治风寒湿痹。死肌。痉。疸。止汗。除热。消食。作煎饵。久服轻身。延年。不饥。一名山蓟。生郑山山谷。 $q{《名医别录》}：【术】味甘。无毒。主治大风在身面。风眩头痛。目泪出。消痰水。逐皮间风水结肿。除心下急满。及霍乱。吐下不止。利腰脐间血。益津液。暖胃。消谷。嗜食。一名山姜。一名山连。生郑山汉中南郑。二月三月八月九月采根。暴干。（防风地榆为之使。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nxz0hvgpJJf', 1, '{"title":"麻黄","description":"<p>12、$u{麻黄}</p>\r\n<p>$q{《神农本草经》}：【麻黄】味苦。温。主治中风伤寒头痛。温疟。发表出汗。去邪热气。止咳逆上气。除寒热。破癥坚积聚。一名龙沙。生晋地。</p>\r\n<p>$q{《名医别录》}：【麻黄】微温。无毒。主治五藏邪气缓急。风胁痛。字乳余疾。止好唾。通腠理。疏伤寒头痛解肌。泄邪恶气。消赤黑斑毒。不可多服。令人虚。一名卑相。一名卑盐。生晋地及河东。立秋采茎。阴干令青。（厚朴为之使。恶辛夷石韦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":11,"yaoNames":"龙沙","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '12、$u{麻黄} $q{《神农本草经》}：【麻黄】味苦。温。主治中风伤寒头痛。温疟。发表出汗。去邪热气。止咳逆上气。除寒热。破癥坚积聚。一名龙沙。生晋地。 $q{《名医别录》}：【麻黄】微温。无毒。主治五藏邪气缓急。风胁痛。字乳余疾。止好唾。通腠理。疏伤寒头痛解肌。泄邪恶气。消赤黑斑毒。不可多服。令人虚。一名卑相。一名卑盐。生晋地及河东。立秋采茎。阴干令青。（厚朴为之使。恶辛夷石韦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('To31b37bc6Z', 1, '{"title":"大黄","description":"<p>13、$u{大黄}</p>\r\n<p>$q{《神农本草经》}：【大黄】味苦。寒。主下瘀血。血闭。寒热。破癥瘕。积聚。留饮宿食。荡涤肠胃。推陈致新。通利水谷道。调中化食。安和五藏。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【大黄】（将军。）大寒。无毒。平胃下气。除痰实。肠间结热。心腹胀满。女子寒血闭胀。小腹痛。诸老血留结。一名黄良。生河西及陇西。二月八月采根。火干。（黄芩为之使。无所畏。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":12,"yaoNames":"将军,川军","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '13、$u{大黄} $q{《神农本草经》}：【大黄】味苦。寒。主下瘀血。血闭。寒热。破癥瘕。积聚。留饮宿食。荡涤肠胃。推陈致新。通利水谷道。调中化食。安和五藏。生河西山谷。 $q{《名医别录》}：【大黄】（将军。）大寒。无毒。平胃下气。除痰实。肠间结热。心腹胀满。女子寒血闭胀。小腹痛。诸老血留结。一名黄良。生河西及陇西。二月八月采根。火干。（黄芩为之使。无所畏。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fd3riAoOlLa', 1, '{"title":"黄芩","description":"<p>14、$u{黄芩}</p>\r\n<p>$q{《神农本草经》}：【黄芩】味苦。平。主治诸热。黄疸。肠澼泄痢。逐水。下血闭。恶疮疽蚀。火疡。一名腐肠。生秭归川谷。</p>\r\n<p>$q{《名医别录》}：【黄芩】大寒。无毒。主治痰热。胃中热。小腹绞痛。消谷。利小肠。女子血闭淋露下血。小儿腹痛。一名空肠。一名内虚。一名黄文。一名经芩。一名妬妇。其【子】主肠澼脓血。生秭归及宛朐。三月三日采根。阴干。（得厚朴黄连止腹痛。得五味子牡蒙牡蛎令人有子。得黄芪白蔹赤小豆治鼠瘘。山茱萸龙骨为之使。恶葱实。畏丹参牡丹藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":13,"yaoNames":"腐肠","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '14、$u{黄芩} $q{《神农本草经》}：【黄芩】味苦。平。主治诸热。黄疸。肠澼泄痢。逐水。下血闭。恶疮疽蚀。火疡。一名腐肠。生秭归川谷。 $q{《名医别录》}：【黄芩】大寒。无毒。主治痰热。胃中热。小腹绞痛。消谷。利小肠。女子血闭淋露下血。小儿腹痛。一名空肠。一名内虚。一名黄文。一名经芩。一名妬妇。其【子】主肠澼脓血。生秭归及宛朐。三月三日采根。阴干。（得厚朴黄连止腹痛。得五味子牡蒙牡蛎令人有子。得黄芪白蔹赤小豆治鼠瘘。山茱萸龙骨为之使。恶葱实。畏丹参牡丹藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MCBshcFNHhk', 1, '{"title":"细辛","description":"<p>16、$u{细辛}</p>\r\n<p>$q{《神农本草经》}：【细辛】味辛。温。主治咳逆。头痛脑动。百节拘挛。风湿痹痛。死肌。久服明目。利九窍。轻身。长年。一名小辛。生华阴山谷。</p>\r\n<p>$q{《名医别录》}：【细辛】无毒。主温中。下气。破痰。利水道。开胸中。除喉痹。齆鼻风痫。癫疾。下乳结。汗不出。血不行。安五藏。益肝胆。通精气。生华阴。二月八月采根。阴干。（曾青桑白皮为之使。反藜芦。恶狼毒山茱萸黄芪。畏滑石消石。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":15,"yaoNames":"小辛","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '16、$u{细辛} $q{《神农本草经》}：【细辛】味辛。温。主治咳逆。头痛脑动。百节拘挛。风湿痹痛。死肌。久服明目。利九窍。轻身。长年。一名小辛。生华阴山谷。 $q{《名医别录》}：【细辛】无毒。主温中。下气。破痰。利水道。开胸中。除喉痹。齆鼻风痫。癫疾。下乳结。汗不出。血不行。安五藏。益肝胆。通精气。生华阴。二月八月采根。阴干。（曾青桑白皮为之使。反藜芦。恶狼毒山茱萸黄芪。畏滑石消石。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JFnirDnffR9', 1, '{"title":"当归","description":"<p>17、$u{当归}</p>\r\n<p>$q{《神农本草经》}：【当归】味甘。温。主治咳逆上气。温疟寒热洗洗在皮肤中。妇人漏下绝子。诸恶疮疡。金创。煮饮之。一名干归。生陇西川谷。</p>\r\n<p>$q{《名医别录》}：【当归】味辛。无毒。主温中止痛。除客血内塞。中风痓。汗不出。湿痹。中恶。客气虚冷。补五藏。生肌肉。生陇西。二月八月采根。阴干。（恶䕡茹。畏菖蒲海藻牡蒙。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":16,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '17、$u{当归} $q{《神农本草经》}：【当归】味甘。温。主治咳逆上气。温疟寒热洗洗在皮肤中。妇人漏下绝子。诸恶疮疡。金创。煮饮之。一名干归。生陇西川谷。 $q{《名医别录》}：【当归】味辛。无毒。主温中止痛。除客血内塞。中风痓。汗不出。湿痹。中恶。客气虚冷。补五藏。生肌肉。生陇西。二月八月采根。阴干。（恶䕡茹。畏菖蒲海藻牡蒙。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Hs7PKqMqKRj', 1, '{"title":"杏仁","description":"<p>18、$u{杏仁}</p>\r\n<p>$q{《神农本草经》}：【杏核】味甘。温。主治咳逆上气。雷鸣。喉痹。下气。产乳。金创。寒心。贲豚。生晋山川谷。</p>\r\n<p>$q{《名医别录》}：【杏核】味苦。冷利。有毒。主治惊痫。心下烦热。风气去来。时行头痛。解肌。消心下急。杀狗毒。一名杏子。五月采。其两仁者杀人。可以毒狗。【花】味苦。无毒。主补不足。女子伤中。寒热痹。厥逆。【实】味酸。不可多食。伤筋骨。生晋山。（得火良。恶黄芪黄芩葛根。解锡毒。畏蘘草。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":17,"yaoNames":"杏核仁","aliases":[{"bieming":"杏子","name":"杏仁"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '18、$u{杏仁} $q{《神农本草经》}：【杏核】味甘。温。主治咳逆上气。雷鸣。喉痹。下气。产乳。金创。寒心。贲豚。生晋山川谷。 $q{《名医别录》}：【杏核】味苦。冷利。有毒。主治惊痫。心下烦热。风气去来。时行头痛。解肌。消心下急。杀狗毒。一名杏子。五月采。其两仁者杀人。可以毒狗。【花】味苦。无毒。主补不足。女子伤中。寒热痹。厥逆。【实】味酸。不可多食。伤筋骨。生晋山。（得火良。恶黄芪黄芩葛根。解锡毒。畏蘘草。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S7mhkBtEhPL', 1, '{"title":"石膏","description":"<p>19、$u{石膏}</p>\r\n<p>$q{《神农本草经》}：【石膏】味辛。微寒。主治中风寒热。心下逆气。惊喘。口干舌焦不能息。腹中坚痛。除邪鬼。产乳。金疮。生齐山山谷。</p>\r\n<p>$q{《名医别录》}：【石膏】味甘。大寒。无毒。主除时气。头痛。身热。三焦大热。皮肤热。肠胃中鬲热。解肌。发汗。止消渴。烦逆。腹胀。暴气喘息。咽热。亦可作浴汤。一名细石。细理白泽者者良。黄者令人淋。生齐山及齐卢山鲁蒙山。采无时。（鸡子为之使。恶莽草毒公。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":18,"yaoNames":"寒水石","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '19、$u{石膏} $q{《神农本草经》}：【石膏】味辛。微寒。主治中风寒热。心下逆气。惊喘。口干舌焦不能息。腹中坚痛。除邪鬼。产乳。金疮。生齐山山谷。 $q{《名医别录》}：【石膏】味甘。大寒。无毒。主除时气。头痛。身热。三焦大热。皮肤热。肠胃中鬲热。解肌。发汗。止消渴。烦逆。腹胀。暴气喘息。咽热。亦可作浴汤。一名细石。细理白泽者者良。黄者令人淋。生齐山及齐卢山鲁蒙山。采无时。（鸡子为之使。恶莽草毒公。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8714SID7nWu', 1, '{"title":"厚朴","description":"<p>20、$u{厚朴}</p>\r\n<p>$q{《神农本草经》}：【厚朴】味苦。温。主治中风。伤寒。头痛。寒热。惊悸气。血痹。死肌。去三虫。生交趾山谷。</p>\r\n<p>$q{《名医别录》}：【厚朴】大温。无毒。主温中。益气。消痰。下气。治霍乱及腹痛胀满。胃中冷逆。胸中呕逆不止。泄痢。淋露。除惊。去留热。止烦满。厚肠胃。一名厚皮。一名赤朴。其树名榛。子名逐杨。治鼠瘘。明目。益气。生交趾宛朐。三月九月十月采皮。阴干。（干姜为之使。恶泽泻寒水石消石。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":19,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '20、$u{厚朴} $q{《神农本草经》}：【厚朴】味苦。温。主治中风。伤寒。头痛。寒热。惊悸气。血痹。死肌。去三虫。生交趾山谷。 $q{《名医别录》}：【厚朴】大温。无毒。主温中。益气。消痰。下气。治霍乱及腹痛胀满。胃中冷逆。胸中呕逆不止。泄痢。淋露。除惊。去留热。止烦满。厚肠胃。一名厚皮。一名赤朴。其树名榛。子名逐杨。治鼠瘘。明目。益气。生交趾宛朐。三月九月十月采皮。阴干。（干姜为之使。恶泽泻寒水石消石。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Sfmcy2PNzjm', 1, '{"title":"芎䓖","description":"<p>21、$u{芎䓖}：芎藭</p>\r\n<p>$q{《神农本草经》}：【芎藭】味辛。温。主治中风入脑头痛。寒痹。筋挛缓急。金疮。妇人血闭无子。生武功川谷。</p>\r\n<p>$q{《名医别录》}：【芎藭】无毒。主除脑中冷动。面上游风去来。目泪出。多涕唾。忽忽如醉。诸寒冷气。心腹坚痛。中恶。卒急肿痛。胁风痛。温中内寒。一名胡穷。一名香果。其叶名蘼芜。生武功斜谷西岭。三月四月采根。暴干。（白芷为之使。恶黄连。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":20,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '21、$u{芎䓖}：芎藭 $q{《神农本草经》}：【芎藭】味辛。温。主治中风入脑头痛。寒痹。筋挛缓急。金疮。妇人血闭无子。生武功川谷。 $q{《名医别录》}：【芎藭】无毒。主除脑中冷动。面上游风去来。目泪出。多涕唾。忽忽如醉。诸寒冷气。心腹坚痛。中恶。卒急肿痛。胁风痛。温中内寒。一名胡穷。一名香果。其叶名蘼芜。生武功斜谷西岭。三月四月采根。暴干。（白芷为之使。恶黄连。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T3B7gaA2R03', 1, '{"title":"阿胶","description":"<p>22、$u{阿胶}</p>\r\n<p>$q{《神农本草经》}：【阿胶】味甘。平。主治心腹内崩。劳极洒洒如疟状。腰腹痛。四肢酸疼。女子下血。安胎。久服轻身。益气。一名傅致胶。生东阿。</p>\r\n<p>$q{《名医别录》}：【阿胶】微温。无毒。主丈夫少腹痛。虚劳羸瘦。阴气不足。脚酸不能久立。养肝气。生东平郡。煮牛皮作之。出东阿。（恶大黄。得火良。）</p>\r\n<p>$q{《名医别录》}：【白胶】温。无毒。主治吐血。下血。崩中不止。四肢酸疼。多汗。淋露。折跌伤损。生云中。煮鹿角作之。（得火良。畏大黄。）</p>\r\n<p>$q{《药性论》}：【阿胶】君。主坚筋骨。益气。止痢。署预为之使。</p>\r\n<p>$q{《药性论》}：【白胶】又名黄明胶。能主男子肾藏气衰虚劳损。妇人服之。令有子。能安胎去冷。治漏下赤白。主吐血。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":21,"yaoNames":"傅致胶","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '22、$u{阿胶} $q{《神农本草经》}：【阿胶】味甘。平。主治心腹内崩。劳极洒洒如疟状。腰腹痛。四肢酸疼。女子下血。安胎。久服轻身。益气。一名傅致胶。生东阿。 $q{《名医别录》}：【阿胶】微温。无毒。主丈夫少腹痛。虚劳羸瘦。阴气不足。脚酸不能久立。养肝气。生东平郡。煮牛皮作之。出东阿。（恶大黄。得火良。） $q{《名医别录》}：【白胶】温。无毒。主治吐血。下血。崩中不止。四肢酸疼。多汗。淋露。折跌伤损。生云中。煮鹿角作之。（得火良。畏大黄。） $q{《药性论》}：【阿胶】君。主坚筋骨。益气。止痢。署预为之使。 $q{《药性论》}：【白胶】又名黄明胶。能主男子肾藏气衰虚劳损。妇人服之。令有子。能安胎去冷。治漏下赤白。主吐血。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C74sm5pJRdN', 1, '{"title":"五味子","description":"<p>23、$u{五味子}</p>\r\n<p>$q{《神农本草经》}：【五味子】味酸。温。主益气。咳逆上气。劳伤羸瘦。补不足。强阴。益男子精。生齐山山谷。</p>\r\n<p>$q{《名医别录》}：【五味子】无毒。主养五藏。除热。生阴中肌。一名会及。一名玄及。生齐山及代郡。八月采实。阴干。（苁蓉为之使。恶葳蕤。胜乌头。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":22,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '23、$u{五味子} $q{《神农本草经》}：【五味子】味酸。温。主益气。咳逆上气。劳伤羸瘦。补不足。强阴。益男子精。生齐山山谷。 $q{《名医别录》}：【五味子】无毒。主养五藏。除热。生阴中肌。一名会及。一名玄及。生齐山及代郡。八月采实。阴干。（苁蓉为之使。恶葳蕤。胜乌头。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MDfiJ4S7u0U', 1, '{"title":"牡蛎","description":"<p>24、$u{牡蛎}</p>\r\n<p>$q{《神农本草经》}：【牡蛎】味咸。平。主治伤寒寒热。温疟洒洒。惊恚怒气。除拘缓。鼠瘘。女子带下赤白。久服强骨节。杀邪鬼。延年。一名蛎蛤。生东海池泽。</p>\r\n<p>$q{《名医别录》}：【牡蛎】微寒。无毒。主除留热在关节荣卫。虚热去来不定。烦满。止汗。心痛气结。止渴。除老血。涩大小肠。止大小便。治泄精喉痹咳嗽心胁下痞热。一名牡蛤。生东海。采时。（贝母为之使。得甘草牛膝远志蛇床良。恶麻黄吴茱萸辛夷。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":23,"yaoNames":"蛎蛤","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '24、$u{牡蛎} $q{《神农本草经》}：【牡蛎】味咸。平。主治伤寒寒热。温疟洒洒。惊恚怒气。除拘缓。鼠瘘。女子带下赤白。久服强骨节。杀邪鬼。延年。一名蛎蛤。生东海池泽。 $q{《名医别录》}：【牡蛎】微寒。无毒。主除留热在关节荣卫。虚热去来不定。烦满。止汗。心痛气结。止渴。除老血。涩大小肠。止大小便。治泄精喉痹咳嗽心胁下痞热。一名牡蛤。生东海。采时。（贝母为之使。得甘草牛膝远志蛇床良。恶麻黄吴茱萸辛夷。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i7j1zMcc48a', 1, '{"title":"黄芪","description":"<p>26、$u{黄芪}</p>\r\n<p>$q{《神农本草经》}：【黄耆】味甘。微温。主治痈疽。久败疮。排脓止痛。大风癞疾。五痔。鼠瘘。补虚。小儿百病。一名戴糁。生蜀郡山谷。</p>\r\n<p>$q{《名医别录》}：【黄耆】无毒。主治妇人子藏风邪气。逐五藏间恶血。补丈夫虚损。五劳羸瘦。止渴。腹痛泄利。益气。利阴气。生白水者冷。补。其【茎叶】治渴及筋挛。痈肿。疽疮。一名戴椹。一名独椹。一名芰草。一名蜀脂。一名百本。生蜀郡白水汉中。二月十月采。阴干。（恶龟甲。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":25,"yaoNames":"黄耆","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '26、$u{黄芪} $q{《神农本草经》}：【黄耆】味甘。微温。主治痈疽。久败疮。排脓止痛。大风癞疾。五痔。鼠瘘。补虚。小儿百病。一名戴糁。生蜀郡山谷。 $q{《名医别录》}：【黄耆】无毒。主治妇人子藏风邪气。逐五藏间恶血。补丈夫虚损。五劳羸瘦。止渴。腹痛泄利。益气。利阴气。生白水者冷。补。其【茎叶】治渴及筋挛。痈肿。疽疮。一名戴椹。一名独椹。一名芰草。一名蜀脂。一名百本。生蜀郡白水汉中。二月十月采。阴干。（恶龟甲。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JMfcgoRTH0J', 1, '{"title":"柴胡","description":"<p>28、$u{柴胡}</p>\r\n<p>$q{《神农本草经》}：【茈胡】味苦。平。主治心腹。去肠胃中结气。饮食积聚。寒热邪气。推陈致新。久服轻身。明目。益精。一名地薰。生弘农川谷。</p>\r\n<p>$q{《名医别录》}：【茈胡】微寒。无毒。主除伤寒。心下烦热。诸痰热结实。胸中邪逆。五藏间游气。大肠停积水胀。及湿痹拘挛。亦可作浴汤。一名山菜。一名茹草。【叶】一名芸蒿。辛香可食。生洪农及宛朐。二月八月采根。暴干。（得茯苓桔梗大黄石膏麻子仁甘草桂。以水一斗煮。取四升。入消石三方寸匕。治伤寒寒热头痛心下烦满。半夏为之使。恶皂荚。畏女菀藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":27,"yaoNames":"地薰,茈胡","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '28、$u{柴胡} $q{《神农本草经》}：【茈胡】味苦。平。主治心腹。去肠胃中结气。饮食积聚。寒热邪气。推陈致新。久服轻身。明目。益精。一名地薰。生弘农川谷。 $q{《名医别录》}：【茈胡】微寒。无毒。主除伤寒。心下烦热。诸痰热结实。胸中邪逆。五藏间游气。大肠停积水胀。及湿痹拘挛。亦可作浴汤。一名山菜。一名茹草。【叶】一名芸蒿。辛香可食。生洪农及宛朐。二月八月采根。暴干。（得茯苓桔梗大黄石膏麻子仁甘草桂。以水一斗煮。取四升。入消石三方寸匕。治伤寒寒热头痛心下烦满。半夏为之使。恶皂荚。畏女菀藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t7DkIvGNO8b', 1, '{"title":"桔梗","description":"<p>30、$u{桔梗}</p>\r\n<p>$q{《神农本草经》}：【桔梗】味辛。微温。主治胸胁痛如刀刺。腹满。肠鸣幽幽。惊恐悸气。生嵩高山谷。</p>\r\n<p>$q{《名医别录》}：【桔梗】味苦。有小毒。主利五藏肠胃。补血气。除寒热风痹。温中。消谷。治喉咽痛。下蛊毒。一名利如。一名房图。一名白药。一名梗草。一名荠苨。生嵩高及宛朐。二八月采根。暴干。（节皮为之使。得牡蛎远志治恚怒。得消石石膏治伤寒。畏白及龙眼龙胆。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":29,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '30、$u{桔梗} $q{《神农本草经》}：【桔梗】味辛。微温。主治胸胁痛如刀刺。腹满。肠鸣幽幽。惊恐悸气。生嵩高山谷。 $q{《名医别录》}：【桔梗】味苦。有小毒。主利五藏肠胃。补血气。除寒热风痹。温中。消谷。治喉咽痛。下蛊毒。一名利如。一名房图。一名白药。一名梗草。一名荠苨。生嵩高及宛朐。二八月采根。暴干。（节皮为之使。得牡蛎远志治恚怒。得消石石膏治伤寒。畏白及龙眼龙胆。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k2cI79Wat6h', 1, '{"title":"桃仁","description":"<p>31、$u{桃仁}</p>\r\n<p>$q{《神农本草经》}：【桃核】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。</p>\r\n<p>$q{《名医别录》}：【桃核】味甘。无毒。主咳逆上气。消心下坚。除卒暴击血。破癥瘕。通月水。止痛。七月采取仁。阴干。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":30,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '31、$u{桃仁} $q{《神农本草经》}：【桃核】味苦。平。主治瘀血。血闭瘕邪气。杀小虫。 $q{《名医别录》}：【桃核】味甘。无毒。主咳逆上气。消心下坚。除卒暴击血。破癥瘕。通月水。止痛。七月采取仁。阴干。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TvTXZli2dE7', 1, '{"title":"泽泻","description":"<p>32、$u{泽泻}</p>\r\n<p>$q{《神农本草经》}：【泽泻】味甘。寒。主治风寒湿痹。乳难。消水。养五藏。益气力。肥健。久服耳目聪明。不饥。延年。轻身。面生光。能行水上。一名水泻。一名芒芋。一名鹄泻。生汝南池泽。</p>\r\n<p>$q{《名医别录》}：【泽泻】味咸。无毒。主补虚损五劳。除五藏痞满。起阴气。止泄精消渴淋沥。逐膀胱三焦停水。扁鹊云多服病人眼。一名及泻。生汝南。五月六月八月采根。阴干。（畏海蛤文蛤。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":31,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '32、$u{泽泻} $q{《神农本草经》}：【泽泻】味甘。寒。主治风寒湿痹。乳难。消水。养五藏。益气力。肥健。久服耳目聪明。不饥。延年。轻身。面生光。能行水上。一名水泻。一名芒芋。一名鹄泻。生汝南池泽。 $q{《名医别录》}：【泽泻】味咸。无毒。主补虚损五劳。除五藏痞满。起阴气。止泄精消渴淋沥。逐膀胱三焦停水。扁鹊云多服病人眼。一名及泻。生汝南。五月六月八月采根。阴干。（畏海蛤文蛤。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4lJokf6uHXR', 1, '{"title":"百合","description":"<p>33、$u{百合}</p>\r\n<p>$q{《神农本草经》}：【百合】味甘。平。主治邪气腹胀。心痛。利大小便。补中益气。生荆州川谷。</p>\r\n<p>$q{《名医别录》}：【百合】无毒。主除浮肿。胪胀。痞满。寒热。通身疼痛。及乳难喉痹肿。止涕泪。一名重葙。一名重迈。一名摩罗。一名中逢花。一名强瞿。生荆州。二月八月采根。暴干。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":32,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '33、$u{百合} $q{《神农本草经》}：【百合】味甘。平。主治邪气腹胀。心痛。利大小便。补中益气。生荆州川谷。 $q{《名医别录》}：【百合】无毒。主除浮肿。胪胀。痞满。寒热。通身疼痛。及乳难喉痹肿。止涕泪。一名重葙。一名重迈。一名摩罗。一名中逢花。一名强瞿。生荆州。二月八月采根。暴干。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IHSagd4ikNY', 1, '{"title":"石蜜","description":"<p>34、$u{蜜}（白蜜）</p>\n<p>$q{《神农本草经》}：【石蜜】味甘。平。主治心腹邪气。诸惊痫痓。安五藏。诸不足。益气。补中。止痛。解毒。除众病。和百药。久服强志。轻身。不饥。不老。一名石饴。生武都山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【石蜜】微温。无毒。主养脾气。除心烦。食饮不下。止肠澼。肌中疼痛。口疮。明耳目。久服延年神仙。生武都河源山谷及诸山石中。色白如膏者良。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":33,"yaoNames":"白蜜,蜜","aliases":[{"bieming":"白蜜","name":"蜜"},{"bieming":"食蜜","name":"蜜"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '34、$u{蜜}（白蜜） $q{《神农本草经》}：【石蜜】味甘。平。主治心腹邪气。诸惊痫痓。安五藏。诸不足。益气。补中。止痛。解毒。除众病。和百药。久服强志。轻身。不饥。不老。一名石饴。生武都山谷。 $q{《名医别录》}：【石蜜】微温。无毒。主养脾气。除心烦。食饮不下。止肠澼。肌中疼痛。口疮。明耳目。久服延年神仙。生武都河源山谷及诸山石中。色白如膏者良。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M9HezPeSGkC', 1, '{"title":"防己","description":"<p>35、$u{防己}（木防己）</p>\r\n<p>$q{《神农本草经》}：【防己】味辛。平。主治风寒。温疟。热气。诸痫。除邪。利大小便。一名解离。生汉中川谷。</p>\r\n<p>$q{《名医别录》}：【防己】味苦。温。无毒。主治水肿。风肿。去膀胱热。伤寒。寒热邪气。中风。手脚挛急。止泄。散痈肿恶结。诸蜗疥癣。虫疮。通腠理。利九窍。文如车辐理解者良。生汉中。二月八月采根。阴干。（殷孽为之使。杀雄黄毒。恶细辛。畏萆薢。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":34,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '35、$u{防己}（木防己） $q{《神农本草经》}：【防己】味辛。平。主治风寒。温疟。热气。诸痫。除邪。利大小便。一名解离。生汉中川谷。 $q{《名医别录》}：【防己】味苦。温。无毒。主治水肿。风肿。去膀胱热。伤寒。寒热邪气。中风。手脚挛急。止泄。散痈肿恶结。诸蜗疥癣。虫疮。通腠理。利九窍。文如车辐理解者良。生汉中。二月八月采根。阴干。（殷孽为之使。杀雄黄毒。恶细辛。畏萆薢。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u6WaDjpcWhR', 1, '{"title":"滑石","description":"<p>36、$u{滑石}</p>\r\n<p>$q{《神农本草经》}：【滑石】味甘。寒。主治身热。泄澼。女子乳难。癃闭。利小便。荡胃中积聚寒热。益精气。久服轻身。耐饥。长年。生赭阳山谷。</p>\r\n<p>$q{《名医别录》}：【滑石】大寒。无毒。通九窍六府津液。去留结。止渴。令人利中。一名液石。一名共石。一名脆石。一名番石。生赭阳及太山之阴或掖北白山或卷山。采无时。（石韦为之使。恶曾青。）</p>\r\n<p>$q{《药性论》}∶【滑石】臣。一名夕冷。能疗五淋。主难产。服其末。又末与丹参蜜猪脂为膏。入其月。即空心酒下弹丸大。临产倍服。令滑胎易生。除烦热心躁。偏主石淋。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":35,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '36、$u{滑石} $q{《神农本草经》}：【滑石】味甘。寒。主治身热。泄澼。女子乳难。癃闭。利小便。荡胃中积聚寒热。益精气。久服轻身。耐饥。长年。生赭阳山谷。 $q{《名医别录》}：【滑石】大寒。无毒。通九窍六府津液。去留结。止渴。令人利中。一名液石。一名共石。一名脆石。一名番石。生赭阳及太山之阴或掖北白山或卷山。采无时。（石韦为之使。恶曾青。） $q{《药性论》}∶【滑石】臣。一名夕冷。能疗五淋。主难产。服其末。又末与丹参蜜猪脂为膏。入其月。即空心酒下弹丸大。临产倍服。令滑胎易生。除烦热心躁。偏主石淋。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nP2w4ZP4Yic', 1, '{"title":"牡丹皮","description":"<p>37、$u{牡丹皮}</p>\r\n<p>$q{《神农本草经》}：【牡丹】味辛。寒。主治寒热。中风。瘛疭。痉。惊痫。邪气。除癥坚。瘀血留舍肠胃。安五藏。治痈疮。一名鹿韭。一名鼠姑。生巴郡山谷。</p>\r\n<p>$q{《名医别录》}：【牡丹】味苦。微寒。无毒。主除时气。头痛。客热。五劳。劳气。头腰痛。风噤。癫疾。生巴郡及汉中。二月八月采根。阴干。（畏菟丝子。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":36,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '37、$u{牡丹皮} $q{《神农本草经》}：【牡丹】味辛。寒。主治寒热。中风。瘛疭。痉。惊痫。邪气。除癥坚。瘀血留舍肠胃。安五藏。治痈疮。一名鹿韭。一名鼠姑。生巴郡山谷。 $q{《名医别录》}：【牡丹】味苦。微寒。无毒。主除时气。头痛。客热。五劳。劳气。头腰痛。风噤。癫疾。生巴郡及汉中。二月八月采根。阴干。（畏菟丝子。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03dIYYkyQRn', 1, '{"title":"蜀椒","description":"<p>38、$u{蜀椒}</p>\r\n<p>$q{《神农本草经》}：【蜀椒】味辛。温。主治邪气咳逆。温中。逐骨节皮肤死肌。寒湿痹痛。下气。久服之头不白。轻身。增年。生武都川谷。</p>\r\n<p>$q{《名医别录》}：【蜀椒】大热。有毒。主除五藏六府寒冷。伤寒。温疟。大风。汗不出。心腹留饮宿食。止肠澼下利。泄精。女子字乳余疾。散风邪。瘕结。水肿。黄疸。鬼疰。蛊毒。杀虫鱼毒。久服开腠理。通血脉。坚齿发。调关节。耐寒暑。可作膏药。多食令人乏气。口闭者杀人。一名巴椒。一名蓎藙。生武都及巴郡。八月采实。阴干。（杏仁为之使。畏槖吾。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":37,"yaoNames":"川椒","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '38、$u{蜀椒} $q{《神农本草经》}：【蜀椒】味辛。温。主治邪气咳逆。温中。逐骨节皮肤死肌。寒湿痹痛。下气。久服之头不白。轻身。增年。生武都川谷。 $q{《名医别录》}：【蜀椒】大热。有毒。主除五藏六府寒冷。伤寒。温疟。大风。汗不出。心腹留饮宿食。止肠澼下利。泄精。女子字乳余疾。散风邪。瘕结。水肿。黄疸。鬼疰。蛊毒。杀虫鱼毒。久服开腠理。通血脉。坚齿发。调关节。耐寒暑。可作膏药。多食令人乏气。口闭者杀人。一名巴椒。一名蓎藙。生武都及巴郡。八月采实。阴干。（杏仁为之使。畏槖吾。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pyZLleBsXOb', 1, '{"title":"栝蒌根","description":"<p>39、$u{栝楼根}</p>\r\n<p>$q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。</p>\r\n<p>$q{《名医别录》}：【栝楼根】无毒。主除肠胃中痼热。八疸。身面黄。唇干口燥。短气。通月水。止小便利。一名果裸。一名天瓜。一名泽姑。生洪农及山阴地。入土深者良。生卤地者有毒。二月八月采根。暴干。三十日成。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":38,"yaoNames":"瓜蒌根,栝楼根,括蒌根","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '39、$u{栝楼根} $q{《神农本草经》}：【栝楼】味苦。寒。主治消渴。身热烦满。大热。补虚。安中。续绝伤。一名地楼。生弘农川谷。 $q{《名医别录》}：【栝楼根】无毒。主除肠胃中痼热。八疸。身面黄。唇干口燥。短气。通月水。止小便利。一名果裸。一名天瓜。一名泽姑。生洪农及山阴地。入土深者良。生卤地者有毒。二月八月采根。暴干。三十日成。（枸杞为之使。恶干姜。畏牛膝干漆。反乌头。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2gRWUBY7CiY', 1, '{"title":"粳米","description":"<p>40、$u{粳米}</p>\r\n<p>$q{《名医别录》}：【粳米】味甘苦。平。无毒。主益气。止烦。止泄。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":39,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '40、$u{粳米} $q{《名医别录》}：【粳米】味甘苦。平。无毒。主益气。止烦。止泄。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PeV28d5T6et', 1, '{"title":"知母","description":"<p>41、$u{知母}</p>\r\n<p>$q{《神农本草经》}：【知母】味苦。寒。主治消渴热中。除邪气。肢体浮肿。下水。补不足。益气。一名蚳母。一名连母。一名野蓼。一名地参。一名水参。一名水浚。一名货母。一名蝭母。生河内川谷。</p>\r\n<p>$q{《名医别录》}：【知母】无毒。主治伤寒久疟烦热。胁下邪气。膈中恶。及风汗内疸。多服令人泄。一名女雷。一名女理。一名儿草。一名鹿列。一名韭逢。一名儿踵草。一名东根。一名水须。一名沈燔。一名薅。生河内。二月八月采根。暴干。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":40,"yaoNames":"蚳母,连母,野蓼,地参,水参,水浚,货母,蝭母","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '41、$u{知母} $q{《神农本草经》}：【知母】味苦。寒。主治消渴热中。除邪气。肢体浮肿。下水。补不足。益气。一名蚳母。一名连母。一名野蓼。一名地参。一名水参。一名水浚。一名货母。一名蝭母。生河内川谷。 $q{《名医别录》}：【知母】无毒。主治伤寒久疟烦热。胁下邪气。膈中恶。及风汗内疸。多服令人泄。一名女雷。一名女理。一名儿草。一名鹿列。一名韭逢。一名儿踵草。一名东根。一名水须。一名沈燔。一名薅。生河内。二月八月采根。暴干。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KIP0kUQVkZG', 1, '{"title":"猪胆","description":"<p>42、$u{猪胆汁}（猪胆）[$q{《伤寒论》}有“无猪胆。以羊胆代之”语，故附青羊胆。]</p>\r\n<p>$q{《名医别录》}：【猪胆】治伤寒热渴。</p>\r\n<p>$q{《名医别录》}：【青羊胆】治青盲。明目。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":41,"yaoNames":"猪胆汁,大猪胆汁,大猪胆","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '42、$u{猪胆汁}（猪胆）[$q{《伤寒论》}有“无猪胆。以羊胆代之”语，故附青羊胆。] $q{《名医别录》}：【猪胆】治伤寒热渴。 $q{《名医别录》}：【青羊胆】治青盲。明目。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('blvt71sB8Zu', 1, '{"title":"防风","description":"<p>43、$u{防风}</p>\r\n<p>$q{《神农本草经》}：【防风】味甘。温。主治大风头眩痛。恶风。风邪。目盲无所见。风行周身。骨节疼痹。烦满。久服轻身。一名铜芸。生沙苑川泽。</p>\r\n<p>$q{《名医别录》}：【防风】味辛。无毒。主治胁痛胁风头面去来。四肢挛急。字乳金疮内痉。一名茴草。一名百枝。一名屏风。一名䕡根。一名百蜚。生沙苑及邯郸琅邪上蔡。二月十月采根。暴干。（得泽泻藁本治风。得当归芍药阳起石禹余粮治妇人子藏风。恶干姜藜芦白蔹芫花。杀附子毒。）又。叉头者令人发狂。叉尾者发痼疾。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":42,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '43、$u{防风} $q{《神农本草经》}：【防风】味甘。温。主治大风头眩痛。恶风。风邪。目盲无所见。风行周身。骨节疼痹。烦满。久服轻身。一名铜芸。生沙苑川泽。 $q{《名医别录》}：【防风】味辛。无毒。主治胁痛胁风头面去来。四肢挛急。字乳金疮内痉。一名茴草。一名百枝。一名屏风。一名䕡根。一名百蜚。生沙苑及邯郸琅邪上蔡。二月十月采根。暴干。（得泽泻藁本治风。得当归芍药阳起石禹余粮治妇人子藏风。恶干姜藜芦白蔹芫花。杀附子毒。）又。叉头者令人发狂。叉尾者发痼疾。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vL3tFGA7NwL', 1, '{"title":"龙骨","description":"<p>45、$u{龙骨}</p>\r\n<p>$q{《神农本草经》}：【龙骨】味甘。平。无毒。主治心腹鬼疰。精物。老魅。咳逆。泄痢脓血。女子漏下。癥瘕坚结。小儿热气惊痫。</p>\r\n<p>$q{《名医别录》}：【龙骨】微寒。无毒。主治心腹烦满。四肢痿枯。汗出。夜卧自惊。恚怒。伏气在心下。不得喘息。肠痈内疽阴蚀。止汗。小便利。溺血。养精神。定魂魄。安五藏。</p>\r\n<p>$q{《名医别录》}：【白龙骨】治梦寐泄精。小便泄精。</p>\r\n<p>$q{《药性论》}：【龙骨】君。忌鱼。有小毒。逐邪气。安心神。止冷痢及下脓血。女子崩中带下。止梦泄精。夜梦鬼交。治尿血。虚而多梦纷纭者加而用之。</p>\r\n<p>$q{《神农本草经》}：【龙齿】主治小儿大人惊痫。癫疾狂走。心下结气。不能喘息。诸痉。杀精物。久服轻身。通神明。延年。生晋地川谷。</p>\r\n<p>$q{《名医别录》}：【龙齿】主治小儿五惊。十二痫。身热不可近人。大人骨间寒热。又杀蛊毒。【角】主治惊痫瘛疭。身热如火。腹中坚及热泄。生晋地及太山岩水岸土穴石中死龙处。采无时。（龙骨。得人参牛黄良。畏石膏龙角。畏干漆蜀椒理石。）</p>\r\n<p>$q{《药性论》}：【龙齿】君。镇心。安魂魄。齿角俱主小儿大热。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":44,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '45、$u{龙骨} $q{《神农本草经》}：【龙骨】味甘。平。无毒。主治心腹鬼疰。精物。老魅。咳逆。泄痢脓血。女子漏下。癥瘕坚结。小儿热气惊痫。 $q{《名医别录》}：【龙骨】微寒。无毒。主治心腹烦满。四肢痿枯。汗出。夜卧自惊。恚怒。伏气在心下。不得喘息。肠痈内疽阴蚀。止汗。小便利。溺血。养精神。定魂魄。安五藏。 $q{《名医别录》}：【白龙骨】治梦寐泄精。小便泄精。 $q{《药性论》}：【龙骨】君。忌鱼。有小毒。逐邪气。安心神。止冷痢及下脓血。女子崩中带下。止梦泄精。夜梦鬼交。治尿血。虚而多梦纷纭者加而用之。 $q{《神农本草经》}：【龙齿】主治小儿大人惊痫。癫疾狂走。心下结气。不能喘息。诸痉。杀精物。久服轻身。通神明。延年。生晋地川谷。 $q{《名医别录》}：【龙齿】主治小儿五惊。十二痫。身热不可近人。大人骨间寒热。又杀蛊毒。【角】主治惊痫瘛疭。身热如火。腹中坚及热泄。生晋地及太山岩水岸土穴石中死龙处。采无时。（龙骨。得人参牛黄良。畏石膏龙角。畏干漆蜀椒理石。） $q{《药性论》}：【龙齿】君。镇心。安魂魄。齿角俱主小儿大热。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DDXydmiFQLK', 1, '{"title":"麦门冬","description":"<p>50、$u{麦门冬}</p>\r\n<p>$q{《神农本草经》}：【麦门冬】味甘。平。主治心腹结气。伤中。伤饱。胃络脉绝。羸瘦。短气。久服轻身。不老。不饥。生函谷川谷。</p>\r\n<p>$q{《名医别录》}：【麦门冬】微寒。无毒。主治身重目黄。心下支满。虚劳客热。口干燥渴。止呕吐。愈痿蹶。强阴。益精。消谷调中。保神。定肺气。安五藏。令人肥健。美颜色。有子。秦名羊韭。齐名爱韭。楚名乌韭。越名羊蓍。一名禹葭。一名禹余粮。叶如韭。冬夏长生。生函谷及堤坂肥土石间久废处。二月三月八月十月采。阴干。（地黄车前为之使。恶款冬苦瓠。畏苦参青蘘。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":49,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '50、$u{麦门冬} $q{《神农本草经》}：【麦门冬】味甘。平。主治心腹结气。伤中。伤饱。胃络脉绝。羸瘦。短气。久服轻身。不老。不饥。生函谷川谷。 $q{《名医别录》}：【麦门冬】微寒。无毒。主治身重目黄。心下支满。虚劳客热。口干燥渴。止呕吐。愈痿蹶。强阴。益精。消谷调中。保神。定肺气。安五藏。令人肥健。美颜色。有子。秦名羊韭。齐名爱韭。楚名乌韭。越名羊蓍。一名禹葭。一名禹余粮。叶如韭。冬夏长生。生函谷及堤坂肥土石间久废处。二月三月八月十月采。阴干。（地黄车前为之使。恶款冬苦瓠。畏苦参青蘘。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n7KV9vTrthx', 1, '{"title":"薯蓣","description":"<p>51、$u{薯蓣}</p>\r\n<p>$q{《神农本草经》}：【署预】味甘。温。主治伤中。补虚羸。除寒热邪气。补中。益气力。长肌肉。久服耳目聪明。轻身。不饥。延年。一名山芋。生嵩高山谷。</p>\r\n<p>$q{《名医别录》}：【署预】平。无毒。主治头面游风风头眼眩。下气。止腰痛。补虚劳羸瘦。充五藏。除烦热。强阴。秦楚名玉延。郑越名土藷。生嵩高。二月八月采根。暴干。（紫芝为之使。恶甘遂。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":50,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '51、$u{薯蓣} $q{《神农本草经》}：【署预】味甘。温。主治伤中。补虚羸。除寒热邪气。补中。益气力。长肌肉。久服耳目聪明。轻身。不饥。延年。一名山芋。生嵩高山谷。 $q{《名医别录》}：【署预】平。无毒。主治头面游风风头眼眩。下气。止腰痛。补虚劳羸瘦。充五藏。除烦热。强阴。秦楚名玉延。郑越名土藷。生嵩高。二月八月采根。暴干。（紫芝为之使。恶甘遂。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rOi0RaqbWeB', 1, '{"title":"薏苡仁","description":"<p>52、$u{薏苡仁}</p>\r\n<p>$q{《神农本草经》}：【薏苡人】味甘。微寒。主治筋急拘挛。不可屈伸。风湿痹。下气。久服轻身益气。其根下三虫。一名解蠡。生真定平泽。</p>\r\n<p>$q{《名医别录》}：【薏苡人】无毒。主除筋骨邪气不仁。利肠胃。消水肿。令人能食。一名屋菼。一名起实。一名赣。生真定。八月采实。采根无时。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":51,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '52、$u{薏苡仁} $q{《神农本草经》}：【薏苡人】味甘。微寒。主治筋急拘挛。不可屈伸。风湿痹。下气。久服轻身益气。其根下三虫。一名解蠡。生真定平泽。 $q{《名医别录》}：【薏苡人】无毒。主除筋骨邪气不仁。利肠胃。消水肿。令人能食。一名屋菼。一名起实。一名赣。生真定。八月采实。采根无时。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nMnl8EhuWTn', 1, '{"title":"䗪虫","description":"<p>55、$u{䗪虫}</p>\r\n<p>$q{《神农本草经》}：【䗪虫】味咸。寒。主治心腹寒热洗洗。血积癥瘕。破坚。下血闭。生子大良。一名地鳖。生河东川泽。</p>\r\n<p>$q{《名医别录》}：【䗪虫】有毒。一名土鳖。生河东及沙中。人家墙壁下土中湿处。十月取暴干。（畏皂荚菖蒲。）</p>\r\n<p>$q{《药性论》}：【䗪虫】使。畏屋游。味苦咸。治月水不通。破恶血积聚。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":54,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '55、$u{䗪虫} $q{《神农本草经》}：【䗪虫】味咸。寒。主治心腹寒热洗洗。血积癥瘕。破坚。下血闭。生子大良。一名地鳖。生河东川泽。 $q{《名医别录》}：【䗪虫】有毒。一名土鳖。生河东及沙中。人家墙壁下土中湿处。十月取暴干。（畏皂荚菖蒲。） $q{《药性论》}：【䗪虫】使。畏屋游。味苦咸。治月水不通。破恶血积聚。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ozDrmO1Ighz', 1, '{"title":"矾石","description":"<p>56、$u{矾石}</p>\r\n<p>$q{《神农本草经》}：【矾石】味酸。寒。主治寒热。泄利。白沃。阴蚀。恶疮。目痛。坚骨齿。炼饵服之。轻身。不老增年。一名羽涅。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【矾石】无毒。除固热在骨髓。去鼻中息肉。岐伯云久服伤人骨。能使铁为铜。一名羽泽。生河西及陇西武都石门。采无时。（甘草为之使。恶牡蛎。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":55,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '56、$u{矾石} $q{《神农本草经》}：【矾石】味酸。寒。主治寒热。泄利。白沃。阴蚀。恶疮。目痛。坚骨齿。炼饵服之。轻身。不老增年。一名羽涅。生河西山谷。 $q{《名医别录》}：【矾石】无毒。除固热在骨髓。去鼻中息肉。岐伯云久服伤人骨。能使铁为铜。一名羽泽。生河西及陇西武都石门。采无时。（甘草为之使。恶牡蛎。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q7UHJJ3ORHQ', 1, '{"title":"胶饴","description":"<p>57、$u{胶饴}（饴）</p>\r\n<p>$q{《名医别录》}：【饴糖】味甘。微温。主补虚乏。止渴。去血。</p>\r\n<p>$q{《日华子本草》}：【饴糖】益气力。消痰止嗽。并润五藏。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":56,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '57、$u{胶饴}（饴） $q{《名医别录》}：【饴糖】味甘。微温。主补虚乏。止渴。去血。 $q{《日华子本草》}：【饴糖】益气力。消痰止嗽。并润五藏。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('14GklrlZE7t', 1, '{"title":"鳖甲","description":"<p>60、$u{鳖甲}</p>\r\n<p>$q{《神农本草经》}：【鳖甲】味咸。平。主治心腹癥瘕。坚积。寒热。去痞息肉。阴蚀。痔。恶肉。生丹阳池泽。</p>\r\n<p>$q{《名医别录》}：【鳖甲】无毒。主治温疟。血瘕。腰痛。小儿胁下坚。【肉】味甘。治伤中。益气。补不足。生丹阳。取无时。（恶矾石。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":59,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '60、$u{鳖甲} $q{《神农本草经》}：【鳖甲】味咸。平。主治心腹癥瘕。坚积。寒热。去痞息肉。阴蚀。痔。恶肉。生丹阳池泽。 $q{《名医别录》}：【鳖甲】无毒。主治温疟。血瘕。腰痛。小儿胁下坚。【肉】味甘。治伤中。益气。补不足。生丹阳。取无时。（恶矾石。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1rOkrjGOCab', 1, '{"title":"赤石脂","description":"<p>65、$u{赤石脂}</p>\r\n<p>$q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。</p>\r\n<p>$q{《名医别录》}：【赤石脂】味甘酸辛。大温。无毒。主养心气。明目。益精。治腹痛。泄澼。下痢赤白。小便利。及痈疽疮痔。女子崩中漏下。产难。胞衣不出。久服补髓。好颜色。益智。不饥。轻身。延年。生济南射阳。及太山之阴。采无时。（恶大黄。畏芫花。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":64,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '65、$u{赤石脂} $q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。 $q{《名医别录》}：【赤石脂】味甘酸辛。大温。无毒。主养心气。明目。益精。治腹痛。泄澼。下痢赤白。小便利。及痈疽疮痔。女子崩中漏下。产难。胞衣不出。久服补髓。好颜色。益智。不饥。轻身。延年。生济南射阳。及太山之阴。采无时。（恶大黄。畏芫花。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ul8euTuPbq0', 1, '{"title":"雄黄","description":"<p>68、$u{雄黄}</p>\r\n<p>$q{《神农本草经》}：【雄黄】味苦。平。寒。主治寒热。鼠瘘。恶疮。疽痔。死肌。杀精物。恶鬼。邪气。百虫。毒肿。胜五兵。炼食之。轻身。神仙。一名黄食石。生武都山谷。</p>\r\n<p>$q{《名医别录》}：【雄黄】味甘。大温。有毒。主治疥虫。𧏾疮。目痛。鼻中息肉。及绝筋。破骨。百节中大积聚。癖气。中恶。腹痛。鬼疰。杀诸蛇虺毒。解藜芦毒。悦泽人面。饵服之。皆飞入人脑中。胜鬼神。延年益寿。保中不饥。得铜可作金。生武都敦煌山之阳。采无时。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":67,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '68、$u{雄黄} $q{《神农本草经》}：【雄黄】味苦。平。寒。主治寒热。鼠瘘。恶疮。疽痔。死肌。杀精物。恶鬼。邪气。百虫。毒肿。胜五兵。炼食之。轻身。神仙。一名黄食石。生武都山谷。 $q{《名医别录》}：【雄黄】味甘。大温。有毒。主治疥虫。𧏾疮。目痛。鼻中息肉。及绝筋。破骨。百节中大积聚。癖气。中恶。腹痛。鬼疰。杀诸蛇虺毒。解藜芦毒。悦泽人面。饵服之。皆飞入人脑中。胜鬼神。延年益寿。保中不饥。得铜可作金。生武都敦煌山之阳。采无时。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gFgG38KNuFm', 1, '{"title":"蜀漆","description":"<p>69、$u{蜀漆}</p>\r\n<p>$q{《神农本草经》}：【蜀漆】味辛。平。主治疟。及咳逆寒热。腹中癥坚。痞结。积聚。邪气。蛊毒。鬼疰。生江林山川谷。</p>\r\n<p>$q{《名医别录》}：【蜀漆】微温。有毒。主治胸中邪结气。吐出之。生江林山及蜀汉中。恒山苗也。五月采叶。阴干。（栝楼为之使。恶贯众。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":68,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '69、$u{蜀漆} $q{《神农本草经》}：【蜀漆】味辛。平。主治疟。及咳逆寒热。腹中癥坚。痞结。积聚。邪气。蛊毒。鬼疰。生江林山川谷。 $q{《名医别录》}：【蜀漆】微温。有毒。主治胸中邪结气。吐出之。生江林山及蜀汉中。恒山苗也。五月采叶。阴干。（栝楼为之使。恶贯众。）', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CdBvjhzVtG6', 1, '{"title":"小麦","description":"<p>70、$u{小麦}</p>\r\n<p>$q{《名医别录》}：【小麦】味甘。微寒。无毒。主除热。止燥渴咽干。利小便。养肝气。止漏血唾血。以作【曲】。温。消谷。止痢。以作【面】。温。不能消热。止烦。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":69,"yaoNames":"","aliases":[{"bieming":"小麦汁","name":"小麦"},{"bieming":"小麦粥","name":"小麦"},{"bieming":"麦粥","name":"小麦"}]}}', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '2024-09-14T16:56:58.000Z', '70、$u{小麦} $q{《名医别录》}：【小麦】味甘。微寒。无毒。主除热。止燥渴咽干。利小便。养肝气。止漏血唾血。以作【曲】。温。消谷。止痢。以作【面】。温。不能消热。止烦。', '2024-09-14T16:56:58.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('udN4qy4NAcw', 1, '{"title":"苦参","description":"<p>72、$u{苦参}</p>\r\n<p>$q{《神农本草经》}：【苦参】味苦。寒。主治心腹结气。癥瘕。积聚。黄疸。溺有余沥。逐水。除痈肿。补中。明目。止泪。一名水槐。一名苦。生汝南山谷。</p>\r\n<p>$q{《名医别录》}：【苦参】无毒。养肝胆气。安五藏。定志。益精。利九窍。除伏热。肠澼。止渴。醒酒。小便黄赤。治恶疮。下部慝。平胃气。令人嗜食。轻身。一名地槐。一名菟槐。一名骄槐。一名白茎。一名虎麻。一名岑茎。一名禄白。一名陵郎。生汝南及田野。三月八月十月采根。暴干。（玄参为之使。恶贝母漏芦菟丝。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":71,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '72、$u{苦参} $q{《神农本草经》}：【苦参】味苦。寒。主治心腹结气。癥瘕。积聚。黄疸。溺有余沥。逐水。除痈肿。补中。明目。止泪。一名水槐。一名苦。生汝南山谷。 $q{《名医别录》}：【苦参】无毒。养肝胆气。安五藏。定志。益精。利九窍。除伏热。肠澼。止渴。醒酒。小便黄赤。治恶疮。下部慝。平胃气。令人嗜食。轻身。一名地槐。一名菟槐。一名骄槐。一名白茎。一名虎麻。一名岑茎。一名禄白。一名陵郎。生汝南及田野。三月八月十月采根。暴干。（玄参为之使。恶贝母漏芦菟丝。反藜芦。）', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VbIDIYURZdR', 1, '{"title":"赤消","description":"<p>73、$u{赤消}（消石）</p>\r\n<p>$q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。）</p>\r\n<p>$q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。）</p>\r\n<p>$q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。）</p>\r\n<p>$q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。</p>\r\n<p>$q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":72,"yaoNames":"硝石,消石,赤硝","aliases":[{"bieming":"硝石","name":"赤消"}]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '73、$u{赤消}（消石） $q{《神农本草经》}：【朴消】味苦。寒。主治百病。除寒热邪气。逐六府积聚。结固留癖。能化七十二种石。炼饵服之。轻身。神仙。生益州山谷。 $q{《名医别录》}：【朴消】味辛。大寒。无毒。主治胃中食饮热结。破留血闭绝。停痰痞满。推陈致新。炼之白如银。能寒能热能滑能涩。能辛能苦能咸能酸。入地千岁不变。色青白者佳。黄者伤人。赤者杀人。一名消石朴。生益州有咸水之阳。采无时。（畏麦句姜。） $q{《神农本草经》}：【消石】味苦寒。主治五藏积热。胃胀闭。涤去蓄结饮食。推陈致新。除邪气。炼之如膏。久服轻身。一名芒消。生益州山谷。 $q{《名医别录》}：【消石】味辛。大寒。无毒。主治五藏十二经脉中百二十疾。暴伤寒腹中大热。止烦满消渴。利小便及瘘蚀疮。天地至神之物。能化成十二种石。生益州。及武都陇西西羌。采无时。（萤火为之使。恶苦参苦菜。畏女菀。） $q{《名医别录》}：【芒消】味辛苦。大寒。主治五藏积聚。久热胃闭。除邪气。破留血腹中淡实结搏。通脉。利大小便及月水。破五淋。推陈致新。生于朴消。（石韦为之使。畏麦句姜。） $q{《药性论》}：【芒消】使。味咸，有小毒。能通女子月闭。癥瘕。下瘰疬，黄疸病。主堕胎。患漆疮。汁傅之。主时疾壅热。能散恶血。 $q{《药性论》}：【玄明粉】味辛甘。性冷。无毒。治心热烦躁。并五藏宿滞癥结。明目。退膈上虚热。消肿毒。此即朴消炼成者。', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dgPXrO7Zcb7', 1, '{"title":"升麻","description":"<p>74、$u{升麻}</p>\r\n<p>$q{《神农本草经》}：【升麻】味甘。平。解百毒。杀百精老物殃鬼。辟温疫瘴气邪气蛊毒。久服不夭。一名周麻。生益州山谷。</p>\r\n<p>$q{《名医别录》}：【升麻】味苦。微寒。无毒。主解毒入口皆吐出。中恶腹痛。时气毒疠。头痛寒热。风肿诸毒。喉痛口疮。久服轻身长年。生益州。二月八月采根。日干。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":73,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '74、$u{升麻} $q{《神农本草经》}：【升麻】味甘。平。解百毒。杀百精老物殃鬼。辟温疫瘴气邪气蛊毒。久服不夭。一名周麻。生益州山谷。 $q{《名医别录》}：【升麻】味苦。微寒。无毒。主解毒入口皆吐出。中恶腹痛。时气毒疠。头痛寒热。风肿诸毒。喉痛口疮。久服轻身长年。生益州。二月八月采根。日干。', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wDdw8s8LVWE', 1, '{"title":"鸡子黄","description":"<p>81、$u{鸡子黄}（鸡黄）</p>\r\n<p>$q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":80,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '81、$u{鸡子黄}（鸡黄） $q{《神农本草经》}：【鸡子】主除热火疮。治痫痓。可作虎魄神物。生朝鲜平泽。', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ASxxg5RfLMb', 1, '{"title":"山茱萸","description":"<p>96、$u{山茱萸}</p>\r\n<p>$q{《神农本草经》}：【山茱萸】味酸。平。主治心下邪气。寒热。温中。逐寒湿痹。去三虫。久服轻身。一名蜀枣。生汉中山谷。</p>\r\n<p>$q{《名医别录》}：【山茱萸】微温。无毒。主治肠胃风邪。寒热。疝瘕。头脑风。风气去来。鼻塞。目黄。耳聋。面疱。温中。下气。出汗。强阴。益精。安五藏。通九窍。止小便利。久服明目。强力。长年。一名鸡足。一名思益。一名寇实。生汉中及琅邪宛朐东海承县。九月十月采实。阴干。（蓼实为之使。恶桔梗防风防己。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":95,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '96、$u{山茱萸} $q{《神农本草经》}：【山茱萸】味酸。平。主治心下邪气。寒热。温中。逐寒湿痹。去三虫。久服轻身。一名蜀枣。生汉中山谷。 $q{《名医别录》}：【山茱萸】微温。无毒。主治肠胃风邪。寒热。疝瘕。头脑风。风气去来。鼻塞。目黄。耳聋。面疱。温中。下气。出汗。强阴。益精。安五藏。通九窍。止小便利。久服明目。强力。长年。一名鸡足。一名思益。一名寇实。生汉中及琅邪宛朐东海承县。九月十月采实。阴干。（蓼实为之使。恶桔梗防风防己。）', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ug7wsIcyGqw', 1, '{"title":"瞿麦","description":"<p>97、$u{瞿麦}</p>\r\n<p>$q{《神农本草经》}：【瞿麦】味苦。寒。主治关格诸癃结。小便不通。出刺。决痈肿。明目去翳。破胎堕子。下闭血。一名巨句麦。生太山川谷。</p>\r\n<p>$q{《名医别录》}：【瞿麦】味辛。无毒。主养肾气。逐膀胱邪逆。止霍乱。长毛发。一名大菊。一名大兰。生太山。立秋采实。阴干。（蘘草牡丹为之使。恶桑螵蛸。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":96,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '97、$u{瞿麦} $q{《神农本草经》}：【瞿麦】味苦。寒。主治关格诸癃结。小便不通。出刺。决痈肿。明目去翳。破胎堕子。下闭血。一名巨句麦。生太山川谷。 $q{《名医别录》}：【瞿麦】味辛。无毒。主养肾气。逐膀胱邪逆。止霍乱。长毛发。一名大菊。一名大兰。生太山。立秋采实。阴干。（蘘草牡丹为之使。恶桑螵蛸。）', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xoqRCmUZylQ', 1, '{"title":"赤小豆","description":"<p>98、$u{赤小豆}（赤豆）</p>\r\n<p>$q{《神农本草经》}：【赤小豆】主下水。排痈肿脓血。</p>\r\n<p>$q{《名医别录》}：【赤小豆】味甘酸。平温。无毒。主治寒热热中消渴。止泄。利小便。吐逆。卒澼。下胀满。又叶名【藿】。主治小便数。去烦热。</p>\r\n<p>$q{《药性论》}：【赤小豆】使。味甘。能消热毒痈肿。散恶血不尽。烦满。治水肿。皮肌胀满。擣薄涂痈肿上。主小儿急黄。烂疮。取汁令洗之。不过三度差。能令人美食。末与鸡子白调。涂热毒痈肿差。通气。健脾胃。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":97,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '98、$u{赤小豆}（赤豆） $q{《神农本草经》}：【赤小豆】主下水。排痈肿脓血。 $q{《名医别录》}：【赤小豆】味甘酸。平温。无毒。主治寒热热中消渴。止泄。利小便。吐逆。卒澼。下胀满。又叶名【藿】。主治小便数。去烦热。 $q{《药性论》}：【赤小豆】使。味甘。能消热毒痈肿。散恶血不尽。烦满。治水肿。皮肌胀满。擣薄涂痈肿上。主小儿急黄。烂疮。取汁令洗之。不过三度差。能令人美食。末与鸡子白调。涂热毒痈肿差。通气。健脾胃。', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zdySy9e78kG', 1, '{"title":"瓜蒂","description":"<p>99、$u{瓜蒂}</p>\r\n<p>$q{《神农本草经》}：【瓜蒂】味苦。寒。有毒。主治大水。身面四肢浮肿。下水。杀蛊毒。咳逆上气。食诸果不消。病在胸腹中。皆吐下之。生嵩高平泽。</p>\r\n<p>$q{《名医别录》}：【瓜蒂】有毒。去鼻中息肉。治黄疸。其【花】主心痛咳逆。生嵩高。七月七日采。阴干。</p>\r\n<p>$q{《药性论》}：【瓜蒂】使。茎主鼻中息肉齆鼻。和小豆丁香吹鼻。治黄。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":98,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '99、$u{瓜蒂} $q{《神农本草经》}：【瓜蒂】味苦。寒。有毒。主治大水。身面四肢浮肿。下水。杀蛊毒。咳逆上气。食诸果不消。病在胸腹中。皆吐下之。生嵩高平泽。 $q{《名医别录》}：【瓜蒂】有毒。去鼻中息肉。治黄疸。其【花】主心痛咳逆。生嵩高。七月七日采。阴干。 $q{《药性论》}：【瓜蒂】使。茎主鼻中息肉齆鼻。和小豆丁香吹鼻。治黄。', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hmJnKWK15KJ', 1, '{"title":"皂荚","description":"<p>102、$u{皂荚}</p>\r\n<p>$q{《神农本草经》}：【皂荚】味辛咸。温。主治风痹。死肌。邪气。风头泪出。下水。利九窍。杀鬼精物。生雍州川谷。</p>\r\n<p>$q{《名医别录》}：【皂荚】有小毒。主治腹胀满。消谷。破咳嗽囊结。妇人胞下落。明目。益精。可为沐药。不入汤。生雍州及鲁邹县。如猪牙者良。九月十月采荚。阴干。（青葙子为之使。恶麦门冬。畏空青人参苦参。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":101,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '2024-09-14T16:56:59.000Z', '102、$u{皂荚} $q{《神农本草经》}：【皂荚】味辛咸。温。主治风痹。死肌。邪气。风头泪出。下水。利九窍。杀鬼精物。生雍州川谷。 $q{《名医别录》}：【皂荚】有小毒。主治腹胀满。消谷。破咳嗽囊结。妇人胞下落。明目。益精。可为沐药。不入汤。生雍州及鲁邹县。如猪牙者良。九月十月采荚。阴干。（青葙子为之使。恶麦门冬。畏空青人参苦参。）', '2024-09-14T16:56:59.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ErucDpix02e', 1, '{"title":"紫参","description":"<p>108、$u{紫参}</p>\r\n<p>$q{《神农本草经》}：【紫参】味苦辛。寒。主治心腹积聚。寒热邪气。通九窍。利大小便。一名牡蒙。生河西山谷。</p>\r\n<p>$q{《名医别录》}：【紫参】微寒。无毒。主治肠胃大热。唾血。衄血。肠中聚血。痈肿诸疮。止渴。益精。一名众戎。一名童肠。一名马行。生河西及宛朐。三月采根。火炙使紫色。（畏辛夷。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":107,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '108、$u{紫参} $q{《神农本草经》}：【紫参】味苦辛。寒。主治心腹积聚。寒热邪气。通九窍。利大小便。一名牡蒙。生河西山谷。 $q{《名医别录》}：【紫参】微寒。无毒。主治肠胃大热。唾血。衄血。肠中聚血。痈肿诸疮。止渴。益精。一名众戎。一名童肠。一名马行。生河西及宛朐。三月采根。火炙使紫色。（畏辛夷。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PEcY2j6wjoH', 1, '{"title":"射干","description":"<p>110、$u{射干}（乌扇）</p>\r\n<p>$q{《神农本草经》}：【射干】味苦。平。主治咳逆上气。喉痹咽痛。不得消息。散结气。腹中邪逆。食饮大热。一名乌扇。一名乌蒲。生南阳川谷。</p>\r\n<p>$q{《名医别录》}：【射干】微温。有毒。主治老血在心肝脾间。咳唾。言语气臭。散胸中气。久服令人虚。一名乌翣。一名乌吹。一名草姜。生南阳田野。三月三日采根。阴干。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":109,"yaoNames":"","aliases":[{"bieming":"乌扇","name":"射干"}]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '110、$u{射干}（乌扇） $q{《神农本草经》}：【射干】味苦。平。主治咳逆上气。喉痹咽痛。不得消息。散结气。腹中邪逆。食饮大热。一名乌扇。一名乌蒲。生南阳川谷。 $q{《名医别录》}：【射干】微温。有毒。主治老血在心肝脾间。咳唾。言语气臭。散胸中气。久服令人虚。一名乌翣。一名乌吹。一名草姜。生南阳田野。三月三日采根。阴干。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('woIsPez0Ouc', 1, '{"title":"代赭石","description":"<p>112、$u{赭石}（代赭，代赭石）</p>\r\n<p>$q{《神农本草经》}：【代赭】味苦。寒。主治鬼疰。贼风。蛊毒。杀精物恶鬼。腹中毒邪气。女子赤沃漏下。一名须丸。生齐国山谷。</p>\r\n<p>$q{《名医别录》}：【代赭】味甘。无毒。主带下百病。产难。胞衣不出。堕胎。养血气。除五藏血脉中热。血痹血瘀。大人小儿惊气入腹。及阴痿不起。一名血师。生齐国。赤红青色。如鸡冠有泽。染爪甲不渝者良。采无时。（畏天雄。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":111,"yaoNames":"代赭,赭石","aliases":[{"bieming":"赭石","name":"代赭石"},{"bieming":"代赭","name":"代赭石"}]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '112、$u{赭石}（代赭，代赭石） $q{《神农本草经》}：【代赭】味苦。寒。主治鬼疰。贼风。蛊毒。杀精物恶鬼。腹中毒邪气。女子赤沃漏下。一名须丸。生齐国山谷。 $q{《名医别录》}：【代赭】味甘。无毒。主带下百病。产难。胞衣不出。堕胎。养血气。除五藏血脉中热。血痹血瘀。大人小儿惊气入腹。及阴痿不起。一名血师。生齐国。赤红青色。如鸡冠有泽。染爪甲不渝者良。采无时。（畏天雄。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eOGYO6mpDY8', 1, '{"title":"紫葳","description":"<p>113、$u{紫葳}</p>\r\n<p>$q{《神农本草经》}：【紫葳】味酸。微寒。主治妇人产乳余疾。崩中。癥瘕。血闭。寒热。羸瘦。养胎。生西海川谷。</p>\r\n<p>$q{《名医别录》}：【紫葳】无毒。【茎叶】味苦。无毒。治痿蹶。益气。一名陵苕。一名芺华。一名陵时。生西海及山阳。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":112,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '113、$u{紫葳} $q{《神农本草经》}：【紫葳】味酸。微寒。主治妇人产乳余疾。崩中。癥瘕。血闭。寒热。羸瘦。养胎。生西海川谷。 $q{《名医别录》}：【紫葳】无毒。【茎叶】味苦。无毒。治痿蹶。益气。一名陵苕。一名芺华。一名陵时。生西海及山阳。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('46OxMBGC5c7', 1, '{"title":"蜣螂","description":"<p>114、$u{蜣螂}</p>\r\n<p>$q{《神农本草经》}：【蜣螂】味咸。寒。主治小儿惊痫。瘛疭。腹胀。寒热。大人癫疾。狂易。一名蛣蜣。火熬之良。生长沙池泽。</p>\r\n<p>$q{《名医别录》}：【蜣螂】有毒。主治手足端寒。肢满贲豚。生长沙。五月五日取。蒸。藏之。临用当炙。勿置水中。令人吐。（畏羊肉石膏。）又。捣为丸。塞下部。引痔虫出尽。永瘥。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":113,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '114、$u{蜣螂} $q{《神农本草经》}：【蜣螂】味咸。寒。主治小儿惊痫。瘛疭。腹胀。寒热。大人癫疾。狂易。一名蛣蜣。火熬之良。生长沙池泽。 $q{《名医别录》}：【蜣螂】有毒。主治手足端寒。肢满贲豚。生长沙。五月五日取。蒸。藏之。临用当炙。勿置水中。令人吐。（畏羊肉石膏。）又。捣为丸。塞下部。引痔虫出尽。永瘥。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xg7IDhYbYBc', 1, '{"title":"鼠妇","description":"<p>115、$u{鼠妇}</p>\r\n<p>$q{《神农本草经》}：【鼠妇】味酸。温。主治气癃。不得小便。妇人月闭。血瘕。痫痓。寒热。利水道。一名负蟠。一名𧉅蝛。生魏郡平谷。</p>\r\n<p>$q{《名医别录》}：【鼠妇】微寒。无毒。一名蜲𧑓。生魏郡及人家地上。五月五日取。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":114,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '115、$u{鼠妇} $q{《神农本草经》}：【鼠妇】味酸。温。主治气癃。不得小便。妇人月闭。血瘕。痫痓。寒热。利水道。一名负蟠。一名𧉅蝛。生魏郡平谷。 $q{《名医别录》}：【鼠妇】微寒。无毒。一名蜲𧑓。生魏郡及人家地上。五月五日取。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GuKvN0MgqAD', 1, '{"title":"蜂窠","description":"<p>116、$u{蜂窠}</p>\r\n<p>$q{《神农本草经》}：【露蜂房】味苦。平。主治惊痫。瘛疭。寒热邪气。癫疾。鬼精蛊毒。肠痔。火熬之良。一名蜂场。生牂牁山谷。</p>\r\n<p>$q{《名医别录》}：【露蜂房】味咸。有毒。主治蜂毒。毒肿。一名百穿。一名蜂窠。生䍧牱。七月七日采。阴干。（恶干姜丹参黄芩芍药牡蛎。）又合乱发蛇皮三味合烧灰。酒服方寸匕。日二。治诸恶疽附骨痈。根在藏府。历节肿出。疖肿恶脉诸毒皆差。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":115,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '116、$u{蜂窠} $q{《神农本草经》}：【露蜂房】味苦。平。主治惊痫。瘛疭。寒热邪气。癫疾。鬼精蛊毒。肠痔。火熬之良。一名蜂场。生牂牁山谷。 $q{《名医别录》}：【露蜂房】味咸。有毒。主治蜂毒。毒肿。一名百穿。一名蜂窠。生䍧牱。七月七日采。阴干。（恶干姜丹参黄芩芍药牡蛎。）又合乱发蛇皮三味合烧灰。酒服方寸匕。日二。治诸恶疽附骨痈。根在藏府。历节肿出。疖肿恶脉诸毒皆差。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BFmkWqxUMUs', 1, '{"title":"石韦","description":"<p>118、$u{石韦}</p>\r\n<p>$q{《神农本草经》}：【石韦】味苦。平。无毒。主治劳热。邪气。五癃闭不通。利小便水道。一名石䩾。生华阴山谷。</p>\r\n<p>$q{《名医别录》}：【石韦】味甘。无毒。主止烦。下气。通膀胱满。补五劳。安五藏。去恶风。益精气。一名石皮。用之去黄毛。毛射人肺。令人咳。不可治。生华阴。不闻水及人声者。良。二月采叶。阴干。（杏人为之使。得菖蒲良。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":117,"yaoNames":"石苇","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '118、$u{石韦} $q{《神农本草经》}：【石韦】味苦。平。无毒。主治劳热。邪气。五癃闭不通。利小便水道。一名石䩾。生华阴山谷。 $q{《名医别录》}：【石韦】味甘。无毒。主止烦。下气。通膀胱满。补五劳。安五藏。去恶风。益精气。一名石皮。用之去黄毛。毛射人肺。令人咳。不可治。生华阴。不闻水及人声者。良。二月采叶。阴干。（杏人为之使。得菖蒲良。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MN2tqTw73w6', 1, '{"title":"云母","description":"<p>119、$u{云母}</p>\r\n<p>$q{《神农本草经》}：【云母】味甘。平。主治身皮死肌。中风寒热。如在车船上。除邪气。安五藏。益子精。明目。久服轻身。延年。一名云珠。一名云华。一名云英。一名云液。一名云沙。一名磷石。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【云母】无毒。下气坚肌。续绝补中。治五劳七伤。虚损少气。止痢。久服悦泽不老。耐寒暑。志高神仙。一名云珠。色多赤。一名云华。五色具。一名云英。色多青。一名云液。色多白。一名云沙。色青黄。一名磷石。色正白。生太山齐庐山。及琅琊北定山石间。二月采。（泽泻为之使。畏鳝甲。反流水。恶徐长卿。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":118,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '119、$u{云母} $q{《神农本草经》}：【云母】味甘。平。主治身皮死肌。中风寒热。如在车船上。除邪气。安五藏。益子精。明目。久服轻身。延年。一名云珠。一名云华。一名云英。一名云液。一名云沙。一名磷石。生太山山谷。 $q{《名医别录》}：【云母】无毒。下气坚肌。续绝补中。治五劳七伤。虚损少气。止痢。久服悦泽不老。耐寒暑。志高神仙。一名云珠。色多赤。一名云华。五色具。一名云英。色多青。一名云液。色多白。一名云沙。色青黄。一名磷石。色正白。生太山齐庐山。及琅琊北定山石间。二月采。（泽泻为之使。畏鳝甲。反流水。恶徐长卿。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ZuiC9ADA2V', 1, '{"title":"菊花","description":"<p>120、$u{菊花}</p>\r\n<p>$q{《神农本草经》}：【菊花】味苦。平。主治风头眩肿痛。目欲脱。泪出。皮肤死肌。恶风湿痹。久服利血气。轻身。耐老延年。一名节华。生雍州川泽。</p>\r\n<p>$q{《名医别录》}：【菊花】味甘。无毒。主治腰痛去来陶陶。除胸中烦热。安肠胃。利五脉。调四肢。一名日精。一名女节。一名女华。一名女茎。一名更生。一名周盈。一名傅延年。一名阴成。生雍州及田野。正月采根。三月采叶。五月采茎。九月采花。十一月采实。皆阴干。（术枸杞根桑根白皮为之使。）</p>\r\n<p>$q{《药性论》}∶【甘菊花】使。能治热头风旋倒地。脑骨疼痛。身上诸风令消散。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":119,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '120、$u{菊花} $q{《神农本草经》}：【菊花】味苦。平。主治风头眩肿痛。目欲脱。泪出。皮肤死肌。恶风湿痹。久服利血气。轻身。耐老延年。一名节华。生雍州川泽。 $q{《名医别录》}：【菊花】味甘。无毒。主治腰痛去来陶陶。除胸中烦热。安肠胃。利五脉。调四肢。一名日精。一名女节。一名女华。一名女茎。一名更生。一名周盈。一名傅延年。一名阴成。生雍州及田野。正月采根。三月采叶。五月采茎。九月采花。十一月采实。皆阴干。（术枸杞根桑根白皮为之使。） $q{《药性论》}∶【甘菊花】使。能治热头风旋倒地。脑骨疼痛。身上诸风令消散。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cSR0rsnZv7C', 1, '{"title":"白石脂","description":"<p>122、$u{白石脂}</p>\r\n<p>$q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。</p>\r\n<p>$q{《名医别录》}：【白石脂】味甘酸。平。无毒。主养肺气。厚肠。补骨髓。治五藏惊悸不足。心下烦。止腹痛。下水。小肠澼热溏。便脓血。女子崩中漏下。赤白沃。排痈疽疮痔。久服安心。不饥。轻身长年。生太山之阴。采无时。（得厚朴并米汁饮。止便脓。䴏屎为之使。恶松脂。畏黄芩。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":121,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '122、$u{白石脂} $q{《神农本草经》}：【青石赤石黄石白石黑石脂等】味甘。平。主治黄疸。泄利。肠澼脓血。阴蚀。下血赤白。邪气痈肿。疽痔恶疮。头疡。疥瘙。久服补髓。益气。肥健。不饥。轻身。延年。五石脂各随五色补五藏。生南山之阳山谷中。 $q{《名医别录》}：【白石脂】味甘酸。平。无毒。主养肺气。厚肠。补骨髓。治五藏惊悸不足。心下烦。止腹痛。下水。小肠澼热溏。便脓血。女子崩中漏下。赤白沃。排痈疽疮痔。久服安心。不饥。轻身长年。生太山之阴。采无时。（得厚朴并米汁饮。止便脓。䴏屎为之使。恶松脂。畏黄芩。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DThHnTLC5ju', 1, '{"title":"盐","description":"<p>123、$u{盐}</p>\r\n<p>$q{《名医别录》}：【卤咸】味咸。无毒。去五藏肠胃留热。结气。心下坚。食已呕逆。喘满。明目。目痛。生河盐池。</p>\r\n<p>$q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。</p>\r\n<p>$q{《名医别录》}：【大盐】味甘咸。寒。无毒。主肠胃结热。喘逆。吐胸中病。生邯郸及河东。（漏芦为之使。）</p>\r\n<p>$q{《药性论》}：【盐】有小毒。能杀一切毒气。鬼疰气。主心痛中恶。或连腰脐者。盐如鸡子大。青布裹烧赤。内酒中。顿服。当吐恶物。主小儿卒不尿。安盐于脐中。灸之。面上五色疮。盐汤绵浸搨疮上。日五六度易。差。又和槐白皮切蒸。治脚气。又空心揩齿。少时吐水中洗眼。夜见小字。良。治妇人隐处疼痛者。盐青布裹熨之。主鬼疰尸疰。下部蚀疮。炒盐布裹坐熨之。兼主火灼疮。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":122,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '123、$u{盐} $q{《名医别录》}：【卤咸】味咸。无毒。去五藏肠胃留热。结气。心下坚。食已呕逆。喘满。明目。目痛。生河盐池。 $q{《名医别录》}：【戎盐】味咸。寒。无毒。主心腹痛。溺血。吐血。齿舌血出。一名胡盐。生胡盐山。及西羌北地。及酒泉福禄城东南角。北海青。南海赤。十月采。 $q{《名医别录》}：【大盐】味甘咸。寒。无毒。主肠胃结热。喘逆。吐胸中病。生邯郸及河东。（漏芦为之使。） $q{《药性论》}：【盐】有小毒。能杀一切毒气。鬼疰气。主心痛中恶。或连腰脐者。盐如鸡子大。青布裹烧赤。内酒中。顿服。当吐恶物。主小儿卒不尿。安盐于脐中。灸之。面上五色疮。盐汤绵浸搨疮上。日五六度易。差。又和槐白皮切蒸。治脚气。又空心揩齿。少时吐水中洗眼。夜见小字。良。治妇人隐处疼痛者。盐青布裹熨之。主鬼疰尸疰。下部蚀疮。炒盐布裹坐熨之。兼主火灼疮。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KeCSoielG2F', 1, '{"title":"紫石英","description":"<p>124、$u{紫石英}</p>\r\n<p>$q{《神农本草经》}：【紫石英】味甘。温。主治心腹咳逆邪气。补不足。女子风寒在子宫。绝孕十年无子。久服温中。轻身。延年。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【紫石英】味辛。无毒。主治上气心腹痛。寒热邪气结气。补心气不足。定惊悸。安魂魄。填下焦。止消渴。除胃中久寒。散痈肿。令人悦泽。生太山。采无时。（长石为之使。得茯苓人参芍药共治心中结气。得天雄菖蒲共治霍乱。畏扁青附子。不欲鳝甲黄连麦句姜。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":123,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '124、$u{紫石英} $q{《神农本草经》}：【紫石英】味甘。温。主治心腹咳逆邪气。补不足。女子风寒在子宫。绝孕十年无子。久服温中。轻身。延年。生太山山谷。 $q{《名医别录》}：【紫石英】味辛。无毒。主治上气心腹痛。寒热邪气结气。补心气不足。定惊悸。安魂魄。填下焦。止消渴。除胃中久寒。散痈肿。令人悦泽。生太山。采无时。（长石为之使。得茯苓人参芍药共治心中结气。得天雄菖蒲共治霍乱。畏扁青附子。不欲鳝甲黄连麦句姜。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E5qbjuyOeWF', 1, '{"title":"天雄","description":"<p>126、$u{天雄}</p>\r\n<p>$q{《神农本草经》}：【天雄】味辛。温。主治大风。寒湿痹。历节痛。拘挛缓急。破积聚。邪气。金创。强筋骨。轻身。健行。一名白幕。生少室山谷。</p>\r\n<p>$q{《名医别录》}：【天雄】味甘。大温。有大毒。主治头面风去来疼痛。心腹结积。关节重不能行步。除骨间痛。长阴气。强志。令人武勇。力作不倦。又堕胎。生少室。二月采根。阴干。（远志为之使。恶腐婢。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":125,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '126、$u{天雄} $q{《神农本草经》}：【天雄】味辛。温。主治大风。寒湿痹。历节痛。拘挛缓急。破积聚。邪气。金创。强筋骨。轻身。健行。一名白幕。生少室山谷。 $q{《名医别录》}：【天雄】味甘。大温。有大毒。主治头面风去来疼痛。心腹结积。关节重不能行步。除骨间痛。长阴气。强志。令人武勇。力作不倦。又堕胎。生少室。二月采根。阴干。（远志为之使。恶腐婢。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ODZGxGssDUt', 1, '{"title":"酸枣仁","description":"<p>130、$u{酸枣仁}</p>\r\n<p>$q{《神农本草经》}：【酸枣】味酸。平。主治心腹寒热。邪结气。四肢酸疼湿痹。久服安五藏。轻身。延年。生河东川泽。</p>\r\n<p>$q{《名医别录》}：【酸枣】无毒。主治烦心不得眠。脐上下痛。血转。久泄。虚汗。烦渴。补中。益肝气。坚筋骨。助阴气。令人肥健。生河东。八月采实。阴干。卅日成。（恶防己。）</p>\r\n<p>$q{《药性论》}：【酸枣人】主筋骨风。沙末作汤服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":129,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '130、$u{酸枣仁} $q{《神农本草经》}：【酸枣】味酸。平。主治心腹寒热。邪结气。四肢酸疼湿痹。久服安五藏。轻身。延年。生河东川泽。 $q{《名医别录》}：【酸枣】无毒。主治烦心不得眠。脐上下痛。血转。久泄。虚汗。烦渴。补中。益肝气。坚筋骨。助阴气。令人肥健。生河东。八月采实。阴干。卅日成。（恶防己。） $q{《药性论》}：【酸枣人】主筋骨风。沙末作汤服之。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CPNE5J4Tnwm', 1, '{"title":"款冬花","description":"<p>134、$u{款冬花}</p>\r\n<p>$q{《神农本草经》}：【款冬】味辛。温。主治咳逆上气。善喘。喉痹。诸惊痫。寒热邪气。一名橐吾。一名颗东。一名虎须。一名菟奚。生常山山谷。</p>\r\n<p>$q{《名医别录》}：【款冬】味甘。无毒。主消渴。喘息呼吸。一名氐冬。生常山及上党水傍。十一月采花。阴干。（杏仁为之使。得紫菀良。恶皂荚消石玄参。畏贝母辛夷麻黄黄芪黄芩青葙。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":133,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '134、$u{款冬花} $q{《神农本草经》}：【款冬】味辛。温。主治咳逆上气。善喘。喉痹。诸惊痫。寒热邪气。一名橐吾。一名颗东。一名虎须。一名菟奚。生常山山谷。 $q{《名医别录》}：【款冬】味甘。无毒。主消渴。喘息呼吸。一名氐冬。生常山及上党水傍。十一月采花。阴干。（杏仁为之使。得紫菀良。恶皂荚消石玄参。畏贝母辛夷麻黄黄芪黄芩青葙。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iNByjKej50u', 1, '{"title":"紫菀","description":"<p>135、$u{紫菀}</p>\r\n<p>$q{《神农本草经》}：【紫菀】味苦。温。主治咳逆上气。胸中寒热结气。去蛊毒、痿蹶。安五藏。生房龄山谷。</p>\r\n<p>$q{《名医别录》}：【紫菀】味辛。无毒。主治咳唾脓血。止喘悸。五劳体虚。补不足。小儿惊痫。一名紫蒨。一名青苑。生房陵及真定邯郸。二月三月采根。阴干。（款冬为之使。恶天雄瞿麦雷丸远志。畏茵陈蒿。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":134,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '135、$u{紫菀} $q{《神农本草经》}：【紫菀】味苦。温。主治咳逆上气。胸中寒热结气。去蛊毒、痿蹶。安五藏。生房龄山谷。 $q{《名医别录》}：【紫菀】味辛。无毒。主治咳唾脓血。止喘悸。五劳体虚。补不足。小儿惊痫。一名紫蒨。一名青苑。生房陵及真定邯郸。二月三月采根。阴干。（款冬为之使。恶天雄瞿麦雷丸远志。畏茵陈蒿。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rw6Mqj3o4qB', 1, '{"title":"泽漆","description":"<p>136、$u{泽漆}</p>\r\n<p>$q{《神农本草经》}：【泽漆】味苦。微寒。主治皮肤热。大腹水气。四肢面目浮肿。丈夫阴气不足。生太山川泽。</p>\r\n<p>$q{《名医别录》}：【泽漆】味辛。无毒。利大小肠。明目。轻身。一名漆茎。大戟苗也。生太山。三月三日七月七日采茎叶。阴干。（小豆为之使。恶署预。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":135,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '136、$u{泽漆} $q{《神农本草经》}：【泽漆】味苦。微寒。主治皮肤热。大腹水气。四肢面目浮肿。丈夫阴气不足。生太山川泽。 $q{《名医别录》}：【泽漆】味辛。无毒。利大小肠。明目。轻身。一名漆茎。大戟苗也。生太山。三月三日七月七日采茎叶。阴干。（小豆为之使。恶署预。）', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LoZ0ORbfbD5', 1, '{"title":"白前","description":"<p>137、$u{白前}</p>\r\n<p>$q{《名医别录》}：【白前】味甘。微温。无毒。主治胸胁逆气。咳嗽上气。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":136,"yaoNames":"","aliases":[]}}', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '2024-09-14T16:57:00.000Z', '137、$u{白前} $q{《名医别录》}：【白前】味甘。微温。无毒。主治胸胁逆气。咳嗽上气。', '2024-09-14T16:57:00.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
